INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (6396, 'MANGO', NULL, N'1-4', N'May-July', N'May-July', N'5,6,7', N'Vegetative stage', N'2', 'NORMAL', 'YES', '• ಸಾಲುಗಳ ಮಧ್ಯ ರೆಂಟೆ ಹೊಡೆದು, ಹರಗಿ, ಭೂಮಿಯನ್ನು ಸ್ವಚ್ಛ ಮಾಡುವುದು
• ನಂತರ ಗಿಡದ ಸುತ್ತ ಪಾತಿ ಮಾಡಿ LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ರಸಗೊಬ್ಬರಗಳನ್ನು ಕೊಡುವುದು
• ಹಸಿರೆಲೆ ಗೊಬ್ಬರದ ಗಿಡಗಳಾದ ಸೆಣಬು, ಅಲಸಂದಿ ಅಥವಾ ಹುರುಳಿ ಬೆಳೆಯನ್ನು ಬೆಳೆಯುವುದರಿಂದ ಭೂಮಿಯ ಫಲವತ್ತತೆಯನ್ನು ಹೆಚ್ಚಿಸಬಹುದು
• ತೋಟದ ಮಧ್ಯದಲ್ಲಿ ಶೇಂಗಾ, ಸೂರ್ಯಕಾಂತಿ ಅಥವಾ ತರಕಾರಿ ಬೆಳೆಗಳನ್ನು ಅಂತರಬೆಳೆಗಳನ್ನಾಗಿ ಬೆಳೆಯಬಹುದು', NULL, '• Clean the soil by harrowing between the rows
• Then make a bed around the plant and apply the recommended fertilizers based on LRI
• Growing green manure crops such as jute, linseed or buckwheat can increase the fertility of the soil
• Groundnut, sunflower or vegetable crops can be grown as intercrops in the middle of the garden', NULL, 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (6359, 'MANGO', NULL, N'<1', N'May', N'May', N'5', N'Land Preparation', N'0', 'NIL', 'NIL', 'ಪೂರ್ವಸಿದ್ದತೆ: ಭೂಮಿಯನ್ನು ಚೆನ್ನಾಗಿ ಉಳುಮೆ ಮಾಡಿ ಸಿದ್ಧಪಡಿಸಿಕೊಂಡು 8 ಮೀ. x 8 ಮೀ. ಅಂತರದಲ್ಲಿ 3x3x3 ಅಡಿ ಗಾತ್ರದ ಗುಣಿಗಳನ್ನು ತೆಗೆದು ನಾಟಿಗೆ ಸಿದ್ಧಪಡಿಸಿಕೊಳ್ಳುವುದು', NULL, 'Preparation: Prepare the land by ploughing it well and making 3x3x3 feet pits at a distance of 8 m. x 8 m. and preparing it for planting.', NULL, 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (6360, 'MANGO', NULL, N'<1', N'June-July', N'June-July', N'6,7', N'Planting', N'1', 'NORMAL', 'YES', '• ಕೊಟ್ಟಿಗೆ ಗೊಬ್ಬರ ಮತ್ತು ಮೇಲ್ಮಣ್ಣಿನ ಮಿಶ್ರಣದಿಂದ ಸಿದ್ಧಪಡಿಸಿಕೊಂಡ ಗುಣಿಗಳನ್ನು ತುಂಬಿ ನಂತರ ಗುಣಿಯ ಮಧ್ಯಭಗದಲ್ಲಿ ಗಿಡಗಳನ್ನು ನಾಟಿ ಮಾಡುವುದು
• ನಾಟಿ ಮಾಡಿದ ನಂತರ ಗಿಡದಿಂದ 0.5 ಮೀ. ಅಂತರದಲ್ಲಿ ಪಾತಿ ಮಾಡಿ LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ರಸಗೊಬ್ಬರವನ್ನು ಕೊಡುವುದು', NULL, '• Fill the prepared holes with a mixture of manure and topsoil and then plant the plants in the middle of the holes. • After planting, make a hole at a distance of 0.5 m from the plants and apply the recommended fertilizer based on LRI.', NULL, 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (6361, 'MANGO', NULL, N'<1', N'June-July', N'June-July', N'6,7', N'Planting', N'1', 'NORMAL', 'NO', '• ಮಳೆಯ ಮುನ್ಸೂಚನೆಯನ್ನು ಗಮನದಲ್ಲಿಟ್ಟುಕೊಂಡು ಕೊಟ್ಟಿಗೆ ಗೊಬ್ಬರ ಮತ್ತು ಮೇಲ್ಮಣ್ಣಿನ ಮಿಶ್ರಣದಿಂದ ಸಿದ್ಧಪಡಿಸಿಕೊಂಡ ಗುಣಿಗಳನ್ನು ತುಂಬಿ ನಂತರ ಗುಣಿಯ ಮಧ್ಯಭಗದಲ್ಲಿ ಗಿಡಗಳನ್ನು ನಾಟಿ ಮಾಡುವುದು
• ನಾಟಿ ಮಾಡಿದ ನಂತರ ಗಿಡದಿಂದ 0.5 ಮೀ. ಅಂತರದಲ್ಲಿ ಪಾತಿ ಮಾಡಿ LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ರಸಗೊಬ್ಬರವನ್ನು ಕೊಡುವುದು 
• ನಾಟಿ ಮಾಡಿದ ನಂತರ ಮಳೆ ಮುನ್ಸೂಚನೆ ಇಲ್ಲದ್ದಿದ್ದರೆ ಗಿಡಗಳಿಗೆ ಕೃಷಿ ಹೊಂಡ, ಇತರ ಮೂಲಗಳಲ್ಲಿ ಲಭ್ಯವಿರುವ ನೀರನ್ನು ಬಳಸಿ ಸಂರಕ್ಷಣಾ ನೀರಾವರಿ ಒದಗಿಸುವುದು', NULL, '• Keeping in mind the rainfall forecast, fill the prepared holes with a mixture of cow dung and topsoil and then plant the plants in the middle of the holes
• After planting, make a bed at a distance of 0.5 m from the plants and apply the recommended fertilizer based on LRI 
• If there is no rainfall forecast after planting, provide conservation irrigation to the plants using water available from agricultural wells and other sources', NULL, 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (6362, 'MANGO', NULL, N'<1', N'June-July', N'June-July', N'6,7', N'Planting', N'1', 'BELOW NORMAL', 'YES', '• ಮಳೆಯ ಮುನ್ಸೂಚನೆಯನ್ನು ಗಮನದಲ್ಲಿಟ್ಟುಕೊಂಡು ಕೊಟ್ಟಿಗೆ ಗೊಬ್ಬರ ಮತ್ತು ಮೇಲ್ಮಣ್ಣಿನ ಮಿಶ್ರಣದಿಂದ ಸಿದ್ಧಪಡಿಸಿಕೊಂಡ ಗುಣಿಗಳನ್ನು ತುಂಬಿ ನಂತರ ಗುಣಿಯ ಮಧ್ಯಭಗದಲ್ಲಿ ಗಿಡಗಳನ್ನು ನಾಟಿ ಮಾಡುವುದು
• ನಾಟಿ ಮಾಡಿದ ನಂತರ ಗಿಡದಿಂದ 0.5 ಮೀ. ಅಂತರದಲ್ಲಿ ಪಾತಿ ಮಾಡಿ LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ರಸಗೊಬ್ಬರವನ್ನು ಕೊಡುವುದು', NULL, '• Keeping in mind the rainfall forecast, fill the prepared holes with a mixture of cow dung and topsoil and then plant the plants in the middle of the holes. • After planting, make a bed at a distance of 0.5 m from the plants and apply the recommended fertilizer based on the LRI.', NULL, NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (6363, 'MANGO', NULL, N'<1', N'June-July', N'June-July', N'6,7', N'Planting', N'1', 'BELOW NORMAL', 'NO', '• ನೀರಾವರಿ ಸೌಲಭ್ಯವಿದ್ದಲ್ಲಿ ಕೊಟ್ಟಿಗೆ ಗೊಬ್ಬರ ಮತ್ತು ಮೇಲ್ಮಣ್ಣಿನ ಮಿಶ್ರಣದಿಂದ ಸಿದ್ಧಪಡಿಸಿಕೊಂಡ ಗುಣಿಗಳನ್ನು ತುಂಬಿ ನಂತರ ಗುಣಿಯ ಮಧ್ಯಭಗದಲ್ಲಿ ಗಿಡಗಳನ್ನು ನಾಟಿ ಮಾಡುವುದು 
