INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (6387, 'MANGO', NULL, N'<1', N'February-March', N'February-March', N'2,3', N'Vegetative stage', N'4', 'BELOW NORMAL', 'NO', 'ಕೃಷಿ ಹೊಂಡ, ಇತರ ಮೂಲಗಳಲ್ಲಿ ಲಭ್ಯವಿರುವ ನೀರನ್ನು ಬಳಸಿ ಸಂರಕ್ಷಣಾ ನೀರಾವರಿ ಕೊಡುವುದು. ಗಿಡದ ಸುತ್ತಲು ಒಣಗಿದ ಎಲೆಗಳಿಂದ ಮಣ್ಣಿನ ಮೇಲೊದಿಕೆ ಮಾಡುವುದರಿಂದ ಮಣ್ಣಿನ ತೇವಾಂಶವನ್ನು ಕಾಪಾಡಿಕೊಳ್ಳಬಹುದು', NULL, 'Conservation irrigation is done using water available from agricultural wells and other sources. Mulching the soil with dry leaves around the plant can help maintain soil moisture.', NULL, 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (6388, 'MANGO', NULL, N'<1', N'February-March', N'February-March', N'2,3', N'Vegetative stage', N'4', 'ABOVE NORMAL', 'YES', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', NULL, 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field.', NULL, 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (6401, 'MANGO', NULL, N'1-4', N'May-July', N'May-July', N'5,6,7', N'Vegetative stage', N'2', 'ABOVE NORMAL', 'NO', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', NULL, 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field.', NULL, 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (6402, 'MANGO', NULL, N'1-4', N'August-September', N'August-September', N'8,9', N'Vegetative stage', N'2', 'NORMAL', 'YES', '• ತೋಟದಲ್ಲಿ ಹಸಿರೆಲೆ ಗೊಬ್ಬರದ ಗಿಡಗಳನ್ನು ಬೆಳೆದಿದ್ದರೆ ಅವನ್ನು ಬಿತ್ತಿದ 45 ದಿನಗಳ ನಂತರ ಮಣ್ಣಿಗೆ ಸೇರಿಸುವುದು
• ತೋಟದ ಮಧ್ಯ ಅಂತರಬೆಳೆ ಬೆಳೆದಿದ್ದರೆ ಅವುಗಳಿಗೆ ತಗುಲುವ ರೋಗ ಮತ್ತು ಕೀಟಗಳ ಮೇಲೆ ಗಮನ ಹರಿಸುವುದು', NULL, '• If green manure crops are grown in the garden, incorporate them into the soil 45 days after sowing. • If intercrops are grown in the garden, pay attention to the diseases and pests that they are susceptible to.', NULL, 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
