INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (6407, 'MANGO', NULL, N'1-4', N'August-September', N'August-September', N'8,9', N'Vegetative stage', N'2', 'ABOVE NORMAL', 'NO', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', NULL, 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field.', NULL, 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (6408, 'MANGO', NULL, N'1-4', N'October-November', N'October-November', N'10,11', N'Vegetative stage', N'2', 'NORMAL', 'YES', 'ಸೂಚಿಸಲಾದ ಸಸ್ಯ ಸಂರಕ್ಷಣಾ ಕ್ರಮಗಳನ್ನು ಕೈಗೊಳ್ಳುವುದು', 'ಜಿಗಿ ಹುಳು ಹಾಗೂ ಶಲ್ಕ ಕೀಟ ಕಂಡು ಬಂದಲ್ಲಿ ಲೀ. ನೀರಿಗೆ 0.3 ಮಿ.ಲೀ. ಇಮೀಡಾಕ್ಲೋಪ್ರಿಡ್ 17.8 SL ಅಥವಾ 5% ಬೇವಿನ ಬೀಜದ ಕಷಾಯವನ್ನು ಬೆರೆಸಿ ಸಿಂಪಡಿಸುವುದು', 'Carrying out the recommended plant protection measures', 'If leafhoppers and scale insects are found, spray with 0.3 ml of Imidacloprid 17.8 SL or 5% neem seed extract per liter of water', 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (6428, 'MANGO', NULL, N'1-4', N'April', N'April', N'4', N'Vegetative stage', N'5', 'BELOW NORMAL', 'YES', 'ಪ್ರಸ್ತುತ ಹಂತದಲ್ಲಿ ಬೆಳೆ ಉತ್ತಮವಾಗಿದ್ದರೆ, ಇತರೆ ಬೆಳೆ ಬೆಳೆದಿದ್ದಲ್ಲಿ ಅವುಗಳ ನಿರ್ವಹಣೆಯತ್ತ ಗಮನಹರಿಸುವುದು', NULL, 'If the crop is good at the current stage, focus on managing other crops if they have grown.', NULL, 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (6429, 'MANGO', NULL, N'1-4', N'April', N'April', N'4', N'Vegetative stage', N'5', 'BELOW NORMAL', 'NO', 'ಕೃಷಿ ಹೊಂಡ, ಇತರ ಮೂಲಗಳಲ್ಲಿ ಲಭ್ಯವಿರುವ ನೀರನ್ನು ಬಳಸಿ ಸಂರಕ್ಷಣಾ ನೀರಾವರಿ ಕೊಡುವುದು. ಗಿಡದ ಸುತ್ತಲು ಒಣಗಿದ ಎಲೆಗಳಿಂದ ಮಣ್ಣಿನ ಮೇಲೊದಿಕೆ ಮಾಡುವುದರಿಂದ ಮಣ್ಣಿನ ತೇವಾಂಶವನ್ನು ಕಾಪಾಡಿಕೊಳ್ಳಬಹುದು', NULL, 'Conservation irrigation is done using water available from agricultural wells and other sources. Mulching the soil with dry leaves around the plant can help maintain soil moisture.', NULL, 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (6430, 'MANGO', NULL, N'1-4', N'April', N'April', N'4', N'Vegetative stage', N'5', 'ABOVE NORMAL', 'YES', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', 'ಕಾಂಡ ಕೊರಕ ಕಂಡು ಬಂದಲ್ಲಿ ಎಕೆರೆಗೆ 4-5 ಹಳದಿ ಮೋಹಕ ಅಂಟು ಬಲೆಗಳನ್ನು ಅಥವಾ ಎಕೆರೆಗೆ 10 ಲಿಂಗಾಕರ್ಷಕ ಮೋಹಕ ಬಲೆಗಳನ್ನು ಬಳಸುವುದು. ರಂಧ್ರಗಳನ್ನು ಕೆಸರು ಮಣ್ಣಿನಿಂದ ಮುಚ್ಚುವುದು ಹಾಗೂ ಪ್ರತಿ ರಂಧ್ರಕ್ಕೆ 5 ಮಿಲೀ. ಕ್ವಿನಾಲ್‌ಫಾಸ್ 25 EC ಅನ್ನು ಪಿಚಕಾರಿಯ ಮೂಲಕ ರಂಧ್ರಕ್ಕೆ ಸೇರಿಸುವುದು. ಚಿಬ್ಬು ರೋಗ ಕಂಡುಬಂದಲ್ಲಿ 1% ರ ಬೋರ್ಡೋ ದ್ರಾವಣ ಅಥವಾ 1 ಗ್ರಾಂ. ಕಾರ್ಬೆಂಡಜಿಮ್ 50 WP ಸೇರಿಸಿ ಸಿಂಪಡಿಸುವುದು', 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field.', 'If stem borer is found, use 4-5 yellow attractant traps per acre or 10 sex attractant traps per acre. Cover the holes with silt soil and add 5 ml. Quinalphos 25 EC per hole through a syringe. If powdery mildew is found, spray with 1% Bordeaux mixture or 1 g. Carbendazim 50 WP', 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (6431, 'MANGO', NULL, N'1-4', N'April', N'April', N'4', N'Vegetative stage', N'5', 'ABOVE NORMAL', 'NO', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', NULL, 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field.', NULL, 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (6434, 'MANGO (EARLY VARIETIES)', NULL, N'>4', N'May-July', N'May-July', N'5,6,7', N'Vegetative stage', N'2', 'BELOW NORMAL', 'YES', '• ಸಾಲುಗಳ ಮಧ್ಯ ರೆಂಟೆ ಹೊಡೆದು, ಹರಗಿ, ಭೂಮಿಯನ್ನು ಸ್ವಚ್ಛ ಮಾಡುವುದು 
 • ಕೊಂಬೆಗಳನ್ನು ಸವರುವುದು (ಪ್ರೂನಿಂಗ್ ಮಾಡುವುದು)‌, ಇದರಿಂದ ಹೊಸ ಚಿಗುರು ಬರುವುದಕ್ಕೆ ಸಹಕಾರಿಯಾಗುತ್ತದೆ. (ಹೆಚ್ಚಿನ ಮಾಹಿತಿಗಾಗಿ ಮಾವು ಬೆಳೆ ಪದ್ಧತಿಯಲ್ಲಿ ವೀಕ್ಷಿಸಬಹುದು)
• ನಂತರ ಗಿಡದ ಸುತ್ತ ಪಾತಿ ಮಾಡಿ LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ರಸಗೊಬ್ಬರಗಳನ್ನು ಕೊಡುವುದು
 • ಹಸಿರೆಲೆ ಗೊಬ್ಬರದ ಗಿಡಗಳಾದ ಸೆಣಬು, ಅಲಸಂದಿ ಅಥವಾ ಹುರುಳಿ ಬೆಳೆಯನ್ನು ಬೆಳೆಯುವುದರಿಂದ ಭೂಮಿಯ ಫಲವತ್ತತೆಯನ್ನು ಹೆಚ್ಚಿಸಬಹುದು
 • ತೋಟದ ಮಧ್ಯದಲ್ಲಿ ಶೇಂಗಾ, ಸೂರ್ಯಕಾಂತಿ ಅಥವಾ ತರಕಾರಿ ಬೆಳೆಗಳನ್ನು ಅಂತರಬೆಳೆಗಳನ್ನಾಗಿ ಬೆಳೆಯಬಹುದು', 'ಜಿಗಿ ಹುಳು ಹಾಗೂ ಶಲ್ಕ ಕೀಟ ಕಂಡು ಬಂದಲ್ಲಿ ಲೀ. ನೀರಿಗೆ 0.3 ಮಿಲೀ. ಇಮೀಡಾಕ್ಲೋಪ್ರಿಡ್ 17.8 SL ಅಥವಾ 5% ಬೇವಿನ ಬೀಜದ ಕಷಾಯವನ್ನು ಬೆರೆಸಿ ಸಿಂಪರಿಸುವುದು', '• Clean the soil by harrowing and spreading between the rows 
• Pruning the branches, which helps in the emergence of new shoots. (For more information, see Mango Crop System)
• Then make a bed around the plant and apply fertilizers recommended based on LRI
• Growing green manure crops such as jute, sorghum or buckwheat can increase the fertility of the soil
• Groundnut, sunflower or vegetable crops can be grown as intercrops in the middle of the garden', 'If leafhoppers and scale insects are found, spray with 0.3 ml of Imidacloprid 17.8 SL per liter of water or 5% neem seed extract', 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (6435, 'MANGO (EARLY VARIETIES)', NULL, N'>4', N'May-July', N'May-July', N'5,6,7', N'Vegetative stage', N'2', 'BELOW NORMAL', 'NO', 'ಗಿಡದ ಸುತ್ತಲು ಒಣಗಿದ ಎಲೆಗಳಿಂದ ಮಣ್ಣಿನ ಮೇಲೊದಿಕೆ ಮಾಡುವುದರಿಂದ ಮಣ್ಣಿನ ತೇವಾಂಶವನ್ನು ಕಾಪಾಡಿಕೊಳ್ಳಬಹುದು', NULL, 'Mulching the soil with dry leaves around the plant can help maintain soil moisture.', NULL, 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (6436, 'MANGO (EARLY VARIETIES)', NULL, N'>4', N'May-July', N'May-July', N'5,6,7', N'Vegetative stage', N'2', 'ABOVE NORMAL', 'YES', 'ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ತೋಟದಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದು ಕೃಷಿ ಹೊಂಡಗಳಲ್ಲಿ ಶೇಖರಿಸಲು ಅನುವುಮಾಡಿಕೊಡಿ', 'ಹಿಟ್ಟು ತಿಗಣೆ ಕಂಡುಬಂದಲ್ಲಿ ಪ್ರತಿ ಲೀಟರ್ ನೀರಿಗೆ 1.25 ಮಿಲೀ. ಬುಪ್ರೊಫೆಜಿನ್ 25% SC ಅಥವಾ 2 ಮಿಲೀ. ಪ್ರೊಫೆನೊಫಾಸ್ 50 EC + 5 ಗ್ರಾಂ ಮೀನಿನ ಎಣ್ಣೆ ರೋಸಿನ್ ಸೋಪ್ ಅಥವಾ 5% ಬೇವಿನ ಬೀಜ ಕಷಾಯವನ್ನು ಬೆರೆಸಿ ಸಿಂಪರಿಸುವುದು', 'If there is heavy rainfall, allow water to drain from the garden and store in agricultural pits.', 'If mealybugs are found, spray 1.25 ml. Buprofezin 25% SC or 2 ml. Profenophos 50 EC + 5 gm fish oil rosin soap or 5% neem seed infusion per liter of water', 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (6437, 'MANGO (EARLY VARIETIES)', NULL, N'>4', N'May-July', N'May-July', N'5,6,7', N'Vegetative stage', N'2', 'ABOVE NORMAL', 'NO', 'ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ತೋಟದಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದು ಕೃಷಿ ಹೊಂಡಗಳಲ್ಲಿ ಶೇಖರಿಸಲು ಅನುವುಮಾಡಿಕೊಡಿ', NULL, 'If there is heavy rainfall, allow water to drain from the garden and store in agricultural pits.', NULL, 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (6438, 'MANGO (EARLY VARIETIES)', NULL, N'>4', N'August-September', N'August-September', N'8,9', N'Vegetative stage', N'2', 'NORMAL', 'YES', 'ಪ್ರಸ್ತುತ ಹಂತದಲ್ಲಿ ಬೆಳೆ ಉತ್ತಮವಾಗಿದ್ದರೆ, ಇತರೆ ಬೆಳೆ ಬೆಳೆದಿದ್ದಲ್ಲಿ ಅವುಗಳ ನಿರ್ವಹಣೆಯತ್ತ ಗಮನಹರಿಸುವುದು', NULL, 'If the crop is good at the current stage, focus on managing other crops if they have grown.', NULL, 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (6439, 'MANGO (EARLY VARIETIES)', NULL, N'>4', N'August-September', N'August-September', N'8,9', N'Vegetative stage', N'2', 'NORMAL', 'NO', 'ಪ್ರಸ್ತುತ ಹಂತದಲ್ಲಿ ಬೆಳೆ ಉತ್ತಮವಾಗಿದ್ದರೆ, ಇತರೆ ಬೆಳೆ ಬೆಳೆದಿದ್ದಲ್ಲಿ ಅವುಗಳ ನಿರ್ವಹಣೆಯತ್ತ ಗಮನಹರಿಸುವುದು', NULL, 'If the crop is good at the current stage, focus on managing other crops if they have grown.', NULL, 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (6432, 'MANGO (EARLY VARIETIES)', NULL, N'>4', N'May-July', N'May-July', N'5,6,7', N'Vegetative stage', N'2', 'NORMAL', 'YES', '• ಸಾಲುಗಳ ಮಧ್ಯ ರೆಂಟೆ ಹೊಡೆದು, ಹರಗಿ, ಭೂಮಿಯನ್ನು ಸ್ವಚ್ಛ ಮಾಡುವುದು 
 • ಕೊಂಬೆಗಳನ್ನು ಸವರುವುದು (ಪ್ರೂನಿಂಗ್ ಮಾಡುವುದು)‌, ಇದರಿಂದ ಹೊಸ ಚಿಗುರು ಬರುವುದಕ್ಕೆ ಸಹಕಾರಿಯಾಗುತ್ತದೆ. (ಹೆಚ್ಚಿನ ಮಾಹಿತಿಗಾಗಿ ಮಾವು ಬೆಳೆ ಪದ್ಧತಿಯಲ್ಲಿ ವೀಕ್ಷಿಸಬಹುದು)
 • ನಂತರ ಗಿಡದ ಸುತ್ತ ಪಾತಿ ಮಾಡಿ LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ರಸಗೊಬ್ಬರಗಳನ್ನು ಕೊಡುವುದು 
 • ಹಸಿರೆಲೆ ಗೊಬ್ಬರದ ಗಿಡಗಳಾದ ಸೆಣಬು, ಅಲಸಂದಿ ಅಥವಾ ಹುರುಳಿ ಬೆಳೆಯನ್ನು ಬೆಳೆಯುವುದರಿಂದ ಭೂಮಿಯ ಫಲವತ್ತತೆಯನ್ನು ಹೆಚ್ಚಿಸಬಹುದು
 • ತೋಟದ ಮಧ್ಯದಲ್ಲಿ ಶೇಂಗಾ, ಸೂರ್ಯಕಾಂತಿ ಅಥವಾ ತರಕಾರಿ ಬೆಳೆಗಳನ್ನು ಅಂತರಬೆಳೆಗಳನ್ನಾಗಿ ಬೆಳೆಯಬಹುದು', 'ಕಾಂಡ ಕೊರಕ ಕಂಡು ಬಂದಲ್ಲಿ ಎಕೆರೆಗೆ 4-5 ಹಳದಿ ಮೋಹಕ ಅಂಟು ಬಲೆಗಳನ್ನು ಅಥವಾ ಎಕೆರೆಗೆ 10 ಲಿಂಗಾಕರ್ಷಕ ಮೋಹಕ ಬಲೆಗಳನ್ನು ಬಳಸುವುದು. ರಂಧ್ರಗಳನ್ನು ಕೆಸರು ಮಣ್ಣಿನಿಂದ ಮುಚ್ಚುವುದು ಹಾಗೂ ಪ್ರತಿ ರಂಧ್ರಕ್ಕೆ 5 ಮಿಲೀ. ಕ್ವಿನಾಲ್‌ಫಾಸ್ 25 EC ಅನ್ನು ಪಿಚಕಾರಿಯ ಮೂಲಕ ರಂಧ್ರಕ್ಕೆ ಸೇರಿಸುವುದು. ಚಿಬ್ಬು ರೋಗ ಕಂಡುಬಂದಲ್ಲಿ 1% ರ ಬೋರ್ಡೋ ದ್ರಾವಣ ಅಥವಾ 1 ಗ್ರಾಂ. ಕಾರ್ಬೆಂಡಜಿಮ್ 50 WP ಸೇರಿಸಿ ಸಿಂಪಡಿಸುವುದು', '• Clean the soil by harrowing and spreading between the rows 
• Pruning the branches, which helps in the emergence of new shoots. (For more information, see Mango Crop System)
• Then make a bed around the plant and apply fertilizers recommended based on LRI 
• Growing green manure crops such as jute, linseed or buckwheat can increase the fertility of the soil
• Groundnut, sunflower or vegetable crops can be grown as intercrops in the middle of the garden', 'If stem borer is found, use 4-5 yellow attractant traps per acre or 10 sex attractant traps per acre. Cover the holes with silt soil and add 5 ml. Quinalphos 25 EC per hole through a syringe. If powdery mildew is found, spray with 1% Bordeaux mixture or 1 g. Carbendazim 50 WP', 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (6433, 'MANGO (EARLY VARIETIES)', NULL, N'>4', N'May-July', N'May-July', N'5,6,7', N'Vegetative stage', N'2', 'NORMAL', 'NO', '• ಸಾಲುಗಳ ಮಧ್ಯ ರೆಂಟೆ ಹೊಡೆದು, ಹರಗಿ, ಭೂಮಿಯನ್ನು ಸ್ವಚ್ಛ ಮಾಡುವುದು
 • ಕೊಂಬೆಗಳನ್ನು ಸವರುವುದು (ಪ್ರೂನಿಂಗ್ ಮಾಡುವುದು)‌, ಇದರಿಂದ ಹೊಸ ಚಿಗುರು ಬರುವುದಕ್ಕೆ ಸಹಕಾರಿಯಾಗುತ್ತದೆ.. (ಹೆಚ್ಚಿನ ಮಾಹಿತಿಗಾಗಿ ಮಾವು ಬೆಳೆ ಪದ್ಧತಿಯಲ್ಲಿ ವೀಕ್ಷಿಸಬಹುದು)
• ನಂತರ ಗಿಡದ ಸುತ್ತ ಪಾತಿ ಮಾಡಿ LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ರಸಗೊಬ್ಬರಗಳನ್ನು ಕೊಡುವುದು
 • ಹಸಿರೆಲೆ ಗೊಬ್ಬರದ ಗಿಡಗಳಾದ ಸೆಣಬು, ಅಲಸಂದಿ ಅಥವಾ ಹುರುಳಿ ಬೆಳೆಯನ್ನು ಬೆಳೆಯುವುದರಿಂದ ಭೂಮಿಯ ಫಲವತ್ತತೆಯನ್ನು ಹೆಚ್ಚಿಸಬಹುದು
 • ತೋಟದ ಮಧ್ಯದಲ್ಲಿ ಶೇಂಗಾ, ಸೂರ್ಯಕಾಂತಿ ಅಥವಾ ತರಕಾರಿ ಬೆಳೆಗಳನ್ನು ಅಂತರಬೆಳೆಗಳನ್ನಾಗಿ ಬೆಳೆಯಬಹುದು', 'ಕಾಂಡ ಕೊರಕ ಕಂಡು ಬಂದಲ್ಲಿ ಎಕೆರೆಗೆ 4-5 ಹಳದಿ ಮೋಹಕ ಅಂಟು ಬಲೆಗಳನ್ನು ಅಥವಾ ಎಕೆರೆಗೆ 10 ಲಿಂಗಾಕರ್ಷಕ ಮೋಹಕ ಬಲೆಗಳನ್ನು ಬಳಸುವುದು. ರಂಧ್ರಗಳನ್ನು ಕೆಸರು ಮಣ್ಣಿನಿಂದ ಮುಚ್ಚುವುದು ಹಾಗೂ ಪ್ರತಿ ರಂಧ್ರಕ್ಕೆ 5 ಮಿಲೀ. ಕ್ವಿನಾಲ್‌ಫಾಸ್ 25 EC ಅನ್ನು ಪಿಚಕಾರಿಯ ಮೂಲಕ ರಂಧ್ರಕ್ಕೆ ಸೇರಿಸುವುದು. ಚಿಬ್ಬು ರೋಗ ಕಂಡುಬಂದಲ್ಲಿ 1% ರ ಬೋರ್ಡೋ ದ್ರಾವಣ ಅಥವಾ 1 ಗ್ರಾಂ. ಕಾರ್ಬೆಂಡಜಿಮ್ 50 WP ಸೇರಿಸಿ ಸಿಂಪಡಿಸುವುದು', '• Clean the soil by harrowing and spreading between the rows
• Pruning the branches, which helps in the emergence of new shoots.. (For more information, see Mango Crop System)
• Then make a bed around the plant and apply fertilizers recommended based on LRI
• Growing green manure plants such as jute, sorghum or buckwheat can increase the fertility of the soil
• Groundnut, sunflower or vegetable crops can be grown as intercrops in the middle of the garden', 'If stem borer is found, use 4-5 yellow attractant traps per acre or 10 sex attractant traps per acre. Cover the holes with silt soil and add 5 ml. Quinalphos 25 EC per hole through a syringe. If powdery mildew is found, spray with 1% Bordeaux mixture or 1 g. Carbendazim 50 WP', 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (6409, 'MANGO', NULL, N'1-4', N'October-November', N'October-November', N'10,11', N'Vegetative stage', N'2', 'NORMAL', 'NO', 'ಸೂಚಿಸಲಾದ ಸಸ್ಯ ಸಂರಕ್ಷಣಾ ಕ್ರಮಗಳನ್ನು ಕೈಗೊಳ್ಳುವುದು', 'ಜಿಗಿ ಹುಳು ಹಾಗೂ ಶಲ್ಕ ಕೀಟ ಕಂಡು ಬಂದಲ್ಲಿ ಲೀ. ನೀರಿಗೆ 0.3 ಮಿ.ಲೀ. ಇಮೀಡಾಕ್ಲೋಪ್ರಿಡ್ 17.8 SL ಅಥವಾ 5% ಬೇವಿನ ಬೀಜದ ಕಷಾಯವನ್ನು ಬೆರೆಸಿ ಸಿಂಪಡಿಸುವುದು', 'Carrying out the recommended plant protection measures', 'If leafhoppers and scale insects are found, spray with 0.3 ml of Imidacloprid 17.8 SL or 5% neem seed extract per liter of water', 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (6410, 'MANGO', NULL, N'1-4', N'October-November', N'October-November', N'10,11', N'Vegetative stage', N'2', 'BELOW NORMAL', 'YES', 'ಪ್ರಸ್ತುತ ಹಂತದಲ್ಲಿ ಬೆಳೆ ಉತ್ತಮವಾಗಿದ್ದರೆ, ಇತರೆ ಬೆಳೆ ಬೆಳೆದಿದ್ದಲ್ಲಿ ಅವುಗಳ ನಿರ್ವಹಣೆಯತ್ತ ಗಮನಹರಿಸುವುದು', NULL, 'If the crop is good at the current stage, focus on managing other crops if they have grown.', NULL, 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (6411, 'MANGO', NULL, N'1-4', N'October-November', N'October-November', N'10,11', N'Vegetative stage', N'2', 'BELOW NORMAL', 'NO', 'ಕೃಷಿ ಹೊಂಡ, ಇತರ ಮೂಲಗಳಲ್ಲಿ ಲಭ್ಯವಿರುವ ನೀರನ್ನು ಬಳಸಿ ಸಂರಕ್ಷಣಾ ನೀರಾವರಿ ಕೊಡುವುದು. ಗಿಡದ ಸುತ್ತಲು ಒಣಗಿದ ಎಲೆಗಳಿಂದ ಮಣ್ಣಿನ ಮೇಲೊದಿಕೆ ಮಾಡುವುದರಿಂದ ಮಣ್ಣಿನ ತೇವಾಂಶವನ್ನು ಕಾಪಾಡಿಕೊಳ್ಳಬಹುದು', 'ಹಿಟ್ಟು ತಿಗಣೆ ಕಂಡುಬಂದಲ್ಲಿ ಪ್ರತಿ ಲೀಟರ್ ನೀರಿಗೆ 1.25 ಮಿ.ಲೀ. ಬುಪ್ರೊಫೆಜಿನ್ 25% SC ಅಥವಾ 2 ಮಿಲೀ. ಪ್ರೊಫೆನೊಫಾಸ್ 50 EC + 5 ಗ್ರಾಂ ಮೀನಿನ ಎಣ್ಣೆ ರೋಸಿನ್ ಸೋಪ್ ಅಥವಾ 5% ಬೇವಿನ ಬೀಜ ಕಷಾಯವನ್ನು ಬೆರೆಸಿ ಸಿಂಪಡಿಸುವುದು', 'Conservation irrigation is done using water available from agricultural wells and other sources. Mulching the soil with dry leaves around the plant can help maintain soil moisture.', 'If mealybugs are found, spray 1.25 ml of Buprofezin 25% SC or 2 ml of Profenophos 50 EC + 5 gm fish oil rosin soap or 5% neem seed infusion per liter of water', 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (6412, 'MANGO', NULL, N'1-4', N'October-November', N'October-November', N'10,11', N'Vegetative stage', N'2', 'ABOVE NORMAL', 'YES', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', NULL, 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field.', NULL, 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (6413, 'MANGO', NULL, N'1-4', N'October-November', N'October-November', N'10,11', N'Vegetative stage', N'2', 'ABOVE NORMAL', 'NO', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', NULL, 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field.', NULL, 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (6414, 'MANGO', NULL, N'1-4', N'December-January', N'December-January', N'12,1', N'Vegetative stage', N'3', 'NORMAL', 'YES', 'ಸಸ್ಯದ ಬೆಳವಣಿಗೆಯನ್ನು ಉತ್ತೇಜಿಸಲು ಹೂ ಗೊಂಚಲು ಕಂಡಲ್ಲಿ ಅವುಗಳನ್ನು ತೆಗೆಯುವುದು', 'ಬೂದಿ ರೋಗ ಕಂಡುಬಂದಲ್ಲಿ ಪ್ರತಿ ಲೀಟರ್ ನೀರಿಗೆ 3.0 ಗ್ರಾಂ. ನೀರಿನಲ್ಲಿ ಕರಗುವ ಗಂಧಕದ ಪುಡಿ ಅಥವಾ 1.0 ಮಿ.ಲೀ. ಹೆಕ್ಸಕೋನೋಜೋಲ್ 5 EC ಅಥವಾ 0.15 ಮಿ.ಲೀ. ಫ್ಲುಕ್ಸಿಪೈರಾಕ್ಸಾಡ್+ಪೈರಾಕ್ಲೊಸ್ರೊಬಿನ್ (500 SC) ಅನ್ನು ಬೆರೆಸಿ ಸಿಂಪಡಿಸುವುದು. ಡೈಬ್ಯಾಕ್ ರೋಗ ಲಕ್ಷಣಗಳು ಕಂಡು ಬಂದರೆ ಶೇ. 0.3 ತಾಮ್ರದ ಆಕ್ಸಿಕ್ಲೋರೈಡ್ 50 WP ಯನ್ನು ಸಿಂಪಡಿಸುವುದು', 'Remove flower clusters if they appear to encourage plant growth.', 'If powdery mildew is found, spray 3.0 gm. Water soluble sulfur powder or 1.0 ml. Hexaconazole 5 EC or 0.15 ml. Fluxipyroxad + Pyraclosrobin (500 SC) mixed together per liter of water. If dieback symptoms are found, spray 0.3% copper oxychloride 50 WP', 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
