INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (6516, 'MANGO (LATE VARIETIES)', NULL, N'>4', N'November-December', N'November-December', N'11,12', N'Vegetative stage', N'2', 'NORMAL', 'YES', 'ಸೂಚಿಸಲಾದ ಸಸ್ಯ ಸಂರಕ್ಷಣಾ ಕ್ರಮಗಳನ್ನು ಕೈಗೊಳ್ಳುವುದು', 'ಜಿಗಿ ಹುಳು ಹಾಗೂ ಶಲ್ಕ ಕೀಟ ಕಂಡು ಬಂದಲ್ಲಿ ಲೀ. ನೀರಿಗೆ 0.3 ಮಿಲೀ. ಇಮೀಡಾಕ್ಲೋಪ್ರಿಡ್ 17.8 SL ಅಥವಾ 5% ಬೇವಿನ ಬೀಜದ ಕಷಾಯವನ್ನು ಬೆರೆಸಿ ಸಿಂಪರಿಸುವುದು', 'Carrying out the recommended plant protection measures', 'If leafhoppers and scale insects are found, spray with 0.3 ml of Imidacloprid 17.8 SL per liter of water or 5% neem seed extract', 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (6517, 'MANGO (LATE VARIETIES)', NULL, N'>4', N'November-December', N'November-December', N'11,12', N'Vegetative stage', N'2', 'NORMAL', 'NO', 'ಸೂಚಿಸಲಾದ ಸಸ್ಯ ಸಂರಕ್ಷಣಾ ಕ್ರಮಗಳನ್ನು ಕೈಗೊಳ್ಳುವುದು', 'ಜಿಗಿ ಹುಳು ಹಾಗೂ ಶಲ್ಕ ಕೀಟ ಕಂಡು ಬಂದಲ್ಲಿ ಲೀ. ನೀರಿಗೆ 0.3 ಮಿಲೀ. ಇಮೀಡಾಕ್ಲೋಪ್ರಿಡ್ 17.8 SL ಅಥವಾ 5% ಬೇವಿನ ಬೀಜದ ಕಷಾಯವನ್ನು ಬೆರೆಸಿ ಸಿಂಪರಿಸುವುದು', 'Carrying out the recommended plant protection measures', 'If leafhoppers and scale insects are found, spray with 0.3 ml of Imidacloprid 17.8 SL per liter of water or 5% neem seed extract', 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (6518, 'MANGO (LATE VARIETIES)', NULL, N'>4', N'November-December', N'November-December', N'11,12', N'Vegetative stage', N'2', 'BELOW NORMAL', 'YES', 'ಪ್ರಸ್ತುತ ಹಂತದಲ್ಲಿ ಬೆಳೆ ಉತ್ತಮವಾಗಿದ್ದರೆ, ಇತರೆ ಬೆಳೆ ಬೆಳೆದಿದ್ದಲ್ಲಿ ಅವುಗಳ ನಿರ್ವಹಣೆಯತ್ತ ಗಮನಹರಿಸುವುದು', NULL, 'If the crop is good at the current stage, focus on managing other crops if they have grown.', NULL, 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (6526, 'MANGO (LATE VARIETIES)', NULL, N'>4', N'January-March', N'January-February-March', N'1,2,3', N'Flowering stage', N'3', 'ABOVE NORMAL', 'YES', 'ಮಳೆ ಇಲ್ಲದ ಸಂದರ್ಭ ನೋಡಿಕೊಂಡು ಕಾಯಿ ಉದುರುವುದನ್ನು ತಡೆಯಲು 10 ಮಿ.ಗ್ರಾಂ 2,4ಡಿ ಅನ್ನು 1 ಲೀ. ನೀರಿನಲ್ಲಿ ಬೆರೆಸಿ ಸಿಂಪಡಿಸುವುದು. 1 ರಿಂದ 4 ವರ್ಷ ಗಿಡಗಳಿಗೆ ಕೃಷಿ ಹೊಂಡ, ಇತರ ಮೂಲಗಳಲ್ಲಿ ಲಭ್ಯವಿರುವ ನೀರನ್ನು ಬಳಸಿ ಸಂರಕ್ಷಣಾ ನೀರಾವರಿ ಕೊಡುವುದು. ಗಿಡದ ಸುತ್ತಲು ಒಣಗಿದ ಎಲೆಗಳಿಂದ ಮಣ್ಣಿನ ಮೇಲೊದಿಕೆ ಮಾಡುವುದರಿಂದ ಮಣ್ಣಿನ ತೇವಾಂಶವನ್ನು ಕಾಪಾಡಿಕೊಳ್ಳಬಹುದು', NULL, 'To prevent fruit drop, spray 10 mg 2,4D mixed in 1 liter of water during dry spells. For 1 to 4 year old plants, provide conservation irrigation using water available from agricultural pits and other sources. Mulching the soil around the plant with dry leaves can help maintain soil moisture.', NULL, 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (6527, 'MANGO (LATE VARIETIES)', NULL, N'>4', N'January-March', N'January-February-March', N'1,2,3', N'Flowering stage', N'3', 'ABOVE NORMAL', 'NO', 'ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ತೋಟದಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದು ಕೃಷಿ ಹೊಂಡಗಳಲ್ಲಿ ಶೇಖರಿಸಲು ಅನುವುಮಾಡಿಕೊಡಿ', 'ಮಾವಿನಲ್ಲಿ ಜಿಗಿಹುಳು, ಬೂದಿರೋಗ ಹಾಗೂ ಚಿಬ್ಬು ರೋಗದಿಂದ ಎಳೆಯ ಕಾಯಿಗಳು ಹಳದಿಯಾಗಿ ಉದುರುವುದನ್ನು ಅಥವಾ ಕಾಯಿ ಉದುರವುದು ಕಂಡು ಬಂದಲ್ಲಿ, ಇವುಗಳ ಹತೋಟಿಗೆ, ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ 0.5 ಮಿ.ಲೀ. ಸಂಯುಕ್ತ ಕೀಟನಾಶಕ ಥೈಯಾಮಿಥೋಕ್ಸಾಮ್ 12.6% + ಲ್ಯಾಮ್ಡಾ ಸೈಹ್ಯಾಲೋತ್ರಿನ 9.5 % ZC + 1 ಗ್ರಾಂ ಸಂಯುಕ್ತ ಶಿಲೀಂದ್ರನಾಶಕ ಟೆಬೂಕೋನಾಜೊಲ್ 50% + ಟ್ರೈಫ್ಲಾಕ್ಸಿಸ್ಟ್ರೋಬಿನ್ 25% WG + 0.5 ಮಿ.ಲೀ. ಪ್ಲಾನೋಫಿಕ್ಸ (NAA) ಅನ್ನು ಬೆರೆಸಿ ಗಿಡದ ಪ್ರತಿ ಭಾಗವು ಚನ್ನಾಗಿ ತೊಯ್ಯುವಹಾಗೆ ಸಿಂಪಡಿಸುವುದು', 'If there is heavy rainfall, allow water to drain from the garden and store in agricultural pits.', 'If young fruits are yellowing or falling off due to leafhopper, powdery mildew and leaf spot in mango, for their control, mix 0.5 ml of compound insecticide Thiamethoxam 12.6% + Lambda Cyhalothrin 9.5 % ZC + 1 gm compound fungicide Tebuconazole 50% + Trifloxystrobin 25% WG + 0.5 ml of Planofix (NAA) per liter of water and spray it thoroughly so that every part of the plant is thoroughly wetted', 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (6528, 'MANGO (LATE VARIETIES)', NULL, N'>4', N'April-May', N'April-May', N'4,5', N'Fruit development stage', N'4', 'NORMAL', 'YES', 'ಸೂಚಿಸಲಾದ ಸಸ್ಯ ಸಂರಕ್ಷಣಾ ಕ್ರಮಗಳನ್ನು ಕೈಗೊಳ್ಳುವುದು', 'ಡೈಬ್ಯಾಕ್ ರೋಗ ಲಕ್ಷಣಗಳು ಕಂಡು ಬಂದರೆ ಶೇ. 0.3 ತಾಮ್ರದ ಆಕ್ಸಿಕ್ಲೋರೈಡ್ 50 WPಯನ್ನು ಸಿಂಪಡಿಸುವುದು', 'Carrying out the recommended plant protection measures', 'Spray 0.3% copper oxychloride 50 WP if symptoms of dieback are observed', 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (6529, 'MANGO (LATE VARIETIES)', NULL, N'>4', N'April-May', N'April-May', N'4,5', N'Fruit development stage', N'4', 'NORMAL', 'NO', 'ಸೂಚಿಸಲಾದ ಸಸ್ಯ ಸಂರಕ್ಷಣಾ ಕ್ರಮಗಳನ್ನು ಕೈಗೊಳ್ಳುವುದು', 'ಡೈಬ್ಯಾಕ್ ರೋಗ ಲಕ್ಷಣಗಳು ಕಂಡು ಬಂದರೆ ಶೇ. 0.3 ತಾಮ್ರದ ಆಕ್ಸಿಕ್ಲೋರೈಡ್ 50 WPಯನ್ನು ಸಿಂಪಡಿಸುವುದು', 'Carrying out the recommended plant protection measures', 'Spray 0.3% copper oxychloride 50 WP if symptoms of dieback are observed', 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
