INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (6552, 'GRAPES', 30, N'<1', N'February-March', N'March', N'3', N'Vegetative stage', N'1', 'ABOVE NORMAL', 'NO', '• ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ
• ದುರ್ಬಲ ಕೊಂಬೆಗಳನ್ನು ತೆಗೆದು ಮುಖ್ಯ ಕೊಂಬೆಗಳನ್ನು ಉಳಿಸಿಕೊಳ್ಳುವುದು', NULL, '• If there has been heavy rainfall in the past few days, allow the water to drain away from the field. • Remove weak branches and keep the main branches.', NULL, 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (6553, 'GRAPES', 30, N'<1', N'April-May', N'April-May', N'4,5', N'Vegetative stage', N'1', 'NORMAL', 'YES', 'ಗಿಡದ ಮುಖ್ಯ ಕಾಂಡವನ್ನು ಚಪ್ಪರದ ಕಂಚಕ್ಕೆ ಕಟ್ಟಿ ಬಳ್ಳಿ ಮೇಲಕ್ಕೆ ಹಬ್ಬುವಂತೆ ಮಾಡುವುದು', NULL, 'Tying the main stem of the plant to a flat surface and allowing the vine to spread upwards', NULL, 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
