INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (6555, 'GRAPES', 30, N'<1', N'April-May', N'April-May', N'4,5', N'Vegetative stage', N'1', 'BELOW NORMAL', 'YES', 'ಗಿಡದ ಮುಖ್ಯ ಕಾಂಡವನ್ನು ಚಪ್ಪರದ ಕಂಚಕ್ಕೆ ಕಟ್ಟಿ ಬಳ್ಳಿ ಮೇಲಕ್ಕೆ ಹಬ್ಬುವಂತೆ ಮಾಡುವುದು', NULL, 'Tying the main stem of the plant to a flat surface and allowing the vine to spread upwards', NULL, 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (6556, 'GRAPES', 30, N'<1', N'April-May', N'April-May', N'4,5', N'Vegetative stage', N'1', 'BELOW NORMAL', 'NO', '• ಗಿಡದ ಮುಖ್ಯ ಕಾಂಡವನ್ನು ಚಪ್ಪರದ ಕಂಚಕ್ಕೆ ಕಟ್ಟಿ ಬಳ್ಳಿ ಮೇಲಕ್ಕೆ ಹಬ್ಬುವಂತೆ ಮಾಡುವುದು
• ಕೃಷಿ ಹೊಂಡ, ಇತರ ಮೂಲಗಳಲ್ಲಿ ಲಭ್ಯವಿರುವ ನೀರನ್ನು ಬಳಸಿ ಸಂರಕ್ಷಣಾ ನೀರಾವರಿ ಕೊಡುವುದು. ಗಿಡದ ಸುತ್ತಲು ಒಣಗಿದ ಎಲೆಗಳಿಂದ ಮಣ್ಣಿನ ಮೇಲೊದಿಕೆ ಮಾಡುವುದರಿಂದ ಮಣ್ಣಿನ ತೇವಾಂಶವನ್ನು ಕಾಪಾಡಿಕೊಳ್ಳಬಹುದು', 'ಹಿಟ್ಟಿನ ತಿಗಣೆ ಮತ್ತು ಥ್ರಿಪ್ಸ್ ನುಶಿ ಕಂಡುಬಂದಲ್ಲಿ ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ 0.5 ಗ್ರಾಂ ಥೈಯೋಮಿಥಾಕ್ಸಾಮ್ 25 WP ಅಥವಾ 0.25 ಗ್ರಾಂ ಅಸಿಟಮಾಪ್ರಿಡ್ 75 SP ಅಥವಾ 1.0 ಮಿ.ಲೀ. ಬುಪ್ರೋಫೆಜಿನ್ 25 SC ಅಥವಾ 2 ಮಿ.ಲೀ. ಪ್ರೋಫೆನೊಪಾಸ್ 50 SP ಅನ್ನು ಬೆರೆಸಿ ಸಿಂಪಡಿಸುವುದು', '• Tie the main stem of the plant to the ground and allow the vine to spread upwards
• Provide conservation irrigation using water available from agricultural wells and other sources. Mulching the soil around the plant with dry leaves can help maintain soil moisture.', 'If mealybugs and thrips are found, spray 0.5 g Thiomethoxam 25 WP or 0.25 g Acetamaprid 75 SP or 1.0 ml Buprofezin 25 SC or 2 ml Profenopas 50 SP per liter of water', 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (6557, 'GRAPES', 30, N'<1', N'April-May', N'April-May', N'4,5', N'Vegetative stage', N'1', 'ABOVE NORMAL', 'YES', '• ಗಿಡದ ಮುಖ್ಯ ಕಾಂಡವನ್ನು ಚಪ್ಪರದ ಕಂಚಕ್ಕೆ ಕಟ್ಟಿ ಬಳ್ಳಿ ಮೇಲಕ್ಕೆ ಹಬ್ಬುವಂತೆ ಮಾಡುವುದು
• ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', NULL, '• Tie the main stem of the plant to the ground and allow the vine to spread upwards. • If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field.', NULL, 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (6558, 'GRAPES', 30, N'<1', N'April-May', N'April-May', N'4,5', N'Vegetative stage', N'1', 'ABOVE NORMAL', 'NO', '• ಗಿಡದ ಮುಖ್ಯ ಕಾಂಡವನ್ನು ಚಪ್ಪರದ ಕಂಚಕ್ಕೆ ಕಟ್ಟಿ ಬಳ್ಳಿ ಮೇಲಕ್ಕೆ ಹಬ್ಬುವಂತೆ ಮಾಡುವುದು
• ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', NULL, '• Tie the main stem of the plant to the ground and allow the vine to spread upwards. • If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field.', NULL, 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (6565, 'GRAPES', 30, N'<1', N'August', N'August', N'8,9,10', N'Vegetative stage', N'1', 'NORMAL', 'YES', '• ಬಳ್ಳಿಯನ್ನು ಚಪ್ಪರಕ್ಕೆ ಹಬ್ಬಿಸುವುದು
• ತೋಟದಲ್ಲಿ ಹಸಿರೆಲೆ ಗೊಬ್ಬರದ ಗಿಡಗಳನ್ನು ಬೆಳೆದಿದ್ದರೆ ಅವನ್ನು ಬಿತ್ತಿದ 45 ದಿನಗಳ ನಂತರ ಮಣ್ಣಿಗೆ ಸೇರಿಸುವುದು
• ತೋಟದ ಮಧ್ಯ ಅಂತರಬೆಳೆ ಬೆಳೆದಿದ್ದರೆ ಅವುಗಳಿಗೆ ತಗುಲುವ ರೋಗ ಮತ್ತು ಕೀಟಗಳ ಮೇಲೆ ಗಮನ ಹರಿಸುವುದು', NULL, '• Spreading the vine over the flat ground
• If green manure plants are grown in the garden, incorporate them into the soil 45 days after sowing
• If intercropping is grown in the garden, pay attention to the diseases and pests that affect them', NULL, 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
