INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (6532, 'MANGO (LATE VARIETIES)', NULL, N'>4', N'April-May', N'April-May', N'4,5', N'Fruit development stage', N'4', 'ABOVE NORMAL', 'YES', 'ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ತೋಟದಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದು ಕೃಷಿ ಹೊಂಡಗಳಲ್ಲಿ ಶೇಖರಿಸಲು ಅನುವುಮಾಡಿಕೊಡಿ', 'ಮಾವಿನಲ್ಲಿ ಜಿಗಿಹುಳು, ಬೂದಿರೋಗ ಹಾಗೂ ಚಿಬ್ಬು ರೋಗದಿಂದ ಎಳೆಯ ಕಾಯಿಗಳು ಹಳದಿಯಾಗಿ ಉದುರುವುದನ್ನು ಅಥವಾ ಕಾಯಿ ಉದುರವುದು ಕಂಡು ಬಂದಲ್ಲಿ, ಇವುಗಳ ಹತೋಟಿಗೆ, ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ 0.5 ಮಿ.ಲೀ. ಸಂಯುಕ್ತ ಕೀಟನಾಶಕ ಥೈಯಾಮಿಥೋಕ್ಸಾಮ್ 12.6% + ಲ್ಯಾಮ್ಡಾ ಸೈಹ್ಯಾಲೋತ್ರಿನ 9.5 % ZC + 1 ಗ್ರಾಂ ಸಂಯುಕ್ತ ಶಿಲೀಂದ್ರನಾಶಕ ಟೆಬೂಕೋನಾಜೊಲ್ 50% + ಟ್ರೈಫ್ಲಾಕ್ಸಿಸ್ಟ್ರೋಬಿನ್ 25% WG + 0.5 ಮಿ.ಲೀ. ಪ್ಲಾನೋಫಿಕ್ಸ (NAA) ಅನ್ನು ಬೆರೆಸಿ ಗಿಡದ ಪ್ರತಿ ಭಾಗವು ಚನ್ನಾಗಿ ತೊಯ್ಯುವಹಾಗೆ ಸಿಂಪಡಿಸುವುದು', 'If there is heavy rainfall, allow water to drain from the garden and store in agricultural pits.', 'If young fruits are yellowing or falling off due to leafhopper, powdery mildew and leaf spot in mango, for their control, mix 0.5 ml of compound insecticide Thiamethoxam 12.6% + Lambda Cyhalothrin 9.5 % ZC + 1 gm compound fungicide Tebuconazole 50% + Trifloxystrobin 25% WG + 0.5 ml of Planofix (NAA) per liter of water and spray it thoroughly so that every part of the plant is thoroughly wetted', 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (6533, 'MANGO (LATE VARIETIES)', NULL, N'>4', N'April-May', N'April-May', N'4,5', N'Fruit development stage', N'4', 'ABOVE NORMAL', 'NO', 'ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ತೋಟದಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದು ಕೃಷಿ ಹೊಂಡಗಳಲ್ಲಿ ಶೇಖರಿಸಲು ಅನುವುಮಾಡಿಕೊಡಿ', NULL, 'If there is heavy rainfall, allow water to drain from the garden and store in agricultural pits.', NULL, 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (6534, 'MANGO (LATE VARIETIES)', NULL, N'>4', N'June-July', N'June-July', N'6,7', N'Fruit maturity stage', N'5', 'NORMAL', 'YES', 'ಸೂಚಿಸಲಾದ ಸಸ್ಯ ಸಂರಕ್ಷಣಾ ಕ್ರಮಗಳನ್ನು ಕೈಗೊಳ್ಳುವುದು', 'ದುಂಡಾಣು ಎಲೆ ಚುಕ್ಕೆ ರೋಗ ಕಂಡು ಬಂದರೆ ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ 3.0 ಗ್ರಾಂ ತಾಮ್ರದ ಆಕ್ಸಿಕ್ಲೋರೈಡ್ 50 WP ಜೊತೆಗೆ 0.5 ಗ್ರಾಂ ಸ್ರೆಫ್ಟೋಸೈಕ್ಲಿನ್ ಸೇರಿಸಿ ಸಿಂಪಡಿಸುವುದು', 'Carrying out the recommended plant protection measures', 'If roundworm leaf spot is detected, spray 3.0 g of copper oxychloride 50 WP per liter of water along with 0.5 g of streptocyline', 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (6535, 'MANGO (LATE VARIETIES)', NULL, N'>4', N'June-July', N'June-July', N'6,7', N'Fruit maturity stage', N'5', 'NORMAL', 'NO', 'ಸೂಚಿಸಲಾದ ಸಸ್ಯ ಸಂರಕ್ಷಣಾ ಕ್ರಮಗಳನ್ನು ಕೈಗೊಳ್ಳುವುದು', 'ದುಂಡಾಣು ಎಲೆ ಚುಕ್ಕೆ ರೋಗ ಕಂಡು ಬಂದರೆ ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ 3.0 ಗ್ರಾಂ ತಾಮ್ರದ ಆಕ್ಸಿಕ್ಲೋರೈಡ್ 50 WP ಜೊತೆಗೆ 0.5 ಗ್ರಾಂ ಸ್ರೆಫ್ಟೋಸೈಕ್ಲಿನ್ ಸೇರಿಸಿ ಸಿಂಪಡಿಸುವುದು', 'Carrying out the recommended plant protection measures', 'If roundworm leaf spot is detected, spray 3.0 g of copper oxychloride 50 WP per liter of water along with 0.5 g of streptocyline', 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (6536, 'MANGO (LATE VARIETIES)', NULL, N'>4', N'June-July', N'June-July', N'6,7', N'Fruit maturity stage', N'5', 'BELOW NORMAL', 'YES', 'ಪ್ರಸ್ತುತ ಹಂತದಲ್ಲಿ ಬೆಳೆ ಉತ್ತಮವಾಗಿದ್ದರೆ, ಇತರೆ ಬೆಳೆ ಬೆಳೆದಿದ್ದಲ್ಲಿ ಅವುಗಳ ನಿರ್ವಹಣೆಯತ್ತ ಗಮನಹರಿಸುವುದು', NULL, 'If the crop is good at the current stage, focus on managing other crops if they have grown.', NULL, 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (6537, 'MANGO (LATE VARIETIES)', NULL, N'>4', N'June-July', N'June-July', N'6,7', N'Fruit maturity stage', N'5', 'BELOW NORMAL', 'NO', 'ಗಿಡದ ಸುತ್ತಲು ಒಣಗಿದ ಎಲೆಗಳಿಂದ ಮಣ್ಣಿನ ಮೇಲೊದಿಕೆ ಮಾಡುವುದರಿಂದ ಮಣ್ಣಿನ ತೇವಾಂಶವನ್ನು ಕಾಪಾಡಿಕೊಳ್ಳಬಹುದು', 'ಒಟೆ ಕೊರಕ ಕಂಡು ಬಂದಲ್ಲಿ ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ 1.0 ಮಿ.ಲೀ. ಡೆಲ್ಟಾಮೆಥ್ರಿನ್ 2.8 EC ಅಥವಾ 1.0 ಗ್ರಾಂ ಅಸಿಫೇಟ್ 75 SP ಅಥವಾ 2.0 ಮಿ.ಲೀ. ಡೈಮಿಥೋಯೇಟ್ 30 EC. ಅನ್ನು ಮಾರ್ಚ್ ತಿಂಗಳ ಎರಡನೇ ವಾರದಲ್ಲಿ ಸಿಂಪರಣೆ ಮಾಡುವುದು. ಈ ಸಿಂಪರಣೆಯನ್ನು ಮೂರು ವಾರಗಳ ನಂತರ ಪುನರಾರ್ತಿಸುವುದು ಉತ್ತಮ. ಮಸಿ ರೋಗಕ್ಕೆ ಕಂಡುಬಂದಲ್ಲಿ ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ 3.0 ಗ್ರಾಂ. ನೀರಿನಲ್ಲಿ ಕರಗುವ ಗಂಧಕವನ್ನು ಬೆರೆಸಿ ಸಿಂಪಡಿಸುವುದು', 'Mulching the soil with dry leaves around the plant can help maintain soil moisture.', 'If Ote borer is found, spray 1.0 ml. Deltamethrin 2.8 EC or 1.0 gm Acephate 75 SP or 2.0 ml. Dimethoate 30 EC per liter of water in the second week of March. It is better to repeat this spray after three weeks. If Ote borer is found, spray 3.0 gm. Water soluble sulphur mixed with water per liter of water', 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (6538, 'MANGO (LATE VARIETIES)', NULL, N'>4', N'June-July', N'June-July', N'6,7', N'Fruit maturity stage', N'5', 'ABOVE NORMAL', 'YES', 'ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ತೋಟದಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದು ಕೃಷಿ ಹೊಂಡಗಳಲ್ಲಿ ಶೇಖರಿಸಲು ಅನುವುಮಾಡಿಕೊಡಿ', 'ಹಣ್ಣಿನ ನೋಣ ಕಂಡು ಬಂದಲ್ಲಿ ಪ್ರತಿ ಹೆಕ್ಟೇರ್ ಗೆ 10 ಮೋಹಕ ಬಲೆಗಳನ್ನುತೂಗು ಹಾಕುವುದು ಅಥವಾ 1.7 ಮಿ.ಲೀ ಡೈಮಿಥೋಯೇಟ್ 30 EC ಅನ್ನು 10 ಗ್ರಾಂ ಬೆಲ್ಲದೊಂದಿಗೆ ಕರಗಿಸಿ ಹಣ್ಣು ಮಾಗುವ ಅವಧಿಯಲ್ಲಿ ಸಿಂಪರಣೆ ಮಾಡುವುದು ಹಾಗೂ ಹಣ್ಣುಗಳು ನಿಂಬೆಹಣ್ಣಿನ ಗಾತ್ರದಲ್ಲಿದ್ದಾಗ 1 ಮಿ.ಲೀ. ಡೆಲ್ಟಾಮೆಥ್ರಿನ್ 2.8 EC ಅನ್ನು ಸಿಂಪರಣೆ ಮಾಡುವುದು. ಕೊಯ್ಲಾದ ನಂತರ 1 ಅಡಿ ಆಳದ ಟ್ರೆಂಚ್‌ಗಳನ್ನು ಕಾಂಡದ 2.5 ರಿಂದ 3 ಮೀ. ದೂರದಲ್ಲಿ ಇಳಜಾರಿಗೆ ಅಡ್ಡಲಾಗಿ ನಿರ್ಮಿಸುವುದು ಉತ್ತಮ', 'If there is heavy rainfall, allow water to drain from the garden and store in agricultural pits.', 'If fruit borer is found, hang 10 bait traps per hectare or spray 1.7 ml Dimethoate 30 EC dissolved in 10 g jaggery during the fruit ripening period and spray 1 ml Deltamethrin 2.8 EC when the fruits are the size of lemons. After harvesting, it is better to make 1 ft deep trenches at a distance of 2.5 to 3 m from the stem, across the ridge', 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (6539, 'MANGO (LATE VARIETIES)', NULL, N'>4', N'June-July', N'June-July', N'6,7', N'Fruit maturity stage', N'5', 'ABOVE NORMAL', 'NO', 'ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ತೋಟದಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದು ಕೃಷಿ ಹೊಂಡಗಳಲ್ಲಿ ಶೇಖರಿಸಲು ಅನುವುಮಾಡಿಕೊಡಿ', NULL, 'If there is heavy rainfall, allow water to drain from the garden and store in agricultural pits.', NULL, 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (6540, 'GRAPES', 30, N'<1', N'September', N'September', N'9', N'Preparation', N'0', 'NIL', 'NIL', 'ಪೂರ್ವಸಿದ್ದತೆ: ನಾಟಿ ಮಾಡುವ 15 ದಿವಸ ಮುಂಚಿತವಾಗಿ 1.8 ಮೀ x 1.8 ಮೀ. ಅಂತರದಲ್ಲಿ 3x3x3 ಅಡಿ ಅಳತೆಯ ಗುಣಿಗಳನ್ನು ತಗೆಯುವುದು. ಗುಣಿಗಳಿಗೆ ಹಸಿರೆಲೆ ಗೊಬ್ಬರ ಮತ್ತು ಮೇಲ್ಮಣ್ಣು ಜೊತೆಗೆ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ಕೊಟ್ಟಿಗೆ ಗೊಬ್ಬರವನ್ನು ಹಾಕುವುದು
• ಚಪ್ಪರ ವಿಧಾನದಲ್ಲಿ ಬಳ್ಳಿಯನ್ನು ಹಬ್ಬಿಸುವುದರ ಮೂಲಕ ಅಧಿಕ ಇಳುವರಿ ಪಡೆಯಬಹುದಾಗಿದೆ. ಅದಕ್ಕಾಗಿ ಸಿದ್ಧತೆಪಡಿಸಿಕೊಳ್ಳಿ', NULL, 'Preparation: Dig 15 days before planting, 1.8 m x 1.8 m. 3x3x3 feet of trenches. Apply green manure and topsoil to the trenches along with recommended manure. • High yield can be obtained by spreading the vine in the flat method. Prepare for it', NULL, 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (6541, 'GRAPES', 30, N'<1', N'October-January', N'October-November-December-January', N'10,11,12,1', N'Planting', N'1', 'NORMAL', 'YES', '• ಉತ್ತಮವಾಗಿ ಬೇರು ಬಿಟ್ಟ ಮೂರು ಕಣ್ಣುಳ್ಳ ಕಡ್ಡಿಗಳನ್ನು ನಾಟಿ ಮಾಡುವುದು 
• ನಾಟಿಯ ನಂತರ LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ರಸಗೊಬ್ಬರವನ್ನು ಒದಗಿಸುವುದು', 'ಹಿಟ್ಟಿನ ತಿಗಣೆ ಮತ್ತು ಥ್ರಿಪ್ಸ್ ನುಶಿ ಕಂಡುಬಂದಲ್ಲಿ ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ 0.5 ಗ್ರಾಂ ಥೈಯೋಮಿಥಾಕ್ಸಾಮ್ 25 WG ಅಥವಾ 0.25 ಗ್ರಾಂ ಅಸಿಟಮಾಪ್ರಿಡ್ 75 SP ಅಥವಾ 1.0 ಮಿ.ಲೀ. ಬುಪ್ರೋಫೆಜಿನ್ 25 SC ಅಥವಾ 2 ಮಿ.ಲೀ. ಪ್ರೋಫೆನೊಪಾಸ್ 50 SP ಅನ್ನು ಬೆರೆಸಿ ಸಿಂಪಡಿಸುವುದು', '• Planting well-rooted three-eyed cuttings 
• Providing recommended fertilizer based on LRI after planting', 'If mealybugs and thrips are found, spray with 0.5 g Thiomethoxam 25 WG or 0.25 g Acetamaprid 75 SP or 1.0 ml Buprofezin 25 SC or 2 ml Profenopas 50 SP per liter of water', 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
