INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (6586, 'GRAPES', 30, N'1-3', N'November-December', N'November-December', N'11,12', N'Vegetative stage', N'1', 'BELOW NORMAL', 'NO', '• ಬಳ್ಳಿಯಲ್ಲಿನ ಅನಗತ್ಯ ಕೊಂಬೆಗಳನ್ನು ಕತ್ತರಿಸಿ ತೆಗೆದುಹಾಕಿ ಮುಖ್ಯ ಕೊಂಬೆಗಳನ್ನು ಮಾತ್ರ ಚಪ್ಪರಕ್ಕೆ ಹಬ್ಬಿಸುವುದರ ಮೂಲಕ ಬಳ್ಳಿಗಳಿಗೆ ನಿಖರ ಆಕಾರದಲ್ಲಿ ಬೆಳೆಯುವಂತೆ ಮಾಡುವುದು (ಬಳ್ಳಿ ಹಬ್ಬಿಸುವುದು ಮತ್ತು ಕತ್ತರಿಸುವುದರ ಹೆಚ್ಚಿನ ಮಾಹಿತಿಗಾಗಿ ತಂತ್ರಾಂಶದಲ್ಲಿರುವ ಈ ಬೆಳೆಯ ಬೇಸಾಯ ಪದ್ದತಿಯನ್ನು ಅನುಸರಿಸಿ)
• ಕೃಷಿ ಹೊಂಡ, ಇತರ ಮೂಲಗಳಲ್ಲಿ ಲಭ್ಯವಿರುವ ನೀರನ್ನು ಬಳಸಿ ಸಂರಕ್ಷಣಾ ನೀರಾವರಿ ಕೊಡುವುದು. ಗಿಡದ ಸುತ್ತಲು ಒಣಗಿದ ಎಲೆಗಳಿಂದ ಮಣ್ಣಿನ ಮೇಲೊದಿಕೆ ಮಾಡುವುದರಿಂದ ಮಣ್ಣಿನ ತೇವಾಂಶವನ್ನು ಕಾಪಾಡಿಕೊಳ್ಳಬಹುದು', NULL, '• Prune the vines to get the right shape by pruning and spreading only the main branches (for more information on pruning and pruning, follow the crop cultivation method in the software)
• Provide conservation irrigation using water available from agricultural wells and other sources. Mulching the soil around the plant with dry leaves can help maintain soil moisture.', NULL, 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (6587, 'GRAPES', 30, N'1-3', N'November-December', N'November-December', N'11,12', N'Vegetative stage', N'1', 'ABOVE NORMAL', 'YES', '• ಬಳ್ಳಿಯಲ್ಲಿನ ಅನಗತ್ಯ ಕೊಂಬೆಗಳನ್ನು ಕತ್ತರಿಸಿ ತೆಗೆದುಹಾಕಿ ಮುಖ್ಯ ಕೊಂಬೆಗಳನ್ನು ಮಾತ್ರ ಚಪ್ಪರಕ್ಕೆ ಹಬ್ಬಿಸುವುದರ ಮೂಲಕ ಬಳ್ಳಿಗಳಿಗೆ ನಿಖರ ಆಕಾರದಲ್ಲಿ ಬೆಳೆಯುವಂತೆ ಮಾಡುವುದು (ಬಳ್ಳಿ ಹಬ್ಬಿಸುವುದು ಮತ್ತು ಕತ್ತರಿಸುವುದರ ಹೆಚ್ಚಿನ ಮಾಹಿತಿಗಾಗಿ ತಂತ್ರಾಂಶದಲ್ಲಿರುವ ಈ ಬೆಳೆಯ ಬೇಸಾಯ ಪದ್ದತಿಯನ್ನು ಅನುಸರಿಸಿ)
• ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', NULL, '• Trim away unwanted branches from the vine and spread only the main branches to the ground to help the vines grow in the correct shape (for more information on spreading and pruning, follow the crop cultivation method in the software)
• If there has been heavy rainfall in the past few days, allow the water to drain away from the field', NULL, 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
