INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (6618, 'GRAPES', 30, N'>3', N'August-October', N'August-September-October', N'8,9,10', N'Vegetative stage', N'4', 'ABOVE NORMAL', 'NO', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', NULL, 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field.', NULL, 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (6619, 'GRAPES', 30, N'>3', N'November-December', N'November-December', N'11,12', N'Flowering', N'5', 'NORMAL', 'YES', 'ಪೂರ್ತಿ ಹೂ ಅರಳಿದ ಹಂತದಲ್ಲಿ ಗೊಂಚಲುಗಳನ್ನು 20 ಮಿ. ಗ್ರಾಂ. ಜಿಬ್ಬರ್ಲಿಕ್ ಆಮ್ಲ 1 ಲೀಟರ್ ನೀರಿನಲ್ಲಿ ಬೆರೆಸಿ ಅದ್ದುವುದರಿಂದ ಗೊಂಚಲಿನಲ್ಲಿ ಹಣ್ಣು ಒತ್ತಾಗಿರುವುದು ಕಡಿಮೆಯಾಗುವುದು. ಸಣ್ಣ ರಂಧ್ರಗಳನ್ನು ಕೊರೆಯುವ ದುಂಬಿ ಕಂಡಲ್ಲಿ ಲೀ. ನೀರಿಗೆ ಡೈಕ್ಲೋರೋವಾಸ್ 76 ಇಸಿ. ಸೇರಿಸಿ ಸಿಂಪಡಿಸುವುದು', 'ಚಿಕ್ಕಟಿ ದುಂಬಿ, ಕಡಜಗಳು ಮತ್ತು ಎಲೆ ತಿನ್ನುವ ಕೀಟ ಕಂಡುಬಂದರೆ ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ 1.0 ಮಿ.ಲೀ. ಸೈಯಾಂಟ್ರನಿಲಿಪ್ರೋಲ್ 10.25 OD ಅಥವಾ 0.5 ಮಿ.ಲೀ. ಲಾಮ್ಡಾ ಸೈಲೋಥ್ರೀನ್ 4.9 CS ಅಥವಾ 2 ಮಿ.ಲೀ. ಕ್ವಿನಾಲ್‌ಫಾಸ್ 25 EC ಅನ್ನು ಸೇರಿಸಿ ಸಿಂಪಡಿಸುವುದು. ಕೇದಿಗೆ ರೋಗ ಕಂಡುಬಂದಲ್ಲಿ ಲೀ. ನೀರಿಗೆ 3.0 ಗ್ರಾಂ ತಾಮ್ರದ ಆಕ್ಸಿಕ್ಲೋರೈಡ್ 50 WP ಅಥವಾ 2 ಗ್ರಾಂ ಮೆಟಲಾಕ್ಸಿಲ್ MZ 72 WP ಅಥವಾ 1 ಮಿ.ಲೀ. ಅಜಾಕ್ಸಿಸ್ಟ್ರೊಬಿನ್ 23 SC ಸೇರಿಸಿ ಸಿಂಪಡಿಸುವುದು', 'At the stage of full bloom, the bunches are dipped in 20 mg. g. Gibberellic acid mixed in 1 liter of water to reduce the density of fruit in the bunch. If small holes are found, spray with dichlorvos 76 EC in 1 liter of water.', 'If small beetles, aphids and leaf-eating insects are found, spray 1.0 ml. Cyanthraniliprol 10.25 OD or 0.5 ml. Lambda Cylothrin 4.9 CS or 2 ml. Quinalphos 25 EC per liter of water. If disease is found in the field, spray 3.0 g. Copper Oxychloride 50 WP or 2 g. Metalaxyl MZ 72 WP or 1 ml. Azoxystrobin 23 SC per liter of water', 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
