INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (6624, 'GRAPES', 30, N'>3', N'November-December', N'November-December', N'11,12', N'Flowering', N'5', 'ABOVE NORMAL', 'NO', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', NULL, 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field.', NULL, 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (6625, 'GRAPES', 30, N'>3', N'January-February', N'January-February', N'1,2', N'Fruit set and development', N'6', 'NORMAL', 'YES', 'ಕಾಯಿ ಕಚ್ಚುವ ಹಂತದಲ್ಲಿ ಗೊಂಚಲುಗಳನ್ನು 50 ಮಿ. ಗ್ರಾಂ. ಜಿಬ್ಬರ್ಲಿಕ್ ಆಮ್ಲ 1 ಲೀಟರ್ ನೀರಿನಲ್ಲಿ ಬೆರೆಸಿ ಅದ್ದುವುದರಿಂದ ಹಣ್ಣುಗಳ ಗಾತ್ರ ದ್ವಿಗುಣಗೊಳ್ಳುವುದು', 'ಬೂದಿ ರೋಗ ಕಂಡುಬಂದಲ್ಲಿ ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ 3.0 ಗ್ರಾಂ ನೀರಿನಲ್ಲಿ ಕರಗುವ ಗಂಧಕದ ಪುಡಿ ಅಥವಾ 2.0 ಗ್ರಾಂ ಟ್ರೆಡೆಮೆಫಾನ್ 25 WP ಅಥವಾ 1.0 ಗ್ರಾಂ ಕಾರ್ಬೆಂಡಜಿಂ 50 WP ಅಥವಾ 0.5 ಗ್ರಾಂ ಮೈಕ್ಲೋಬ್ಯೂಟಾನಿಲ್ 10 WP ಅನ್ನು ಬೆರೆಸಿ ಸಿಂಪಡಿಸುವುದು', 'At the stage of fruit set, the clusters are dipped in 50 mg. of Gibberellic acid mixed in 1 liter of water to double the size of the fruits.', 'If powdery mildew is found, spray with 3.0 g water-soluble sulfur powder or 2.0 g tredemefon 25 WP or 1.0 g carbendazim 50 WP or 0.5 g myclobutanil 10 WP per liter of water', 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (6626, 'GRAPES', 30, N'>3', N'January-February', N'January-February', N'1,2', N'Fruit set and development', N'6', 'NORMAL', 'NO', 'ಕಾಯಿ ಕಚ್ಚುವ ಹಂತದಲ್ಲಿ ಗೊಂಚಲುಗಳನ್ನು 50 ಮಿ. ಗ್ರಾಂ. ಜಿಬ್ಬರ್ಲಿಕ್ ಆಮ್ಲ 1 ಲೀಟರ್ ನೀರಿನಲ್ಲಿ ಬೆರೆಸಿ ಅದ್ದುವುದರಿಂದ ಹಣ್ಣುಗಳ ಗಾತ್ರ ದ್ವಿಗುಣಗೊಳ್ಳುವುದು', 'ಬೂದಿ ರೋಗ ಕಂಡುಬಂದಲ್ಲಿ ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ 3.0 ಗ್ರಾಂ ನೀರಿನಲ್ಲಿ ಕರಗುವ ಗಂಧಕದ ಪುಡಿ ಅಥವಾ 2.0 ಗ್ರಾಂ ಟ್ರೆಡೆಮೆಫಾನ್ 25 WP ಅಥವಾ 1.0 ಗ್ರಾಂ ಕಾರ್ಬೆಂಡಜಿಂ 50 WP ಅಥವಾ 0.5 ಗ್ರಾಂ ಮೈಕ್ಲೋಬ್ಯೂಟಾನಿಲ್ 10 WP ಅನ್ನು ಬೆರೆಸಿ ಸಿಂಪಡಿಸುವುದು', 'At the stage of fruit set, the clusters are dipped in 50 mg. of Gibberellic acid mixed in 1 liter of water to double the size of the fruits.', 'If powdery mildew is found, spray with 3.0 g water-soluble sulfur powder or 2.0 g tredemefon 25 WP or 1.0 g carbendazim 50 WP or 0.5 g myclobutanil 10 WP per liter of water', 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (6627, 'GRAPES', 30, N'>3', N'January-February', N'January-February', N'1,2', N'Fruit set and development', N'6', 'BELOW NORMAL', 'YES', 'ಕಾಯಿ ಕಚ್ಚುವ ಹಂತದಲ್ಲಿ ಗೊಂಚಲುಗಳನ್ನು 50 ಮಿ. ಗ್ರಾಂ. ಜಿಬ್ಬರ್ಲಿಕ್ ಆಮ್ಲ 1 ಲೀಟರ್ ನೀರಿನಲ್ಲಿ ಬೆರೆಸಿ ಅದ್ದುವುದರಿಂದ ಹಣ್ಣುಗಳ ಗಾತ್ರ ದ್ವಿಗುಣಗೊಳ್ಳುವುದು', NULL, 'At the stage of fruit set, the clusters are dipped in 50 mg. of Gibberellic acid mixed in 1 liter of water to double the size of the fruits.', NULL, 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (6628, 'GRAPES', 30, N'>3', N'January-February', N'January-February', N'1,2', N'Fruit set and development', N'6', 'BELOW NORMAL', 'NO', 'ಕೃಷಿ ಹೊಂಡ, ಇತರ ಮೂಲಗಳಲ್ಲಿ ಲಭ್ಯವಿರುವ ನೀರನ್ನು ಬಳಸಿ ಸಂರಕ್ಷಣಾ ನೀರಾವರಿ ಕೊಡುವುದು', NULL, 'Conservation irrigation using water available from agricultural wells and other sources', NULL, 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (6629, 'GRAPES', 30, N'>3', N'January-February', N'January-February', N'1,2', N'Fruit set and development', N'6', 'ABOVE NORMAL', 'YES', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', NULL, 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field.', NULL, 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (6630, 'GRAPES', 30, N'>3', N'January-February', N'January-February', N'1,2', N'Fruit set and development', N'6', 'ABOVE NORMAL', 'NO', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', NULL, 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field.', NULL, 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (6631, 'GRAPES', 30, N'>3', N'February-March', N'March', N'3', N'Fruit maturity', N'7', 'NORMAL', 'YES', 'ಹಣ್ಣಾದ ಗೊಂಚಲುಗಳನ್ನು ಕೊಯ್ಲು ಮಾಡುವುದು', 'ಹಿಟ್ಟಿನ ತಿಗಣೆ ಮತ್ತು ಥ್ರಿಪ್ಸ್ ನುಶಿ ಕಂಡುಬಂದಲ್ಲಿ ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ 0.5 ಗ್ರಾಂ ಥೈಯೋಮಿಥಾಕ್ಸಾಮ್ 25 WG ಅಥವಾ 0.25 ಗ್ರಾಂ ಅಸಿಟಮಾಪ್ರಿಡ್ 75 SP ಅಥವಾ 1.0 ಮಿ.ಲೀ. ಬುಪ್ರೋಫೆಜಿನ್ 25 SC ಅಥವಾ 2 ಮಿ.ಲೀ. ಪ್ರೋಫೆನೊಪಾಸ್ 50 SP ಅನ್ನು ಬೆರೆಸಿ ಸಿಂಪಡಿಸುವುದು. ಬೂದಿ ರೋಗ ಕಂಡುಬಂದಲ್ಲಿ ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ 3.0 ಗ್ರಾಂ ನೀರಿನಲ್ಲಿ ಕರಗುವ ಗಂಧಕದ ಪುಡಿ ಅಥವಾ 2.0 ಗ್ರಾಂ ಟ್ರೆಡೆಮೆಫಾನ್ 25 WP ಅಥವಾ 1.0 ಗ್ರಾಂ ಕಾರ್ಬೆಂಡಜಿಂ 50 WP ಅಥವಾ 0.5 ಗ್ರಾಂ ಮೈಕ್ಲೋಬ್ಯೂಟಾನಿಲ್ 10 WP ಅನ್ನು ಬೆರೆಸಿ ಸಿಂಪಡಿಸುವುದು', 'Harvesting ripe clusters', 'If mealybugs and thrips are found, spray 0.5 g Thiomethoxam 25 WG or 0.25 g Acetamaprid 75 SP or 1.0 ml Buprofezin 25 SC or 2 ml Profenopas 50 SP per liter of water. If powdery mildew is found, spray 3.0 g water soluble sulfur powder or 2.0 g Tredemefon 25 WP or 1.0 g Carbendazim 50 WP or 0.5 g Myclobutanil 10 WP per liter of water', 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (6653, 'POMEGRANATE', NULL, N'<1', N'July-August', N'July-August', N'7,8', N'Establishment stage', N'2', 'BELOW NORMAL', 'NO', '• ಕೃಷಿ ಹೊಂಡ, ಇತರ ಮೂಲಗಳಲ್ಲಿ ಲಭ್ಯವಿರುವ ನೀರನ್ನು ಬಳಸಿ ನೀರಾವರಿ ಕೊಡುವುದು
• ಗಿಡ ಸ್ಥಾಪಿತವಾಗದೆ ಇರುವ ಜಾಗದಲ್ಲಿ ಬೇರೆ ಸಸಿಯನ್ನು ನೆಡುವುದು
• ಗಿಡಗಳು ನೇರವಾಗಿ ಬೆಳೆಯಲು ಅವುಗಳಿಗೆ ಕೋಲಿನ ಆಸರೆ ಒದಗಿಸುವುದು
• ತೋಟದಲ್ಲಿ ಹಸಿರೆಲೆ ಗೊಬ್ಬರದ ಗಿಡಗಳನ್ನು ಬೆಳೆದಿದ್ದರೆ ಅವನ್ನು ಬಿತ್ತಿದ 45 ದಿನಗಳ ನಂತರ ಮಣ್ಣಿಗೆ ಸೇರಿಸುವುದು
• ತೋಟದ ಮಧ್ಯೆ ಅಂತರಬೆಳೆ ಬೆಳೆದಿದ್ದರೆ ಅವುಗಳಿಗೆ ತಗುಲುವ ರೋಗ ಮತ್ತು ಕೀಟಗಳ ಮೇಲೆ ಗಮನ ಹರಿಸುವುದು', NULL, '• Irrigation using water available from agricultural wells and other sources
• Planting other plants in areas where plants are not established
• Providing support for plants with sticks to grow upright
• If green manure plants are grown in the garden, incorporate them into the soil 45 days after sowing
• If intercrops are grown in the garden, pay attention to the diseases and pests that they are susceptible to', NULL, 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (6654, 'POMEGRANATE', NULL, N'<1', N'July-August', N'July-August', N'7,8', N'Establishment stage', N'2', 'ABOVE NORMAL', 'YES', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', 'ಹಣ್ಣು ಕೊರಕ ನಿಯಂತ್ರಣಕ್ಕಾಗಿ ಹೂವು ಬಿಡುವ ಸಮಯದಿಂದ ಹಣ್ಣು ಕೊಯ್ಲು ಮಾಡುವವರೆಗೆ ಪ್ರತಿ ಮೂರು ವಾರಕ್ಕೊಮ್ಮೆ 0.15 ಮಿ.ಲೀ. ಸೈಯಾಂಟ್ರನಿಲಿಪ್ರೋಲ್‍ 10.26OD ಅಥವಾ 0.5 ಮಿ.ಲೀ. ಸ್ಪೈಯನೋಸಾಡ್ 45 SC ಅಥವಾ 0.5 ಮಿ.ಲೀ. ಸೈಪರ್‌ಮೆಥ್ರಿನ್ 25 EC ಅನ್ನು ಪ್ರತಿ ಲೀಟರ್ ನೀರಿಗೆ ಬೆರೆಸಿ ಸಿಂಪಡಿಸುವುದು', 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field.', 'For fruit borer control, spray 0.15 ml. Cyantraniliprole 10.26OD or 0.5 ml. Spyanosad 45 SC or 0.5 ml. Cypermethrin 25 EC per liter of water every three weeks from the time of flowering to fruit harvest', 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (6655, 'POMEGRANATE', NULL, N'<1', N'July-August', N'July-August', N'7,8', N'Establishment stage', N'2', 'ABOVE NORMAL', 'NO', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', NULL, 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field.', NULL, NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (6656, 'POMEGRANATE', NULL, N'<1', N'September-October', N'September-October', N'9,10', N'Vegetative stage', N'2', 'NORMAL', 'YES', '• ತೋಟದಲ್ಲಿ ಅಂತರ ಬೇಸಾಯದ ಮೂಲಕ ಕಳೆ ನಿರ್ವಹಣೆ ಮಾಡಿ LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ರಸಗೊಬ್ಬರಗಳನ್ನು ಒದಗಿಸುವುದು
• ಪ್ರಸ್ತುತ ಹಂತದಲ್ಲಿ ಬೆಳೆ ಉತ್ತಮವಾಗಿದ್ದರೆ, ಇತರೆ ಬೆಳೆ ಬೆಳೆದಿದ್ದಲ್ಲಿ ಅವುಗಳ ನಿರ್ವಹಣೆಯತ್ತ ಗಮನಹರಿಸುವುದು', NULL, '• Manage weeds through intercropping in the garden and provide fertilizers recommended based on LRI
• If the crop is good at the current stage, focus on managing other crops if they are grown', NULL, NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (6657, 'POMEGRANATE', NULL, N'<1', N'September-October', N'September-October', N'9,10', N'Vegetative stage', N'2', 'NORMAL', 'NO', '• ತೋಟದಲ್ಲಿ ಅಂತರ ಬೇಸಾಯದ ಮೂಲಕ ಕಳೆ ನಿರ್ವಹಣೆ ಮಾಡಿ LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ರಸಗೊಬ್ಬರಗಳನ್ನು ಒದಗಿಸುವುದು
• ಪ್ರಸ್ತುತ ಹಂತದಲ್ಲಿ ಬೆಳೆ ಉತ್ತಮವಾಗಿದ್ದರೆ, ಇತರೆ ಬೆಳೆ ಬೆಳೆದಿದ್ದಲ್ಲಿ ಅವುಗಳ ನಿರ್ವಹಣೆಯತ್ತ ಗಮನಹರಿಸುವುದು', NULL, '• Manage weeds through intercropping in the garden and provide fertilizers recommended based on LRI
• If the crop is good at the current stage, focus on managing other crops if they are grown', NULL, NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (6658, 'POMEGRANATE', NULL, N'<1', N'September-October', N'September-October', N'9,10', N'Vegetative stage', N'2', 'BELOW NORMAL', 'YES', '• ತೋಟದಲ್ಲಿ ಅಂತರ ಬೇಸಾಯದ ಮೂಲಕ ಕಳೆ ನಿರ್ವಹಣೆ ಮಾಡಿ LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ರಸಗೊಬ್ಬರಗಳನ್ನು ಒದಗಿಸುವುದು
• ಪ್ರಸ್ತುತ ಹಂತದಲ್ಲಿ ಬೆಳೆ ಉತ್ತಮವಾಗಿದ್ದರೆ, ಇತರೆ ಬೆಳೆ ಬೆಳೆದಿದ್ದಲ್ಲಿ ಅವುಗಳ ನಿರ್ವಹಣೆಯತ್ತ ಗಮನಹರಿಸುವುದು', NULL, '• Manage weeds through intercropping in the garden and provide fertilizers recommended based on LRI
• If the crop is good at the current stage, focus on managing other crops if they are grown', NULL, NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (6680, 'POMEGRANATE', NULL, N'1-2', N'May-June', N'May-June', N'5,6', N'Vegetative stage', N'2', 'NORMAL', 'YES', '• ತೋಟದ ಮಧ್ಯೆ ಉಳುಮೆ ಮಾಡಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ಕೊಟ್ಟಿಗೆ ಗೊಬ್ಬರ ಮತ್ತು LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ರಸಗೊಬ್ಬರವನ್ನು ಕೊಡುವುದು
• ಗಿಡಗಳಿಗೆ ಆಕಾರ ಒದಗಿಸಲು ಅನಗತ್ಯ ರೆಂಬೆಗಳನ್ನು ಕತ್ತರಿಸುವುದು (ಹೆಚ್ಚಿನ ಮಾಹಿತಿಗಾಗಿ ತಂತ್ರಾಂಶದಲ್ಲಿರುವ ದಾಳಿಂಬೆ ಬೆಳೆ ಪದ್ಧತಿಯಲ್ಲಿ ವೀಕ್ಷಿಸಬಹುದು)
• ಹಸಿರೆಲೆ ಗೊಬ್ಬರದ ಗಿಡಗಳಾದ ಸೆಣಬು, ಅಲಸಂದಿ ಅಥವಾ ಹುರುಳಿ ಬೆಳೆಯನ್ನು ಬೆಳೆಯುವುದರಿಂದ ಭೂಮಿಯ ಫಲವತ್ತತೆಯನ್ನು ಹೆಚ್ಚಿಸಬಹುದು
• ಅಥವಾ ತೋಟದ ಮಧ್ಯ ಅಂತರ ಬೆಳೆಗಳನ್ನು ಬೆಳೆಯಬಹುದು', 'ಕಾಂಡ ಕೊರಕ ಕಂಡು ಬಂದಲ್ಲಿ ಕಾಂಡ ಕೊರೆದ ಪ್ರತಿ ರಂಧ್ರಗಳಿಗೆ 0.3 ಮಿ.ಲೀ. ಸ್ಪೈನೋಸಾಡ್‍ 45 SC ಅಥವಾ 0.5 ಮಿ.ಲೀ. ಇಂಡಾಕ್ಸಾಕಾರ್ಬ 14.5 SC ಅನ್ನು ಪ್ರತಿ ಲೀಟರ್ ನೀರಿಗೆ ಬೆರೆಸಿ 10 ಮಿ.ಲೀ. ದ್ರಾವಣವನ್ನು ಸಿರಿಂಜ ಮೂಲಕ ರಂಧ್ರಗಳಲ್ಲಿ ಹಾಕಿ ಶೇ. 10 ರ ಬೋರ್ಡೋ ಪೇಸ್ಟ್ ನಿಂದ ರಂಧ್ರಗಳನ್ನು ಮುಚ್ಚುವುದು', '• Ploughing the garden and applying the recommended manure and fertilizer based on LRI
• Pruning the plants to give shape (for more information, see the pomegranate cropping system in the software)
• Growing green manure crops such as jute, sorghum or buckwheat can increase the fertility of the soil
• Or intercropping can be done in the garden', 'If stem borer is found, for each hole in the stem, mix 0.3 ml. Spinosad 45 SC or 0.5 ml. Indoxacarb 14.5 SC per liter of water and inject 10 ml. of the solution into the holes through a syringe and seal the holes with 10% Bordeaux paste', 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
