INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (6673, 'POMEGRANATE', NULL, N'<1', N'January-February', N'January-February', N'1,2', N'Vegetative stage', N'2', 'ABOVE NORMAL', 'NO', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', 'ಶಲ್ಕ ಕೀಟ ಹಾಗೂ ಥ್ರಿಪ್ಸ್ ಕಂಡುಬಂದರೆ ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ 1 ಮಿ.ಲೀ. ಸೈಯಾಂಟ್ರನಿಲಿಪ್ರೋಲ್ 10.26 OD ಅಥವಾ 0.2 ಗ್ರಾಂ ಇಮಾಮೆಕ್ಟಿನ್ ಬೆಂಜೋಯೇಟ್ 5 SG ಅಥವಾ 2 ಮಿ ಲೀ. ಪ್ರೊಫೆನೋಫಾಸ್ 50 EC+ 5 ಮಿ.ಲೀ. ಫಿಶ್‌ಆಯಲ್ ರೋಸಿನ್ ಸೋಪ್ ಸೇರಿಸಿ ಸಿಂಪಡಿಸುವುದು', 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field.', 'If scale insects and thrips are found, spray 1 ml. Cyantraniliprole 10.26 OD or 0.2 gm. Emamectin Benzoate 5 SG or 2 ml. Profenophos 50 EC + 5 ml. Fish Oil Rosin Soap per liter of water', 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
