INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (6650, 'POMEGRANATE', NULL, N'<1', N'July-August', N'July-August', N'7,8', N'Establishment stage', N'2', 'NORMAL', 'YES', '• ಗಿಡಗಳು ನೇರವಾಗಿ ಬೆಳೆಯಲು ಅವುಗಳಿಗೆ ಕೋಲಿನ ಆಸರೆ ಒದಗಿಸುವುದು
• ತೋಟದಲ್ಲಿ ಹಸಿರೆಲೆ ಗೊಬ್ಬರದ ಗಿಡಗಳನ್ನು ಬೆಳೆದಿದ್ದರೆ ಅವನ್ನು ಬಿತ್ತಿದ 45 ದಿನಗಳ ನಂತರ ಮಣ್ಣಿಗೆ ಸೇರಿಸುವುದು
• ತೋಟದ ಮಧ್ಯೆ ಅಂತರಬೆಳೆ ಬೆಳೆದಿದ್ದರೆ ಅವುಗಳಿಗೆ ತಗುಲುವ ರೋಗ ಮತ್ತು ಕೀಟಗಳ ಮೇಲೆ ಗಮನ ಹರಿಸುವುದು
• ಗಿಡ ಸ್ಥಾಪಿತವಾಗದೆ ಇರುವ ಜಾಗದಲ್ಲಿ ಬೇರೆ ಸಸಿಯನ್ನು ನೆಡುವುದು', 'ಹಣ್ಣು ಕೊಳೆ ರೋಗದ ನಿಯಂತ್ರಣಕ್ಕಾಗಿ ಹೂಬಿಡುವ ಸಮಯದಿಂದ ಹಣ್ಣು ಕೊಯ್ಲು ಮಾಡುವವರೆಗೆ ಪ್ರತಿ ಮೂರು ವಾರಕ್ಕೊಮ್ಮೆ 2 ಗ್ರಾಂ ಜೈನೆಬ್ ಅಥವಾ 2 ಗ್ರಾಂ ಮೆಂಕೋಜೆಬ್ 75 WP ಅಥವಾ 1 ಗ್ರಾಂ. ಥೈಯೋಫಿನೇಟ್‍ ಮಿಥೈಲ್‍ 70 WP ಪ್ರತಿ ಲೀಟರ್ ನೀರಿಗೆ ಬೆರೆಸಿ ಸಿಂಪಡಿಸುವುದು', '• Provide support for the plants to grow upright
• If green manure plants are grown in the garden, incorporate them into the soil 45 days after sowing
• If intercrops are grown in the garden, pay attention to the diseases and pests that they can be affected by
• Plant another plant in the area where the plant is not established', 'For the control of fruit rot, spray 2 gm of Zaineb or 2 gm of Mencozeb 75 WP or 1 gm of Thiophinate Methyl 70 WP mixed in per liter of water every three weeks from the time of flowering to fruit harvesting', 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
