INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (6749, 'POMEGRANATE', NULL, N'>2', N'March-April', N'March-April', N'3,4', N'Vegetative stage', N'8', 'BELOW NORMAL', 'NO', '• ಹಣ್ಣುಗಳ ಕೊಯ್ಲಿನ ನಂತರ ಒಣ ಕೊಂಬೆಗಳನ್ನು ತೆಗೆದುಹಾಕುವುದು
