INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (6835, 'GUAVA', NULL, N'>4', N'March-April', N'March-April', N'3,4', N'Pruning/ Resting', N'6', 'ABOVE NORMAL', 'YES', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', NULL, 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field.', NULL, 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (6836, 'GUAVA', NULL, N'>4', N'March-April', N'March-April', N'3,4', N'Pruning/ Resting', N'6', 'ABOVE NORMAL', 'NO', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', NULL, 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field.', NULL, 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (6837, 'SAPOTA', NULL, N'>1', N'May', N'May', N'5', N'Preparation', N'0', 'NIL', 'NIL', 'ಪೂರ್ವಸಿದ್ದತೆ:  ಭೂಮಿಯನ್ನು 2-3 ಬಾರಿ ಉಳುಮೆ ಮಾಡಿ 10 ಮೀ x 10 ಮೀ. ಅಂತರದ 1x1x1 ಮೀಟರ್ ಗಾತ್ರದ ಗುಣಿಗಳನ್ನು ತೆಗೆದು ಮೇಲ್ಮಣ್ಣು ಮತ್ತು ಕೊಟ್ಟಿಗೆ ಗೊಬ್ಬರ ಮಿಶ್ರಣಮಾಡಿ ತುಂಬುವುದು', NULL, 'Preparation: Plow the land 2-3 times and dig 1x1x1 meter pits with a spacing of 10 m x 10 m and fill them with a mixture of topsoil and manure.', NULL, 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (6838, 'SAPOTA', NULL, N'>1', N'June', N'June', N'6', N'Planting', N'1', 'NORMAL', 'YES', 'ಗುಣಿಯ ಮಧ್ಯದಲ್ಲಿ ಕಸಿ ಗಿಡವನ್ನು ನಾಟಿ ಮಾಡಿ ಕೋಲನ್ನು ಕಟ್ಟಿ ಗಿಡಕ್ಕೆ ಆಸರೆ ಒದಗಿಸುವುದು. ನಂತರ LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ರಸಗೊಬ್ಬರವನ್ನು ಒದಗಿಸುವುದು', NULL, 'Plant the grafted plant in the middle of the hole and tie a stake to provide support to the plant. Then provide fertilizer as recommended based on LRI.', NULL, 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (6839, 'SAPOTA', NULL, N'>1', N'June', N'June', N'6', N'Planting', N'1', 'NORMAL', 'NO', 'ಮಳೆಯ ಮುನ್ಸೂಚನೆಯನ್ನು ಗಮನದಲ್ಲಿಟ್ಟುಕೊಂಡು ಗುಣಿಯ ಮಧ್ಯದಲ್ಲಿ ಕಸಿ ಗಿಡವನ್ನು ನಾಟಿ ಮಾಡಿ ಕೋಲನ್ನು ಕಟ್ಟಿ ಗಿಡಕ್ಕೆ ಆಸರೆ ಒದಗಿಸುವುದು. ನಂತರ LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ರಸಗೊಬ್ಬರವನ್ನು ಒದಗಿಸುವುದು', NULL, 'Keeping in mind the rainfall forecast, plant the grafted plant in the middle of the hole and tie a stake to provide support to the plant. Then provide the fertilizer recommended based on the LRI.', NULL, 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (6814, 'GUAVA', NULL, N'>4', N'September-October', N'September-October', N'9,10', N'Flower bud initiation & Flowering', N'3', 'NORMAL', 'NO', 'ಸೂಚಿಸಲಾದ ಸಸ್ಯ ಸಂರಕ್ಷಣಾ ಕ್ರಮಗಳನ್ನು ಕೈಗೊಳ್ಳುವುದು', 'ಹಣ್ಣು ಕೊಳೆ ರೋಗದ ನಿಯಂತ್ರಣಕ್ಕಾಗಿ ಹೂ ಬಿಡುವ ಸಮಯದಲ್ಲಿ ಗಿಡಗಳಿಗೆ 2 ಗ್ರಾಂ ಕ್ಲೋರೋಥೆಲೋನಿಲ್‍ 70 WP ಅಥವಾ 3 ಗ್ರಾಂ ತಾಮ್ರದ ಆಕ್ಸಿಕ್ಲೋರೈಡ್‍ 50 WP ಅಥವಾ 100 ppm ಆರಿಯೋಫಜಿನ್‍ (100 ಮಿ.ಗ್ರಾಂ. 1 ಲೀ. ನೀರಿನಲ್ಲಿ) ಅಥವಾ 2 ಗ್ರಾಂ ಜೈನೆಬ್‍ 75 WP ಅನ್ನು ಬೆರೆಸಿ ಸಿಂಪಡಿಸುವುದು ಉತ್ತಮ', 'Carrying out the recommended plant protection measures', 'To control fruit rot, it is best to spray the plants with 2 gm Chlorothalonil 70 WP or 3 gm Copper Oxychloride 50 WP or 100 ppm Areophazine (100 mg in 1 liter of water) or 2 gm Zaineb 75 WP during flowering', 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (6815, 'GUAVA', NULL, N'>4', N'September-October', N'September-October', N'9,10', N'Flower bud initiation & Flowering', N'3', 'BELOW NORMAL', 'YES', 'ಪ್ರಸ್ತುತ ಹಂತದಲ್ಲಿ ಬೆಳೆ ಉತ್ತಮವಾಗಿದ್ದರೆ, ಇತರೆ ಬೆಳೆ ಬೆಳೆದಿದ್ದಲ್ಲಿ ಅವುಗಳ ನಿರ್ವಹಣೆಯತ್ತ ಗಮನಹರಿಸುವುದು', NULL, 'If the crop is good at the current stage, focus on managing other crops if they have grown.', NULL, 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (6816, 'GUAVA', NULL, N'>4', N'September-October', N'September-October', N'9,10', N'Flower bud initiation & Flowering', N'3', 'BELOW NORMAL', 'NO', 'ಕೃಷಿ ಹೊಂಡ, ಇತರ ಮೂಲಗಳಲ್ಲಿ ಲಭ್ಯವಿರುವ ನೀರನ್ನು ಬಳಸಿ ನೀರಾವರಿ ಕೊಡುವುದು', NULL, 'Irrigation using water available from agricultural wells and other sources', NULL, 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (6817, 'GUAVA', NULL, N'>4', N'September-October', N'September-October', N'9,10', N'Flower bud initiation & Flowering', N'3', 'ABOVE NORMAL', 'YES', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', '•ಹಿಟ್ಟು ತಿಗಣೆ ಹಾಗೂ ಶಲ್ಕಕೀಟ ಕಂಡು ಬಂದಲ್ಲಿ ಲೀ. ನೀರಿಗೆ 1.25 ಮಿಲೀ. ಬುಪ್ರೊಫೆಜಿನ್ 25% SC ಅಥವಾ 2 ಮಿಲೀ. ಪ್ರೊಫೆನೊಫಾಸ್ 50 EC+ 5 ಗ್ರಾಂ ಮೀನಿನ ಎಣ್ಣೆ ರೋಸಿನ್ ಸೋಪ್ ಅಥವಾ 5% ಬೇವಿನ ಬೀಜ ಕಷಾಯವನ್ನು ಬೆರೆಸಿ ಸಿಂಪರಿಸುವುದು ಸಿಂಪಡಿಸುವುದು

•ಚಿಬ್ಬು ರೋಗ ಕಂಡುಬಂದರೆ ಲೀ. ನೀರಿಗೆ 2.0 ಗ್ರಾಂ ತಾಮ್ರದ ಆಕ್ಸಿಕ್ಲೋರೈಡ್ 50 WP ಅಥವಾ 1 ಗ್ರಾಂ ಕಾರ್ಬೆಂಡಜಿಂ 50 WP ಅಥವಾ ಥಯೋಫಿನೆಟ್ ಮಿಥೈಲ್ 70 WP ಸೇರಿಸಿ ಸಿಂಪರಿಸುವುದು. ಬಿಳಿನೊಣ ಬಾಧೆಗೆ ಲೀ. ನೀರಿಗೆ 5 ಮಿ.ಲೀ. ಬೇವಿನ ಎಣ್ಣೆ + 5 ಮಿಲೀ. ಮೀನೆಣ್ಣೆ ಸಿಂಪರಣೆ ಮಾಡುವುದು', 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field.', '•If mealybugs and scale insects are found, spray 1.25 ml. Buprofezin 25% SC or 2 ml. Profenophos 50 EC + 5 gm fish oil mixed with rosin soap or 5% neem seed decoction per liter of water

•If scab is found, spray 2.0 gm copper oxychloride 50 WP or 1 gm carbendazim 50 WP or thiophene methyl 70 WP per liter of water. For whitefly infestation, spray 5 ml. Neem oil + 5 ml. Fish oil per liter of water', 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (6818, 'GUAVA', NULL, N'>4', N'September-October', N'September-October', N'9,10', N'Flower bud initiation & Flowering', N'3', 'ABOVE NORMAL', 'NO', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', NULL, 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field.', NULL, 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (6819, 'GUAVA', NULL, N'>4', N'November-December', N'November-December', N'11,12', N'Fruit setting & Fruit maturing', N'4', 'NORMAL', 'YES', '• ಎಲೆಗಳು ತಾಮ್ರ ವರ್ಣಕ್ಕೆ ತಿರುಗಿದಲ್ಲಿ ಗಿಡಗಳಿಗೆ ಶೇ. 0.5 ರ ಡಿ.ಎ.ಪಿ. ಮತ್ತು ಸತುವಿನ ಸಲ್ಫೇಟ್‌ಗಳನ್ನು ಅಕ್ಟೋಬರ್-ನವೆಂಬರ್ ತಿಂಗಳಲ್ಲಿ 4-6 ಸಲ ಪ್ರತಿ ವಾರಕ್ಕೊಮ್ಮೆ ಸಿಂಪರಣೆ ಮಾಡುವುದು. ಪ್ರತಿ ಕಿ. ಗ್ರಾಂ. ಸತುವಿನ ಸಲ್ಫೇಟ್ ದ್ರಾವಣಕ್ಕೆ 0.5 ಕಿ.ಗ್ರಾಂ. ಸುಣ್ಣದೊಂದಿಗೆ ಬೆರೆಸಿ ತಟಸ್ಥಗೊಳಿಸಿ
• ಗಿಡಗಳಿಗೆ LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಲಾದ ಪೊಟ್ಯಾಷ್‌ಯುಕ್ತ ಗೊಬ್ಬರವನ್ನು ಕೊಡುವುದು, ಇದರಿಂದ ಹಣ್ಣುಗಳ ಬೆಳವಣಿಗೆ ಉತ್ತಮವಾಗಿರುತ್ತದೆ', '•ಕಜ್ಜಿ ತಿಗಣೆ ಕಂಡುಬಂದಲ್ಲಿ ಲೀ. ನೀರಿಗೆ ಪ್ರತಿ ಲೀಟರ್ ನೀರಿಗೆ 0.3 ಮಿಲಿ ಇಮಿಡಾಕ್ಲೋಪ್ರಿಡ್ 17.8% SL ಅಥವಾ 0.3 ಗ್ರಾಂ ಥಿಯಾಮೆಥಾಕ್ಸಮ್ 25% WG ಅಥವಾ 0.5 ಮಿಲಿ ಲ್ಯಾಂಬ್ಡಾ-ಸೈಹಲೋಥ್ರಿನ್ 5% EC ಸೇರಿಸಿ ಸಿಂಪಡಿಸುವುದು

•ಚಿಬ್ಬು ರೋಗ ಕಂಡುಬಂದರೆ ಲೀ. ನೀರಿಗೆ 2.0 ಗ್ರಾಂ ತಾಮ್ರದ ಆಕ್ಸಿಕ್ಲೋರೈಡ್ 50 WP ಅಥವಾ 1 ಗ್ರಾಂ ಕಾರ್ಬೆಂಡಜಿಂ 50 WP ಅಥವಾ ಥಯೋಫಿನೆಟ್ ಮಿಥೈಲ್ 70 WP ಸೇರಿಸಿ ಸಿಂಪರಿಸುವುದು. ಬಿಳಿನೊಣ ಬಾಧೆಗೆ ಲೀ. ನೀರಿಗೆ 5 ಮಿ.ಲೀ. ಬೇವಿನ ಎಣ್ಣೆ + 5 ಮಿಲೀ. ಮೀನೆಣ್ಣೆ ಸಿಂಪರಣೆ ಮಾಡುವುದು', '• If the leaves turn copper in color, spray the plants with 0.5% DAP and zinc sulphate 4-6 times a week in the month of October-November. For every kg. of zinc sulphate solution, mix 0.5 kg. of lime and neutralize it. • Give the plants a potash fertilizer recommended based on LRI, so that the growth of fruits is good.', '•If scabies is found, spray 0.3 ml of imidacloprid 17.8% SL or 0.3 g of thiamethoxam 25% WG or 0.5 ml of lambda-cyhalothrin 5% EC per liter of water

•If scab is found, spray 2.0 g of copper oxychloride 50 WP or 1 g of carbendazim 50 WP or thiophene methyl 70 WP per liter of water. For whitefly infestation, spray 5 ml of neem oil + 5 ml of fish oil per liter of water', 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
