INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (6887, 'SAPOTA', NULL, N'1-4', N'September-October', N'September-October', N'9,10', N'Vegetative stage', N'3', 'NORMAL', 'NO', '• ಗಿಡಗಳನ್ನು ನೆಲದಿಂದ 60-70 ಸೆಂ.ಮೀ. ಎತ್ತರದಲ್ಲಿ ಕವಲುಗಳು ಬರುವುದನ್ನು ಉತ್ತೇಜಿಸಲು ಕತ್ತರಿಸುವುದು (ಹೆಚ್ಚಿನ ಮಾಹಿತಿಗಾಗಿ ತಂತ್ರಾಂಶದಲ್ಲಿರುವ ಸಪೋಟ ಬೆಳೆ ಪದ್ಧತಿಯಲ್ಲಿ ವೀಕ್ಷಿಸಬಹುದು)', NULL, '• Prune the plants at a height of 60-70 cm from the ground to encourage branching (for more information, see Sapota Crop System in the software)', NULL, 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (6888, 'SAPOTA', NULL, N'1-4', N'September-October', N'September-October', N'9,10', N'Vegetative stage', N'3', 'BELOW NORMAL', 'YES', '• ಗಿಡಗಳನ್ನು ನೆಲದಿಂದ 60-70 ಸೆಂ.ಮೀ. ಎತ್ತರದಲ್ಲಿ ಕವಲುಗಳು ಬರುವುದನ್ನು ಉತ್ತೇಜಿಸಲು ಕತ್ತರಿಸುವುದು (ಹೆಚ್ಚಿನ ಮಾಹಿತಿಗಾಗಿ ತಂತ್ರಾಂಶದಲ್ಲಿರುವ ಸಪೋಟ ಬೆಳೆ ಪದ್ಧತಿಯಲ್ಲಿ ವೀಕ್ಷಿಸಬಹುದು)', '•ಶಲ್ಕ ಕೀಟ ಹಾಗೂ ಥ್ರಿಪ್ಸ್ ಕಂಡುಬಂದರೆ ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ 1.0 ಮಿ.ಲೀ. ಸೈಯಾಂಟ್ರನಿಲಿಪ್ರೋಲ್ 10.26 OD ಅಥವಾ 0.2 ಗ್ರಾಂ  ಇಮಾಮೆಕ್ಟಿನ್ ಬೆಂಜೋಯೇಟ್ 5.0 SG ಅಥವಾ 2.0 ಮಿ ಲೀ. ಪ್ರೊಫೆನೋಫಾಸ್ 50 EC+ 5.0 ಮಿ.ಲೀ.  ಫಿಶ್‌ಆಯಲ್ ರೋಸಿನ್ ಸೋಪ್ ಅನ್ನು ಬೆರೆಸಿ ಸಿಂಪಡಿಸುವುದು
•ಕಪ್ಪು ಬೂಷ್ಟು ಶಿಲೀಂಧ್ರ ರೋಗ ಕಂಡು ಬಂದಲ್ಲಿ ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ 3.0 ಗ್ರಾಂ ಶೇ. 80 ರ ನೀರಿನಲ್ಲಿ ಕರಗುವ ಗಂಧಕ ಅಥವಾ 1.7 ಗ್ರಾಂ ಡೈಮಿಥೋಯೇಟ್ 30 EC ಅಥವಾ 2.0 ಗ್ರಾಂ ಮ್ಯಾಂಕೋಜೆಬ್ 75 WP ಸೇರಿಸಿ ಸಿಂಪಡಿಸುವುದು', '• Prune the plants at a height of 60-70 cm from the ground to encourage branching (for more information, see Sapota Crop System in the software)', '•If scale insects and thrips are found, spray 1.0 ml of Cyanthraniliprol 10.26 OD or 0.2 g of Emamectin Benzoate 5.0 SG or 2.0 ml of Profenophos 50 EC + 5.0 ml of Fish Oil Rosin Soap per liter of water
•If black mold is found, spray 3.0 g of 80% water-soluble sulfur or 1.7 g of Dimethoate 30 EC or 2.0 g of Mancozeb 75 WP per liter of water', 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (6847, 'SAPOTA', NULL, N'>1', N'July-August', N'July-August', N'7,8', N'Establishment stage', N'2', 'BELOW NORMAL', 'NO', '• ಗಿಡ ಸ್ಥಾಪಿತವಾಗದೆ ಇರುವ ಜಾಗದಲ್ಲಿ ಬೇರೆ ಸಸಿಯನ್ನು ನೆಡುವುದು 
• ಕೃಷಿ ಹೊಂಡ, ಇತರ ಮೂಲಗಳಲ್ಲಿ ಲಭ್ಯವಿರುವ ನೀರನ್ನು ಬಳಸಿ ನೀರಾವರಿ ಕೊಡುವುದು
• ನಾಟಿ ಮಾಡಿದ ನಂತರ ತೋಟದ ಮಧ್ಯೆ ಹಸಿರೆಲೆಗೊಬ್ಬರದ ಬೆಳೆ ಅಥವಾ ಅಂತರ ಬೆಳೆಗಳನ್ನು ಬೆಳೆಯಬಹುದು', NULL, '• Planting another plant in the area where the plant is not established 
• Irrigation using water available from agricultural wells, other sources
• After planting, green manure crops or intercrops can be grown in the middle of the garden', NULL, 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (6848, 'SAPOTA', NULL, N'>1', N'July-August', N'July-August', N'7,8', N'Establishment stage', N'2', 'ABOVE NORMAL', 'YES', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', NULL, 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field.', NULL, 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
