INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (6931, 'SAPOTA', NULL, N'>4', N'November-Demember', N'November-Demember', N'11,12', N'Fruit set and development stage', N'6', 'BELOW NORMAL', 'NO', 'ಕೃಷಿ ಹೊಂಡ, ಇತರ ಮೂಲಗಳಲ್ಲಿ ಲಭ್ಯವಿರುವ ನೀರನ್ನು ಬಳಸಿ ನೀರಾವರಿ ಕೊಡುವುದು', 'ಕಾಂಡ ಕೊರಕ ಕಂಡು ಬಂದಲ್ಲಿ ಕಾಂಡ ಕೊರೆದ ಪ್ರತಿ ರಂಧ್ರಗಳಿಗೆ 2 ಮಿ.ಲೀ. ಕ್ಲೋರಾಂಟ್ರನಿಲಿಪ್ರೋಲ್ 18.5 SC ಪ್ರತಿ ಲೀಟರ್ ನೀರಿನಲ್ಲಿ ಬೆರೆಸಿ 10 ಮಿ.ಲೀ. ದ್ರಾವಣವನ್ನು ಸಿರಿಂಜ ಮೂಲಕ ರಂಧ್ರಗಳಲ್ಲಿ ಹಾಕಿ ಶೇ. 10 ರ ಬೋರ್ಡೋ ಪೇಸ್ಟಯಿಂದ ರಂಧ್ರಗಳನ್ನು ಮುಚ್ಚವುದು', 'Irrigation using water available from agricultural wells and other sources', 'If stem borer is found, mix 2 ml of chlorantraniliprole 18.5 SC per liter of water for each hole in the stem and inject 10 ml of the solution into the holes through a syringe and seal the holes with 10% Bordeaux paste', 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
