INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7045, 'COCONUT', 21, N'<1', N'February-March', N'February-March', N'2,3', N'Vegetative stage', N'6', 'NORMAL', 'YES', 'ಸೂಚಿಸಲಾದ ಸಸ್ಯ ಸಂರಕ್ಷಣಾ ಕ್ರಮಗಳನ್ನು ಕೈಗೊಳ್ಳುವುದು', 'ಕೆಂಪು ಮೂತಿಯ ದುಂಬಿ ಭಾದೆ ಕಂಡು ಬಂದಲ್ಲಿ ಹುಳುವಿರುವ ಕಡೆ ಒಂದು ರಂಧ್ರವನ್ನು ಮಾಡಿ ಅದಕ್ಕೆ 4 ಮಿ.ಲೀ. ಕ್ಲೋರಾಂಟ್ರನಿಲಿಪ್ರೋಲ್ 18.5 SC ಅಥವಾ 4 ಮಿ.ಲೀ. ಇಂಡಾಕ್ಸಾಕಾರ್ಬ 14.5 SC ಅನ್ನು ಪ್ರತಿ ಲೀಟರ್ ನೀರಿನಲ್ಲಿ ಬೆರೆಸಿ ಸುರಿಯುವುದು', 'Carrying out the recommended plant protection measures', 'If red-nosed beetle infestation is found, make a hole in the area where the worm is and pour 4 ml. Chlorantraniliprole 18.5 SC or 4 ml. Indoxacarb 14.5 SC mixed in every liter of water', 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7046, 'COCONUT', 21, N'<1', N'February-March', N'February-March', N'2,3', N'Vegetative stage', N'6', 'NORMAL', 'NO', 'ಸೂಚಿಸಲಾದ ಸಸ್ಯ ಸಂರಕ್ಷಣಾ ಕ್ರಮಗಳನ್ನು ಕೈಗೊಳ್ಳುವುದು', 'ಕೆಂಪು ಮೂತಿಯ ದುಂಬಿ ಭಾದೆ ಕಂಡು ಬಂದಲ್ಲಿ ಹುಳುವಿರುವ ಕಡೆ ಒಂದು ರಂಧ್ರವನ್ನು ಮಾಡಿ ಅದಕ್ಕೆ 4 ಮಿ.ಲೀ. ಕ್ಲೋರಾಂಟ್ರನಿಲಿಪ್ರೋಲ್ 18.5 SC ಅಥವಾ 4 ಮಿ.ಲೀ. ಇಂಡಾಕ್ಸಾಕಾರ್ಬ 14.5 SC ಅನ್ನು ಪ್ರತಿ ಲೀಟರ್ ನೀರಿನಲ್ಲಿ ಬೆರೆಸಿ ಸುರಿಯುವುದು', 'Carrying out the recommended plant protection measures', 'If red-nosed beetle infestation is found, make a hole in the area where the worm is and pour 4 ml. Chlorantraniliprole 18.5 SC or 4 ml. Indoxacarb 14.5 SC mixed in every liter of water', 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7047, 'COCONUT', 21, N'<1', N'February-March', N'February-March', N'2,3', N'Vegetative stage', N'6', 'BELOW NORMAL', 'YES', 'ಪ್ರಸ್ತುತ ಹಂತದಲ್ಲಿ ಬೆಳೆ ಉತ್ತಮವಾಗಿದ್ದರೆ, ಇತರೆ ಬೆಳೆ ಬೆಳೆದಿದ್ದಲ್ಲಿ ಅವುಗಳ ನಿರ್ವಹಣೆಯತ್ತ ಗಮನಹರಿಸುವುದು', NULL, 'If the crop is good at the current stage, focus on managing other crops if they have grown.', NULL, 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7048, 'COCONUT', 21, N'<1', N'February-March', N'February-March', N'2,3', N'Vegetative stage', N'6', 'BELOW NORMAL', 'NO', 'ಕೃಷಿ ಹೊಂಡ, ಇತರ ಮೂಲಗಳಲ್ಲಿ ಲಭ್ಯವಿರುವ ನೀರನ್ನು ಬಳಸಿ ಸಂರಕ್ಷಣಾ ನೀರಾವರಿ ಕೊಡುವುದು. ಮಣ್ಣಿನ ತೇವಾಂಶವನ್ನು ಸಂರಕ್ಷಿಸಲು ತೆಂಗಿನ ಚಿಪ್ಪುಗಳು ಅಥವಾ ಗರಿಗಳಿಂದ ಮೇಲೊದಿಕೆ ಮಾಡುವುದು', NULL, 'Conservation irrigation using water available from agricultural wells and other sources. Mulching with coconut shells or feathers to conserve soil moisture.', NULL, 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7049, 'COCONUT', 21, N'<1', N'February-March', N'February-March', N'2,3', N'Vegetative stage', N'6', 'ABOVE NORMAL', 'YES', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', NULL, 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field.', NULL, 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7050, 'COCONUT', 21, N'<1', N'February-March', N'February-March', N'2,3', N'Vegetative stage', N'6', 'ABOVE NORMAL', 'NO', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', 'ಗರಿತಿನ್ನುವ ಕಪ್ಪು ತಲೆ ಕಂಬಳಿ ಹುಳು ಕಂಡು ಬಂದಾಗ ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ 0.1 ಮಿ.ಲೀ. ಕ್ಲೋರಾಂಟ್ರನಿಲಿಪ್ರೋಲ್ 18.5 SC ಅಥವಾ 1.5 ಮಿ.ಲೀ. ಅಜಾಡಿರೆಕ್ಟಿನ್ ಅನ್ನು ಸಿಂಪಡಿಸುವುದು
•20 ಗೋನಿಯಾಜಸ್ ಅಥವಾ 30 ಬಕ್ರಾನ್ ಪರತಂತ್ರ ಜೀವಿಗಳನ್ನು ಪ್ರತಿ ಮರಕ್ಕೆ 15 ದಿನಗಳಿಗೊಮ್ಮೆ4 ಬಾರಿ ಬಿಡುವುದು', 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field.', 'When black-headed cotton bollworm is found, spray 0.1 ml. Chlorantraniliprole 18.5 SC or 1.5 ml. Azadirachtin per liter of water
•Release 20 Goniages or 30 Bacran parasites per tree 4 times every 15 days', 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7051, 'COCONUT', 21, N'<1', N'April-May', N'April-May', N'4,5', N'Vegetative stage', N'7', 'NORMAL', 'YES', 'ನಾಟಿ ಮಾಡಿದ ಪ್ರಾರಂಭದ ವರ್ಷಗಳಲ್ಲಿ ಗಿಡಗಳಿಗೆ ನೆರಳನ್ನು ಒದಗಿಸುವುದು. 1 ಅಡಿ ಆಳದ ಟ್ರೆಂಚ್‌ಗಳನ್ನು ಕಾಂಡದ 2.5 ರಿಂದ 3 ಮೀ. ದೂರದಲ್ಲಿ ಇಳಜಾರಿಗೆ ಅಡ್ಡಲಾಗಿ ನಿರ್ಮಿಸುವುದು', NULL, 'Provide shade to the plants in the initial years after planting. Make 1 foot deep trenches 2.5 to 3 m. away from the trunk, across the slope.', NULL, 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7070, 'COCONUT', 21, N'1-4', N'September-October', N'September-October', N'9,10', N'Vegetative stage', N'4', 'NORMAL', 'NO', 'ಮರದ ಸುತ್ತಲು ಪಾತಿ ಮಾಡಿ LRI ಆಧರಿಸಿ ಶಫಾರಸ್ಸು ಮಾಡಿದ ಗೊಬ್ಬರವನ್ನು ಮೇಲುಗೊಬ್ಬರವನ್ನು ಕೊಡುವುದು', 'ಕೆಂಪು ಮೂತಿಯ ದುಂಬಿ ಭಾದೆ ಕಂಡು ಬಂದಲ್ಲಿ ಹುಳುವಿರುವ ಕಡೆ ಒಂದು ರಂಧ್ರವನ್ನು ಮಾಡಿ ಅದಕ್ಕೆ 4 ಮಿ.ಲೀ. ಕ್ಲೋರಾಂಟ್ರನಿಲಿಪ್ರೋಲ್ 18.5 SC ಅಥವಾ 4 ಮಿ.ಲೀ. ಇಂಡಾಕ್ಸಾಕಾರ್ಬ 14.5 SC ಅನ್ನು ಪ್ರತಿ ಲೀಟರ್ ನೀರಿನಲ್ಲಿ ಬೆರೆಸಿ ಸುರಿಯುವುದು', 'Make a bed around the tree and top-dress with the recommended fertilizer based on LRI.', 'If red-nosed beetle infestation is found, make a hole in the area where the worm is and pour 4 ml. Chlorantraniliprole 18.5 SC or 4 ml. Indoxacarb 14.5 SC mixed in every liter of water', 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7071, 'COCONUT', 21, N'1-4', N'September-October', N'September-October', N'9,10', N'Vegetative stage', N'4', 'BELOW NORMAL', 'YES', 'ಮರದ ಸುತ್ತಲು ಪಾತಿ ಮಾಡಿ LRI ಆಧರಿಸಿ ಶಫಾರಸ್ಸು ಮಾಡಿದ ಗೊಬ್ಬರವನ್ನು ಮೇಲುಗೊಬ್ಬರವನ್ನು ಕೊಡುವುದು', NULL, 'Make a bed around the tree and top-dress with the recommended fertilizer based on LRI.', NULL, 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7072, 'COCONUT', 21, N'1-4', N'September-October', N'September-October', N'9,10', N'Vegetative stage', N'4', 'BELOW NORMAL', 'NO', 'ಕೃಷಿ ಹೊಂಡ, ಇತರ ಮೂಲಗಳಲ್ಲಿ ಲಭ್ಯವಿರುವ ನೀರನ್ನು ಬಳಸಿ ಸಂರಕ್ಷಣಾ ನೀರಾವರಿ ಕೊಡುವುದು. ಮಣ್ಣಿನ ತೇವಾಂಶವನ್ನು ಸಂರಕ್ಷಿಸಲು ತೆಂಗಿನ ಚಿಪ್ಪುಗಳು ಅಥವಾ ಗರಿಗಳಿಂದ ಮೇಲೊದಿಕೆ ಮಾಡುವುದು', NULL, 'Conservation irrigation using water available from agricultural wells and other sources. Mulching with coconut shells or feathers to conserve soil moisture.', NULL, 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7073, 'COCONUT', 21, N'1-4', N'September-October', N'September-October', N'9,10', N'Vegetative stage', N'4', 'ABOVE NORMAL', 'YES', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', 'ಎಲೆಚುಕ್ಕೆ ಅಥವಾ ಕಣ್ಣು ಕೊಳೆ ರೋಗ ಕಂಡುಬಂದಲ್ಲಿ ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ 2 ಗ್ರಾಂ ಮ್ಯಾಂಕೋಜೆಬ್ 75 WP ಅಥವಾ 3 ಗ್ರಾಂ ತಾಮ್ರದ ಆಕ್ಸಿಕ್ಲೋರೈಡ್ 50 WP ಅನ್ನು ಗರಿಗಳ ಮೇಲೆ ಸಿಂಪಡಿಸುವುದು', 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field.', 'If leaf spot or eye rot is observed, spray 2 grams of Mancozeb 75 WP or 3 grams of Copper Oxychloride 50 WP per liter of water on the feathers', 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7074, 'COCONUT', 21, N'1-4', N'September-October', N'September-October', N'9,10', N'Vegetative stage', N'4', 'ABOVE NORMAL', 'NO', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', 'ಸುಳಿಕೊರೆಯುವ ರೈನೋಸರಸ್ ದುಂಬಿಯ ಬಾಧೆ ಕಂಡುಬಂದಲ್ಲಿ
• ಎಳೆಯ ವಯಸ್ಸಿನ ಗಿಡಗಳ ಎಲೆಗಳನ್ನು ಒಟ್ಟುಗೂಡಿಸಿ ಕಟ್ಟವುದು ಉತ್ತಮ
• ಸುಳಿಯ ಭಾಗದ ರಂಧ್ರದಲ್ಲಿ ಕಬ್ಬಿಣದ ಕೊಕ್ಕೆಯನ್ನು ತೂರಿಸಿ ದುಂಬಿಗಳನ್ನು ಹೊರ ತೆಗೆದು ಸಾಯಿಸುವುದು 
• ಒಳ 2-3 ಗಿರಿಗಳ ಬುಡದಲ್ಲಿ 250 ಗ್ರಾಂ. ಕಹಿ ಬೇವಿನ ಹಿಂಡಿಯೊಂದಿಗೆ ಅಲ್ಪ ಪ್ರಮಾಣದ ಮರಳನ್ನು ಸೇರಿಸಿ ಹಾಕುವುದು
• ಪ್ರತಿ ಹೆಕ್ಟೇರ್‌ಗೆ 1 ಸಿ.ಪಿ. ಸಿ.ಆರ್.ಐ. ಮಾದರಿ ಮೋಹಕ ಬಲೆಗಳನ್ನು ಇಡುವುದು
• ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ 2 ಮಿ.ಲೀ. ಕ್ಲೋರೋಪೈರಿಫಾಸ್ ಅನ್ನು ಬೆರೆಸಿ 3 ಘನ.ಮೀ.ಕಾಂಪೋಸ್ಟ್ ಗುಂಡಿಗಳಿಗೆ ಉಪಯೋಗಿಸುವುದು', 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field.', 'If you find a problem with Rhinoceroses borer
• It is better to collect and tie the leaves of young plants
• Insert an iron hook into the hole in the borer and kill the borers 
• At the base of the inner 2-3 ridges, add 250 gm. of bitter neem powder along with a small amount of sand
• Place 1 C.P. C.R.I. type trap per hectare
• Mix 2 ml. Chlorpyrifos per liter of water and use it for 3 cubic meters of compost pits', 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7075, 'COCONUT', 21, N'1-4', N'November-January', N'November-December-January', N'11,12,1', N'Vegetative stage', N'5', 'NORMAL', 'YES', 'ತೋಟದಲ್ಲಿ ಕಳೆ ನಿರ್ವಹಣೆ ಮಾಡಿ ಸ್ವಚ್ಛವಾಗಿಡುವುದು', NULL, 'Weed management and keeping the garden clean', NULL, 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7085, 'COCONUT', 21, N'1-4', N'February-March', N'February-March', N'2,3', N'Vegetative stage', N'6', 'ABOVE NORMAL', 'YES', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', NULL, 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field.', NULL, 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
