INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7089, 'COCONUT', 21, N'1-4', N'April-May', N'April-May', N'4,5', N'Vegetative stage', N'7', 'BELOW NORMAL', 'YES', 'ನಾಟಿ ಮಾಡಿದ ಪ್ರಾರಂಭದ ವರ್ಷಗಳಲ್ಲಿ ಗಿಡಗಳಿಗೆ ನೆರಳನ್ನು ಒದಗಿಸುವುದು', NULL, 'Providing shade to plants in the early years after planting', NULL, 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7076, 'COCONUT', 21, N'1-4', N'November-January', N'November-December-January', N'11,12,1', N'Vegetative stage', N'5', 'NORMAL', 'NO', 'ತೋಟದಲ್ಲಿ ಕಳೆ ನಿರ್ವಹಣೆ ಮಾಡಿ ಸ್ವಚ್ಛವಾಗಿಡುವುದು', NULL, 'Weed management and keeping the garden clean', NULL, 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7077, 'COCONUT', 21, N'1-4', N'November-January', N'November-December-January', N'11,12,1', N'Vegetative stage', N'5', 'BELOW NORMAL', 'YES', 'ತೋಟದಲ್ಲಿ ಕಳೆ ನಿರ್ವಹಣೆ ಮಾಡಿ ಸ್ವಚ್ಛವಾಗಿಡುವುದು', NULL, 'Weed management and keeping the garden clean', NULL, 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7078, 'COCONUT', 21, N'1-4', N'November-January', N'November-December-January', N'11,12,1', N'Vegetative stage', N'5', 'BELOW NORMAL', 'NO', 'ಕೃಷಿ ಹೊಂಡ, ಇತರ ಮೂಲಗಳಲ್ಲಿ ಲಭ್ಯವಿರುವ ನೀರನ್ನು ಬಳಸಿ ಸಂರಕ್ಷಣಾ ನೀರಾವರಿ ಕೊಡುವುದು', 'ಕೆಂಪು ಮೂತಿಯ ದುಂಬಿ ಭಾದೆ ಕಂಡು ಬಂದಲ್ಲಿ ಹುಳುವಿರುವ ಕಡೆ ಒಂದು ರಂಧ್ರವನ್ನು ಮಾಡಿ ಅದಕ್ಕೆ 4 ಮಿ.ಲೀ. ಕ್ಲೋರಾಂಟ್ರನಿಲಿಪ್ರೋಲ್ 18.5 SC ಅಥವಾ 4 ಮಿ.ಲೀ. ಇಂಡಾಕ್ಸಾಕಾರ್ಬ 14.5 SC ಅನ್ನು ಪ್ರತಿ ಲೀಟರ್ ನೀರಿನಲ್ಲಿ ಬೆರೆಸಿ ಸುರಿಯುವುದು', 'Conservation irrigation using water available from agricultural wells and other sources', 'If red-nosed beetle infestation is found, make a hole in the area where the worm is and pour 4 ml. Chlorantraniliprole 18.5 SC or 4 ml. Indoxacarb 14.5 SC mixed in every liter of water', 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7079, 'COCONUT', 21, N'1-4', N'November-January', N'November-December-January', N'11,12,1', N'Vegetative stage', N'5', 'ABOVE NORMAL', 'YES', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', NULL, 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field.', NULL, 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7080, 'COCONUT', 21, N'1-4', N'November-January', N'November-December-January', N'11,12,1', N'Vegetative stage', N'5', 'ABOVE NORMAL', 'NO', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', NULL, 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field.', NULL, 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7081, 'COCONUT', 21, N'1-4', N'February-March', N'February-March', N'2,3', N'Vegetative stage', N'6', 'NORMAL', 'YES', 'ಪ್ರಸ್ತುತ ಹಂತದಲ್ಲಿ ಬೆಳೆ ಉತ್ತಮವಾಗಿದ್ದರೆ, ಇತರೆ ಬೆಳೆ ಬೆಳೆದಿದ್ದಲ್ಲಿ ಅವುಗಳ ನಿರ್ವಹಣೆಯತ್ತ ಗಮನಹರಿಸುವುದು', NULL, 'If the crop is good at the current stage, focus on managing other crops if they have grown.', NULL, 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7082, 'COCONUT', 21, N'1-4', N'February-March', N'February-March', N'2,3', N'Vegetative stage', N'6', 'NORMAL', 'NO', 'ಪ್ರಸ್ತುತ ಹಂತದಲ್ಲಿ ಬೆಳೆ ಉತ್ತಮವಾಗಿದ್ದರೆ, ಇತರೆ ಬೆಳೆ ಬೆಳೆದಿದ್ದಲ್ಲಿ ಅವುಗಳ ನಿರ್ವಹಣೆಯತ್ತ ಗಮನಹರಿಸುವುದು', NULL, 'If the crop is good at the current stage, focus on managing other crops if they have grown.', NULL, 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7083, 'COCONUT', 21, N'1-4', N'February-March', N'February-March', N'2,3', N'Vegetative stage', N'6', 'BELOW NORMAL', 'YES', 'ಸೂಚಿಸಲಾದ ಸಸ್ಯ ಸಂರಕ್ಷಣಾ ಕ್ರಮಗಳನ್ನು ಕೈಗೊಳ್ಳುವುದು', 'ಗರಿತಿನ್ನುವ ಕಪ್ಪು ತಲೆ ಕಂಬಳಿ ಹುಳು ಕಂಡು ಬಂದಾಗ ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ 0.1 ಮಿ.ಲೀ. ಕ್ಲೋರಾಂಟ್ರನಿಲಿಪ್ರೋಲ್ 18.5 SC ಅಥವಾ 1.5 ಮಿ.ಲೀ. ಅಜಾಡಿರೆಕ್ಟಿನ್ ಅನ್ನು ಸಿಂಪಡಿಸುವುದು
•20 ಗೋನಿಯಾಜಸ್ ಅಥವಾ 30 ಬಕ್ರಾನ್ ಪರತಂತ್ರ ಜೀವಿಗಳನ್ನು ಪ್ರತಿ ಮರಕ್ಕೆ 15 ದಿನಗಳಿಗೊಮ್ಮೆ4 ಬಾರಿ ಬಿಡುವುದು', 'Carrying out the recommended plant protection measures', 'When black-headed cotton bollworm is found, spray 0.1 ml. Chlorantraniliprole 18.5 SC or 1.5 ml. Azadirachtin per liter of water
•Release 20 Goniages or 30 Bacran parasites per tree 4 times every 15 days', 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7084, 'COCONUT', 21, N'1-4', N'February-March', N'February-March', N'2,3', N'Vegetative stage', N'6', 'BELOW NORMAL', 'NO', 'ಕೃಷಿ ಹೊಂಡ, ಇತರ ಮೂಲಗಳಲ್ಲಿ ಲಭ್ಯವಿರುವ ನೀರನ್ನು ಬಳಸಿ ಸಂರಕ್ಷಣಾ ನೀರಾವರಿ ಕೊಡುವುದು. ಮಣ್ಣಿನ ತೇವಾಂಶವನ್ನು ಸಂರಕ್ಷಿಸಲು ತೆಂಗಿನ ಚಿಪ್ಪುಗಳು ಅಥವಾ ಗರಿಗಳಿಂದ ಮೇಲೊದಿಕೆ ಮಾಡುವುದು', NULL, 'Conservation irrigation using water available from agricultural wells and other sources. Mulching with coconut shells or feathers to conserve soil moisture.', NULL, 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7052, 'COCONUT', 21, N'<1', N'April-May', N'April-May', N'4,5', N'Vegetative stage', N'7', 'NORMAL', 'NO', 'ನಾಟಿ ಮಾಡಿದ ಪ್ರಾರಂಭದ ವರ್ಷಗಳಲ್ಲಿ ಗಿಡಗಳಿಗೆ ನೆರಳನ್ನು ಒದಗಿಸುವುದು. 1 ಅಡಿ ಆಳದ ಟ್ರೆಂಚ್‌ಗಳನ್ನು ಕಾಂಡದ 2.5 ರಿಂದ 3 ಮೀ. ದೂರದಲ್ಲಿ ಇಳಜಾರಿಗೆ ಅಡ್ಡಲಾಗಿ ನಿರ್ಮಿಸುವುದು', NULL, 'Provide shade to the plants in the initial years after planting. Make 1 foot deep trenches 2.5 to 3 m. away from the trunk, across the slope.', NULL, 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7053, 'COCONUT', 21, N'<1', N'April-May', N'April-May', N'4,5', N'Vegetative stage', N'7', 'BELOW NORMAL', 'YES', 'ಗಿಡಗಳನ್ನು ಬಿಸಿಲಿನಿಂದ ರಕ್ಷಿಸಲು ಗಿಡಗಳಿಗೆ ನೆರಳನ್ನು ಒದಗಿಸಿ, ಕೃಷಿ ಹೊಂಡ, ಇತರ ಮೂಲಗಳಲ್ಲಿ ಲಭ್ಯವಿರುವ ನೀರನ್ನು ಬಳಸಿ ಸಂರಕ್ಷಣಾ ನೀರಾವರಿ ಕೊಡುವುದು. ಮಣ್ಣಿನ ತೇವಾಂಶವನ್ನು ಸಂರಕ್ಷಿಸಲು ತೆಂಗಿನ ಚಿಪ್ಪುಗಳು ಅಥವಾ ಗರಿಗಳಿಂದ ಮೇಲೊದಿಕೆ ಮಾಡುವುದು', 'ಗೊಣ್ಣೆಹುಳು ಕಂಡು ಬಂದಲ್ಲಿ ಮುಂಗಾರು ಹಂಗಾಮಿನ ಮೊದಲ ಮಳೆ ಬಿದ್ದ ಕೂಡಲೇ ಆ ದಿನ ರಾತ್ರಿ 7.30 ರಿಂದ 8.30 ರ ವರೆಗೆ ದುಂಬಿಗಳನ್ನುದೀಪಾಕರ್ಷಣೆ ಮಾಡಿ ನಾಶಪಡಿಸುವುದು ಹಾಗೂ ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ 10 ಮಿ.ಲೀ. ಕ್ಲೋರೊಪೈರಿಫಾಸ್ 20 EC ಅನ್ನು ಬೆರೆಸಿ ಗಿಡದ ಬುಡಕ್ಕೆ ಸುರಿಯುವುದು', 'Provide shade to protect plants from the sun, and provide conservation irrigation using water available from agricultural wells and other sources. Mulch with coconut shells or feathers to conserve soil moisture.', 'If the caterpillars are found, immediately after the first rain of the monsoon season, destroy the caterpillars by lighting lamps between 7.30 and 8.30 pm that day and mix 10 ml of Chlorpyrifos 20 EC per liter of water and pour it at the base of the plant', 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7054, 'COCONUT', 21, N'<1', N'April-May', N'April-May', N'4,5', N'Vegetative stage', N'7', 'BELOW NORMAL', 'NO', 'ಗಿಡಗಳನ್ನು ಬಿಸಿಲಿನಿಂದ ರಕ್ಷಿಸಲು ಗಿಡಗಳಿಗೆ ನೆರಳನ್ನು ಒದಗಿಸಿ, ಕೃಷಿ ಹೊಂಡ, ಇತರ ಮೂಲಗಳಲ್ಲಿ ಲಭ್ಯವಿರುವ ನೀರನ್ನು ಬಳಸಿ ಸಂರಕ್ಷಣಾ ನೀರಾವರಿ ಕೊಡುವುದು. ಮಣ್ಣಿನ ತೇವಾಂಶವನ್ನು ಸಂರಕ್ಷಿಸಲು ತೆಂಗಿನ ಚಿಪ್ಪುಗಳು ಅಥವಾ ಗರಿಗಳಿಂದ ಮೇಲೊದಿಕೆ ಮಾಡುವುದು', 'ಸುಳಿಕೊರೆಯುವ ರೈನೋಸರಸ್ ದುಂಬಿಯ ಬಾಧೆ ಕಂಡುಬಂದಲ್ಲಿ
• ಎಳೆಯ ವಯಸ್ಸಿನ ಗಿಡಗಳ ಎಲೆಗಳನ್ನು ಒಟ್ಟುಗೂಡಿಸಿ ಕಟ್ಟವುದು ಉತ್ತಮ
• ಸುಳಿಯ ಭಾಗದ ರಂಧ್ರದಲ್ಲಿ ಕಬ್ಬಿಣದ ಕೊಕ್ಕೆಯನ್ನು ತೂರಿಸಿ ದುಂಬಿಗಳನ್ನು ಹೊರ ತೆಗೆದು ಸಾಯಿಸುವುದು 
• ಒಳ 2-3 ಗಿರಿಗಳ ಬುಡದಲ್ಲಿ 250 ಗ್ರಾಂ. ಕಹಿ ಬೇವಿನ ಹಿಂಡಿಯೊಂದಿಗೆ ಅಲ್ಪ ಪ್ರಮಾಣದ ಮರಳನ್ನು ಸೇರಿಸಿ ಹಾಕುವುದು
• ಪ್ರತಿ ಹೆಕ್ಟೇರ್‌ಗೆ 1 ಸಿ.ಪಿ. ಸಿ.ಆರ್.ಐ. ಮಾದರಿ ಮೋಹಕ ಬಲೆಗಳನ್ನು ಇಡುವುದು
• ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ 2 ಮಿ.ಲೀ. ಕ್ಲೋರೋಪೈರಿಫಾಸ್ ಅನ್ನು ಬೆರೆಸಿ 3 ಘನ.ಮೀ.ಕಾಂಪೋಸ್ಟ್ ಗುಂಡಿಗಳಿಗೆ ಉಪಯೋಗಿಸುವುದು', 'Provide shade to protect plants from the sun, and provide conservation irrigation using water available from agricultural wells and other sources. Mulch with coconut shells or feathers to conserve soil moisture.', 'If you find a problem with Rhinoceroses borer
• It is better to collect and tie the leaves of young plants
• Insert an iron hook into the hole in the borer and kill the borers 
• At the base of the inner 2-3 ridges, add 250 gm. of bitter neem powder along with a small amount of sand
• Place 1 C.P. C.R.I. type trap per hectare
• Mix 2 ml. Chlorpyrifos per liter of water and use it for 3 cubic meters of compost pits', 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7055, 'COCONUT', 21, N'<1', N'April-May', N'April-May', N'4,5', N'Vegetative stage', N'7', 'ABOVE NORMAL', 'YES', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', NULL, 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field.', NULL, 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7056, 'COCONUT', 21, N'<1', N'April-May', N'April-May', N'4,5', N'Vegetative stage', N'7', 'ABOVE NORMAL', 'NO', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', 'ಕೆಂಪು ಮೂತಿಯ ದುಂಬಿ ಭಾದೆ ಕಂಡು ಬಂದಲ್ಲಿ ಹುಳುವಿರುವ ಕಡೆ ಒಂದು ರಂಧ್ರವನ್ನು ಮಾಡಿ ಅದಕ್ಕೆ 4 ಮಿ.ಲೀ. ಕ್ಲೋರಾಂಟ್ರನಿಲಿಪ್ರೋಲ್ 18.5 SC ಅಥವಾ 4 ಮಿ.ಲೀ. ಇಂಡಾಕ್ಸಾಕಾರ್ಬ 14.5 SC ಅನ್ನು ಪ್ರತಿ ಲೀಟರ್ ನೀರಿನಲ್ಲಿ ಬೆರೆಸಿ ಸುರಿಯುವುದು', 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field.', 'If red-nosed beetle infestation is found, make a hole in the area where the worm is and pour 4 ml. Chlorantraniliprole 18.5 SC or 4 ml. Indoxacarb 14.5 SC mixed in every liter of water', 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7057, 'COCONUT', 21, N'1-4', N'May-June', N'May-June', N'5,6', N'Vegetative stage', N'2', 'NORMAL', 'YES', 'ತೋಟದ ಮಧ್ಯೆ ಉಳುಮೆ ಮಾಡಿ ಮರದ ಸುತ್ತಲು ಪಾತಿ ಮಾಡಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ಕೊಟ್ಟಿಗೆ ಗೊಬ್ಬರ ಮತ್ತು LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ರಸಗೊಬ್ಬರವನ್ನು ಕೊಡುವುದು', NULL, 'Plowing the middle of the garden, making a bed around the tree, applying the recommended manure and fertilizer based on the LRI', NULL, 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
