INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7730, 'MANGO (MID VARIETIES)', NULL, N'>4', N'May-June', N'May-June', N'5,6', N'Fruit maturity stage', N'5', 'ABOVE NORMAL', 'NO', 'ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ತೋಟದಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದು ಕೃಷಿ ಹೊಂಡಗಳಲ್ಲಿ ಶೇಖರಿಸಲು ಅನುವುಮಾಡಿಕೊಡಿ', NULL, 'If there is heavy rainfall, allow water to drain from the garden and store in agricultural pits.', NULL, 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7768, 'GRAPES', 30, N'<1', N'October-January', N'October-November-December-January', N'10,11,12,1', N'Planting', N'1', 'NORMAL', 'YES', '• ಉತ್ತಮವಾಗಿ ಬೇರು ಬಿಟ್ಟ ಮೂರು ಕಣ್ಣುಳ್ಳ ಕಡ್ಡಿಗಳನ್ನು ನಾಟಿ ಮಾಡುವುದು 
• ನಾಟಿಯ ನಂತರ LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ರಸಗೊಬ್ಬರವನ್ನು ಒದಗಿಸುವುದು', 'ಹಿಟ್ಟಿನ ತಿಗಣೆ ಮತ್ತು ಥ್ರಿಪ್ಸ್ ನುಶಿ ಕಂಡುಬಂದಲ್ಲಿ ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ 0.5 ಗ್ರಾಂ ಥೈಯೋಮಿಥಾಕ್ಸಾಮ್ 25 WG ಅಥವಾ 0.25 ಗ್ರಾಂ ಅಸಿಟಮಾಪ್ರಿಡ್ 75 SP ಅಥವಾ 1.0 ಮಿ.ಲೀ. ಬುಪ್ರೋಫೆಜಿನ್ 25 SC ಅಥವಾ 2 ಮಿ.ಲೀ. ಪ್ರೋಫೆನೊಪಾಸ್ 50 SP ಅನ್ನು ಬೆರೆಸಿ ಸಿಂಪಡಿಸುವುದು', '• Planting well-rooted three-eyed cuttings 
• Providing recommended fertilizer based on LRI after planting', 'If mealybugs and thrips are found, spray with 0.5 g Thiomethoxam 25 WG or 0.25 g Acetamaprid 75 SP or 1.0 ml Buprofezin 25 SC or 2 ml Profenopas 50 SP per liter of water', 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7769, 'GRAPES', 30, N'<1', N'October-January', N'October-November-December-January', N'10,11,12,1', N'Planting', N'1', 'NORMAL', 'NO', '• ಮಳೆಯ ಮುನ್ಸೂಚನೆಯನ್ನು ಗಮನದಲ್ಲಿಟ್ಟುಕೊಂಡು ಉತ್ತಮವಾಗಿ ಬೇರು ಬಿಟ್ಟ ಮೂರು ಕಣ್ಣುಳ್ಳ ಕಡ್ಡಿಗಳನ್ನು ನಾಟಿ ಮಾಡುವುದು
