INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7788, 'GRAPES', 30, N'<1', N'June-July', N'June-July', N'6,7', N'Vegetative stage', N'1', 'BELOW NORMAL', 'YES', '• ಬಳ್ಳಿಯನ್ನು ಚಪ್ಪರಕ್ಕೆ ಹಬ್ಬುವಂತೆ ಮಾಡುವುದು
• ತೋಟದ ಮಧ್ಯೆ ಉಳುಮೆ ಮಾಡಿ LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಲಾದ ರಸಗೊಬ್ಬರವನ್ನು ಒದಗಿಸುವುದು
• ಹಸಿರೆಲೆ ಗೊಬ್ಬರದ ಬೆಳೆ ಅಥವಾ ಅಂತರ ಬೆಳೆಗಳನ್ನು ಬಿತ್ತಬಹುದು', 'ಚಿಬ್ಬು ರೋಗದ ಹತೋಟಿಗಾಗಿ ಶೇ.1 ರ ಬೋರ್ಡೋ ದ್ರಾವಣ ಸಿಂಪಡಿಸುವುದು ನಂತರ ಪ್ರತಿ ಲೀಟರ್ ನೀರಿಗೆ 1 ಗ್ರಾಂ ಕಾರ್ಬೆಂಡಜಿಮ್ 50 WP ಅಥವಾ 1.5 ಮಿ.ಲೀ. ಡೈಫೆನೊಕೊನೋಜೋಲ್ 25 EC ಅಥವಾ 2.5 ಗ್ರಾಂ ಕಾಪರ್ ಆಕ್ಸಿಕ್ಲೋರೈಡ್ 50 WP ಅನ್ನು 10-15 ದಿನಗಳ ಅಂತರದಲ್ಲಿ ಸಿಂಪರಣೆ ಮಾಡುವುದು', '• Spread the vine over the field
• Plough the field and provide fertilizer as recommended based on LRI
• Green manure crops or intercrops can be sown', 'To control powdery mildew, spray 1% Bordeaux mixture followed by 1 gram Carbendazim 50 WP or 1.5 ml Difenoconazole 25 EC or 2.5 grams Copper Oxychloride 50 WP per liter of water at an interval of 10-15 days', 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
