INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7798, 'GRAPES', 30, N'1-3', N'June-July', N'June-July', N'6,7', N'Vegetative stage', N'1', 'NORMAL', 'YES', '• ಬಳ್ಳಿಯನ್ನು ಚಪ್ಪರಕ್ಕೆ ಹಬ್ಬುವಂತೆ ಮಾಡುವುದು (ಬಳ್ಳಿ ಹಬ್ಬಿಸುವುದು ಮತ್ತು ಕತ್ತರಿಸುವುದರ ಹೆಚ್ಚಿನ ಮಾಹಿತಿಗಾಗಿ ತಂತ್ರಾಂಶದಲ್ಲಿರುವ ಈ ಬೆಳೆಯ ಬೇಸಾಯ ಪದ್ದತಿಯನ್ನು ಅನುಸರಿಸಿ)
• ತೋಟದ ಮಧ್ಯೆ ಉಳುಮೆ ಮಾಡಿ LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಲಾದ ರಸಗೊಬ್ಬರವನ್ನು ಒದಗಿಸುವುದು
• ಹಸಿರೆಲೆ ಗೊಬ್ಬರದ ಬೆಳೆ ಅಥವಾ ಅಂತರ ಬೆಳೆಗಳನ್ನು ಬಿತ್ತಬಹುದು', NULL, '• Spread the vines on the flat (For more information on spreading and pruning, follow the cultivation method of this crop in the software)
