INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7806, 'GRAPES', 30, N'1-3', N'August-October', N'August-September-October', N'8,9,10', N'Vegetative stage', N'1', 'BELOW NORMAL', 'YES', '• ತೋಟದಲ್ಲಿ ಹಸಿರೆಲೆ ಗೊಬ್ಬರದ ಗಿಡಗಳನ್ನು ಬೆಳೆದಿದ್ದರೆ ಅವನ್ನು ಬಿತ್ತಿದ 45 ದಿನಗಳ ನಂತರ ಮಣ್ಣಿಗೆ ಸೇರಿಸುವುದು
• LRI ಶಿಫಾರಸ್ಸು ಮಾಡಲಾದ ರಸಗೊಬ್ಬರಗಳನ್ನು ಬಳ್ಳಿಗಳಿಗೆ ಒದಗಿಸುವುದು
• ತೋಟದ ಮಧ್ಯ ಅಂತರಬೆಳೆ ಬೆಳೆದಿದ್ದರೆ ಅವುಗಳಿಗೆ ತಗುಲುವ ರೋಗ ಮತ್ತು ಕೀಟಗಳ ಮೇಲೆ ಗಮನ ಹರಿಸುವುದು', 'ಚಿಬ್ಬು ರೋಗದ ಹತೋಟಿಗಾಗಿ ಶೇ.1 ರ ಬೋರ್ಡೋ ದ್ರಾವಣ ಸಿಂಪಡಿಸುವುದು ನಂತರ ಪ್ರತಿ ಲೀಟರ್ ನೀರಿಗೆ 1 ಗ್ರಾಂ ಕಾರ್ಬೆಂಡಜಿಮ್ 50 WP ಅಥವಾ 1.5 ಮಿ.ಲೀ. ಡೈಫೆನೊಕೊನೋಜೋಲ್ 25 EC ಅಥವಾ 2.5 ಗ್ರಾಂ ಕಾಪರ್ ಆಕ್ಸಿಕ್ಲೋರೈಡ್ 50 WP ಅನ್ನು 10-15 ದಿನಗಳ ಅಂತರದಲ್ಲಿ ಸಿಂಪರಣೆ ಮಾಡುವುದು', '• If green manure crops are grown in the garden, incorporate them into the soil 45 days after sowing
• Provide LRI recommended fertilizers to the vines
• If intercrops are grown in the garden, pay attention to the diseases and pests that they are susceptible to', 'To control powdery mildew, spray 1% Bordeaux mixture followed by 1 gram Carbendazim 50 WP or 1.5 ml Difenoconazole 25 EC or 2.5 grams Copper Oxychloride 50 WP per liter of water at an interval of 10-15 days', 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7807, 'GRAPES', 30, N'1-3', N'August-October', N'August-September-October', N'8,9,10', N'Vegetative stage', N'1', 'BELOW NORMAL', 'NO', 'ಕೃಷಿ ಹೊಂಡ, ಇತರ ಮೂಲಗಳಲ್ಲಿ ಲಭ್ಯವಿರುವ ನೀರನ್ನು ಬಳಸಿ ಸಂರಕ್ಷಣಾ ನೀರಾವರಿ ಕೊಡುವುದು. ಗಿಡದ ಸುತ್ತಲು ಒಣಗಿದ ಎಲೆಗಳಿಂದ ಮಣ್ಣಿನ ಮೇಲೊದಿಕೆ ಮಾಡುವುದರಿಂದ ಮಣ್ಣಿನ ತೇವಾಂಶವನ್ನು ಕಾಪಾಡಿಕೊಳ್ಳಬಹುದು', NULL, 'Conservation irrigation is done using water available from agricultural wells and other sources. Mulching the soil with dry leaves around the plant can help maintain soil moisture.', NULL, 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7808, 'GRAPES', 30, N'1-3', N'August-October', N'August-September-October', N'8,9,10', N'Vegetative stage', N'1', 'ABOVE NORMAL', 'YES', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', 'ಚಿಕ್ಕಟಿ ದುಂಬಿ, ಕಡಜಗಳು ಮತ್ತು ಎಲೆ ತಿನ್ನುವ ಕೀಟ ಕಂಡುಬಂದಲ್ಲಿ ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ 1.0 ಮಿ.ಲೀ. ಸೈಯಾಂಟ್ರನಿಲಿಪ್ರೋಲ್ 10.25 OD ಅಥವಾ 0.5 ಮಿ.ಲೀ. ಲಾಮ್ಡಾ ಸೈಲೋಥ್ರೀನ್ 4.9 CS ಅಥವಾ 2 ಮಿ.ಲೀ. ಕ್ವಿನಾಲ್‌ಫಾಸ್ 25 EC ಅನ್ನು ಬೆರೆಸಿ ಸಿಂಪಡಿಸುವುದು. ಕೇದಿಗೆ ರೋಗ ಕಂಡುಬಂದಲ್ಲಿ ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ 3.0 ಗ್ರಾಂ ತಾಮ್ರದ ಆಕ್ಸಿಕ್ಲೋರೈಡ್ 50 WP ಅಥವಾ 2 ಗ್ರಾಂ ಸೈಮಾಕ್ಸಿನಿಲ್‍ 8+ ಮ್ಯಾಂಕೋಜೆಬ್‍ 64 WP ಅಥವಾ 2.5 ಗ್ರಾಂ ಫ್ಲೂಪಿಕೊಲೈಡ್ 4.44+ಫಾಸಿಟಾಲ್‍ AL 66.67 WG ಅನ್ನು ಬೆರೆಸಿ ಸಿಂಪಡಿಸುವುದು', 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field.', 'If small beetles, aphids and leaf-eating insects are found, spray 1.0 ml of Cyanthraniliprol 10.25 OD or 0.5 ml of Lambda Cylothrin 4.9 CS or 2 ml of Quinalphos 25 EC per liter of water. If disease is found in the field, spray 3.0 g of Copper Oxychloride 50 WP or 2 g of Cymaxinil 8+ Mancozeb 64 WP or 2.5 g of Flupicolide 4.44+Fasitol AL 66.67 WG per liter of water', 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7809, 'GRAPES', 30, N'1-3', N'August-October', N'August-September-October', N'8,9,10', N'Vegetative stage', N'1', 'ABOVE NORMAL', 'NO', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', NULL, 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field.', NULL, 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7810, 'GRAPES', 30, N'1-3', N'November-December', N'November-December', N'11,12', N'Vegetative stage', N'1', 'NORMAL', 'YES', '• ಬಳ್ಳಿಯಲ್ಲಿನ ಅನಗತ್ಯ ಕೊಂಬೆಗಳನ್ನು ಕತ್ತರಿಸಿ ತೆಗೆದುಹಾಕಿ ಮುಖ್ಯ ಕೊಂಬೆಗಳನ್ನು ಮಾತ್ರ ಚಪ್ಪರಕ್ಕೆ ಹಬ್ಬಿಸುವುದರ ಮೂಲಕ ಬಳ್ಳಿಗಳಿಗೆ ನಿಖರ ಆಕಾರದಲ್ಲಿ ಬೆಳೆಯುವಂತೆ ಮಾಡುವುದು (ಬಳ್ಳಿ ಹಬ್ಬಿಸುವುದು ಮತ್ತು ಕತ್ತರಿಸುವುದರ ಹೆಚ್ಚಿನ ಮಾಹಿತಿಗಾಗಿ ತಂತ್ರಾಂಶದಲ್ಲಿರುವ ಈ ಬೆಳೆಯ ಬೇಸಾಯ ಪದ್ದತಿಯನ್ನು ಅನುಸರಿಸಿ)
• ಸಸ್ಯದ ಬೆಳವಣಿಗೆಯನ್ನು ಉತ್ತೇಜಿಸಲು ಹೂ ಗೊಂಚಲು ಕಂಡಲ್ಲಿ ಅವುಗಳನ್ನು ತೆಗೆಯುವುದು', 'ಹಿಟ್ಟಿನ ತಿಗಣೆ ಮತ್ತು ಥ್ರಿಪ್ಸ್ ನುಶಿ ಕಂಡುಬಂದಲ್ಲಿ ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ 0.5 ಗ್ರಾಂ ಥೈಯೋಮಿಥಾಕ್ಸಾಮ್ 25 WG ಅಥವಾ 0.25 ಗ್ರಾಂ ಅಸಿಟಮಾಪ್ರಿಡ್ 75 SP ಅಥವಾ 1.0 ಮಿ.ಲೀ. ಬುಪ್ರೋಫೆಜಿನ್ 25 SC ಅಥವಾ 2 ಮಿ.ಲೀ. ಪ್ರೋಫೆನೊಪಾಸ್ 50 SP ಅನ್ನು ಬೆರೆಸಿ ಸಿಂಪಡಿಸುವುದು. ಬೂದಿ ರೋಗ ಕಂಡುಬಂದಲ್ಲಿ ಲೀ. ನೀರಿಗೆ 3.0 ಗ್ರಾಂ ನೀರಿನಲ್ಲಿ ಕರಗುವ ಗಂಧಕದ ಪುಡಿ ಅಥವಾ 2.0 ಗ್ರಾಂ ಟ್ರೆಡೆಮೆಫಾನ್ 25 WP ಅಥವಾ 1.0 ಗ್ರಾಂ ಕಾರ್ಬೆಂಡಜಿಂ 50 WP ಅಥವಾ 0.5 ಗ್ರಾಂ ಮೈಕ್ಲೋಬ್ಯೂಟಾನಿಲ್ 10 WP ಅನ್ನು ಸೇರಿಸಿ ಸಿಂಪಡಿಸುವುದು', '• Prune away unwanted branches from the vine and spread only the main branches to the ground to help the vines grow in the correct shape (for more information on spreading and pruning, follow the cultivation method of this crop in the software)
• Remove flower clusters if they appear to encourage plant growth', 'If mealybugs and thrips are found, spray 0.5 g Thiomethoxam 25 WG or 0.25 g Acetamaprid 75 SP or 1.0 ml Buprofezin 25 SC or 2 ml Profenopas 50 SP per liter of water. If powdery mildew is found, spray 3.0 g water-soluble sulfur powder or 2.0 g Tredemefon 25 WP or 1.0 g Carbendazim 50 WP or 0.5 g Myclobutanil 10 WP per liter of water', 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7811, 'GRAPES', 30, N'1-3', N'November-December', N'November-December', N'11,12', N'Vegetative stage', N'1', 'NORMAL', 'NO', '• ಬಳ್ಳಿಯಲ್ಲಿನ ಅನಗತ್ಯ ಕೊಂಬೆಗಳನ್ನು ಕತ್ತರಿಸಿ ತೆಗೆದುಹಾಕಿ ಮುಖ್ಯ ಕೊಂಬೆಗಳನ್ನು ಮಾತ್ರ ಚಪ್ಪರಕ್ಕೆ ಹಬ್ಬಿಸುವುದರ ಮೂಲಕ ಬಳ್ಳಿಗಳಿಗೆ ನಿಖರ ಆಕಾರದಲ್ಲಿ ಬೆಳೆಯುವಂತೆ ಮಾಡುವುದು (ಬಳ್ಳಿ ಹಬ್ಬಿಸುವುದು ಮತ್ತು ಕತ್ತರಿಸುವುದರ ಹೆಚ್ಚಿನ ಮಾಹಿತಿಗಾಗಿ ತಂತ್ರಾಂಶದಲ್ಲಿರುವ ಈ ಬೆಳೆಯ ಬೇಸಾಯ ಪದ್ದತಿಯನ್ನು ಅನುಸರಿಸಿ)
• ಸಸ್ಯದ ಬೆಳವಣಿಗೆಯನ್ನು ಉತ್ತೇಜಿಸಲು ಹೂ ಗೊಂಚಲು ಕಂಡಲ್ಲಿ ಅವುಗಳನ್ನು ತೆಗೆಯುವುದು', 'ಹಿಟ್ಟಿನ ತಿಗಣೆ ಮತ್ತು ಥ್ರಿಪ್ಸ್ ನುಶಿ ಕಂಡುಬಂದಲ್ಲಿ ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ 0.5 ಗ್ರಾಂ ಥೈಯೋಮಿಥಾಕ್ಸಾಮ್ 25 WG ಅಥವಾ 0.25 ಗ್ರಾಂ ಅಸಿಟಮಾಪ್ರಿಡ್ 75 SP ಅಥವಾ 1.0 ಮಿ.ಲೀ. ಬುಪ್ರೋಫೆಜಿನ್ 25 SC ಅಥವಾ 2 ಮಿ.ಲೀ. ಪ್ರೋಫೆನೊಪಾಸ್ 50 SP ಅನ್ನು ಬೆರೆಸಿ ಸಿಂಪಡಿಸುವುದು. ಬೂದಿ ರೋಗ ಕಂಡುಬಂದಲ್ಲಿ ಲೀ. ನೀರಿಗೆ 3.0 ಗ್ರಾಂ ನೀರಿನಲ್ಲಿ ಕರಗುವ ಗಂಧಕದ ಪುಡಿ ಅಥವಾ 2.0 ಗ್ರಾಂ ಟ್ರೆಡೆಮೆಫಾನ್ 25 WP ಅಥವಾ 1.0 ಗ್ರಾಂ ಕಾರ್ಬೆಂಡಜಿಂ 50 WP ಅಥವಾ 0.5 ಗ್ರಾಂ ಮೈಕ್ಲೋಬ್ಯೂಟಾನಿಲ್ 10 WP ಅನ್ನು ಸೇರಿಸಿ ಸಿಂಪಡಿಸುವುದು', '• Prune away unwanted branches from the vine and spread only the main branches to the ground to help the vines grow in the correct shape (for more information on spreading and pruning, follow the cultivation method of this crop in the software)
• Remove flower clusters if they appear to encourage plant growth', 'If mealybugs and thrips are found, spray 0.5 g Thiomethoxam 25 WG or 0.25 g Acetamaprid 75 SP or 1.0 ml Buprofezin 25 SC or 2 ml Profenopas 50 SP per liter of water. If powdery mildew is found, spray 3.0 g water-soluble sulfur powder or 2.0 g Tredemefon 25 WP or 1.0 g Carbendazim 50 WP or 0.5 g Myclobutanil 10 WP per liter of water', 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
