INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7813, 'GRAPES', 30, N'1-3', N'November-December', N'November-December', N'11,12', N'Vegetative stage', N'1', 'BELOW NORMAL', 'NO', '• ಬಳ್ಳಿಯಲ್ಲಿನ ಅನಗತ್ಯ ಕೊಂಬೆಗಳನ್ನು ಕತ್ತರಿಸಿ ತೆಗೆದುಹಾಕಿ ಮುಖ್ಯ ಕೊಂಬೆಗಳನ್ನು ಮಾತ್ರ ಚಪ್ಪರಕ್ಕೆ ಹಬ್ಬಿಸುವುದರ ಮೂಲಕ ಬಳ್ಳಿಗಳಿಗೆ ನಿಖರ ಆಕಾರದಲ್ಲಿ ಬೆಳೆಯುವಂತೆ ಮಾಡುವುದು (ಬಳ್ಳಿ ಹಬ್ಬಿಸುವುದು ಮತ್ತು ಕತ್ತರಿಸುವುದರ ಹೆಚ್ಚಿನ ಮಾಹಿತಿಗಾಗಿ ತಂತ್ರಾಂಶದಲ್ಲಿರುವ ಈ ಬೆಳೆಯ ಬೇಸಾಯ ಪದ್ದತಿಯನ್ನು ಅನುಸರಿಸಿ)
• ಕೃಷಿ ಹೊಂಡ, ಇತರ ಮೂಲಗಳಲ್ಲಿ ಲಭ್ಯವಿರುವ ನೀರನ್ನು ಬಳಸಿ ಸಂರಕ್ಷಣಾ ನೀರಾವರಿ ಕೊಡುವುದು. ಗಿಡದ ಸುತ್ತಲು ಒಣಗಿದ ಎಲೆಗಳಿಂದ ಮಣ್ಣಿನ ಮೇಲೊದಿಕೆ ಮಾಡುವುದರಿಂದ ಮಣ್ಣಿನ ತೇವಾಂಶವನ್ನು ಕಾಪಾಡಿಕೊಳ್ಳಬಹುದು', NULL, '• Prune the vines to get the right shape by pruning and spreading only the main branches (for more information on pruning and pruning, follow the crop cultivation method in the software)
• Provide conservation irrigation using water available from agricultural wells and other sources. Mulching the soil around the plant with dry leaves can help maintain soil moisture.', NULL, 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7814, 'GRAPES', 30, N'1-3', N'November-December', N'November-December', N'11,12', N'Vegetative stage', N'1', 'ABOVE NORMAL', 'YES', '• ಬಳ್ಳಿಯಲ್ಲಿನ ಅನಗತ್ಯ ಕೊಂಬೆಗಳನ್ನು ಕತ್ತರಿಸಿ ತೆಗೆದುಹಾಕಿ ಮುಖ್ಯ ಕೊಂಬೆಗಳನ್ನು ಮಾತ್ರ ಚಪ್ಪರಕ್ಕೆ ಹಬ್ಬಿಸುವುದರ ಮೂಲಕ ಬಳ್ಳಿಗಳಿಗೆ ನಿಖರ ಆಕಾರದಲ್ಲಿ ಬೆಳೆಯುವಂತೆ ಮಾಡುವುದು (ಬಳ್ಳಿ ಹಬ್ಬಿಸುವುದು ಮತ್ತು ಕತ್ತರಿಸುವುದರ ಹೆಚ್ಚಿನ ಮಾಹಿತಿಗಾಗಿ ತಂತ್ರಾಂಶದಲ್ಲಿರುವ ಈ ಬೆಳೆಯ ಬೇಸಾಯ ಪದ್ದತಿಯನ್ನು ಅನುಸರಿಸಿ)
• ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', NULL, '• Trim away unwanted branches from the vine and spread only the main branches to the ground to help the vines grow in the correct shape (for more information on spreading and pruning, follow the crop cultivation method in the software)
• If there has been heavy rainfall in the past few days, allow the water to drain away from the field', NULL, 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7815, 'GRAPES', 30, N'1-3', N'November-December', N'November-December', N'11,12', N'Vegetative stage', N'1', 'ABOVE NORMAL', 'NO', '• ಬಳ್ಳಿಯಲ್ಲಿನ ಅನಗತ್ಯ ಕೊಂಬೆಗಳನ್ನು ಕತ್ತರಿಸಿ ತೆಗೆದುಹಾಕಿ ಮುಖ್ಯ ಕೊಂಬೆಗಳನ್ನು ಮಾತ್ರ ಚಪ್ಪರಕ್ಕೆ ಹಬ್ಬಿಸುವುದರ ಮೂಲಕ ಬಳ್ಳಿಗಳಿಗೆ ನಿಖರ ಆಕಾರದಲ್ಲಿ ಬೆಳೆಯುವಂತೆ ಮಾಡುವುದು (ಬಳ್ಳಿ ಹಬ್ಬಿಸುವುದು ಮತ್ತು ಕತ್ತರಿಸುವುದರ ಹೆಚ್ಚಿನ ಮಾಹಿತಿಗಾಗಿ ತಂತ್ರಾಂಶದಲ್ಲಿರುವ ಈ ಬೆಳೆಯ ಬೇಸಾಯ ಪದ್ದತಿಯನ್ನು ಅನುಸರಿಸಿ)
• ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', NULL, '• Trim away unwanted branches from the vine and spread only the main branches to the ground to help the vines grow in the correct shape (for more information on spreading and pruning, follow the crop cultivation method in the software)
• If there has been heavy rainfall in the past few days, allow the water to drain away from the field', NULL, 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7816, 'GRAPES', 30, N'1-3', N'January-February', N'January-February', N'1,2', N'Vegetative stage', N'1', 'NORMAL', 'YES', 'ಸೂಚಿಸಲಾದ ಸಸ್ಯ ಸಂರಕ್ಷಣಾ ಕ್ರಮಗಳನ್ನು ಕೈಗೊಳ್ಳುವುದು', 'ಚಿಕ್ಕಟಿ ದುಂಬಿ, ಕಡಜಗಳು ಮತ್ತು ಎಲೆ ತಿನ್ನುವ ಕೀಟ ಕಂಡುಬಂದರೆ ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ 1.0 ಮಿ.ಲೀ. ಸೈಯಾಂಟ್ರನಿಲಿಪ್ರೋಲ್ 10.25 OD ಅಥವಾ 0.5 ಮಿ.ಲೀ. ಲಾಮ್ಡಾ ಸೈಲೋಥ್ರೀನ್ 4.9 CS ಅಥವಾ 2 ಮಿ.ಲೀ. ಕ್ವಿನಾಲ್‌ಫಾಸ್ 25 EC ಅನ್ನು ಸೇರಿಸಿ ಸಿಂಪಡಿಸುವುದು. ಕೇದಿಗೆ ರೋಗ ಕಂಡುಬಂದಲ್ಲಿ ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ 3.0 ಗ್ರಾಂ ತಾಮ್ರದ ಆಕ್ಸಿಕ್ಲೋರೈಡ್ 50 WP ಅಥವಾ 2 ಗ್ರಾಂ ಸೈಮಾಕ್ಸಿನಿಲ್‍ 8+ ಮ್ಯಾಂಕೋಜೆಬ್‍ 64 WP ಅಥವಾ 2.5 ಗ್ರಾಂ ಫ್ಲೂಪಿಕೊಲೈಡ್ 4.44+ಫಾಸಿಟಾಲ್‍ AL 66.67 WG ಅನ್ನು ಬೆರೆಸಿ ಸಿಂಪಡಿಸುವುದು', 'Carrying out the recommended plant protection measures', 'If small beetles, aphids and leaf-eating insects are found, spray 1.0 ml. Cyanthraniliprol 10.25 OD or 0.5 ml. Lambda Cylothrin 4.9 CS or 2 ml. Quinalphos 25 EC per liter of water. If disease is found in the sorghum, spray 3.0 gm. Copper Oxychloride 50 WP or 2 gm. Cymaxinil 8+ Mancozeb 64 WP or 2.5 gm. Flupicolide 4.44+Fasitol AL 66.67 WG per liter of water', 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7817, 'GRAPES', 30, N'1-3', N'January-February', N'January-February', N'1,2', N'Vegetative stage', N'1', 'NORMAL', 'NO', 'ಸೂಚಿಸಲಾದ ಸಸ್ಯ ಸಂರಕ್ಷಣಾ ಕ್ರಮಗಳನ್ನು ಕೈಗೊಳ್ಳುವುದು', 'ಚಿಕ್ಕಟಿ ದುಂಬಿ, ಕಡಜಗಳು ಮತ್ತು ಎಲೆ ತಿನ್ನುವ ಕೀಟ ಕಂಡುಬಂದರೆ ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ 1.0 ಮಿ.ಲೀ. ಸೈಯಾಂಟ್ರನಿಲಿಪ್ರೋಲ್ 10.25 OD ಅಥವಾ 0.5 ಮಿ.ಲೀ. ಲಾಮ್ಡಾ ಸೈಲೋಥ್ರೀನ್ 4.9 CS ಅಥವಾ 2 ಮಿ.ಲೀ. ಕ್ವಿನಾಲ್‌ಫಾಸ್ 25 EC ಅನ್ನು ಸೇರಿಸಿ ಸಿಂಪಡಿಸುವುದು. ಕೇದಿಗೆ ರೋಗ ಕಂಡುಬಂದಲ್ಲಿ ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ 3.0 ಗ್ರಾಂ ತಾಮ್ರದ ಆಕ್ಸಿಕ್ಲೋರೈಡ್ 50 WP ಅಥವಾ 2 ಗ್ರಾಂ ಸೈಮಾಕ್ಸಿನಿಲ್‍ 8+ ಮ್ಯಾಂಕೋಜೆಬ್‍ 64 WP ಅಥವಾ 2.5 ಗ್ರಾಂ ಫ್ಲೂಪಿಕೊಲೈಡ್ 4.44+ಫಾಸಿಟಾಲ್‍ AL 66.67 WG ಅನ್ನು ಬೆರೆಸಿ ಸಿಂಪಡಿಸುವುದು', 'Carrying out the recommended plant protection measures', 'If small beetles, aphids and leaf-eating insects are found, spray 1.0 ml. Cyanthraniliprol 10.25 OD or 0.5 ml. Lambda Cylothrin 4.9 CS or 2 ml. Quinalphos 25 EC per liter of water. If disease is found in the sorghum, spray 3.0 gm. Copper Oxychloride 50 WP or 2 gm. Cymaxinil 8+ Mancozeb 64 WP or 2.5 gm. Flupicolide 4.44+Fasitol AL 66.67 WG per liter of water', 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7818, 'GRAPES', 30, N'1-3', N'January-February', N'January-February', N'1,2', N'Vegetative stage', N'1', 'BELOW NORMAL', 'YES', 'ಪ್ರಸ್ತುತ ಹಂತದಲ್ಲಿ ಬೆಳೆ ಉತ್ತಮವಾಗಿದ್ದರೆ, ಇತರೆ ಬೆಳೆ ಬೆಳೆದಿದ್ದಲ್ಲಿ ಅವುಗಳ ನಿರ್ವಹಣೆಯತ್ತ ಗಮನಹರಿಸುವುದು', NULL, 'If the crop is good at the current stage, focus on managing other crops if they have grown.', NULL, 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
