INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7823, 'GRAPES', 30, N'1-3', N'February-March', N'March', N'3', N'Vegetative stage', N'1', 'NORMAL', 'NO', 'ಪ್ರಸ್ತುತ ಹಂತದಲ್ಲಿ ಬೆಳೆ ಉತ್ತಮವಾಗಿದ್ದರೆ, ಇತರೆ ಬೆಳೆ ಬೆಳೆದಿದ್ದಲ್ಲಿ ಅವುಗಳ ನಿರ್ವಹಣೆಯತ್ತ ಗಮನಹರಿಸುವುದು', NULL, 'If the crop is good at the current stage, focus on managing other crops if they have grown.', NULL, 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7824, 'GRAPES', 30, N'1-3', N'February-March', N'March', N'3', N'Vegetative stage', N'1', 'BELOW NORMAL', 'YES', 'ಪ್ರಸ್ತುತ ಹಂತದಲ್ಲಿ ಬೆಳೆ ಉತ್ತಮವಾಗಿದ್ದರೆ, ಇತರೆ ಬೆಳೆ ಬೆಳೆದಿದ್ದಲ್ಲಿ ಅವುಗಳ ನಿರ್ವಹಣೆಯತ್ತ ಗಮನಹರಿಸುವುದು', NULL, 'If the crop is good at the current stage, focus on managing other crops if they have grown.', NULL, 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7853, 'GRAPES', 30, N'>3', N'January-February', N'January-February', N'1,2', N'Fruit set and development', N'6', 'NORMAL', 'NO', 'ಕಾಯಿ ಕಚ್ಚುವ ಹಂತದಲ್ಲಿ ಗೊಂಚಲುಗಳನ್ನು 50 ಮಿ. ಗ್ರಾಂ. ಜಿಬ್ಬರ್ಲಿಕ್ ಆಮ್ಲ 1 ಲೀಟರ್ ನೀರಿನಲ್ಲಿ ಬೆರೆಸಿ ಅದ್ದುವುದರಿಂದ ಹಣ್ಣುಗಳ ಗಾತ್ರ ದ್ವಿಗುಣಗೊಳ್ಳುವುದು', 'ಬೂದಿ ರೋಗ ಕಂಡುಬಂದಲ್ಲಿ ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ 3.0 ಗ್ರಾಂ ನೀರಿನಲ್ಲಿ ಕರಗುವ ಗಂಧಕದ ಪುಡಿ ಅಥವಾ 2.0 ಗ್ರಾಂ ಟ್ರೆಡೆಮೆಫಾನ್ 25 WP ಅಥವಾ 1.0 ಗ್ರಾಂ ಕಾರ್ಬೆಂಡಜಿಂ 50 WP ಅಥವಾ 0.5 ಗ್ರಾಂ ಮೈಕ್ಲೋಬ್ಯೂಟಾನಿಲ್ 10 WP ಅನ್ನು ಬೆರೆಸಿ ಸಿಂಪಡಿಸುವುದು', 'At the stage of fruit set, the clusters are dipped in 50 mg. of Gibberellic acid mixed in 1 liter of water to double the size of the fruits.', 'If powdery mildew is found, spray with 3.0 g water-soluble sulfur powder or 2.0 g tredemefon 25 WP or 1.0 g carbendazim 50 WP or 0.5 g myclobutanil 10 WP per liter of water', 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7854, 'GRAPES', 30, N'>3', N'January-February', N'January-February', N'1,2', N'Fruit set and development', N'6', 'BELOW NORMAL', 'YES', 'ಕಾಯಿ ಕಚ್ಚುವ ಹಂತದಲ್ಲಿ ಗೊಂಚಲುಗಳನ್ನು 50 ಮಿ. ಗ್ರಾಂ. ಜಿಬ್ಬರ್ಲಿಕ್ ಆಮ್ಲ 1 ಲೀಟರ್ ನೀರಿನಲ್ಲಿ ಬೆರೆಸಿ ಅದ್ದುವುದರಿಂದ ಹಣ್ಣುಗಳ ಗಾತ್ರ ದ್ವಿಗುಣಗೊಳ್ಳುವುದು', NULL, 'At the stage of fruit set, the clusters are dipped in 50 mg. of Gibberellic acid mixed in 1 liter of water to double the size of the fruits.', NULL, 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7855, 'GRAPES', 30, N'>3', N'January-February', N'January-February', N'1,2', N'Fruit set and development', N'6', 'BELOW NORMAL', 'NO', 'ಕೃಷಿ ಹೊಂಡ, ಇತರ ಮೂಲಗಳಲ್ಲಿ ಲಭ್ಯವಿರುವ ನೀರನ್ನು ಬಳಸಿ ಸಂರಕ್ಷಣಾ ನೀರಾವರಿ ಕೊಡುವುದು', NULL, 'Conservation irrigation using water available from agricultural wells and other sources', NULL, 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7856, 'GRAPES', 30, N'>3', N'January-February', N'January-February', N'1,2', N'Fruit set and development', N'6', 'ABOVE NORMAL', 'YES', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', NULL, 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field.', NULL, 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7857, 'GRAPES', 30, N'>3', N'January-February', N'January-February', N'1,2', N'Fruit set and development', N'6', 'ABOVE NORMAL', 'NO', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', NULL, 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field.', NULL, 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7858, 'GRAPES', 30, N'>3', N'February-March', N'March', N'3', N'Fruit maturity', N'7', 'NORMAL', 'YES', 'ಹಣ್ಣಾದ ಗೊಂಚಲುಗಳನ್ನು ಕೊಯ್ಲು ಮಾಡುವುದು', 'ಹಿಟ್ಟಿನ ತಿಗಣೆ ಮತ್ತು ಥ್ರಿಪ್ಸ್ ನುಶಿ ಕಂಡುಬಂದಲ್ಲಿ ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ 0.5 ಗ್ರಾಂ ಥೈಯೋಮಿಥಾಕ್ಸಾಮ್ 25 WG ಅಥವಾ 0.25 ಗ್ರಾಂ ಅಸಿಟಮಾಪ್ರಿಡ್ 75 SP ಅಥವಾ 1.0 ಮಿ.ಲೀ. ಬುಪ್ರೋಫೆಜಿನ್ 25 SC ಅಥವಾ 2 ಮಿ.ಲೀ. ಪ್ರೋಫೆನೊಪಾಸ್ 50 SP ಅನ್ನು ಬೆರೆಸಿ ಸಿಂಪಡಿಸುವುದು. ಬೂದಿ ರೋಗ ಕಂಡುಬಂದಲ್ಲಿ ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ 3.0 ಗ್ರಾಂ ನೀರಿನಲ್ಲಿ ಕರಗುವ ಗಂಧಕದ ಪುಡಿ ಅಥವಾ 2.0 ಗ್ರಾಂ ಟ್ರೆಡೆಮೆಫಾನ್ 25 WP ಅಥವಾ 1.0 ಗ್ರಾಂ ಕಾರ್ಬೆಂಡಜಿಂ 50 WP ಅಥವಾ 0.5 ಗ್ರಾಂ ಮೈಕ್ಲೋಬ್ಯೂಟಾನಿಲ್ 10 WP ಅನ್ನು ಬೆರೆಸಿ ಸಿಂಪಡಿಸುವುದು', 'Harvesting ripe clusters', 'If mealybugs and thrips are found, spray 0.5 g Thiomethoxam 25 WG or 0.25 g Acetamaprid 75 SP or 1.0 ml Buprofezin 25 SC or 2 ml Profenopas 50 SP per liter of water. If powdery mildew is found, spray 3.0 g water soluble sulfur powder or 2.0 g Tredemefon 25 WP or 1.0 g Carbendazim 50 WP or 0.5 g Myclobutanil 10 WP per liter of water', 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7886, 'POMEGRANATE', NULL, N'<1', N'September-October', N'September-October', N'9,10', N'Vegetative stage', N'2', 'BELOW NORMAL', 'NO', '• ಕೃಷಿ ಹೊಂಡ, ಇತರ ಮೂಲಗಳಲ್ಲಿ ಲಭ್ಯವಿರುವ ನೀರನ್ನು ಬಳಸಿ ನೀರಾವರಿ ಕೊಡುವುದು
• ತೋಟದಲ್ಲಿ ಅಂತರ ಬೇಸಾಯದ ಮೂಲಕ ಕಳೆ ನಿರ್ವಹಣೆ ಮಾಡಿ LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ರಸಗೊಬ್ಬರಗಳನ್ನು ಒದಗಿಸುವುದು
• ಪ್ರಸ್ತುತ ಹಂತದಲ್ಲಿ ಬೆಳೆ ಉತ್ತಮವಾಗಿದ್ದರೆ, ಇತರೆ ಬೆಳೆ ಬೆಳೆದಿದ್ದಲ್ಲಿ ಅವುಗಳ ನಿರ್ವಹಣೆಯತ್ತ ಗಮನಹರಿಸುವುದು', NULL, '• Irrigation using water available from agricultural wells and other sources
• Weed management through intercropping in the garden and providing fertilizers recommended based on LRI
• If the crop is good at the current stage, focus on managing other crops if they are grown', NULL, 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7887, 'POMEGRANATE', NULL, N'<1', N'September-October', N'September-October', N'9,10', N'Vegetative stage', N'2', 'ABOVE NORMAL', 'YES', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', 'ಸಸ್ಯ ಹೇನು, ಹಿಟ್ಟುತಿಗಣೆ, ಬಿಳಿನೊಣ, ಥ್ರಿಪ್ಸ್ ನುಸಿ ನಿಯಂತ್ರಣಕ್ಕಾಗಿ ಪ್ರತಿ ಲೀಟರ್ ನೀರಿಗೆ 0.2 ಗ್ರಾಂ ಥೈಯೋಮಿಥಾಕ್ಸಾಮ್ 25 WG ಅಥವಾ 0.25 ಮಿ.ಲೀ. ಇಮಿಡಾಕ್ಲೋಪ್ರಿಡ್ 200 SL ಅನ್ನು ಬೆರೆಸಿ ಸಿಂಪಡಿಸುವುದು', 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field.', 'Spraying with 0.2 g Thiomethoxam 25 WG or 0.25 ml Imidacloprid 200 SL per liter of water for the control of aphids, mealybugs, whiteflies, and thrips', 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7888, 'POMEGRANATE', NULL, N'<1', N'September-October', N'September-October', N'9,10', N'Vegetative stage', N'2', 'ABOVE NORMAL', 'NO', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', NULL, 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field.', NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7889, 'POMEGRANATE', NULL, N'<1', N'November-December', N'November-December', N'11,12', N'Vegetative stage', N'2', 'NORMAL', 'YES', 'ಗಿಡಗಳಿಗೆ ಆಕಾರ ಒದಗಿಸಲು 3-4 ಮುಖ್ಯ ರೆಂಬೆಗಳನ್ನು ಉಳಿಸಿಕೊಂಡು ಅನಗತ್ಯ ರೆಂಬೆಗಳನ್ನು ಕತ್ತರಿಸುವುದು (ಹೆಚ್ಚಿನ ಮಾಹಿತಿಗಾಗಿ ತಂತ್ರಾಂಶದಲ್ಲಿರುವ ದಾಳಿಂಬೆ ಬೆಳೆ ಪದ್ಧತಿಯಲ್ಲಿ ವೀಕ್ಷಿಸಬಹುದು)', NULL, 'To shape the plants, keep 3-4 main branches and cut off unnecessary branches (for more information, see the pomegranate cropping system in the software)', NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7890, 'POMEGRANATE', NULL, N'<1', N'November-December', N'November-December', N'11,12', N'Vegetative stage', N'2', 'NORMAL', 'NO', 'ಗಿಡಗಳಿಗೆ ಆಕಾರ ಒದಗಿಸಲು 3-4 ಮುಖ್ಯ ರೆಂಬೆಗಳನ್ನು ಉಳಿಸಿಕೊಂಡು ಅನಗತ್ಯ ರೆಂಬೆಗಳನ್ನು ಕತ್ತರಿಸುವುದು (ಹೆಚ್ಚಿನ ಮಾಹಿತಿಗಾಗಿ ತಂತ್ರಾಂಶದಲ್ಲಿರುವ ದಾಳಿಂಬೆ ಬೆಳೆ ಪದ್ಧತಿಯಲ್ಲಿ ವೀಕ್ಷಿಸಬಹುದು)', NULL, 'To shape the plants, keep 3-4 main branches and cut off unnecessary branches (for more information, see the pomegranate cropping system in the software)', NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7891, 'POMEGRANATE', NULL, N'<1', N'November-December', N'November-December', N'11,12', N'Vegetative stage', N'2', 'BELOW NORMAL', 'YES', 'ಗಿಡಗಳಿಗೆ ಆಕಾರ ಒದಗಿಸಲು 3-4 ಮುಖ್ಯ ರೆಂಬೆಗಳನ್ನು ಉಳಿಸಿಕೊಂಡು ಅನಗತ್ಯ ರೆಂಬೆಗಳನ್ನು ಕತ್ತರಿಸುವುದು (ಹೆಚ್ಚಿನ ಮಾಹಿತಿಗಾಗಿ ತಂತ್ರಾಂಶದಲ್ಲಿರುವ ದಾಳಿಂಬೆ ಬೆಳೆ ಪದ್ಧತಿಯಲ್ಲಿ ವೀಕ್ಷಿಸಬಹುದು)', NULL, 'To shape the plants, keep 3-4 main branches and cut off unnecessary branches (for more information, see the pomegranate cropping system in the software)', NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7825, 'GRAPES', 30, N'1-3', N'February-March', N'March', N'3', N'Vegetative stage', N'1', 'BELOW NORMAL', 'NO', 'ಕೃಷಿ ಹೊಂಡ, ಇತರ ಮೂಲಗಳಲ್ಲಿ ಲಭ್ಯವಿರುವ ನೀರನ್ನು ಬಳಸಿ ಸಂರಕ್ಷಣಾ ನೀರಾವರಿ ಕೊಡುವುದು. ಗಿಡದ ಸುತ್ತಲು ಒಣಗಿದ ಎಲೆಗಳಿಂದ ಮಣ್ಣಿನ ಮೇಲೊದಿಕೆ ಮಾಡುವುದರಿಂದ ಮಣ್ಣಿನ ತೇವಾಂಶವನ್ನು ಕಾಪಾಡಿಕೊಳ್ಳಬಹುದು', 'ಹಿಟ್ಟಿನ ತಿಗಣೆ ಮತ್ತು ಥ್ರಿಪ್ಸ್ ನುಶಿ ಕಂಡುಬಂದಲ್ಲಿ ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ 0.5 ಗ್ರಾಂ ಥೈಯೋಮಿಥಾಕ್ಸಾಮ್ 25 WG ಅಥವಾ 0.25 ಗ್ರಾಂ ಅಸಿಟಮಾಪ್ರಿಡ್ 75 SP ಅಥವಾ 1.0 ಮಿ.ಲೀ. ಬುಪ್ರೋಫೆಜಿನ್ 25 SC ಅಥವಾ 2 ಮಿ.ಲೀ. ಪ್ರೋಫೆನೊಪಾಸ್ 50 SP ಅನ್ನು ಬೆರೆಸಿ ಸಿಂಪಡಿಸುವುದು. ಬೂದಿ ರೋಗ ಕಂಡುಬಂದಲ್ಲಿ ಲೀ. ನೀರಿಗೆ 3.0 ಗ್ರಾಂ ನೀರಿನಲ್ಲಿ ಕರಗುವ ಗಂಧಕದ ಪುಡಿ ಅಥವಾ 2.0 ಗ್ರಾಂ ಟ್ರೆಡೆಮೆಫಾನ್ 25 WP ಅಥವಾ 1.0 ಗ್ರಾಂ ಕಾರ್ಬೆಂಡಜಿಂ 50 WP ಅಥವಾ 0.5 ಗ್ರಾಂ ಮೈಕ್ಲೋಬ್ಯೂಟಾನಿಲ್ 10 WP 0.5 ಗ್ರಾಂ ಸೇರಿಸಿ ಸಿಂಪಡಿಸುವುದು', 'Conservation irrigation is done using water available from agricultural wells and other sources. Mulching the soil with dry leaves around the plant can help maintain soil moisture.', 'If mealybugs and thrips are found, spray 0.5 g Thiomethoxam 25 WG or 0.25 g Acetamaprid 75 SP or 1.0 ml Buprofezin 25 SC or 2 ml Profenopas 50 SP per liter of water. If powdery mildew is found, spray 3.0 g water-soluble sulfur powder or 2.0 g Tredemefon 25 WP or 1.0 g Carbendazim 50 WP or 0.5 g Myclobutanil 10 WP per liter of water', 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7826, 'GRAPES', 30, N'1-3', N'February-March', N'March', N'3', N'Vegetative stage', N'1', 'ABOVE NORMAL', 'YES', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', NULL, 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field.', NULL, 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7827, 'GRAPES', 30, N'1-3', N'February-March', N'March', N'3', N'Vegetative stage', N'1', 'ABOVE NORMAL', 'NO', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', NULL, 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field.', NULL, 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7828, 'GRAPES', 30, N'1-3', N'April-May', N'April-May', N'4,5', N'Vegetative stage', N'1', 'NORMAL', 'YES', 'ಸೂಚಿಸಲಾದ ಸಸ್ಯ ಸಂರಕ್ಷಣಾ ಕ್ರಮಗಳನ್ನು ಕೈಗೊಳ್ಳುವುದು', 'ಕಾಂಡ ಕತ್ತರಿಸುವ ದುಂಬಿ ಭಾದೆ ಕಂಡುಬಂದಲ್ಲಿ ಪ್ರತಿ ಲೀಟರ್ ನೀರಿಗೆ 3 ಗ್ರಾಂ ಕಾಪರ್ ಆಕ್ಸಿಕ್ಲೋರೈಡ್ 50 WP ಮತ್ತು ಬೇವಿನ ಸೋಪಿನಿಂದ ತಯಾರಿಸಿದ ಮಿಶ್ರಣವನ್ನು ಕಾಂಡದ ಸುತ್ತಲು ಹಚ್ಚುವುದು ಅಥವಾ 2 ಮಿ. ಲೀ. ಕ್ವಿನಾಲ್ ಫಾಸ್ 25 EC ಅನ್ನು ಬೆರೆಸಿ ಸಿಂಪಡಿಸುವುದು', 'Carrying out the recommended plant protection measures', 'If stem borer infestation is found, apply a mixture of 3 grams of copper oxychloride 50 WP and neem soap per liter of water around the stem or spray 2 ml. of Quinol Phos 25 EC', 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7829, 'GRAPES', 30, N'1-3', N'April-May', N'April-May', N'4,5', N'Vegetative stage', N'1', 'NORMAL', 'NO', 'ಸೂಚಿಸಲಾದ ಸಸ್ಯ ಸಂರಕ್ಷಣಾ ಕ್ರಮಗಳನ್ನು ಕೈಗೊಳ್ಳುವುದು', 'ಕಾಂಡ ಕತ್ತರಿಸುವ ದುಂಬಿ ಭಾದೆ ಕಂಡುಬಂದಲ್ಲಿ ಪ್ರತಿ ಲೀಟರ್ ನೀರಿಗೆ 3 ಗ್ರಾಂ ಕಾಪರ್ ಆಕ್ಸಿಕ್ಲೋರೈಡ್ 50 WP ಮತ್ತು ಬೇವಿನ ಸೋಪಿನಿಂದ ತಯಾರಿಸಿದ ಮಿಶ್ರಣವನ್ನು ಕಾಂಡದ ಸುತ್ತಲು ಹಚ್ಚುವುದು ಅಥವಾ 2 ಮಿ. ಲೀ. ಕ್ವಿನಾಲ್ ಫಾಸ್ 25 EC ಅನ್ನು ಬೆರೆಸಿ ಸಿಂಪಡಿಸುವುದು', 'Carrying out the recommended plant protection measures', 'If stem borer infestation is found, apply a mixture of 3 grams of copper oxychloride 50 WP and neem soap per liter of water around the stem or spray 2 ml. of Quinol Phos 25 EC', 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7830, 'GRAPES', 30, N'1-3', N'April-May', N'April-May', N'4,5', N'Vegetative stage', N'1', 'BELOW NORMAL', 'YES', 'ಪ್ರಸ್ತುತ ಹಂತದಲ್ಲಿ ಬೆಳೆ ಉತ್ತಮವಾಗಿದ್ದರೆ, ಇತರೆ ಬೆಳೆ ಬೆಳೆದಿದ್ದಲ್ಲಿ ಅವುಗಳ ನಿರ್ವಹಣೆಯತ್ತ ಗಮನಹರಿಸುವುದು', NULL, 'If the crop is good at the current stage, focus on managing other crops if they have grown.', NULL, 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7859, 'GRAPES', 30, N'>3', N'February-March', N'March', N'3', N'Fruit maturity', N'7', 'NORMAL', 'NO', 'ಹಣ್ಣಾದ ಗೊಂಚಲುಗಳನ್ನು ಕೊಯ್ಲು ಮಾಡುವುದು', 'ಹಿಟ್ಟಿನ ತಿಗಣೆ ಮತ್ತು ಥ್ರಿಪ್ಸ್ ನುಶಿ ಕಂಡುಬಂದಲ್ಲಿ ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ 0.5 ಗ್ರಾಂ ಥೈಯೋಮಿಥಾಕ್ಸಾಮ್ 25 WG ಅಥವಾ 0.25 ಗ್ರಾಂ ಅಸಿಟಮಾಪ್ರಿಡ್ 75 SP ಅಥವಾ 1.0 ಮಿ.ಲೀ. ಬುಪ್ರೋಫೆಜಿನ್ 25 SC ಅಥವಾ 2 ಮಿ.ಲೀ. ಪ್ರೋಫೆನೊಪಾಸ್ 50 SP ಅನ್ನು ಬೆರೆಸಿ ಸಿಂಪಡಿಸುವುದು. ಬೂದಿ ರೋಗ ಕಂಡುಬಂದಲ್ಲಿ ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ 3.0 ಗ್ರಾಂ ನೀರಿನಲ್ಲಿ ಕರಗುವ ಗಂಧಕದ ಪುಡಿ ಅಥವಾ 2.0 ಗ್ರಾಂ ಟ್ರೆಡೆಮೆಫಾನ್ 25 WP ಅಥವಾ 1.0 ಗ್ರಾಂ ಕಾರ್ಬೆಂಡಜಿಂ 50 WP ಅಥವಾ 0.5 ಗ್ರಾಂ ಮೈಕ್ಲೋಬ್ಯೂಟಾನಿಲ್ 10 WP ಅನ್ನು ಬೆರೆಸಿ ಸಿಂಪಡಿಸುವುದು', 'Harvesting ripe clusters', 'If mealybugs and thrips are found, spray 0.5 g Thiomethoxam 25 WG or 0.25 g Acetamaprid 75 SP or 1.0 ml Buprofezin 25 SC or 2 ml Profenopas 50 SP per liter of water. If powdery mildew is found, spray 3.0 g water soluble sulfur powder or 2.0 g Tredemefon 25 WP or 1.0 g Carbendazim 50 WP or 0.5 g Myclobutanil 10 WP per liter of water', 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7860, 'GRAPES', 30, N'>3', N'February-March', N'March', N'3', N'Fruit maturity', N'7', 'BELOW NORMAL', 'YES', 'ಹಣ್ಣಾದ ಗೊಂಚಲುಗಳನ್ನು ಕೊಯ್ಲು ಮಾಡುವುದು', NULL, 'Harvesting ripe clusters', NULL, 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7861, 'GRAPES', 30, N'>3', N'February-March', N'March', N'3', N'Fruit maturity', N'7', 'BELOW NORMAL', 'NO', 'ಹಣ್ಣಾದ ಗೊಂಚಲುಗಳನ್ನು ಕೊಯ್ಲು ಮಾಡುವುದು', NULL, 'Harvesting ripe clusters', NULL, 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7862, 'GRAPES', 30, N'>3', N'February-March', N'March', N'3', N'Fruit maturity', N'7', 'ABOVE NORMAL', 'YES', 'ಮಳೆ ಇಲ್ಲದ ಸಂದರ್ಭ ನೋಡಿಕೊಂಡು ಹಣ್ಣಾದ ಗೊಂಚಲುಗಳನ್ನು ಕೊಯ್ಲು ಮಾಡುವುದು. ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', NULL, 'Harvest the ripe bunches when there is no rain. If there has been heavy rain in the past few days, allow the water to drain away so that it does not stagnate in the field.', NULL, 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7863, 'GRAPES', 30, N'>3', N'February-March', N'March', N'3', N'Fruit maturity', N'7', 'ABOVE NORMAL', 'NO', 'ಮಳೆ ಇಲ್ಲದ ಸಂದರ್ಭ ನೋಡಿಕೊಂಡು ಹಣ್ಣಾದ ಗೊಂಚಲುಗಳನ್ನು ಕೊಯ್ಲು ಮಾಡುವುದು. ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', NULL, 'Harvest the ripe bunches when there is no rain. If there has been heavy rain in the past few days, allow the water to drain away so that it does not stagnate in the field.', NULL, 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7864, 'GRAPES', 30, N'>3', N'April-May', N'April-May', N'4,5', N'Summer pruning', N'2', 'NORMAL', 'YES', 'ಬೇಸಿಗೆ ಚಾಟನಿ ಮಾಡುವುದು ಹಾಗೂ ಚಾಟನಿ ಮಾಡಿದ ಕಾಂಡಗಳಿಗೆ ಬೊರ್ಡೋ ಪೇಸ್ಟ್ ಲೇಪಿಸುವುದು. ಚಾಟನಿ ಮಾಡಿದ ನಂತರ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ಮೇಲು ಗೊಬ್ಬರವನ್ನು ಕೊಡುವುದು', NULL, 'Summer pruning and applying Bordeaux paste to the pruned stems. After pruning, apply the recommended top dressing.', NULL, 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
