INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7866, 'GRAPES', 30, N'>3', N'April-May', N'April-May', N'4,5', N'Summer pruning', N'2', 'BELOW NORMAL', 'YES', 'ಬೇಸಿಗೆ ಚಾಟನಿ ಮಾಡುವುದು ಹಾಗೂ ಚಾಟನಿ ಮಾಡಿದ ಕಾಂಡಗಳಿಗೆ ಬೊರ್ಡೋ ಪೇಸ್ಟ್ ಲೇಪಿಸುವುದು. ಚಾಟನಿ ಮಾಡಿದ ನಂತರ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ಮೇಲು ಗೊಬ್ಬರವನ್ನು ಕೊಡುವುದು', NULL, 'Summer pruning and applying Bordeaux paste to the pruned stems. After pruning, apply the recommended top dressing.', NULL, 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7867, 'GRAPES', 30, N'>3', N'April-May', N'April-May', N'4,5', N'Summer pruning', N'2', 'BELOW NORMAL', 'NO', 'ಬೇಸಿಗೆ ಚಾಟನಿ ಮಾಡುವುದು ಹಾಗೂ ಚಾಟನಿ ಮಾಡಿದ ಕಾಂಡಗಳಿಗೆ ಬೊರ್ಡೋ ಪೇಸ್ಟ್ ಲೇಪಿಸುವುದು. ಬೇಸಿಗೆ ಚಾಟನಿ ಮಾಡುವುದರ ಜೊತೆಗೆ ಸಂರಕ್ಷಣಾ ನೀರಾವರಿ ಕೊಡುವುದು', NULL, 'Summer pruning and applying Bordeaux paste to the pruned stems. Summer pruning and providing conservation irrigation', NULL, 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7892, 'POMEGRANATE', NULL, N'<1', N'November-December', N'November-December', N'11,12', N'Vegetative stage', N'2', 'BELOW NORMAL', 'NO', '• ಕೃಷಿ ಹೊಂಡ, ಇತರ ಮೂಲಗಳಲ್ಲಿ ಲಭ್ಯವಿರುವ ನೀರನ್ನು ಬಳಸಿ ನೀರಾವರಿ ಕೊಡುವುದು
• ಗಿಡಗಳಿಗೆ ಆಕಾರ ಒದಗಿಸಲು 3-4 ಮುಖ್ಯ ರೆಂಬೆಗಳನ್ನು ಉಳಿಸಿಕೊಂಡು ಅನಗತ್ಯ ರೆಂಬೆಗಳನ್ನು ಕತ್ತರಿಸುವುದು (ಹೆಚ್ಚಿನ ಮಾಹಿತಿಗಾಗಿ ತಂತ್ರಾಂಶದಲ್ಲಿರುವ ದಾಳಿಂಬೆ ಬೆಳೆ ಪದ್ಧತಿಯಲ್ಲಿ ವೀಕ್ಷಿಸಬಹುದು)', NULL, '• Irrigation using water available from agricultural wells, other sources
• Pruning of unnecessary branches while keeping 3-4 main branches to give shape to the plants (for more information, see Pomegranate Crop System in the software)', NULL, 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
