INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7840, 'GRAPES', 30, N'>3', N'August-October', N'August-September-October', N'8,9,10', N'Vegetative stage', N'4', 'NORMAL', 'YES', 'ಸೆಪ್ಟೆಂಬರ್‌ ತಿಂಗಳಲ್ಲಿ ಚಳಿಗಾಲ ಚಾಟನಿ (ಪ್ರೂನಿಂಗ್) ಮಾಡುವುದು. ಪ್ರೂನಿಂಗ್ ಮಾಡದ ನಂತರ ಆರನೇ ಹಾಗೂ ನಂತರದ ಕಣ್ಣುಗಳಿಗೆ ಶೇಕಡ 2ರ ಹೈಡ್ರೋಜನ್ ಸೈನಾಮೈಡ್ ರಾಸಾಯನಿಕ ದ್ರಾವಣದಲ್ಲಿ ಹತ್ತಿಯನ್ನು ಅದ್ದಿ ಲೇಪಿಸುವುದರಿಂದ ಬೀಜರಹಿತ ದ್ರಾಕ್ಷಿ ಬೆಳೆಯಲ್ಲಿ ಕಣ್ಣು ಚಿಗುರುವಿಕೆಯ ಪ್ರಮಾಣ ಹೆಚ್ಚುತ್ತದೆ‌', 'ಚಿಬ್ಬು ರೋಗದ ಹತೋಟಿಗಾಗಿ ಶೇ.1 ರ ಬೋರ್ಡೋ ದ್ರಾವಣ ಸಿಂಪಡಿಸುವುದು ನಂತರ ಪ್ರತಿ ಲೀಟರ್ ನೀರಿಗೆ 1 ಗ್ರಾಂ ಕಾರ್ಬೆಂಡಜಿಮ್ 50 WP ಅಥವಾ 1.5 ಮಿ.ಲೀ. ಡೈಫೆನೊಕೊನೋಜೋಲ್ 25 EC ಅಥವಾ 2.5 ಗ್ರಾಂ ಕಾಪರ್ ಆಕ್ಸಿಕ್ಲೋರೈಡ್ 50 WP ಅನ್ನು 10-15 ದಿನಗಳ ಅಂತರದಲ್ಲಿ ಸಿಂಪರಣೆ ಮಾಡುವುದು', 'Winter pruning is done in September. After pruning, cotton soaked in 2% hydrogen cyanamide solution and applied to the sixth and subsequent buds increases the rate of budding in seedless grape crops.', 'To control powdery mildew, spray 1% Bordeaux mixture followed by 1 gram Carbendazim 50 WP or 1.5 ml Difenoconazole 25 EC or 2.5 grams Copper Oxychloride 50 WP per liter of water at an interval of 10-15 days', 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7841, 'GRAPES', 30, N'>3', N'August-October', N'August-September-October', N'8,9,10', N'Vegetative stage', N'4', 'NORMAL', 'NO', 'ಸೆಪ್ಟೆಂಬರ್‌ ತಿಂಗಳಲ್ಲಿ ಚಳಿಗಾಲ ಚಾಟನಿ (ಪ್ರೂನಿಂಗ್) ಮಾಡುವುದು. ಪ್ರೂನಿಂಗ್ ಮಾಡದ ನಂತರ ಆರನೇ ಹಾಗೂ ನಂತರದ ಕಣ್ಣುಗಳಿಗೆ ಶೇಕಡ 2ರ ಹೈಡ್ರೋಜನ್ ಸೈನಾಮೈಡ್ ರಾಸಾಯನಿಕ ದ್ರಾವಣದಲ್ಲಿ ಹತ್ತಿಯನ್ನು ಅದ್ದಿ ಲೇಪಿಸುವುದರಿಂದ ಬೀಜರಹಿತ ದ್ರಾಕ್ಷಿ ಬೆಳೆಯಲ್ಲಿ ಕಣ್ಣು ಚಿಗುರುವಿಕೆಯ ಪ್ರಮಾಣ ಹೆಚ್ಚುತ್ತದೆ‌', 'ಚಿಬ್ಬು ರೋಗದ ಹತೋಟಿಗಾಗಿ ಶೇ.1 ರ ಬೋರ್ಡೋ ದ್ರಾವಣ ಸಿಂಪಡಿಸುವುದು ನಂತರ ಪ್ರತಿ ಲೀಟರ್ ನೀರಿಗೆ 1 ಗ್ರಾಂ ಕಾರ್ಬೆಂಡಜಿಮ್ 50 WP ಅಥವಾ 1.5 ಮಿ.ಲೀ. ಡೈಫೆನೊಕೊನೋಜೋಲ್ 25 EC ಅಥವಾ 2.5 ಗ್ರಾಂ ಕಾಪರ್ ಆಕ್ಸಿಕ್ಲೋರೈಡ್ 50 WP ಅನ್ನು 10-15 ದಿನಗಳ ಅಂತರದಲ್ಲಿ ಸಿಂಪರಣೆ ಮಾಡುವುದು', 'Winter pruning is done in September. After pruning, cotton soaked in 2% hydrogen cyanamide solution and applied to the sixth and subsequent buds increases the rate of budding in seedless grape crops.', 'To control powdery mildew, spray 1% Bordeaux mixture followed by 1 gram Carbendazim 50 WP or 1.5 ml Difenoconazole 25 EC or 2.5 grams Copper Oxychloride 50 WP per liter of water at an interval of 10-15 days', 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7842, 'GRAPES', 30, N'>3', N'August-October', N'August-September-October', N'8,9,10', N'Vegetative stage', N'4', 'BELOW NORMAL', 'YES', 'ಸೆಪ್ಟೆಂಬರ್‌ ತಿಂಗಳಲ್ಲಿ ಚಳಿಗಾಲ ಚಾಟನಿ (ಪ್ರೂನಿಂಗ್) ಮಾಡುವುದು. ಪ್ರೂನಿಂಗ್ ಮಾಡದ ನಂತರ ಆರನೇ ಹಾಗೂ ನಂತರದ ಕಣ್ಣುಗಳಿಗೆ ಶೇಕಡ 2ರ ಹೈಡ್ರೋಜನ್ ಸೈನಾಮೈಡ್ ರಾಸಾಯನಿಕ ದ್ರಾವಣದಲ್ಲಿ ಹತ್ತಿಯನ್ನು ಅದ್ದಿ ಲೇಪಿಸುವುದರಿಂದ ಬೀಜರಹಿತ ದ್ರಾಕ್ಷಿ ಬೆಳೆಯಲ್ಲಿ ಕಣ್ಣು ಚಿಗುರುವಿಕೆಯ ಪ್ರಮಾಣ ಹೆಚ್ಚುತ್ತದೆ‌', NULL, 'Winter pruning is done in September. After pruning, cotton soaked in 2% hydrogen cyanamide solution and applied to the sixth and subsequent buds increases the rate of budding in seedless grape crops.', NULL, 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7873, 'POMEGRANATE', NULL, N'<1', N'June', N'June', N'6', N'Planting', N'1', 'BELOW NORMAL', 'YES', '• ನೀರಾವರಿ ಸೌಲಭ್ಯವಿದ್ದಲ್ಲಿ ಗಿಡಗಳನ್ನು ನಾಟಿ ಮಾಡುವುದು. ನಾಟಿ ಮಾಡಿದ ನಂತರ LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ರಸಗೊಬ್ಬರವನ್ನು ಕೊಡುವುದು
• ನಾಟಿ ಮಾಡಿದ ಗಿಡಗಳಿಗೆ ಕೋಲಿನ ಆಸರೆ ಒದಗಿಸುವುದು
• ದಾಳಿಂಬೆ ನಾಟಿಯ ನಂತರ ತೋಟದ ಮಧ್ಯೆ ಹಸಿರೆಲೆ ಗೊಬ್ಬರದ ಗಿಡಗಳಾದ ಸೆಣಬು, ಅಲಸಂದಿ ಅಥವಾ ಹುರುಳಿ ಬೆಳೆಯನ್ನು ಬೆಳೆಯುವುದರಿಂದ ಭೂಮಿಯ ಫಲವತ್ತತೆಯನ್ನು ಹೆಚ್ಚಿಸಬಹುದು
• ಅಥವಾ ತೋಟದ ಮಧ್ಯ ಅಂತರ ಬೆಳೆಗಳನ್ನು ಬೆಳೆಯಬಹುದು', NULL, '• Planting plants if irrigation facilities are available. After planting, apply fertilizer as recommended based on LRI
• Providing support for the planted plants with stakes
• After planting pomegranate, growing green manure plants such as jute, sorghum or buckwheat in the middle of the garden can increase the fertility of the soil
• Or intercropping can be done in the middle of the garden', NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
