INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7843, 'GRAPES', 30, N'>3', N'August-October', N'August-September-October', N'8,9,10', N'Vegetative stage', N'4', 'BELOW NORMAL', 'NO', 'ಸೆಪ್ಟೆಂಬರ್‌ ತಿಂಗಳಲ್ಲಿ ಚಳಿಗಾಲ ಚಾಟನಿ (ಪ್ರೂನಿಂಗ್) ಮಾಡುವುದು. ಪ್ರೂನಿಂಗ್ ಮಾಡದ ನಂತರ ಆರನೇ ಹಾಗೂ ನಂತರದ ಕಣ್ಣುಗಳಿಗೆ ಶೇಕಡ 2ರ ಹೈಡ್ರೋಜನ್ ಸೈನಾಮೈಡ್ ರಾಸಾಯನಿಕ ದ್ರಾವಣದಲ್ಲಿ ಹತ್ತಿಯನ್ನು ಅದ್ದಿ ಲೇಪಿಸುವುದರಿಂದ ಬೀಜರಹಿತ ದ್ರಾಕ್ಷಿ ಬೆಳೆಯಲ್ಲಿ ಕಣ್ಣು ಚಿಗುರುವಿಕೆಯ ಪ್ರಮಾಣ ಹೆಚ್ಚುತ್ತದೆ‌', NULL, 'Winter pruning is done in September. After pruning, cotton soaked in 2% hydrogen cyanamide solution and applied to the sixth and subsequent buds increases the rate of budding in seedless grape crops.', NULL, 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7844, 'GRAPES', 30, N'>3', N'August-October', N'August-September-October', N'8,9,10', N'Vegetative stage', N'4', 'ABOVE NORMAL', 'YES', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', NULL, 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field.', NULL, 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7845, 'GRAPES', 30, N'>3', N'August-October', N'August-September-October', N'8,9,10', N'Vegetative stage', N'4', 'ABOVE NORMAL', 'NO', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', NULL, 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field.', NULL, 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7846, 'GRAPES', 30, N'>3', N'November-December', N'November-December', N'11,12', N'Flowering', N'5', 'NORMAL', 'YES', 'ಪೂರ್ತಿ ಹೂ ಅರಳಿದ ಹಂತದಲ್ಲಿ ಗೊಂಚಲುಗಳನ್ನು 20 ಮಿ. ಗ್ರಾಂ. ಜಿಬ್ಬರ್ಲಿಕ್ ಆಮ್ಲ 1 ಲೀಟರ್ ನೀರಿನಲ್ಲಿ ಬೆರೆಸಿ ಅದ್ದುವುದರಿಂದ ಗೊಂಚಲಿನಲ್ಲಿ ಹಣ್ಣು ಒತ್ತಾಗಿರುವುದು ಕಡಿಮೆಯಾಗುವುದು. ಸಣ್ಣ ರಂಧ್ರಗಳನ್ನು ಕೊರೆಯುವ ದುಂಬಿ ಕಂಡಲ್ಲಿ ಲೀ. ನೀರಿಗೆ ಡೈಕ್ಲೋರೋವಾಸ್ 76 ಇಸಿ. ಸೇರಿಸಿ ಸಿಂಪಡಿಸುವುದು', 'ಚಿಕ್ಕಟಿ ದುಂಬಿ, ಕಡಜಗಳು ಮತ್ತು ಎಲೆ ತಿನ್ನುವ ಕೀಟ ಕಂಡುಬಂದರೆ ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ 1.0 ಮಿ.ಲೀ. ಸೈಯಾಂಟ್ರನಿಲಿಪ್ರೋಲ್ 10.25 OD ಅಥವಾ 0.5 ಮಿ.ಲೀ. ಲಾಮ್ಡಾ ಸೈಲೋಥ್ರೀನ್ 4.9 CS ಅಥವಾ 2 ಮಿ.ಲೀ. ಕ್ವಿನಾಲ್‌ಫಾಸ್ 25 EC ಅನ್ನು ಸೇರಿಸಿ ಸಿಂಪಡಿಸುವುದು. ಕೇದಿಗೆ ರೋಗ ಕಂಡುಬಂದಲ್ಲಿ ಲೀ. ನೀರಿಗೆ 3.0 ಗ್ರಾಂ ತಾಮ್ರದ ಆಕ್ಸಿಕ್ಲೋರೈಡ್ 50 WP ಅಥವಾ 2 ಗ್ರಾಂ ಮೆಟಲಾಕ್ಸಿಲ್ MZ 72 WP ಅಥವಾ 1 ಮಿ.ಲೀ. ಅಜಾಕ್ಸಿಸ್ಟ್ರೊಬಿನ್ 23 SC ಸೇರಿಸಿ ಸಿಂಪಡಿಸುವುದು', 'At the stage of full bloom, the bunches are dipped in 20 mg. g. Gibberellic acid mixed in 1 liter of water to reduce the density of fruit in the bunch. If small holes are found, spray with dichlorvos 76 EC in 1 liter of water.', 'If small beetles, aphids and leaf-eating insects are found, spray 1.0 ml. Cyanthraniliprol 10.25 OD or 0.5 ml. Lambda Cylothrin 4.9 CS or 2 ml. Quinalphos 25 EC per liter of water. If disease is found in the field, spray 3.0 g. Copper Oxychloride 50 WP or 2 g. Metalaxyl MZ 72 WP or 1 ml. Azoxystrobin 23 SC per liter of water', 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7877, 'POMEGRANATE', NULL, N'<1', N'July-August', N'July-August', N'7,8', N'Establishment stage', N'2', 'NORMAL', 'YES', '• ಗಿಡಗಳು ನೇರವಾಗಿ ಬೆಳೆಯಲು ಅವುಗಳಿಗೆ ಕೋಲಿನ ಆಸರೆ ಒದಗಿಸುವುದು
• ತೋಟದಲ್ಲಿ ಹಸಿರೆಲೆ ಗೊಬ್ಬರದ ಗಿಡಗಳನ್ನು ಬೆಳೆದಿದ್ದರೆ ಅವನ್ನು ಬಿತ್ತಿದ 45 ದಿನಗಳ ನಂತರ ಮಣ್ಣಿಗೆ ಸೇರಿಸುವುದು
• ತೋಟದ ಮಧ್ಯೆ ಅಂತರಬೆಳೆ ಬೆಳೆದಿದ್ದರೆ ಅವುಗಳಿಗೆ ತಗುಲುವ ರೋಗ ಮತ್ತು ಕೀಟಗಳ ಮೇಲೆ ಗಮನ ಹರಿಸುವುದು
• ಗಿಡ ಸ್ಥಾಪಿತವಾಗದೆ ಇರುವ ಜಾಗದಲ್ಲಿ ಬೇರೆ ಸಸಿಯನ್ನು ನೆಡುವುದು', 'ಹಣ್ಣು ಕೊಳೆ ರೋಗದ ನಿಯಂತ್ರಣಕ್ಕಾಗಿ ಹೂಬಿಡುವ ಸಮಯದಿಂದ ಹಣ್ಣು ಕೊಯ್ಲು ಮಾಡುವವರೆಗೆ ಪ್ರತಿ ಮೂರು ವಾರಕ್ಕೊಮ್ಮೆ 2 ಗ್ರಾಂ ಜೈನೆಬ್ ಅಥವಾ 2 ಗ್ರಾಂ ಮೆಂಕೋಜೆಬ್ 75 WP ಅಥವಾ 1 ಗ್ರಾಂ. ಥೈಯೋಫಿನೇಟ್‍ ಮಿಥೈಲ್‍ 70 WP ಪ್ರತಿ ಲೀಟರ್ ನೀರಿಗೆ ಬೆರೆಸಿ ಸಿಂಪಡಿಸುವುದು', '• Provide support for the plants to grow upright
• If green manure plants are grown in the garden, incorporate them into the soil 45 days after sowing
• If intercrops are grown in the garden, pay attention to the diseases and pests that they can be affected by
• Plant another plant in the area where the plant is not established', 'For the control of fruit rot, spray 2 gm of Zaineb or 2 gm of Mencozeb 75 WP or 1 gm of Thiophinate Methyl 70 WP mixed in per liter of water every three weeks from the time of flowering to fruit harvesting', 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7878, 'POMEGRANATE', NULL, N'<1', N'July-August', N'July-August', N'7,8', N'Establishment stage', N'2', 'NORMAL', 'NO', '• ಗಿಡಗಳು ನೇರವಾಗಿ ಬೆಳೆಯಲು ಅವುಗಳಿಗೆ ಕೋಲಿನ ಆಸರೆ ಒದಗಿಸುವುದು
• ತೋಟದಲ್ಲಿ ಹಸಿರೆಲೆ ಗೊಬ್ಬರದ ಗಿಡಗಳನ್ನು ಬೆಳೆದಿದ್ದರೆ ಅವನ್ನು ಬಿತ್ತಿದ 45 ದಿನಗಳ ನಂತರ ಮಣ್ಣಿಗೆ ಸೇರಿಸುವುದು
• ತೋಟದ ಮಧ್ಯೆ ಅಂತರಬೆಳೆ ಬೆಳೆದಿದ್ದರೆ ಅವುಗಳಿಗೆ ತಗುಲುವ ರೋಗ ಮತ್ತು ಕೀಟಗಳ ಮೇಲೆ ಗಮನ ಹರಿಸುವುದು• ಗಿಡ ಸ್ಥಾಪಿತವಾಗದೆ ಇರುವ ಜಾಗದಲ್ಲಿ ಬೇರೆ ಸಸಿಯನ್ನು ನೆಡುವುದು', 'ಹಣ್ಣು ಕೊಳೆ ರೋಗದ ನಿಯಂತ್ರಣಕ್ಕಾಗಿ ಹೂಬಿಡುವ ಸಮಯದಿಂದ ಹಣ್ಣು ಕೊಯ್ಲು ಮಾಡುವವರೆಗೆ ಪ್ರತಿ ಮೂರು ವಾರಕ್ಕೊಮ್ಮೆ 2 ಗ್ರಾಂ ಜೈನೆಬ್ ಅಥವಾ 2 ಗ್ರಾಂ ಮೆಂಕೋಜೆಬ್ 75 WP ಅಥವಾ 1 ಗ್ರಾಂ. ಥೈಯೋಫಿನೇಟ್‍ ಮಿಥೈಲ್‍ 70 WP ಪ್ರತಿ ಲೀಟರ್ ನೀರಿಗೆ ಬೆರೆಸಿ ಸಿಂಪಡಿಸುವುದು', '• Provide support for the plants to grow upright
• If green manure plants are grown in the garden, incorporate them into the soil 45 days after sowing
• If intercrops are grown in the garden, pay attention to the diseases and pests they are exposed to• Plant another plant in the area where the plant is not established', 'For the control of fruit rot, spray 2 gm of Zaineb or 2 gm of Mencozeb 75 WP or 1 gm of Thiophinate Methyl 70 WP mixed in per liter of water every three weeks from the time of flowering to fruit harvesting', 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7879, 'POMEGRANATE', NULL, N'<1', N'July-August', N'July-August', N'7,8', N'Establishment stage', N'2', 'BELOW NORMAL', 'YES', '• ಗಿಡ ಸ್ಥಾಪಿತವಾಗದೆ ಇರುವ ಜಾಗದಲ್ಲಿ ಬೇರೆ ಸಸಿಯನ್ನು ನೆಡುವುದು
• ಗಿಡಗಳು ನೇರವಾಗಿ ಬೆಳೆಯಲು ಅವುಗಳಿಗೆ ಕೋಲಿನ ಆಸರೆ ಒದಗಿಸುವುದು
• ತೋಟದಲ್ಲಿ ಹಸಿರೆಲೆ ಗೊಬ್ಬರದ ಗಿಡಗಳನ್ನು ಬೆಳೆದಿದ್ದರೆ ಅವನ್ನು ಬಿತ್ತಿದ 45 ದಿನಗಳ ನಂತರ ಮಣ್ಣಿಗೆ ಸೇರಿಸುವುದು
• ತೋಟದ ಮಧ್ಯೆ ಅಂತರಬೆಳೆ ಬೆಳೆದಿದ್ದರೆ ಅವುಗಳಿಗೆ ತಗುಲುವ ರೋಗ ಮತ್ತು ಕೀಟಗಳ ಮೇಲೆ ಗಮನ ಹರಿಸುವುದು', 'ಜಮೀನಿನಲ್ಲಿ ಬೋರಾನ್ ಕೊರತೆಯಿದ್ದರೆ ಹಣ್ಣು ಸೀಳುತ್ತವೆ. ಇದಕ್ಕೆ 1 ಗ್ರಾಂ ಬೋರಾಕ್ಸ್ (0.1 %) ಒಂದು ಲೀಟರ್‍ ನೀರಿನಲ್ಲಿ ಬೆರೆಸಿ ಸಿಂಪಡಿಸುವುದು', '• Planting another plant in the area where the plant is not established
• Providing support for the plants with sticks so that they can grow upright
• If green manure plants are grown in the garden, incorporate them into the soil 45 days after sowing
• If intercrops are grown in the garden, pay attention to the diseases and pests that they are susceptible to', 'If there is a deficiency of boron in the field, the fruits will crack. For this, mix 1 gram of borax (0.1%) in one liter of water and spray it', 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7910, 'POMEGRANATE', NULL, N'1-2', N'May-June', N'May-June', N'5,6', N'Vegetative stage', N'2', 'BELOW NORMAL', 'NO', '• ಕೃಷಿ ಹೊಂಡ, ಇತರ ಮೂಲಗಳಲ್ಲಿ ಲಭ್ಯವಿರುವ ನೀರನ್ನು ಬಳಸಿ ನೀರಾವರಿ ಕೊಡುವುದು
• ತೋಟದ ಮಧ್ಯೆ ಉಳುಮೆ ಮಾಡಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ಕೊಟ್ಟಿಗೆ ಗೊಬ್ಬರ ಮತ್ತು LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ರಸಗೊಬ್ಬರವನ್ನು ಕೊಡುವುದು
• ಗಿಡಗಳಿಗೆ ಆಕಾರ ಒದಗಿಸಲು ಅನಗತ್ಯ ರೆಂಬೆಗಳನ್ನು ಕತ್ತರಿಸುವುದು (ಹೆಚ್ಚಿನ ಮಾಹಿತಿಗಾಗಿ ತಂತ್ರಾಂಶದಲ್ಲಿರುವ ದಾಳಿಂಬೆ ಬೆಳೆ ಪದ್ಧತಿಯಲ್ಲಿ ವೀಕ್ಷಿಸಬಹುದು)
• ಹಸಿರೆಲೆ ಗೊಬ್ಬರದ ಗಿಡಗಳಾದ ಸೆಣಬು, ಅಲಸಂದಿ ಅಥವಾ ಹುರುಳಿ ಬೆಳೆಯನ್ನು ಬೆಳೆಯುವುದರಿಂದ ಭೂಮಿಯ ಫಲವತ್ತತೆಯನ್ನು ಹೆಚ್ಚಿಸಬಹುದು
• ಅಥವಾ ತೋಟದ ಮಧ್ಯ ಅಂತರ ಬೆಳೆಗಳನ್ನು ಬೆಳೆಯಬಹುದು', NULL, '• Irrigation using water available from agricultural wells, other sources
• Ploughing the garden and applying recommended manure and fertilizer based on LRI
• Pruning unwanted branches to give shape to the plants (for more information, see the pomegranate cropping system in the software)
• Growing green manure crops such as jute, sorghum or buckwheat can increase the fertility of the soil
• Or intercropping can be done in the garden', NULL, 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7911, 'POMEGRANATE', NULL, N'1-2', N'May-June', N'May-June', N'5,6', N'Vegetative stage', N'2', 'ABOVE NORMAL', 'YES', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', NULL, 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field.', NULL, 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7912, 'POMEGRANATE', NULL, N'1-2', N'May-June', N'May-June', N'5,6', N'Vegetative stage', N'2', 'ABOVE NORMAL', 'NO', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', NULL, 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field.', NULL, 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7913, 'POMEGRANATE', NULL, N'1-2', N'July-August', N'July-August', N'7,8', N'Vegetative stage', N'2', 'NORMAL', 'YES', '• ತೋಟದಲ್ಲಿ ಹಸಿರೆಲೆ ಗೊಬ್ಬರದ ಗಿಡಗಳನ್ನು ಬೆಳೆದಿದ್ದರೆ ಅವನ್ನು ಬಿತ್ತಿದ 45 ದಿನಗಳ ನಂತರ ಮಣ್ಣಿಗೆ ಸೇರಿಸುವುದು
• ತೋಟದ ಮಧ್ಯೆ ಅಂತರಬೆಳೆ ಬೆಳೆದಿದ್ದರೆ ಅವುಗಳಿಗೆ ತಗುಲುವ ರೋಗ ಮತ್ತು ಕೀಟಗಳ ಮೇಲೆ ಗಮನ ಹರಿಸುವುದು', 'ದುಂಡಾಣು ಎಲೆಚುಕ್ಕೆ ಕಂಡು ಬಂದಾಗ ಪ್ರಾರಂಭಿಕ ಹಂತದಲ್ಲಿ 0.5 ಗ್ರಾಂ 2 ಬ್ರೋಮೋ-2 ನೈಟ್ರೋಪ್ರೋಪೇನ್‍1,3 ಅಥವಾ 0.5 ಗ್ರಾಂ ಸ್ಟ್ರೆಪ್ಟೋಸೈಕ್ಲೀನ್‍ ಅಥವಾ 3.0 ಗ್ರಾಂ ತಾಮ್ರದ ಆಕ್ಸಿಕ್ಲೋರೈಡ್‍ 50 WP ಅನ್ನು ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿನಲ್ಲಿ ಬೆರೆಸಿ ಸಿಂಪಡಿಸುವುದು. ಹವಾಮಾನ ಹಾಗೂ ರೋಗ ಬಾಧೆಗೆ ಅನುಸಾರವಾಗಿ 5 ರಿಂದ 6 ಸಿಂಪರಣೆಗಳನ್ನು 10 ದಿನಗಳ ಅಂತರದಲ್ಲಿ ಕೈಗೊಳ್ಳುವುದು ಉತ್ತಮ', '• If green manure crops are grown in the garden, incorporate them into the soil 45 days after sowing. • If intercrops are grown in the garden, pay attention to the diseases and pests that they are susceptible to.', 'When round leaf spot is found, spray 0.5 g 2 bromo-2 nitropropane 1,3 or 0.5 g streptocycline or 3.0 g copper oxychloride 50 WP per liter of water at the initial stage. It is better to do 5 to 6 sprays at an interval of 10 days depending on the weather and disease severity', 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7847, 'GRAPES', 30, N'>3', N'November-December', N'November-December', N'11,12', N'Flowering', N'5', 'NORMAL', 'NO', 'ಪೂರ್ತಿ ಹೂ ಅರಳಿದ ಹಂತದಲ್ಲಿ ಗೊಂಚಲುಗಳನ್ನು 20 ಮಿ. ಗ್ರಾಂ. ಜಿಬ್ಬರ್ಲಿಕ್ ಆಮ್ಲ 1 ಲೀಟರ್ ನೀರಿನಲ್ಲಿ ಬೆರೆಸಿ ಅದ್ದುವುದರಿಂದ ಗೊಂಚಲಿನಲ್ಲಿ ಹಣ್ಣು ಒತ್ತಾಗಿರುವುದು ಕಡಿಮೆಯಾಗುವುದು. ಸಣ್ಣ ರಂಧ್ರಗಳನ್ನು ಕೊರೆಯುವ ದುಂಬಿ ಕಂಡಲ್ಲಿ ಲೀ. ನೀರಿಗೆ ಡೈಕ್ಲೋರೋವಾಸ್ 76 ಇಸಿ. ಸೇರಿಸಿ ಸಿಂಪಡಿಸುವುದು', 'ಚಿಕ್ಕಟಿ ದುಂಬಿ, ಕಡಜಗಳು ಮತ್ತು ಎಲೆ ತಿನ್ನುವ ಕೀಟ ಕಂಡುಬಂದರೆ ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ 1.0 ಮಿ.ಲೀ. ಸೈಯಾಂಟ್ರನಿಲಿಪ್ರೋಲ್ 10.25 OD ಅಥವಾ 0.5 ಮಿ.ಲೀ. ಲಾಮ್ಡಾ ಸೈಲೋಥ್ರೀನ್ 4.9 CS ಅಥವಾ 2 ಮಿ.ಲೀ. ಕ್ವಿನಾಲ್‌ಫಾಸ್ 25 EC ಅನ್ನು ಸೇರಿಸಿ ಸಿಂಪಡಿಸುವುದು. ಕೇದಿಗೆ ರೋಗ ಕಂಡುಬಂದಲ್ಲಿ ಲೀ. ನೀರಿಗೆ 3.0 ಗ್ರಾಂ ತಾಮ್ರದ ಆಕ್ಸಿಕ್ಲೋರೈಡ್ 50 WP ಅಥವಾ 2 ಗ್ರಾಂ ಮೆಟಲಾಕ್ಸಿಲ್ MZ 72 WP ಅಥವಾ 1 ಮಿ.ಲೀ. ಅಜಾಕ್ಸಿಸ್ಟ್ರೊಬಿನ್ 23 SC ಸೇರಿಸಿ ಸಿಂಪಡಿಸುವುದು', 'At the stage of full bloom, the bunches are dipped in 20 mg. g. Gibberellic acid mixed in 1 liter of water to reduce the density of fruit in the bunch. If small holes are found, spray with dichlorvos 76 EC in 1 liter of water.', 'If small beetles, aphids and leaf-eating insects are found, spray 1.0 ml. Cyanthraniliprol 10.25 OD or 0.5 ml. Lambda Cylothrin 4.9 CS or 2 ml. Quinalphos 25 EC per liter of water. If disease is found in the field, spray 3.0 g. Copper Oxychloride 50 WP or 2 g. Metalaxyl MZ 72 WP or 1 ml. Azoxystrobin 23 SC per liter of water', 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7848, 'GRAPES', 30, N'>3', N'November-December', N'November-December', N'11,12', N'Flowering', N'5', 'BELOW NORMAL', 'YES', 'ಪೂರ್ತಿ ಹೂ ಅರಳಿದ ಹಂತದಲ್ಲಿ ಗೊಂಚಲುಗಳನ್ನು 20 ಮಿ. ಗ್ರಾಂ. ಜಿಬ್ಬರ್ಲಿಕ್ ಆಮ್ಲ 1 ಲೀಟರ್ ನೀರಿನಲ್ಲಿ ಬೆರೆಸಿ ಅದ್ದುವುದರಿಂದ ಗೊಂಚಲಿನಲ್ಲಿ ಹಣ್ಣು ಒತ್ತಾಗಿರುವುದು ಕಡಿಮೆಯಾಗುವುದು', NULL, 'At the stage of full bloom, the bunches are dipped in 20 mg. of Gibberellic acid mixed in 1 liter of water to reduce the density of fruit in the bunches.', NULL, 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7849, 'GRAPES', 30, N'>3', N'November-December', N'November-December', N'11,12', N'Flowering', N'5', 'BELOW NORMAL', 'NO', 'ಕೃಷಿ ಹೊಂಡ, ಇತರ ಮೂಲಗಳಲ್ಲಿ ಲಭ್ಯವಿರುವ ನೀರನ್ನು ಬಳಸಿ ಸಂರಕ್ಷಣಾ ನೀರಾವರಿ ಕೊಡುವುದು', NULL, 'Conservation irrigation using water available from agricultural wells and other sources', NULL, 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7850, 'GRAPES', 30, N'>3', N'November-December', N'November-December', N'11,12', N'Flowering', N'5', 'ABOVE NORMAL', 'YES', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', NULL, 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field.', NULL, 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7851, 'GRAPES', 30, N'>3', N'November-December', N'November-December', N'11,12', N'Flowering', N'5', 'ABOVE NORMAL', 'NO', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', NULL, 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field.', NULL, 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7852, 'GRAPES', 30, N'>3', N'January-February', N'January-February', N'1,2', N'Fruit set and development', N'6', 'NORMAL', 'YES', 'ಕಾಯಿ ಕಚ್ಚುವ ಹಂತದಲ್ಲಿ ಗೊಂಚಲುಗಳನ್ನು 50 ಮಿ. ಗ್ರಾಂ. ಜಿಬ್ಬರ್ಲಿಕ್ ಆಮ್ಲ 1 ಲೀಟರ್ ನೀರಿನಲ್ಲಿ ಬೆರೆಸಿ ಅದ್ದುವುದರಿಂದ ಹಣ್ಣುಗಳ ಗಾತ್ರ ದ್ವಿಗುಣಗೊಳ್ಳುವುದು', 'ಬೂದಿ ರೋಗ ಕಂಡುಬಂದಲ್ಲಿ ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ 3.0 ಗ್ರಾಂ ನೀರಿನಲ್ಲಿ ಕರಗುವ ಗಂಧಕದ ಪುಡಿ ಅಥವಾ 2.0 ಗ್ರಾಂ ಟ್ರೆಡೆಮೆಫಾನ್ 25 WP ಅಥವಾ 1.0 ಗ್ರಾಂ ಕಾರ್ಬೆಂಡಜಿಂ 50 WP ಅಥವಾ 0.5 ಗ್ರಾಂ ಮೈಕ್ಲೋಬ್ಯೂಟಾನಿಲ್ 10 WP ಅನ್ನು ಬೆರೆಸಿ ಸಿಂಪಡಿಸುವುದು', 'At the stage of fruit set, the clusters are dipped in 50 mg. of Gibberellic acid mixed in 1 liter of water to double the size of the fruits.', 'If powdery mildew is found, spray with 3.0 g water-soluble sulfur powder or 2.0 g tredemefon 25 WP or 1.0 g carbendazim 50 WP or 0.5 g myclobutanil 10 WP per liter of water', 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7880, 'POMEGRANATE', NULL, N'<1', N'July-August', N'July-August', N'7,8', N'Establishment stage', N'2', 'BELOW NORMAL', 'NO', '• ಕೃಷಿ ಹೊಂಡ, ಇತರ ಮೂಲಗಳಲ್ಲಿ ಲಭ್ಯವಿರುವ ನೀರನ್ನು ಬಳಸಿ ನೀರಾವರಿ ಕೊಡುವುದು
• ಗಿಡ ಸ್ಥಾಪಿತವಾಗದೆ ಇರುವ ಜಾಗದಲ್ಲಿ ಬೇರೆ ಸಸಿಯನ್ನು ನೆಡುವುದು
• ಗಿಡಗಳು ನೇರವಾಗಿ ಬೆಳೆಯಲು ಅವುಗಳಿಗೆ ಕೋಲಿನ ಆಸರೆ ಒದಗಿಸುವುದು
• ತೋಟದಲ್ಲಿ ಹಸಿರೆಲೆ ಗೊಬ್ಬರದ ಗಿಡಗಳನ್ನು ಬೆಳೆದಿದ್ದರೆ ಅವನ್ನು ಬಿತ್ತಿದ 45 ದಿನಗಳ ನಂತರ ಮಣ್ಣಿಗೆ ಸೇರಿಸುವುದು
• ತೋಟದ ಮಧ್ಯೆ ಅಂತರಬೆಳೆ ಬೆಳೆದಿದ್ದರೆ ಅವುಗಳಿಗೆ ತಗುಲುವ ರೋಗ ಮತ್ತು ಕೀಟಗಳ ಮೇಲೆ ಗಮನ ಹರಿಸುವುದು', NULL, '• Irrigation using water available from agricultural wells and other sources
• Planting other plants in areas where plants are not established
• Providing support for plants with sticks to grow upright
• If green manure plants are grown in the garden, incorporate them into the soil 45 days after sowing
• If intercrops are grown in the garden, pay attention to the diseases and pests that they are susceptible to', NULL, 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7881, 'POMEGRANATE', NULL, N'<1', N'July-August', N'July-August', N'7,8', N'Establishment stage', N'2', 'ABOVE NORMAL', 'YES', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', 'ಹಣ್ಣು ಕೊರಕ ನಿಯಂತ್ರಣಕ್ಕಾಗಿ ಹೂವು ಬಿಡುವ ಸಮಯದಿಂದ ಹಣ್ಣು ಕೊಯ್ಲು ಮಾಡುವವರೆಗೆ ಪ್ರತಿ ಮೂರು ವಾರಕ್ಕೊಮ್ಮೆ 0.15 ಮಿ.ಲೀ. ಸೈಯಾಂಟ್ರನಿಲಿಪ್ರೋಲ್‍ 10.26OD ಅಥವಾ 0.5 ಮಿ.ಲೀ. ಸ್ಪೈಯನೋಸಾಡ್ 45 SC ಅಥವಾ 0.5 ಮಿ.ಲೀ. ಸೈಪರ್‌ಮೆಥ್ರಿನ್ 25 EC ಅನ್ನು ಪ್ರತಿ ಲೀಟರ್ ನೀರಿಗೆ ಬೆರೆಸಿ ಸಿಂಪಡಿಸುವುದು', 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field.', 'For fruit borer control, spray 0.15 ml. Cyantraniliprole 10.26OD or 0.5 ml. Spyanosad 45 SC or 0.5 ml. Cypermethrin 25 EC per liter of water every three weeks from the time of flowering to fruit harvest', 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7882, 'POMEGRANATE', NULL, N'<1', N'July-August', N'July-August', N'7,8', N'Establishment stage', N'2', 'ABOVE NORMAL', 'NO', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', NULL, 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field.', NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7883, 'POMEGRANATE', NULL, N'<1', N'September-October', N'September-October', N'9,10', N'Vegetative stage', N'2', 'NORMAL', 'YES', '• ತೋಟದಲ್ಲಿ ಅಂತರ ಬೇಸಾಯದ ಮೂಲಕ ಕಳೆ ನಿರ್ವಹಣೆ ಮಾಡಿ LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ರಸಗೊಬ್ಬರಗಳನ್ನು ಒದಗಿಸುವುದು
• ಪ್ರಸ್ತುತ ಹಂತದಲ್ಲಿ ಬೆಳೆ ಉತ್ತಮವಾಗಿದ್ದರೆ, ಇತರೆ ಬೆಳೆ ಬೆಳೆದಿದ್ದಲ್ಲಿ ಅವುಗಳ ನಿರ್ವಹಣೆಯತ್ತ ಗಮನಹರಿಸುವುದು', NULL, '• Manage weeds through intercropping in the garden and provide fertilizers recommended based on LRI
• If the crop is good at the current stage, focus on managing other crops if they are grown', NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
