INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7914, 'POMEGRANATE', NULL, N'1-2', N'July-August', N'July-August', N'7,8', N'Vegetative stage', N'2', 'NORMAL', 'NO', '• ತೋಟದಲ್ಲಿ ಹಸಿರೆಲೆ ಗೊಬ್ಬರದ ಗಿಡಗಳನ್ನು ಬೆಳೆದಿದ್ದರೆ ಅವನ್ನು ಬಿತ್ತಿದ 45 ದಿನಗಳ ನಂತರ ಮಣ್ಣಿಗೆ ಸೇರಿಸುವುದು
• ತೋಟದ ಮಧ್ಯೆ ಅಂತರಬೆಳೆ ಬೆಳೆದಿದ್ದರೆ ಅವುಗಳಿಗೆ ತಗುಲುವ ರೋಗ ಮತ್ತು ಕೀಟಗಳ ಮೇಲೆ ಗಮನ ಹರಿಸುವುದು', 'ದುಂಡಾಣು ಎಲೆಚುಕ್ಕೆ ಕಂಡು ಬಂದಾಗ ಪ್ರಾರಂಭಿಕ ಹಂತದಲ್ಲಿ 0.5 ಗ್ರಾಂ 2 ಬ್ರೋಮೋ-2 ನೈಟ್ರೋಪ್ರೋಪೇನ್‍1,3 ಅಥವಾ 0.5 ಗ್ರಾಂ ಸ್ಟ್ರೆಪ್ಟೋಸೈಕ್ಲೀನ್‍ ಅಥವಾ 3.0 ಗ್ರಾಂ ತಾಮ್ರದ ಆಕ್ಸಿಕ್ಲೋರೈಡ್‍ 50 WP ಅನ್ನು ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿನಲ್ಲಿ ಬೆರೆಸಿ ಸಿಂಪಡಿಸುವುದು. ಹವಾಮಾನ ಹಾಗೂ ರೋಗ ಬಾಧೆಗೆ ಅನುಸಾರವಾಗಿ 5 ರಿಂದ 6 ಸಿಂಪರಣೆಗಳನ್ನು 10 ದಿನಗಳ ಅಂತರದಲ್ಲಿ ಕೈಗೊಳ್ಳುವುದು ಉತ್ತಮ', '• If green manure crops are grown in the garden, incorporate them into the soil 45 days after sowing. • If intercrops are grown in the garden, pay attention to the diseases and pests that they are susceptible to.', 'When round leaf spot is found, spray 0.5 g 2 bromo-2 nitropropane 1,3 or 0.5 g streptocycline or 3.0 g copper oxychloride 50 WP per liter of water at the initial stage. It is better to do 5 to 6 sprays at an interval of 10 days depending on the weather and disease severity', 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7915, 'POMEGRANATE', NULL, N'1-2', N'July-August', N'July-August', N'7,8', N'Vegetative stage', N'2', 'BELOW NORMAL', 'YES', '• ತೋಟದಲ್ಲಿ ಹಸಿರೆಲೆ ಗೊಬ್ಬರದ ಗಿಡಗಳನ್ನು ಬೆಳೆದಿದ್ದರೆ ಅವನ್ನು ಬಿತ್ತಿದ 45 ದಿನಗಳ ನಂತರ ಮಣ್ಣಿಗೆ ಸೇರಿಸುವುದು
• ತೋಟದ ಮಧ್ಯೆ ಅಂತರಬೆಳೆ ಬೆಳೆದಿದ್ದರೆ ಅವುಗಳಿಗೆ ತಗುಲುವ ರೋಗ ಮತ್ತು ಕೀಟಗಳ ಮೇಲೆ ಗಮನ ಹರಿಸುವುದು', 'ಜಮೀನಿನಲ್ಲಿ ಬೋರಾನ್ ಕೊರತೆಯಿದ್ದರೆ ಹಣ್ಣು ಸೀಳುತ್ತವೆ. ಇದಕ್ಕೆ 1 ಗ್ರಾಂ ಬೋರಾಕ್ಸ್ (0.1 %) ಒಂದು ಲೀಟರ್‍ ನೀರಿನಲ್ಲಿ ಬೆರೆಸಿ ಸಿಂಪಡಿಸುವುದು. ಹಣ್ಣು ಕೊಳೆ ರೋಗದ ನಿಯಂತ್ರಣಕ್ಕಾಗಿ ಹೂಬಿಡುವ ಸಮಯದಿಂದ ಹಣ್ಣು ಕೊಯ್ಲು ಮಾಡುವವರೆಗೆ ಪ್ರತಿ ಮೂರು ವಾರಕ್ಕೊಮ್ಮೆ 2 ಗ್ರಾಂ ಜೈನೆಬ್ ಅಥವಾ 2 ಗ್ರಾಂ ಮೆಂಕೋಜೆಬ್ 75 WP ಅಥವಾ 1 ಗ್ರಾಂ. ಥೈಯೋಫಿನೇಟ್‍ ಮಿಥೈಲ್‍ 70 WP ಪ್ರತಿ ಲೀಟರ್ ನೀರಿಗೆ ಬೆರೆಸಿ ಸಿಂಪಡಿಸುವುದು', '• If green manure crops are grown in the garden, incorporate them into the soil 45 days after sowing. • If intercrops are grown in the garden, pay attention to the diseases and pests that they are susceptible to.', 'If there is a deficiency of boron in the field, the fruits crack. For this, spray 1 gram of borax (0.1%) mixed in one liter of water. For the control of fruit rot, spray 2 grams of zeineb or 2 grams of mencozeb 75 WP or 1 gram of thiophenate methyl 70 WP mixed in one liter of water every three weeks from the time of flowering to the time of fruit harvesting', 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7916, 'POMEGRANATE', NULL, N'1-2', N'July-August', N'July-August', N'7,8', N'Vegetative stage', N'2', 'BELOW NORMAL', 'NO', '• ಕೃಷಿ ಹೊಂಡ, ಇತರ ಮೂಲಗಳಲ್ಲಿ ಲಭ್ಯವಿರುವ ನೀರನ್ನು ಬಳಸಿ ನೀರಾವರಿ ಕೊಡುವುದು
• ತೋಟದಲ್ಲಿ ಹಸಿರೆಲೆ ಗೊಬ್ಬರದ ಗಿಡಗಳನ್ನು ಬೆಳೆದಿದ್ದರೆ ಅವನ್ನು ಬಿತ್ತಿದ 45 ದಿನಗಳ ನಂತರ ಮಣ್ಣಿಗೆ ಸೇರಿಸುವುದು
• ತೋಟದ ಮಧ್ಯೆ ಅಂತರಬೆಳೆ ಬೆಳೆದಿದ್ದರೆ ಅವುಗಳಿಗೆ ತಗುಲುವ ರೋಗ ಮತ್ತು ಕೀಟಗಳ ಮೇಲೆ ಗಮನ ಹರಿಸುವುದು', NULL, '• Irrigation using water available from agricultural wells and other sources
• If green manure crops are grown in the garden, incorporate them into the soil 45 days after sowing
• If intercrops are grown in the garden, pay attention to the diseases and pests that they are susceptible to', NULL, 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
