INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7633, 'MANGO', NULL, N'1-4', N'August-September', N'August-September', N'8,9', N'Vegetative stage', N'2', 'ABOVE NORMAL', 'YES', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', NULL, 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field.', NULL, 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7634, 'MANGO', NULL, N'1-4', N'August-September', N'August-September', N'8,9', N'Vegetative stage', N'2', 'ABOVE NORMAL', 'NO', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', NULL, 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field.', NULL, 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7635, 'MANGO', NULL, N'1-4', N'October-November', N'October-November', N'10,11', N'Vegetative stage', N'2', 'NORMAL', 'YES', 'ಸೂಚಿಸಲಾದ ಸಸ್ಯ ಸಂರಕ್ಷಣಾ ಕ್ರಮಗಳನ್ನು ಕೈಗೊಳ್ಳುವುದು', 'ಜಿಗಿ ಹುಳು ಹಾಗೂ ಶಲ್ಕ ಕೀಟ ಕಂಡು ಬಂದಲ್ಲಿ ಲೀ. ನೀರಿಗೆ 0.3 ಮಿ.ಲೀ. ಇಮೀಡಾಕ್ಲೋಪ್ರಿಡ್ 17.8 SL ಅಥವಾ 5% ಬೇವಿನ ಬೀಜದ ಕಷಾಯವನ್ನು ಬೆರೆಸಿ ಸಿಂಪಡಿಸುವುದು', 'Carrying out the recommended plant protection measures', 'If leafhoppers and scale insects are found, spray with 0.3 ml of Imidacloprid 17.8 SL or 5% neem seed extract per liter of water', 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7683, 'MANGO (EARLY VARIETIES)', NULL, N'>4', N'February-March', N'February-March', N'2,3', N'Fruit development stage', N'4', 'NORMAL', 'YES', 'ಸೂಚಿಸಲಾದ ಸಸ್ಯ ಸಂರಕ್ಷಣಾ ಕ್ರಮಗಳನ್ನು ಕೈಗೊಳ್ಳುವುದು', 'ಮಾವಿನಲ್ಲಿ ಜಿಗಿಹುಳು, ಬೂದಿರೋಗ ಹಾಗೂ ಚಿಬ್ಬು ರೋಗದಿಂದ ಎಳೆಯ ಕಾಯಿಗಳು ಹಳದಿಯಾಗಿ ಉದುರುವುದನ್ನು ಅಥವಾ ಕಾಯಿ ಉದುರವುದು ಕಂಡು ಬಂದಲ್ಲಿ, ಇವುಗಳ ಹತೋಟಿಗೆ, ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ 0.5 ಮಿ.ಲೀ. ಸಂಯುಕ್ತ ಕೀಟನಾಶಕ ಥೈಯಾಮಿಥೋಕ್ಸಾಮ್ 12.6% + ಲ್ಯಾಮ್ಡಾ ಸೈಹ್ಯಾಲೋತ್ರಿನ 9.5 % ZC + 1 ಗ್ರಾಂ ಸಂಯುಕ್ತ ಶಿಲೀಂದ್ರನಾಶಕ ಟೆಬೂಕೋನಾಜೊಲ್ 50% + ಟ್ರೈಫ್ಲಾಕ್ಸಿಸ್ಟ್ರೋಬಿನ್ 25% WG + 0.5 ಮಿ.ಲೀ. ಪ್ಲಾನೋಫಿಕ್ಸ (NAA) ಅನ್ನು ಬೆರೆಸಿ ಗಿಡದ ಪ್ರತಿ ಭಾಗವು ಚನ್ನಾಗಿ ತೊಯ್ಯುವಹಾಗೆ ಸಿಂಪಡಿಸುವುದು', 'Carrying out the recommended plant protection measures', 'If young fruits are yellowing or falling off due to leafhopper, powdery mildew and leaf spot in mango, for their control, mix 0.5 ml of compound insecticide Thiamethoxam 12.6% + Lambda Cyhalothrin 9.5 % ZC + 1 gm compound fungicide Tebuconazole 50% + Trifloxystrobin 25% WG + 0.5 ml of Planofix (NAA) per liter of water and spray it thoroughly so that every part of the plant is thoroughly wetted', 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7684, 'MANGO (EARLY VARIETIES)', NULL, N'>4', N'February-March', N'February-March', N'2,3', N'Fruit development stage', N'4', 'NORMAL', 'NO', 'ಸೂಚಿಸಲಾದ ಸಸ್ಯ ಸಂರಕ್ಷಣಾ ಕ್ರಮಗಳನ್ನು ಕೈಗೊಳ್ಳುವುದು', 'ಮಾವಿನಲ್ಲಿ ಜಿಗಿಹುಳು, ಬೂದಿರೋಗ ಹಾಗೂ ಚಿಬ್ಬು ರೋಗದಿಂದ ಎಳೆಯ ಕಾಯಿಗಳು ಹಳದಿಯಾಗಿ ಉದುರುವುದನ್ನು ಅಥವಾ ಕಾಯಿ ಉದುರವುದು ಕಂಡು ಬಂದಲ್ಲಿ, ಇವುಗಳ ಹತೋಟಿಗೆ, ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ 0.5 ಮಿ.ಲೀ. ಸಂಯುಕ್ತ ಕೀಟನಾಶಕ ಥೈಯಾಮಿಥೋಕ್ಸಾಮ್ 12.6% + ಲ್ಯಾಮ್ಡಾ ಸೈಹ್ಯಾಲೋತ್ರಿನ 9.5 % ZC + 1 ಗ್ರಾಂ ಸಂಯುಕ್ತ ಶಿಲೀಂದ್ರನಾಶಕ ಟೆಬೂಕೋನಾಜೊಲ್ 50% + ಟ್ರೈಫ್ಲಾಕ್ಸಿಸ್ಟ್ರೋಬಿನ್ 25% WG + 0.5 ಮಿ.ಲೀ. ಪ್ಲಾನೋಫಿಕ್ಸ (NAA) ಅನ್ನು ಬೆರೆಸಿ ಗಿಡದ ಪ್ರತಿ ಭಾಗವು ಚನ್ನಾಗಿ ತೊಯ್ಯುವಹಾಗೆ ಸಿಂಪಡಿಸುವುದು', 'Carrying out the recommended plant protection measures', 'If young fruits are yellowing or falling off due to leafhopper, powdery mildew and leaf spot in mango, for their control, mix 0.5 ml of compound insecticide Thiamethoxam 12.6% + Lambda Cyhalothrin 9.5 % ZC + 1 gm compound fungicide Tebuconazole 50% + Trifloxystrobin 25% WG + 0.5 ml of Planofix (NAA) per liter of water and spray it thoroughly so that every part of the plant is thoroughly wetted', 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7685, 'MANGO (EARLY VARIETIES)', NULL, N'>4', N'February-March', N'February-March', N'2,3', N'Fruit development stage', N'4', 'BELOW NORMAL', 'YES', 'ಸೂಚಿಸಲಾದ ಸಸ್ಯ ಸಂರಕ್ಷಣಾ ಕ್ರಮಗಳನ್ನು ಕೈಗೊಳ್ಳುವುದು', 'ದುಂಡಾಣು ಎಲೆ ಚುಕ್ಕೆ ರೋಗ ಕಂಡು ಬಂದರೆ 3.0 ಗ್ರಾಂ ತಾಮ್ರದ ಆಕ್ಸಿಕ್ಲೋರೈಡ್ 50 WP ಜೊತೆಗೆ 0.5 ಗ್ರಾಂ ಸ್ರೆಫ್ಟೋಸೈಕ್ಲಿನ್ ಪ್ರತಿ ಲೀಟರ್ ನೀರಿಗೆ ಸೇರಿಸಿ ಸಿಂಪಡಿಸುವುದು', 'Carrying out the recommended plant protection measures', 'If round leaf spot disease is detected, spray 3.0 g of copper oxychloride 50 WP with 0.5 g of streptocyline per liter of water', 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7686, 'MANGO (EARLY VARIETIES)', NULL, N'>4', N'February-March', N'February-March', N'2,3', N'Fruit development stage', N'4', 'BELOW NORMAL', 'NO', 'ಗಿಡದ ಸುತ್ತಲು ಒಣಗಿದ ಎಲೆಗಳಿಂದ ಮಣ್ಣಿನ ಮೇಲೊದಿಕೆ ಮಾಡುವುದರಿಂದ ಮಣ್ಣಿನ ತೇವಾಂಶವನ್ನು ಕಾಪಾಡಿಕೊಳ್ಳಬಹುದು', NULL, 'Mulching the soil with dry leaves around the plant can help maintain soil moisture.', NULL, 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7733, 'MANGO (LATE VARIETIES)', NULL, N'>4', N'July-August', N'July-August', N'7,8', N'Vegetative stage', N'2', 'BELOW NORMAL', 'YES', '• ಸಾಲುಗಳ ಮಧ್ಯ ರೆಂಟೆ ಹೊಡೆದು, ಹರಗಿ, ಭೂಮಿಯನ್ನು ಸ್ವಚ್ಛ ಮಾಡುವುದು 
 • ಕೊಂಬೆಗಳನ್ನು ಸವರುವುದು (ಪ್ರೂನಿಂಗ್ ಮಾಡುವುದು)‌, ಇದರಿಂದ ಹೊಸ ಚಿಗುರು ಬರುವುದಕ್ಕೆ ಸಹಕಾರಿಯಾಗುತ್ತದೆ. (ಹೆಚ್ಚಿನ ಮಾಹಿತಿಗಾಗಿ ಮಾವು ಬೆಳೆ ಪದ್ಧತಿಯಲ್ಲಿ ವೀಕ್ಷಿಸಬಹುದು)
• ನಂತರ ಗಿಡದ ಸುತ್ತ ಪಾತಿ ಮಾಡಿ LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ರಸಗೊಬ್ಬರಗಳನ್ನು ಕೊಡುವುದು
 • ಹಸಿರೆಲೆ ಗೊಬ್ಬರದ ಗಿಡಗಳಾದ ಸೆಣಬು, ಅಲಸಂದಿ ಅಥವಾ ಹುರುಳಿ ಬೆಳೆಯನ್ನು ಬೆಳೆಯುವುದರಿಂದ ಭೂಮಿಯ ಫಲವತ್ತತೆಯನ್ನು ಹೆಚ್ಚಿಸಬಹುದು
 • ತೋಟದ ಮಧ್ಯದಲ್ಲಿ ಶೇಂಗಾ, ಸೂರ್ಯಕಾಂತಿ ಅಥವಾ ತರಕಾರಿ ಬೆಳೆಗಳನ್ನು ಅಂತರಬೆಳೆಗಳನ್ನಾಗಿ ಬೆಳೆಯಬಹುದು', 'ಕಾಂಡ ಕೊರಕ ಕಂಡು ಬಂದಲ್ಲಿ ಎಕೆರೆಗೆ 4-5 ಹಳದಿ ಮೋಹಕ ಅಂಟು ಬಲೆಗಳನ್ನು ಅಥವಾ ಎಕೆರೆಗೆ 10 ಲಿಂಗಾಕರ್ಷಕ ಮೋಹಕ ಬಲೆಗಳನ್ನು ಬಳಸುವುದು. ರಂಧ್ರಗಳನ್ನು ಕೆಸರು ಮಣ್ಣಿನಿಂದ ಮುಚ್ಚುವುದು ಹಾಗೂ ಪ್ರತಿ ರಂಧ್ರಕ್ಕೆ 5 ಮಿಲೀ. ಕ್ವಿನಾಲ್‌ಫಾಸ್ 25 EC ಅನ್ನು ಪಿಚಕಾರಿಯ ಮೂಲಕ ರಂಧ್ರಕ್ಕೆ ಸೇರಿಸುವುದು. ಚಿಬ್ಬು ರೋಗ ಕಂಡುಬಂದಲ್ಲಿ 1% ರ ಬೋರ್ಡೋ ದ್ರಾವಣ ಅಥವಾ 1 ಗ್ರಾಂ. ಕಾರ್ಬೆಂಡಜಿಮ್ 50 WP ಅನ್ನು ಸೇರಿಸಿ ಸಿಂಪಡಿಸುವುದು', '• Clean the soil by harrowing and spreading between the rows 
• Pruning the branches, which helps in the emergence of new shoots. (For more information, see Mango Crop System)
• Then make a bed around the plant and apply fertilizers recommended based on LRI
• Growing green manure crops such as jute, sorghum or buckwheat can increase the fertility of the soil
• Groundnut, sunflower or vegetable crops can be grown as intercrops in the middle of the garden', 'If stem borer is found, use 4-5 yellow attractant traps per acre or 10 sex attractant traps per acre. Cover the holes with silt soil and add 5 ml. Quinalphos 25 EC per hole through a syringe. If powdery mildew is found, spray with 1% Bordeaux mixture or 1 gm. Carbendazim 50 WP', 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7734, 'MANGO (LATE VARIETIES)', NULL, N'>4', N'July-August', N'July-August', N'7,8', N'Vegetative stage', N'2', 'BELOW NORMAL', 'NO', 'ಗಿಡದ ಸುತ್ತಲು ಒಣಗಿದ ಎಲೆಗಳಿಂದ ಮಣ್ಣಿನ ಮೇಲೊದಿಕೆ ಮಾಡುವುದರಿಂದ ಮಣ್ಣಿನ ತೇವಾಂಶವನ್ನು ಕಾಪಾಡಿಕೊಳ್ಳಬಹುದು', 'ಚಿಬ್ಬು ರೋಗ ಕಂಡುಬಂದಲ್ಲಿ ಪ್ರತಿ ಲೀಟರ್‍ 1% ರ ಬೋರ್ಡೋ ದ್ರಾವಣ ಅಥವಾ 1 ಗ್ರಾಂ ಕಾರ್ಬೆಂಡಿಯಾಜಿಮ್ 50 WP ಅಥವಾ 1 ಗ್ರಾಂ ಥಿಯೋಫೆನೇಟ್ ಮೀಥೈಲ್ 70 WP ಅಥವಾ 2 ಗ್ರಾಂ ಕ್ಲೋರೊಥಲೋನಿಲ್ 75 WP ಅನ್ನು ಬೆರೆಸಿ ಸಿಂಪಡಿಸುವುದು', 'Mulching the soil with dry leaves around the plant can help maintain soil moisture.', 'If powdery mildew is found, spray with 1% Bordeaux mixture per liter or 1 gm Carbendiazim 50 WP or 1 gm Thiophenate Methyl 70 WP or 2 gm Chlorothalonil 75 WP', 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7735, 'MANGO (LATE VARIETIES)', NULL, N'>4', N'July-August', N'July-August', N'7,8', N'Vegetative stage', N'2', 'ABOVE NORMAL', 'YES', 'ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ತೋಟದಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದು ಕೃಷಿ ಹೊಂಡಗಳಲ್ಲಿ ಶೇಖರಿಸಲು ಅನುವುಮಾಡಿಕೊಡಿ', NULL, 'If there is heavy rainfall, allow water to drain from the garden and store in agricultural pits.', NULL, 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7736, 'MANGO (LATE VARIETIES)', NULL, N'>4', N'July-August', N'July-August', N'7,8', N'Vegetative stage', N'2', 'ABOVE NORMAL', 'NO', 'ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ತೋಟದಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದು ಕೃಷಿ ಹೊಂಡಗಳಲ್ಲಿ ಶೇಖರಿಸಲು ಅನುವುಮಾಡಿಕೊಡಿ', NULL, 'If there is heavy rainfall, allow water to drain from the garden and store in agricultural pits.', NULL, 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7737, 'MANGO (LATE VARIETIES)', NULL, N'>4', N'September-October', N'September-October', N'9,10', N'Vegetative stage', N'2', 'NORMAL', 'YES', 'ಪ್ರಸ್ತುತ ಹಂತದಲ್ಲಿ ಬೆಳೆ ಉತ್ತಮವಾಗಿದ್ದರೆ, ಇತರೆ ಬೆಳೆ ಬೆಳೆದಿದ್ದಲ್ಲಿ ಅವುಗಳ ನಿರ್ವಹಣೆಯತ್ತ ಗಮನಹರಿಸುವುದು', NULL, 'If the crop is good at the current stage, focus on managing other crops if they have grown.', NULL, 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
