INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7636, 'MANGO', NULL, N'1-4', N'October-November', N'October-November', N'10,11', N'Vegetative stage', N'2', 'NORMAL', 'NO', 'ಸೂಚಿಸಲಾದ ಸಸ್ಯ ಸಂರಕ್ಷಣಾ ಕ್ರಮಗಳನ್ನು ಕೈಗೊಳ್ಳುವುದು', 'ಜಿಗಿ ಹುಳು ಹಾಗೂ ಶಲ್ಕ ಕೀಟ ಕಂಡು ಬಂದಲ್ಲಿ ಲೀ. ನೀರಿಗೆ 0.3 ಮಿ.ಲೀ. ಇಮೀಡಾಕ್ಲೋಪ್ರಿಡ್ 17.8 SL ಅಥವಾ 5% ಬೇವಿನ ಬೀಜದ ಕಷಾಯವನ್ನು ಬೆರೆಸಿ ಸಿಂಪಡಿಸುವುದು', 'Carrying out the recommended plant protection measures', 'If leafhoppers and scale insects are found, spray with 0.3 ml of Imidacloprid 17.8 SL or 5% neem seed extract per liter of water', 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7637, 'MANGO', NULL, N'1-4', N'October-November', N'October-November', N'10,11', N'Vegetative stage', N'2', 'BELOW NORMAL', 'YES', 'ಪ್ರಸ್ತುತ ಹಂತದಲ್ಲಿ ಬೆಳೆ ಉತ್ತಮವಾಗಿದ್ದರೆ, ಇತರೆ ಬೆಳೆ ಬೆಳೆದಿದ್ದಲ್ಲಿ ಅವುಗಳ ನಿರ್ವಹಣೆಯತ್ತ ಗಮನಹರಿಸುವುದು', NULL, 'If the crop is good at the current stage, focus on managing other crops if they have grown.', NULL, 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7638, 'MANGO', NULL, N'1-4', N'October-November', N'October-November', N'10,11', N'Vegetative stage', N'2', 'BELOW NORMAL', 'NO', 'ಕೃಷಿ ಹೊಂಡ, ಇತರ ಮೂಲಗಳಲ್ಲಿ ಲಭ್ಯವಿರುವ ನೀರನ್ನು ಬಳಸಿ ಸಂರಕ್ಷಣಾ ನೀರಾವರಿ ಕೊಡುವುದು. ಗಿಡದ ಸುತ್ತಲು ಒಣಗಿದ ಎಲೆಗಳಿಂದ ಮಣ್ಣಿನ ಮೇಲೊದಿಕೆ ಮಾಡುವುದರಿಂದ ಮಣ್ಣಿನ ತೇವಾಂಶವನ್ನು ಕಾಪಾಡಿಕೊಳ್ಳಬಹುದು', 'ಹಿಟ್ಟು ತಿಗಣೆ ಕಂಡುಬಂದಲ್ಲಿ ಪ್ರತಿ ಲೀಟರ್ ನೀರಿಗೆ 1.25 ಮಿ.ಲೀ. ಬುಪ್ರೊಫೆಜಿನ್ 25% SC ಅಥವಾ 2 ಮಿಲೀ. ಪ್ರೊಫೆನೊಫಾಸ್ 50 EC + 5 ಗ್ರಾಂ ಮೀನಿನ ಎಣ್ಣೆ ರೋಸಿನ್ ಸೋಪ್ ಅಥವಾ 5% ಬೇವಿನ ಬೀಜ ಕಷಾಯವನ್ನು ಬೆರೆಸಿ ಸಿಂಪಡಿಸುವುದು', 'Conservation irrigation is done using water available from agricultural wells and other sources. Mulching the soil with dry leaves around the plant can help maintain soil moisture.', 'If mealybugs are found, spray 1.25 ml of Buprofezin 25% SC or 2 ml of Profenophos 50 EC + 5 gm fish oil rosin soap or 5% neem seed infusion per liter of water', 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7639, 'MANGO', NULL, N'1-4', N'October-November', N'October-November', N'10,11', N'Vegetative stage', N'2', 'ABOVE NORMAL', 'YES', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', NULL, 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field.', NULL, 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7640, 'MANGO', NULL, N'1-4', N'October-November', N'October-November', N'10,11', N'Vegetative stage', N'2', 'ABOVE NORMAL', 'NO', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', NULL, 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field.', NULL, 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7641, 'MANGO', NULL, N'1-4', N'December-January', N'December-January', N'12,1', N'Vegetative stage', N'3', 'NORMAL', 'YES', 'ಸಸ್ಯದ ಬೆಳವಣಿಗೆಯನ್ನು ಉತ್ತೇಜಿಸಲು ಹೂ ಗೊಂಚಲು ಕಂಡಲ್ಲಿ ಅವುಗಳನ್ನು ತೆಗೆಯುವುದು', 'ಬೂದಿ ರೋಗ ಕಂಡುಬಂದಲ್ಲಿ ಪ್ರತಿ ಲೀಟರ್ ನೀರಿಗೆ 3.0 ಗ್ರಾಂ. ನೀರಿನಲ್ಲಿ ಕರಗುವ ಗಂಧಕದ ಪುಡಿ ಅಥವಾ 1.0 ಮಿ.ಲೀ. ಹೆಕ್ಸಕೋನೋಜೋಲ್ 5 EC ಅಥವಾ 0.15 ಮಿ.ಲೀ. ಫ್ಲುಕ್ಸಿಪೈರಾಕ್ಸಾಡ್+ಪೈರಾಕ್ಲೊಸ್ರೊಬಿನ್ (500 SC) ಅನ್ನು ಬೆರೆಸಿ ಸಿಂಪಡಿಸುವುದು. ಡೈಬ್ಯಾಕ್ ರೋಗ ಲಕ್ಷಣಗಳು ಕಂಡು ಬಂದರೆ ಶೇ. 0.3 ತಾಮ್ರದ ಆಕ್ಸಿಕ್ಲೋರೈಡ್ 50 WP ಯನ್ನು ಸಿಂಪಡಿಸುವುದು', 'Remove flower clusters if they appear to encourage plant growth.', 'If powdery mildew is found, spray 3.0 gm. Water soluble sulfur powder or 1.0 ml. Hexaconazole 5 EC or 0.15 ml. Fluxipyroxad + Pyraclosrobin (500 SC) mixed together per liter of water. If dieback symptoms are found, spray 0.3% copper oxychloride 50 WP', 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7687, 'MANGO (EARLY VARIETIES)', NULL, N'>4', N'February-March', N'February-March', N'2,3', N'Fruit development stage', N'4', 'ABOVE NORMAL', 'YES', 'ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ತೋಟದಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದು ಕೃಷಿ ಹೊಂಡಗಳಲ್ಲಿ ಶೇಖರಿಸಲು ಅನುವುಮಾಡಿಕೊಡಿ', 'ಒಟೆ ಕೊರಕ ಕಂಡು ಬಂದಲ್ಲಿ ಲೀ. ನೀರಿಗೆ 1.0 ಮಿ.ಲೀ. ಡೆಲ್ಟಾಮೆಥ್ರಿನ್ 2.8 EC ಅಥವಾ 1.0 ಗ್ರಾಂ ಅಸಿಫೇಟ್ 75 SP ಅಥವಾ 2.0 ಮಿ.ಲೀ. ಡೈಮಿಥೋಯೇಟ್ 30 EC ಮಾರ್ಚ್ ತಿಂಗಳ ಎರಡನೇ ವಾರದಲ್ಲಿ ಸಿಂಪರಣೆ ಮಾಡುವುದು. ಈ ಸಿಂಪರಣೆಯನ್ನು ಮೂರು ವಾರಗಳ ನಂತರ ಪುನರಾರ್ತಿಸುವುದು ಉತ್ತಮ. ಮಸಿ ರೋಗಕ್ಕೆ ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ 3.0 ಗ್ರಾಂ. ನೀರಿನಲ್ಲಿ ಕರಗುವ ಗಂಧಕವನ್ನು ಸಿಂಪಡಿಸುವುದು', 'If there is heavy rainfall, allow water to drain from the garden and store in agricultural pits.', 'If Ote borer is found, spray 1.0 ml. Deltamethrin 2.8 EC or 1.0 gm. Acephate 75 SP or 2.0 ml. Dimethoate 30 EC per liter of water in the second week of March. It is better to repeat this spray after three weeks. For powdery mildew, spray 3.0 gm. Water-soluble sulphur per liter of water', 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7688, 'MANGO (EARLY VARIETIES)', NULL, N'>4', N'February-March', N'February-March', N'2,3', N'Fruit development stage', N'4', 'ABOVE NORMAL', 'NO', 'ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ತೋಟದಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದು ಕೃಷಿ ಹೊಂಡಗಳಲ್ಲಿ ಶೇಖರಿಸಲು ಅನುವುಮಾಡಿಕೊಡಿ', NULL, 'If there is heavy rainfall, allow water to drain from the garden and store in agricultural pits.', NULL, 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7689, 'MANGO (EARLY VARIETIES)', NULL, N'>4', N'April', N'April', N'4', N'Fruit maturity stage', N'5', 'NORMAL', 'YES', 'ಸೂಚಿಸಲಾದ ಸಸ್ಯ ಸಂರಕ್ಷಣಾ ಕ್ರಮಗಳನ್ನು ಕೈಗೊಳ್ಳುವುದು', 'ಹಣ್ಣಿನ ನೋಣ ಕಂಡು ಬಂದಲ್ಲಿ ಪ್ರತಿ ಹೆಕ್ಟೇರ್ ಗೆ 10 ಮೋಹಕ ಬಲೆಗಳನ್ನು ತೂಗು ಹಾಕುವುದು ಅಥವಾ. 1.7 ಮಿ.ಲೀ ಡೈಮಿಥೋಯೇಟ್ 30 EC ಯನ್ನು 10 ಗ್ರಾಂ ಬೆಲ್ಲದೊಂದಿಗೆ ಕರಗಿಸಿ ಹಣ್ಣು ಮಾಗುವ ಅವಧಿಯಲ್ಲಿ ಸಿಂಪರಣೆ ಮಾಡುವುದು ಹಾಗೂ ಹಣ್ಣುಗಳು ನಿಂಬೆಹಣ್ಣಿನ ಗಾತ್ರದಲ್ಲಿದ್ದಾಗ 1 ಮಿ.ಲೀ. ಡೆಲ್ಟಾಮೆಥ್ರಿನ್ 2.8 EC ಯನ್ನು ಸಿಂಪರಣೆ ಮಾಡುವುದು. ಕೊಯ್ಲಾದ ನಂತರ 1 ಅಡಿ ಆಳದ ಟ್ರೆಂಚ್‌ಗಳನ್ನು ಕಾಂಡದ 2.5 ರಿಂದ 3 ಮೀ. ದೂರದಲ್ಲಿ ಇಳಜಾರಿಗೆ ಅಡ್ಡಲಾಗಿ ನಿರ್ಮಿಸುವುದು ಉತ್ತಮ', 'Carrying out the recommended plant protection measures', 'If fruit borer is found, hang 10 bait traps per hectare or spray 1.7 ml of Dimethoate 30 EC dissolved in 10 gm jaggery during the fruit ripening period and spray 1 ml of Deltamethrin 2.8 EC when the fruits are the size of lemons. After harvesting, it is better to make 1 foot deep trenches at a distance of 2.5 to 3 m from the stem, across the ridge', 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7690, 'MANGO (EARLY VARIETIES)', NULL, N'>4', N'April', N'April', N'4', N'Fruit maturity stage', N'5', 'NORMAL', 'NO', 'ಸೂಚಿಸಲಾದ ಸಸ್ಯ ಸಂರಕ್ಷಣಾ ಕ್ರಮಗಳನ್ನು ಕೈಗೊಳ್ಳುವುದು', 'ಹಣ್ಣಿನ ನೋಣ ಕಂಡು ಬಂದಲ್ಲಿ ಪ್ರತಿ ಹೆಕ್ಟೇರ್ ಗೆ 10 ಮೋಹಕ ಬಲೆಗಳನ್ನು ತೂಗು ಹಾಕುವುದು ಅಥವಾ. 1.7 ಮಿ.ಲೀ ಡೈಮಿಥೋಯೇಟ್ 30 EC ಯನ್ನು 10 ಗ್ರಾಂ ಬೆಲ್ಲದೊಂದಿಗೆ ಕರಗಿಸಿ ಹಣ್ಣು ಮಾಗುವ ಅವಧಿಯಲ್ಲಿ ಸಿಂಪರಣೆ ಮಾಡುವುದು ಹಾಗೂ ಹಣ್ಣುಗಳು ನಿಂಬೆಹಣ್ಣಿನ ಗಾತ್ರದಲ್ಲಿದ್ದಾಗ 1 ಮಿ.ಲೀ. ಡೆಲ್ಟಾಮೆಥ್ರಿನ್ 2.8 EC ಯನ್ನು ಸಿಂಪರಣೆ ಮಾಡುವುದು. ಕೊಯ್ಲಾದ ನಂತರ 1 ಅಡಿ ಆಳದ ಟ್ರೆಂಚ್‌ಗಳನ್ನು ಕಾಂಡದ 2.5 ರಿಂದ 3 ಮೀ. ದೂರದಲ್ಲಿ ಇಳಜಾರಿಗೆ ಅಡ್ಡಲಾಗಿ ನಿರ್ಮಿಸುವುದು ಉತ್ತಮ', 'Carrying out the recommended plant protection measures', 'If fruit borer is found, hang 10 bait traps per hectare or spray 1.7 ml of Dimethoate 30 EC dissolved in 10 gm jaggery during the fruit ripening period and spray 1 ml of Deltamethrin 2.8 EC when the fruits are the size of lemons. After harvesting, it is better to make 1 foot deep trenches at a distance of 2.5 to 3 m from the stem, across the ridge', 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7691, 'MANGO (EARLY VARIETIES)', NULL, N'>4', N'April', N'April', N'4', N'Fruit maturity stage', N'5', 'BELOW NORMAL', 'YES', 'ಪ್ರಸ್ತುತ ಹಂತದಲ್ಲಿ ಬೆಳೆ ಉತ್ತಮವಾಗಿದ್ದರೆ, ಇತರೆ ಬೆಳೆ ಬೆಳೆದಿದ್ದಲ್ಲಿ ಅವುಗಳ ನಿರ್ವಹಣೆಯತ್ತ ಗಮನಹರಿಸುವುದು', NULL, 'If the crop is good at the current stage, focus on managing other crops if they have grown.', NULL, 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
