INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7743, 'MANGO (LATE VARIETIES)', NULL, N'>4', N'November-December', N'November-December', N'11,12', N'Vegetative stage', N'2', 'NORMAL', 'YES', 'ಸೂಚಿಸಲಾದ ಸಸ್ಯ ಸಂರಕ್ಷಣಾ ಕ್ರಮಗಳನ್ನು ಕೈಗೊಳ್ಳುವುದು', 'ಜಿಗಿ ಹುಳು ಹಾಗೂ ಶಲ್ಕ ಕೀಟ ಕಂಡು ಬಂದಲ್ಲಿ ಲೀ. ನೀರಿಗೆ 0.3 ಮಿಲೀ. ಇಮೀಡಾಕ್ಲೋಪ್ರಿಡ್ 17.8 SL ಅಥವಾ 5% ಬೇವಿನ ಬೀಜದ ಕಷಾಯವನ್ನು ಬೆರೆಸಿ ಸಿಂಪರಿಸುವುದು', 'Carrying out the recommended plant protection measures', 'If leafhoppers and scale insects are found, spray with 0.3 ml of Imidacloprid 17.8 SL per liter of water or 5% neem seed extract', 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
