INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7709, 'MANGO (MID VARIETIES)', NULL, N'>4', N'November-December', N'November-December', N'11,12', N'Vegetative stage', N'2', 'BELOW NORMAL', 'YES', 'ಸೂಚಿಸಲಾದ ಸಸ್ಯ ಸಂರಕ್ಷಣಾ ಕ್ರಮಗಳನ್ನು ಕೈಗೊಳ್ಳುವುದು', 'ಡೈಬ್ಯಾಕ್ ರೋಗ ಲಕ್ಷಣಗಳು ಕಂಡು ಬಂದರೆ ಶೇ. 0.3 ತಾಮ್ರದ ಆಕ್ಸಿಕ್ಲೋರೈಡ್ 50 WP ಅನ್ನು ಬೆರೆಸಿ ಸಿಂಪಡಿಸುವುದು', 'Carrying out the recommended plant protection measures', 'If symptoms of dieback are observed, spray with 0.3% copper oxychloride 50 WP', 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7710, 'MANGO (MID VARIETIES)', NULL, N'>4', N'November-December', N'November-December', N'11,12', N'Vegetative stage', N'2', 'BELOW NORMAL', 'NO', 'ಗಿಡದ ಸುತ್ತಲು ಒಣಗಿದ ಎಲೆಗಳಿಂದ ಮಣ್ಣಿನ ಮೇಲೊದಿಕೆ ಮಾಡುವುದರಿಂದ ಮಣ್ಣಿನ ತೇವಾಂಶವನ್ನು ಕಾಪಾಡಿಕೊಳ್ಳಬಹುದು', NULL, 'Mulching the soil with dry leaves around the plant can help maintain soil moisture.', NULL, 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7711, 'MANGO (MID VARIETIES)', NULL, N'>4', N'November-December', N'November-December', N'11,12', N'Vegetative stage', N'2', 'ABOVE NORMAL', 'YES', 'ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ತೋಟದಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದು ಕೃಷಿ ಹೊಂಡಗಳಲ್ಲಿ ಶೇಖರಿಸಲು ಅನುವುಮಾಡಿಕೊಡಿ', NULL, 'If there is heavy rainfall, allow water to drain from the garden and store in agricultural pits.', NULL, 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
