INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7716, 'MANGO (MID VARIETIES)', NULL, N'>4', N'January-February', N'January-February', N'1,2', N'Flowering stage', N'3', 'BELOW NORMAL', 'NO', 'ಗಿಡದ ಸುತ್ತಲು ಒಣಗಿದ ಎಲೆಗಳಿಂದ ಮಣ್ಣಿನ ಮೇಲೊದಿಕೆ ಮಾಡುವುದರಿಂದ ಮಣ್ಣಿನ ತೇವಾಂಶವನ್ನು ಕಾಪಾಡಿಕೊಳ್ಳಬಹುದು', NULL, 'Mulching the soil with dry leaves around the plant can help maintain soil moisture.', NULL, 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7764, 'MANGO (LATE VARIETIES)', NULL, N'>4', N'June-July', N'June-July', N'6,7', N'Fruit maturity stage', N'5', 'BELOW NORMAL', 'NO', 'ಗಿಡದ ಸುತ್ತಲು ಒಣಗಿದ ಎಲೆಗಳಿಂದ ಮಣ್ಣಿನ ಮೇಲೊದಿಕೆ ಮಾಡುವುದರಿಂದ ಮಣ್ಣಿನ ತೇವಾಂಶವನ್ನು ಕಾಪಾಡಿಕೊಳ್ಳಬಹುದು', 'ಒಟೆ ಕೊರಕ ಕಂಡು ಬಂದಲ್ಲಿ ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ 1.0 ಮಿ.ಲೀ. ಡೆಲ್ಟಾಮೆಥ್ರಿನ್ 2.8 EC ಅಥವಾ 1.0 ಗ್ರಾಂ ಅಸಿಫೇಟ್ 75 SP ಅಥವಾ 2.0 ಮಿ.ಲೀ. ಡೈಮಿಥೋಯೇಟ್ 30 EC. ಅನ್ನು ಮಾರ್ಚ್ ತಿಂಗಳ ಎರಡನೇ ವಾರದಲ್ಲಿ ಸಿಂಪರಣೆ ಮಾಡುವುದು. ಈ ಸಿಂಪರಣೆಯನ್ನು ಮೂರು ವಾರಗಳ ನಂತರ ಪುನರಾರ್ತಿಸುವುದು ಉತ್ತಮ. ಮಸಿ ರೋಗಕ್ಕೆ ಕಂಡುಬಂದಲ್ಲಿ ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ 3.0 ಗ್ರಾಂ. ನೀರಿನಲ್ಲಿ ಕರಗುವ ಗಂಧಕವನ್ನು ಬೆರೆಸಿ ಸಿಂಪಡಿಸುವುದು', 'Mulching the soil with dry leaves around the plant can help maintain soil moisture.', 'If Ote borer is found, spray 1.0 ml. Deltamethrin 2.8 EC or 1.0 gm Acephate 75 SP or 2.0 ml. Dimethoate 30 EC per liter of water in the second week of March. It is better to repeat this spray after three weeks. If Ote borer is found, spray 3.0 gm. Water soluble sulphur mixed with water per liter of water', 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7765, 'MANGO (LATE VARIETIES)', NULL, N'>4', N'June-July', N'June-July', N'6,7', N'Fruit maturity stage', N'5', 'ABOVE NORMAL', 'YES', 'ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ತೋಟದಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದು ಕೃಷಿ ಹೊಂಡಗಳಲ್ಲಿ ಶೇಖರಿಸಲು ಅನುವುಮಾಡಿಕೊಡಿ', 'ಹಣ್ಣಿನ ನೋಣ ಕಂಡು ಬಂದಲ್ಲಿ ಪ್ರತಿ ಹೆಕ್ಟೇರ್ ಗೆ 10 ಮೋಹಕ ಬಲೆಗಳನ್ನುತೂಗು ಹಾಕುವುದು ಅಥವಾ 1.7 ಮಿ.ಲೀ ಡೈಮಿಥೋಯೇಟ್ 30 EC ಅನ್ನು 10 ಗ್ರಾಂ ಬೆಲ್ಲದೊಂದಿಗೆ ಕರಗಿಸಿ ಹಣ್ಣು ಮಾಗುವ ಅವಧಿಯಲ್ಲಿ ಸಿಂಪರಣೆ ಮಾಡುವುದು ಹಾಗೂ ಹಣ್ಣುಗಳು ನಿಂಬೆಹಣ್ಣಿನ ಗಾತ್ರದಲ್ಲಿದ್ದಾಗ 1 ಮಿ.ಲೀ. ಡೆಲ್ಟಾಮೆಥ್ರಿನ್ 2.8 EC ಅನ್ನು ಸಿಂಪರಣೆ ಮಾಡುವುದು. ಕೊಯ್ಲಾದ ನಂತರ 1 ಅಡಿ ಆಳದ ಟ್ರೆಂಚ್‌ಗಳನ್ನು ಕಾಂಡದ 2.5 ರಿಂದ 3 ಮೀ. ದೂರದಲ್ಲಿ ಇಳಜಾರಿಗೆ ಅಡ್ಡಲಾಗಿ ನಿರ್ಮಿಸುವುದು ಉತ್ತಮ', 'If there is heavy rainfall, allow water to drain from the garden and store in agricultural pits.', 'If fruit borer is found, hang 10 bait traps per hectare or spray 1.7 ml Dimethoate 30 EC dissolved in 10 g jaggery during the fruit ripening period and spray 1 ml Deltamethrin 2.8 EC when the fruits are the size of lemons. After harvesting, it is better to make 1 ft deep trenches at a distance of 2.5 to 3 m from the stem, across the ridge', 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7766, 'MANGO (LATE VARIETIES)', NULL, N'>4', N'June-July', N'June-July', N'6,7', N'Fruit maturity stage', N'5', 'ABOVE NORMAL', 'NO', 'ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ತೋಟದಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದು ಕೃಷಿ ಹೊಂಡಗಳಲ್ಲಿ ಶೇಖರಿಸಲು ಅನುವುಮಾಡಿಕೊಡಿ', NULL, 'If there is heavy rainfall, allow water to drain from the garden and store in agricultural pits.', NULL, 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7767, 'GRAPES', 30, N'<1', N'September', N'September', N'9', N'Preparation', N'0', 'NIL', 'NIL', 'ಪೂರ್ವಸಿದ್ದತೆ: ನಾಟಿ ಮಾಡುವ 15 ದಿವಸ ಮುಂಚಿತವಾಗಿ 1.8 ಮೀ x 1.8 ಮೀ. ಅಂತರದಲ್ಲಿ 3x3x3 ಅಡಿ ಅಳತೆಯ ಗುಣಿಗಳನ್ನು ತಗೆಯುವುದು. ಗುಣಿಗಳಿಗೆ ಹಸಿರೆಲೆ ಗೊಬ್ಬರ ಮತ್ತು ಮೇಲ್ಮಣ್ಣು ಜೊತೆಗೆ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ಕೊಟ್ಟಿಗೆ ಗೊಬ್ಬರವನ್ನು ಹಾಕುವುದು
• ಚಪ್ಪರ ವಿಧಾನದಲ್ಲಿ ಬಳ್ಳಿಯನ್ನು ಹಬ್ಬಿಸುವುದರ ಮೂಲಕ ಅಧಿಕ ಇಳುವರಿ ಪಡೆಯಬಹುದಾಗಿದೆ. ಅದಕ್ಕಾಗಿ ಸಿದ್ಧತೆಪಡಿಸಿಕೊಳ್ಳಿ', NULL, 'Preparation: Dig 15 days before planting, 1.8 m x 1.8 m. 3x3x3 feet of trenches. Apply green manure and topsoil to the trenches along with recommended manure. • High yield can be obtained by spreading the vine in the flat method. Prepare for it', NULL, 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7606, 'MANGO', NULL, N'<1', N'December-January', N'December-January', N'12,1', N'Vegetative stage', N'3', 'NORMAL', 'NO', 'ಪ್ರಸ್ತುತ ಹಂತದಲ್ಲಿ ಬೆಳೆ ಉತ್ತಮವಾಗಿದ್ದರೆ, ಇತರೆ ಬೆಳೆ ಬೆಳೆದಿದ್ದಲ್ಲಿ ಅವುಗಳ ನಿರ್ವಹಣೆಯತ್ತ ಗಮನಹರಿಸುವುದು', NULL, 'If the crop is good at the current stage, focus on managing other crops if they have grown.', NULL, 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7607, 'MANGO', NULL, N'<1', N'December-January', N'December-January', N'12,1', N'Vegetative stage', N'3', 'BELOW NORMAL', 'YES', 'ಸಸ್ಯದ ಬೆಳವಣಿಗೆಯನ್ನು ಉತ್ತೇಜಿಸಲು ಹೂ ಗೊಂಚಲು ಕಂಡಲ್ಲಿ ಅವುಗಳನ್ನು ತೆಗೆಯುವುದು', NULL, 'Remove flower clusters if they appear to encourage plant growth.', NULL, 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7608, 'MANGO', NULL, N'<1', N'December-January', N'December-January', N'12,1', N'Vegetative stage', N'3', 'BELOW NORMAL', 'NO', 'ಕೃಷಿ ಹೊಂಡ, ಇತರ ಮೂಲಗಳಲ್ಲಿ ಲಭ್ಯವಿರುವ ನೀರನ್ನು ಬಳಸಿ ಸಂರಕ್ಷಣಾ ನೀರಾವರಿ ಕೊಡುವುದು. ಗಿಡದ ಸುತ್ತಲು ಒಣಗಿದ ಎಲೆಗಳಿಂದ ಮಣ್ಣಿನ ಮೇಲೊದಿಕೆ ಮಾಡುವುದರಿಂದ ಮಣ್ಣಿನ ತೇವಾಂಶವನ್ನು ಕಾಪಾಡಿಕೊಳ್ಳಬಹುದು', NULL, 'Conservation irrigation is done using water available from agricultural wells and other sources. Mulching the soil with dry leaves around the plant can help maintain soil moisture.', NULL, 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7609, 'MANGO', NULL, N'<1', N'December-January', N'December-January', N'12,1', N'Vegetative stage', N'3', 'ABOVE NORMAL', 'YES', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', NULL, 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field.', NULL, 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7610, 'MANGO', NULL, N'<1', N'December-January', N'December-January', N'12,1', N'Vegetative stage', N'3', 'ABOVE NORMAL', 'NO', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', NULL, 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field.', NULL, 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
