INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7347, 'Lemon', NULL, N'>1', N'March-April', N'March-April', N'3,4', N'Vegetative stage', N'6', 'ABOVE NORMAL', 'NO', 'ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', NULL, 'Allow water to drain away from the field so that it does not stagnate.', NULL, NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7348, 'Lemon', NULL, N'1-4', N'May-June', N'May-June', N'5,6', N'Vegetative stage', N'2', 'NORMAL', 'YES', '• ತೋಟದ ಮಧ್ಯೆ ಉಳುಮೆ ಮಾಡಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ಕೊಟ್ಟಿಗೆ ಗೊಬ್ಬರ ಮತ್ತು LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ರಸಗೊಬ್ಬರವನ್ನು ಕೊಡುವುದು
• ಗಿಡಗಳಿಗೆ ಆಕಾರ ಒದಗಿಸಲು ಅನಗತ್ಯ ರೆಂಬೆಗಳನ್ನು ಕತ್ತರಿಸುವುದು (ಹೆಚ್ಚಿನ ಮಾಹಿತಿಗಾಗಿ ತಂತ್ರಾಂಶದಲ್ಲಿರುವ ಲಿಂಬೆ ಬೆಳೆ ಪದ್ಧತಿಯಲ್ಲಿ ವೀಕ್ಷಿಸಬಹುದು)
• ಹಸಿರೆಲೆ ಗೊಬ್ಬರದ ಗಿಡಗಳಾದ ಸೆಣಬು, ಅಲಸಂದಿ ಅಥವಾ ಹುರುಳಿ ಬೆಳೆಯನ್ನು ಬೆಳೆಯುವುದರಿಂದ ಭೂಮಿಯ ಫಲವತ್ತತೆಯನ್ನು ಹೆಚ್ಚಿಸಬಹುದು
• ಅಥವಾ ತೋಟದ ಮಧ್ಯ ಅಂತರ ಬೆಳೆಗಳನ್ನು ಬೆಳೆಯಬಹುದು', NULL, '• Ploughing the garden and applying the recommended manure and fertilizer based on LRI
• Pruning unwanted branches to shape the plants (for more information, see the Lemon Crop System in the software)
• Growing green manure crops such as jute, sorghum or buckwheat can increase soil fertility
