INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7419, 'Lemon', NULL, N'>4', N'March-April', N'March-April', N'3,4', N'Fruit Maturation & Harvesting stage', N'6', 'ABOVE NORMAL', 'NO', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', NULL, 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field.', NULL, NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7420, 'BETEL VINE', NULL, N'<1', N'May', N'May', N'5', N'Preparation', N'0', 'NIL', 'NIL', 'ಪೂರ್ವಸಿದ್ದತೆ (Prepardness): ವೀಳ್ಯೆದೆಲೆ ಬೆಳೆಯಬೇಕೆಂದಿರುವ ಭೂಮಿಯನ್ನು ಆಳವಾಗಿ ಅಗೆದು ಅಥವಾ ಉಳುಮೆಮಾಡಿ ಹದಮಾಡಿಟ್ಟುಕೊಳ್ಳಬೇಕು. ಸ್ಯಾಭಿವೃದ್ಧಿ : ಪೂರ್ತಿ ಬಲಿತ ಬಳ್ಳಿಯ ಕುಡಿಯ ಭಾಗದಿಂದ ಕಡ್ಡಿಗಳನ್ನು ಕತ್ತರಿಸಬೇಕು. ತುಂಡಿನ ಉದ್ದ 30-45 ಸೆಂ. ಮೀ. ಹಾಗೂ ೩-೫ ಕಣ್ಣುಗಳಿರಬೇಕು. ಎರಡು ಕಣ್ಣುಗಳು ಭೂಮಿಯ ಅಡಿಯಲ್ಲಿರುವಂತೆ ನಾಟಿ ಮಾಡಬೇಕು. ಕಡ್ಡಿಯ ಸುತ್ತಲೂ ಮಣ್ಣನ್ನು ಅದುಮಬೇಕು
 ಅಂಬಾಡಿ,ಕರಿಬಳ್ಳಿ, ನಾಗಬಳ್ಳಿ, ಹೊಸಬಳ್ಳಿ, ಜನಬಳ್ಳಿ, ಚಪ್ರಬಳ್ಳಿ, ಮರಎಲೆ, ಕಲ್ಕತ್ತಪಾನ್ ನಾಟಿಗೆ ಸೂಕ್ತತಳಿಗಳು', NULL, 'Prepardness: The land where the betel leaf is to be grown should be dug or ploughed and kept level. Cultivation: Cuttings should be cut from the stem of a fully mature vine. The length of the piece should be 30-45 cm. and it should have 3-5 eyes. It should be planted so that both eyes are under the ground. The soil should be pressed around the cuttings. Ambadi, Kariballi, Nagaballi, Hosaballi, Janaballi, Chapraballi, Maraele, Kalkatthapan are suitable varieties for planting.', 'NIL', 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7455, 'BETEL VINE', NULL, N'1-2', N'July-December', N'July-December', N'7,12', N'Vegetative stage', N'2', 'ABOVE NORMAL', 'YES', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', NULL, 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field.', NULL, NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7456, 'BETEL VINE', NULL, N'1-2', N'July-December', N'July-December', N'7,12', N'Vegetative stage', N'2', 'ABOVE NORMAL', 'NO', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', 'ಸೊರಗು ರೋಗ ನಿಯಂತ್ರಣಕ್ಕಾಗಿ ಶೇ.1 ರ ಬೋರ್ಡೊ ದ್ರಾವಣದಿಂದ ಬಳ್ಳಿಯನ್ನು ಇಳಿಸಿದಾಗ ಮಣ್ಣನ್ನು ತೋಯಿಸಬೇಕು', 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field.', NULL, NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7457, 'BETEL VINE', NULL, N'1-2', N'January-February', N'January-February', N'1,2', N'Vegetative stage', N'3', 'NORMAL', 'YES', '• ಗಿಡದ ಆಕಾರ ರೂಪಿಸಲು ಅನಾವಶ್ಯಕ ಕೊಂಬೆ ಕತ್ತರಿಸುವುದು (ಹೆಚ್ಚಿನ ಮಾಹಿತಿಗಾಗಿ ತಂತ್ರಾಂಶದಲ್ಲಿರುವ ಪೇರಲ ಬೆಳೆಯ ಬೇಸಾಯ ಪದ್ದತಿಯನ್ನು ಅನುಸರಿಸಿ)', 'ಎಲೆ ಚುಕ್ಕೆ ರೋಗ ಮತ್ತು ಕೊಳೆ ರೋಗಗಳ ನಿಯಂತ್ರಣಕ್ಕಾಗಿ ಶೇ.1ರ ಬೋರ್ಡೋ ದ್ರಾವಣ ಅಥವಾ 3 ಗ್ರಾಂ ತಾಮ್ರದ ಆಕ್ಸಿಕ್ಲೋರೈಡ್ 50 ಡಬ್ಲೂಯ.ಪಿ. ಪ್ರತಿ ಲೀಟರ್ ನೀರಿನಲ್ಲಿ ಬೆರಸಿ ಸಿಂಪಡಿಸಬೇಕು', '• Pruning unnecessary branches to shape the plant (for more information, follow the Guava cultivation method in the software)', NULL, NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7458, 'BETEL VINE', NULL, N'1-2', N'January-February', N'January-February', N'1,2', N'Vegetative stage', N'3', 'NORMAL', 'NO', '• ಗಿಡದ ಆಕಾರ ರೂಪಿಸಲು ಅನಾವಶ್ಯಕ ಕೊಂಬೆ ಕತ್ತರಿಸುವುದು (ಹೆಚ್ಚಿನ ಮಾಹಿತಿಗಾಗಿ ತಂತ್ರಾಂಶದಲ್ಲಿರುವ ಪೇರಲ ಬೆಳೆಯ ಬೇಸಾಯ ಪದ್ದತಿಯನ್ನು ಅನುಸರಿಸಿ)', 'ಎಲೆ ಚುಕ್ಕೆ ರೋಗ ಮತ್ತು ಕೊಳೆ ರೋಗಗಳ ನಿಯಂತ್ರಣಕ್ಕಾಗಿ ಶೇ.1ರ ಬೋರ್ಡೋ ದ್ರಾವಣ ಅಥವಾ 3 ಗ್ರಾಂ ತಾಮ್ರದ ಆಕ್ಸಿಕ್ಲೋರೈಡ್ 50 ಡಬ್ಲೂಯ.ಪಿ. ಪ್ರತಿ ಲೀಟರ್ ನೀರಿನಲ್ಲಿ ಬೆರಸಿ ಸಿಂಪಡಿಸಬೇಕು', '• Pruning unnecessary branches to shape the plant (for more information, follow the Guava cultivation method in the software)', NULL, NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
