INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7504, 'BETEL VINE', NULL, N'>2', N'March-April', N'March-April', N'3,4', N'Harvesting', N'6', 'ABOVE NORMAL', 'NO', 'ಬಲಿತ ಎಲೆಗಳನ್ನು ತೊಟ್ಟು ಸಹಿತ ಕೊಯ್ಲು ಮಾಡಬೇಕು', NULL, 'Mature leaves should be harvested along with the stalk.', NULL, NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7505, 'DRUMSTICK', NULL, N'<1', N'May', N'May', N'5', N'Preparation', N'0', 'NIL', 'NIL', 'ಪೂರ್ವಸಿದ್ದತೆ (Preparedness): 0.06 ಘನ ಮೀ. ಗುಣಿಗಳನ್ನು 3.25 ಮೀ. ಅಂತರದಲ್ಲಿ (ಗಿಡ್ಡ ಜಾತಿಗೆ) ಅಥವಾ 5 ಮೀ. ಅಂತರ (ಎತ್ತರ ಜಾತಿಗೆ)ದಲ್ಲಿ ತೆಗೆಯಬೇಕು. ಗುಣಿಗಳಿಗೆ ಸಮಪ್ರಮಾಣದಲ್ಲಿ ಕೊಟ್ಟಿಗೆ ಗೊಬ್ಬರ ಮತ್ತು ಮಣ್ಣು ಕೊಡಬೇಕು. ನಂತರ ಪ್ರತಿ ಗುಣಿಗೆ ಒಂದು ಸಸಿಯನ್ನು ನೆಡಬೇಕು
ಚವಕಚೇರಿ ಮುರುಂಗಾ, ಭಾಗ್ಯ (ಕೆ.ಡಿ.ಎಮ್-೦೧), ಪಿ.ಕೆ.ಎಂ.-೧, ಜಾಫ್ನಾ ನಾಟಿಗೆ ಸೂಕ್ತತಳಿಗಳು', 'ಸಸಿ ಬೆಳೆಸುವ ಕ್ರಮಗಳು : 15 ಸೆಂ. ಮೀ. x 4 ಸೆಂ. ಮೀ. ಅಳತೆಯ ಪಾಲಿಥಿನ್ ಚೀಲದಲ್ಲಿ ಮರಳಿನ ಮಿಶ್ರಣವನ್ನು ತುಂಬಿ, ಪ್ರತಿ ಚೀಲಕ್ಕೆ ಎರಡು ಬೀಜಗಳಂತೆ 2 ಸೆಂ. ಮೀ. ಆಳದಲ್ಲಿ ನೆಟ್ಟು ಪ್ರತಿ ದಿನ ನೀರು ಹಾಕಬೇಕು', 'Preparedness: 0.06 cubic m. The pits should be removed at a distance of 3.25 m. (for short varieties) or 5 m. (for tall varieties). The pits should be given equal amounts of manure and soil. Then one seedling should be planted in each pit.
Suitable varieties for planting are Chavakacheri Murunga, Bhagya (K.D.M.-01), P.K.M.-1, Jaffna', 'Planting system: Plant 2 seeds in a polythene bag of size 15 x 4 cm, water polythene bag daily.', 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7506, 'DRUMSTICK', NULL, N'<1', N'June-July', N'June-July', N'6,7', N'Planting', N'1', 'NORMAL', 'YES', 'ಚವಕಚೇರಿ ಮುರುಂಗಾ, ಭಾಗ್ಯ (ಕೆ.ಡಿ.ಎಮ್-೦೧), ಪಿ.ಕೆ.ಎಂ.-೧, ಜಾಫ್ನಾ ನಾಟಿಗೆ ಸೂಕ್ತತಳಿಗಳು. ಸಸಿಗಳು 3.5 ರಿಂದ 4 ತಿಂಗಳಗಳಲ್ಲಿ 20-30 ಸೆಂ. ಮೀ. ಎತ್ತರ ಬೆಳೆದಾಗ ಹೊಲದಲ್ಲಿ ನೆಡಬೇಕು. ಸಣ್ಣ ಸಸಿಗಳಿಗೆ ಆಧಾರವನ್ನು ಒದಗಿಸಬೇಕು', NULL, 'Chavakacheri Murunga, Bhagya (KDM-01), PKM-1, Jaffna are suitable varieties for planting. The seedlings should be planted in the field when they grow to a height of 20-30 cm in 3.5 to 4 months. Support should be provided for small seedlings.', 'For control of aphids, black carpet moth and gray carpet moth, flower bud/nut borer, when plants are newly sprouted spray 2 ml Malathion 50 E.C per liter of water and Monocrotophos 36 SL dissolve in 1 liter of water it should be mixed with water and sprayed and when flowering starts,', 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7421, 'BETEL VINE', NULL, N'<1', N'June-July', N'June-July', N'6,7', N'Planting', N'1', 'NORMAL', 'YES', 'ನೆರಳು ಮತ್ತು ಆಧಾರಕ್ಕಾಗಿ ನಾಟಿ ಮಾಡುವ ಮರಗಳ ಬೀಜಗಳನ್ನು (ಅಗಸೆ, ಹಾಲವಾಣ ಇತ್ಯಾದಿ) 4 ವಾರಗಳ ಮುಂಚೆ ನಾಟಿ ಮಾಡಬೇಕು. ಅನಂತರ ಬೇರು ಬಿಟ್ಟ ವೀಳ್ಯೆದೆಲೆ ಬಳ್ಳಿಯ ತುಂಡುಗಳನ್ನು ಮರಗಳ ಬಳಿ ನಾಟಿ ಮಾಡಬೇಕು', 'ತೋಟದ ಸುತ್ತಲೂ ಗಾಳಿಯ ತಡೆಗಾಗಿ ಗೋಡೆ ತಡೆ ಅಥವಾ ಜೈವಿಕ ತಡೆಗಳಾದ ನುಗ್ಗೆ, ಹಿಪ್ಪುನೇರಳೆ, ಸೀಮೆ ಹುಣಸೆ ಇತ್ಯಾದಿಮರಗಳನ್ನು ದಟ್ಟವಾಗಿ ಬೆಳೆಯಬೇಕು', 'Seeds of trees to be planted for shade and support (flax, halva etc.) should be sown 4 weeks in advance. Then rooted betel vine pieces should be planted near the trees.', 'Trees such as drumstick,  mulberry, tamarind, etc. should be densely planted around the garden to block the wind.', 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7422, 'BETEL VINE', NULL, N'<1', N'June-July', N'June-July', N'6,7', N'Planting', N'1', 'NORMAL', 'NO', 'ಮಳೆಯ ಮುನ್ಸೂಚನೆಯನ್ನು ಗಮನದಲ್ಲಿಟ್ಟುಕೊಂಡು ನೆರಳು ಮತ್ತು ಆಧಾರಕ್ಕಾಗಿ ನಾಟಿ ಮಾಡುವ ಮರಗಳ ಬೀಜಗಳನ್ನು (ಅಗಸೆ, ಹಾಲವಾಣ ಇತ್ಯಾದಿ) 4 ವಾರಗಳ ಮುಂಚೆ ನಾಟಿ ಮಾಡಬೇಕು. ಅನಂತರ ಬೇರು ಬಿಟ್ಟ ವೀಳ್ಯೆದೆಲೆ ಬಳ್ಳಿಯ ತುಂಡುಗಳನ್ನು ಮರಗಳ ಬಳಿ ನಾಟಿ ಮಾಡಬೇಕು', 'ತೋಟದ ಸುತ್ತಲೂ ಗಾಳಿಯ ತಡೆಗಾಗಿ ಗೋಡೆ ತಡೆ ಅಥವಾ ಜೈವಿಕ ತಡೆಗಳಾದ ನುಗ್ಗೆ, ಹಿಪ್ಪುನೇರಳೆ, ಸೀಮೆ ಹುಣಸೆ ಇತ್ಯಾದಿಮರಗಳನ್ನು ದಟ್ಟವಾಗಿ ಬೆಳೆಯಬೇಕು', 'Keeping in mind the rainfall forecast, seeds of trees to be planted for shade and support (flax, halva etc.) should be sown 4 weeks in advance. Then rooted betel vine pieces should be planted near the trees.', 'Trees such as drumstick,  mulberry, tamarind, etc. should be densely planted around the garden to block the wind.', 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7423, 'BETEL VINE', NULL, N'<1', N'June-July', N'June-July', N'6,7', N'Planting', N'1', 'BELOW NORMAL', 'YES', 'ನೀರಾವರಿ ಸೌಲಭ್ಯವಿದ್ದಲ್ಲಿ ನೆರಳು ಮತ್ತು ಆಧಾರಕ್ಕಾಗಿ ನಾಟಿ ಮಾಡುವ ಮರಗಳ ಬೀಜಗಳನ್ನು (ಅಗಸೆ, ಹಾಲವಾಣ ಇತ್ಯಾದಿ) 4 ವಾರಗಳ ಮುಂಚೆ ನಾಟಿ ಮಾಡಬೇಕು. ಅನಂತರ ಬೇರು ಬಿಟ್ಟ ವೀಳ್ಯೆದೆಲೆ ಬಳ್ಳಿಯ ತುಂಡುಗಳನ್ನು ಮರಗಳ ಬಳಿ ನಾಟಿ ಮಾಡಬೇಕು', NULL, 'If irrigation facilities are available, seeds of shade and support trees (flax, halva, etc.) should be planted 4 weeks in advance. Then rooted betel vine pieces should be planted near the trees.', NULL, NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7424, 'BETEL VINE', NULL, N'<1', N'June-July', N'June-July', N'6,7', N'Planting', N'1', 'BELOW NORMAL', 'NO', 'ನೀರಾವರಿ ಸೌಲಭ್ಯವಿದ್ದಲ್ಲಿ ನೆರಳು ಮತ್ತು ಆಧಾರಕ್ಕಾಗಿ ನಾಟಿ ಮಾಡುವ ಮರಗಳ ಬೀಜಗಳನ್ನು (ಅಗಸೆ, ಹಾಲವಾಣ ಇತ್ಯಾದಿ) 4 ವಾರಗಳ ಮುಂಚೆ ನಾಟಿ ಮಾಡಬೇಕು. ಅನಂತರ ಬೇರು ಬಿಟ್ಟ ವೀಳ್ಯೆದೆಲೆ ಬಳ್ಳಿಯ ತುಂಡುಗಳನ್ನು ಮರಗಳ ಬಳಿ ನಾಟಿ ಮಾಡಬೇಕು', NULL, 'If irrigation facilities are available, seeds of shade and support trees (flax, halva, etc.) should be planted 4 weeks in advance. Then rooted betel vine pieces should be planted near the trees.', NULL, NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7425, 'BETEL VINE', NULL, N'<1', N'June-July', N'June-July', N'6,7', N'Planting', N'1', 'ABOVE NORMAL', 'YES', 'ಹೆಚ್ಚಾಗಿರುವ ನೀರನ್ನು ತೋಟದಿಂದ ಬಸಿದುಹೋಗುವಂತೆ ಮಾಡಿ, ನೆರಳು ಮತ್ತು ಆಧಾರಕ್ಕಾಗಿ ನಾಟಿ ಮಾಡುವ ಮರಗಳ ಬೀಜಗಳನ್ನು (ಅಗಸೆ, ಹಾಲವಾಣ ಇತ್ಯಾದಿ) 4 ವಾರಗಳ ಮುಂಚೆ ನಾಟಿ ಮಾಡಬೇಕು. ಅನಂತರ ಬೇರು ಬಿಟ್ಟ ವೀಳ್ಯೆದೆಲೆ ಬಳ್ಳಿಯ ತುಂಡುಗಳನ್ನು ಮರಗಳ ಬಳಿ ನಾಟಿ ಮಾಡಬೇಕು', NULL, 'To drain excess water from the garden, seeds of shade and support trees (flax, halva, etc.) should be planted 4 weeks in advance. Then rooted betel vine pieces should be planted near the trees.', NULL, NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
