INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7468, 'BETEL VINE', NULL, N'1-2', N'March-April', N'April', N'4', N'Vegetative stage', N'5', 'ABOVE NORMAL', 'NO', 'ಬಲಿತ ಎಲೆಗಳನ್ನು ತೊಟ್ಟು ಸಹಿತ ಕೊಯ್ಲು ಮಾಡಬೇಕು', NULL, 'Mature leaves should be harvested along with the stalk.', NULL, NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7469, 'BETEL VINE', NULL, N'>2', N'May-June', N'May-June', N'5,6', N'Vegetative stage', N'7', 'NORMAL', 'YES', 'ವೀಳ್ಯೆದೆಲೆಯು ಹೆಚ್ಚು ಗೊಬ್ಬರವನ್ನು ಬಯಸುವ ಬೆಳೆ. ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ಕೊಟ್ಟಿಗೆ ಗೊಬ್ಬರ ಮತ್ತು ರಸಗೊಬ್ಬರಗಳನ್ನು ಬಳ್ಳಿಗಳನ್ನು ಇಳಿಸಿದ ಕೂಡಲೇ ಮುಂಗಾರು ಮಳೆಗೆ ಮೊದಲು ಒದಗಿಸಬೇಕು. ಮೊಳಕೆಯೊಡೆದ ಆಧಾರದ ಮರಗಳ ಸಸಿಗಳಲ್ಲಿ ಬೇಕಾದಷ್ಟನ್ನು ಮಾತ್ರ ಉಳಿಸಿಕೊಳ್ಳಬೇಕು. ಆಧಾರ ಮರಗಳ ಕಾಂಡ ನೇರವಾಗಿದ್ದು, ಮುಳ್ಳು ಮತ್ತು ರೆಂಬೆರಹಿತವಾಗಿರಬೇಕು. ಬಳ್ಳಿಯನ್ನು ಮರಕ್ಕೆ ಹಬ್ಬಿಸಿ ಬಾಳೆ ನಾರಿನಿಂದ ಗಂಟು ಹಾಕಿ ಕಟ್ಟಬೇಕು. ಬಳ್ಳಿ ಇಳಿಸುವುದು : ಬಳ್ಳಿ ಮರಕ್ಕೆ ಹಬ್ಬಿದ ಒಂದು ವರ್ಷದ ನಂತರ ಎಲೆಯ ಗಾತ್ರ ಕಡಿಮೆಯಾಗಿ', NULL, 'Betel leaf is a crop that requires a lot of fertilizer. Recommended manure and fertilizers should be provided immediately after the vines are planted, before the monsoon rains. Only the required amount should be retained in the seedlings of the sprouted rootstocks. The trunk of the rootstocks should be straight, thornless and branchless. The vine should be tied to the tree by making a knot with banana fiber. Planting the vine: After one year of planting the vine on the tree, the size of the leaves should decrease.', NULL, NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7507, 'DRUMSTICK', NULL, N'<1', N'June-July', N'June-July', N'6,7', N'Planting', N'1', 'NORMAL', 'NO', 'ಮಳೆಯ ಮುನ್ಸೂಚನೆಯನ್ನು ಗಮನದಲ್ಲಿಟ್ಟುಕೊಂಡು ಚವಕಚೇರಿ ಮುರುಂಗಾ, ಭಾಗ್ಯ (ಕೆ.ಡಿ.ಎಮ್-೦೧), ಪಿ.ಕೆ.ಎಂ.-೧, ಜಾಫ್ನಾ ನಾಟಿಗೆ ಸೂಕ್ತತಳಿಗಳು. ಸಸಿಗಳು 3.5 ರಿಂದ 4 ತಿಂಗಳಗಳಲ್ಲಿ 20-30 ಸೆಂ. ಮೀ. ಎತ್ತರ ಬೆಳೆದಾಗ ಹೊಲದಲ್ಲಿ ನೆಡಬೇಕು. ಸಣ್ಣ ಸಸಿಗಳಿಗೆ ಆಧಾರವನ್ನು ಒದಗಿಸಬೇಕು', NULL, 'Considering the rainfall forecast, Chavakacheri Murunga, Bhagya (KDM-01), PKM-1, Jaffna are suitable varieties for planting. The seedlings should be planted in the field when they grow to a height of 20-30 cm in 3.5 to 4 months. Support should be provided for small seedlings.', 'For control of aphids, black carpet moth and gray carpet moth, flower bud/nut borer, when plants are newly sprouted spray 2 ml Malathion 50 E.C per liter of water and Monocrotophos 36 SL dissolve in 1 liter of water it should be mixed with water and sprayed and when flowering starts,', 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7508, 'DRUMSTICK', NULL, N'<1', N'June-July', N'June-July', N'6,7', N'Planting', N'1', 'BELOW NORMAL', 'YES', 'ನೀರಾವರಿ ಸೌಲಭ್ಯವಿದ್ದಲ್ಲಿ ಚವಕಚೇರಿ ಮುರುಂಗಾ, ಭಾಗ್ಯ (ಕೆ.ಡಿ.ಎಮ್-೦೧), ಪಿ.ಕೆ.ಎಂ.-೧, ಜಾಫ್ನಾ ನಾಟಿಗೆ ಸೂಕ್ತತಳಿಗಳು. ಸಸಿಗಳು 3.5 ರಿಂದ 4 ತಿಂಗಳಗಳಲ್ಲಿ 20-30 ಸೆಂ. ಮೀ. ಎತ್ತರ ಬೆಳೆದಾಗ ಹೊಲದಲ್ಲಿ ನೆಡಬೇಕು. ಸಣ್ಣ ಸಸಿಗಳಿಗೆ ಆಧಾರವನ್ನು ಒದಗಿಸಬೇಕು', NULL, 'If irrigation facilities are available, Chavakacheri Murunga, Bhagya (KDM-01), PKM-1, Jaffna are suitable varieties for planting. The seedlings should be planted in the field when they grow to a height of 20-30 cm in 3.5 to 4 months. Support should be provided for small seedlings.', NULL, NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7509, 'DRUMSTICK', NULL, N'<1', N'June-July', N'June-July', N'6,7', N'Planting', N'1', 'BELOW NORMAL', 'NO', 'ನೀರಾವರಿ ಸೌಲಭ್ಯವಿದ್ದಲ್ಲಿ ಚವಕಚೇರಿ ಮುರುಂಗಾ, ಭಾಗ್ಯ (ಕೆ.ಡಿ.ಎಮ್-೦೧), ಪಿ.ಕೆ.ಎಂ.-೧, ಜಾಫ್ನಾ ನಾಟಿಗೆ ಸೂಕ್ತತಳಿಗಳು. ಸಸಿಗಳು 3.5 ರಿಂದ 4 ತಿಂಗಳಗಳಲ್ಲಿ 20-30 ಸೆಂ. ಮೀ. ಎತ್ತರ ಬೆಳೆದಾಗ ಹೊಲದಲ್ಲಿ ನೆಡಬೇಕು. ಸಣ್ಣ ಸಸಿಗಳಿಗೆ ಆಧಾರವನ್ನು ಒದಗಿಸಬೇಕು', NULL, 'If irrigation facilities are available, Chavakacheri Murunga, Bhagya (KDM-01), PKM-1, Jaffna are suitable varieties for planting. The seedlings should be planted in the field when they grow to a height of 20-30 cm in 3.5 to 4 months. Support should be provided for small seedlings.', NULL, NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7510, 'DRUMSTICK', NULL, N'<1', N'June-July', N'June-July', N'6,7', N'Planting', N'1', 'ABOVE NORMAL', 'YES', 'ಹೆಚ್ಚಾಗಿರುವ ನೀರನ್ನು ತೋಟದಿಂದ ಬಸಿದುಹೋಗುವಂತೆ ಮಾಡಿ, ಚವಕಚೇರಿ ಮುರುಂಗಾ, ಭಾಗ್ಯ (ಕೆ.ಡಿ.ಎಮ್-೦೧), ಪಿ.ಕೆ.ಎಂ.-೧, ಜಾಫ್ನಾ ನಾಟಿಗೆ ಸೂಕ್ತತಳಿಗಳು. ಸಸಿಗಳು 3.5 ರಿಂದ 4 ತಿಂಗಳಗಳಲ್ಲಿ 20-30 ಸೆಂ. ಮೀ. ಎತ್ತರ ಬೆಳೆದಾಗ ಹೊಲದಲ್ಲಿ ನೆಡಬೇಕು. ಸಣ್ಣ ಸಸಿಗಳಿಗೆ ಆಧಾರವನ್ನು ಒದಗಿಸಬೇಕು', NULL, 'Drain excess water from the garden, suitable varieties for planting are Chavakacheri Murunga, Bhagya (KDM-01), PKM-1, Jaffna. The seedlings should be planted in the field when they grow to a height of 20-30 cm in 3.5 to 4 months. Support should be provided for small seedlings.', NULL, NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7511, 'DRUMSTICK', NULL, N'<1', N'June-July', N'June-July', N'6,7', N'Planting', N'1', 'ABOVE NORMAL', 'NO', 'ಹೆಚ್ಚಾಗಿರುವ ನೀರನ್ನು ತೋಟದಿಂದ ಬಸಿದುಹೋಗುವಂತೆ ಮಾಡಿ, ಚವಕಚೇರಿ ಮುರುಂಗಾ, ಭಾಗ್ಯ (ಕೆ.ಡಿ.ಎಮ್-೦೧), ಪಿ.ಕೆ.ಎಂ.-೧, ಜಾಫ್ನಾ ನಾಟಿಗೆ ಸೂಕ್ತತಳಿಗಳು. ಸಸಿಗಳು 3.5 ರಿಂದ 4 ತಿಂಗಳಗಳಲ್ಲಿ 20-30 ಸೆಂ. ಮೀ. ಎತ್ತರ ಬೆಳೆದಾಗ ಹೊಲದಲ್ಲಿ ನೆಡಬೇಕು. ಸಣ್ಣ ಸಸಿಗಳಿಗೆ ಆಧಾರವನ್ನು ಒದಗಿಸಬೇಕು', NULL, 'Drain excess water from the garden, suitable varieties for planting are Chavakacheri Murunga, Bhagya (KDM-01), PKM-1, Jaffna. The seedlings should be planted in the field when they grow to a height of 20-30 cm in 3.5 to 4 months. Support should be provided for small seedlings.', NULL, NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7427, 'BETEL VINE', NULL, N'<1', N'August-December', N'August-December', N'8,9,10,11,12', N'Vegetative stage', N'2', 'NORMAL', 'YES', '• ನಾಟಿಯ ನಂತರ LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ರಸಗೊಬ್ಬರವನ್ನು ಒದಗಿಸುವುದು', 'ವೀಳ್ಯದೆಲೆ ಬೆಳೆಯಲು ನೆರಳು ಮತ್ತು ಆಧಾರಕ್ಕಾಗಿ ನಾಟಿ ಮಾಡುವ ಮರಗಳಲ್ಲಿ ಹಾಲವಾಣದ ಎರಿಥ್ರೀನಾ ಸಬ್‌ಬುಂಬ್ರೆನ್ಸ್ ಎಂಬ ಜಾತಿಯ ಮರಗಳನ್ನು ಉಪಯೋಗಿಸುವುದು. ಇದು ಹಾಲವಾಣದಲ್ಲಿ ಭಾದಿಸುವ ಕಣಜ ಕೀಟಕ್ಕೆ ತಡೆದುಕೊಳ್ಳುವ ಶಕ್ತಿ ಹೊಂದಿದೆ', '• Providing recommended fertilizer based on LRI after planting', 'Among the trees planted for shade and support for growing betel leaves, the species Erythrina spp  is used. It is resistant to the wasp pest.', 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7428, 'BETEL VINE', NULL, N'<1', N'August-December', N'August-December', N'8,9,10,11,12', N'Vegetative stage', N'2', 'NORMAL', 'NO', '• ನಾಟಿಯ ನಂತರ LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ರಸಗೊಬ್ಬರವನ್ನು ಒದಗಿಸುವುದು', 'ವೀಳ್ಯದೆಲೆ ಬೆಳೆಯಲು ನೆರಳು ಮತ್ತು ಆಧಾರಕ್ಕಾಗಿ ನಾಟಿ ಮಾಡುವ ಮರಗಳಲ್ಲಿ ಹಾಲವಾಣದ ಎರಿಥ್ರೀನಾ ಸಬ್‌ಬುಂಬ್ರೆನ್ಸ್ ಎಂಬ ಜಾತಿಯ ಮರಗಳನ್ನು ಉಪಯೋಗಿಸುವುದು. ಇದು ಹಾಲವಾಣದಲ್ಲಿ ಭಾದಿಸುವ ಕಣಜ ಕೀಟಕ್ಕೆ ತಡೆದುಕೊಳ್ಳುವ ಶಕ್ತಿ ಹೊಂದಿದೆ', '• Providing recommended fertilizer based on LRI after planting', 'Among the trees planted for shade and support for growing betel leaves, the species Erythrina spp  is used. It is resistant to the wasp pest.', 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7429, 'BETEL VINE', NULL, N'<1', N'August-December', N'August-December', N'8,9,10,11,12', N'Vegetative stage', N'2', 'BELOW NORMAL', 'YES', '• ಕೃಷಿ ಹೊಂಡ, ಇತರ ಮೂಲಗಳಲ್ಲಿ ಲಭ್ಯವಿರುವ ನೀರನ್ನು ಬಳಸಿ ನೀರಾವರಿ ಕೊಡುವುದು
• ಗಿಡದ ಸುತ್ತಲು ಒಣಗಿದ ಎಲೆಗಳಿಂದ ಮಣ್ಣಿನ ಮೇಲೊದಿಕೆ ಮಾಡುವುದರಿಂದ ಮಣ್ಣಿನ ತೇವಾಂಶವನ್ನು ಕಾಪಾಡಿಕೊಳ್ಳಬಹುದು', NULL, '• Irrigation using water available from agricultural wells and other sources
• Mulching the soil with dry leaves around the plant can help maintain soil moisture', 'NIL', 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7430, 'BETEL VINE', NULL, N'<1', N'August-December', N'August-December', N'8,9,10,11,12', N'Vegetative stage', N'2', 'BELOW NORMAL', 'NO', 'LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ರಸಗೊಬ್ಬರವನ್ನು ಒದಗಿಸುವುದು. ಬಳ್ಳಿಗಳನ್ನು ಇಳಿಸಿದ ಕೂಡಲೇ ಮುಂಗಾರು ಮಳೆಗೆ ಮೊದಲು ಒದಗಿಸಬೇಕು. ಮೊಳಕೆಯೊಡೆದ ಆಧಾರದ ಮರಗಳ ಸಸಿಗಳಲ್ಲಿ ಬೇಕಾದಷ್ಟನ್ನು ಮಾತ್ರ ಉಳಿಸಿಕೊಳ್ಳಬೇಕು', NULL, 'Provide fertilizer as recommended based on LRI. Provide fertilizer immediately after transplanting the vines and before the monsoon rains. Only the required amount should be retained in the seedlings of the sprouted rootstocks.', 'NIL', 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7431, 'BETEL VINE', NULL, N'<1', N'August-December', N'August-December', N'8,9,10,11,12', N'Vegetative stage', N'2', 'ABOVE NORMAL', 'YES', 'ಸೂಚಿಸಲಾದ ಸಸ್ಯ ಸಂರಕ್ಷಣಾ ಕ್ರಮಗಳನ್ನು ಕೈಗೊಳ್ಳುವುದು', 'ವೀಳ್ಯೆದಲೆ ತಿಗಣೆ ಮತ್ತು ಹಿಟ್ಟು ತಿಗಣೆ: ಕೀಟಗಳ ಹತೋಟಿಗಾಗಿ, 2 ಮಿ. ಲೀ. ಫೋಸಲೋನ್ 35 ಇ.ಸಿ. ಅಥವಾ 3 ಮಿ. ಲೀ ನಿಂಬೆಸಿಡಿನ್ 300 ಪಿಪಿಎಂ ಪ್ರತಿ ಲೀಟರ್ ನೀರಿನಲ್ಲಿ ಬೆರೆಸಿ ಸಿಂಪಡಿಸಬೇಕು', 'Carrying out the recommended plant protection measures', 'If leaf beetle and mealybug observe then spray 2 ml of  Phosalone 35 EC or 3 ml Nimbecidine- 300 ppm mixed in per liter of water.', 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7432, 'BETEL VINE', NULL, N'<1', N'August-December', N'August-December', N'8,9,10,11,12', N'Vegetative stage', N'2', 'ABOVE NORMAL', 'NO', 'ಸೂಚಿಸಲಾದ ಸಸ್ಯ ಸಂರಕ್ಷಣಾ ಕ್ರಮಗಳನ್ನು ಕೈಗೊಳ್ಳುವುದು', 'ಜೇಡ ನುಶಿ: ಹತೋಟಿಗಾಗಿ ಪ್ರತಿ ಲೀಟರ್ ನೀರಿಗೆ 1 ಗ್ರಾಂ ಕರಗುವ ಗಂಧಕ 50 WP ಅಥವಾ ೩ ಮಿ. ಲೀ ನಿಂಬೆಸಿಡಿನ್ 300 ಪಿಪಿಎಂ ಬೆರೆಸಿ ಸಿಂಪಡಿಸಬೇಕು', 'Carrying out the recommended plant protection measures', 'Spider mite: For control, spray with 1 gram of wettable sulfur 50 WP or 3 ml Nimbecidine- 300 ppm per liter of water.', 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7433, 'BETEL VINE', NULL, N'<1', N'January-February', N'January-February', N'1,2', N'Vegetative stage', N'3', 'NORMAL', 'YES', 'ನಾಟಿಯಾದ ನಂತರದಲ್ಲಿ ಕಳೆಗಳನ್ನು ತೆಗೆದು ಸ್ವಚ್ಛ ಮಾಡಬೇಕು', NULL, 'After planting, weeds should be removed and cleaned.', NULL, 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7470, 'BETEL VINE', NULL, N'>2', N'May-June', N'May-June', N'5,6', N'Vegetative stage', N'7', 'NORMAL', 'NO', 'ವೀಳ್ಯೆದೆಲೆಯು ಹೆಚ್ಚು ಗೊಬ್ಬರವನ್ನು ಬಯಸುವ ಬೆಳೆ. ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ಕೊಟ್ಟಿಗೆ ಗೊಬ್ಬರ ಮತ್ತು ರಸಗೊಬ್ಬರಗಳನ್ನು ಬಳ್ಳಿಗಳನ್ನು ಇಳಿಸಿದ ಕೂಡಲೇ ಮುಂಗಾರು ಮಳೆಗೆ ಮೊದಲು ಒದಗಿಸಬೇಕು. ಮೊಳಕೆಯೊಡೆದ ಆಧಾರದ ಮರಗಳ ಸಸಿಗಳಲ್ಲಿ ಬೇಕಾದಷ್ಟನ್ನು ಮಾತ್ರ ಉಳಿಸಿಕೊಳ್ಳಬೇಕು. ಆಧಾರ ಮರಗಳ ಕಾಂಡ ನೇರವಾಗಿದ್ದು, ಮುಳ್ಳು ಮತ್ತು ರೆಂಬೆರಹಿತವಾಗಿರಬೇಕು. ಬಳ್ಳಿಯನ್ನು ಮರಕ್ಕೆ ಹಬ್ಬಿಸಿ ಬಾಳೆ ನಾರಿನಿಂದ ಗಂಟು ಹಾಕಿ ಕಟ್ಟಬೇಕು. ಬಳ್ಳಿ ಇಳಿಸುವುದು : ಬಳ್ಳಿ ಮರಕ್ಕೆ ಹಬ್ಬಿದ ಒಂದು ವರ್ಷದ ನಂತರ ಎಲೆಯ ಗಾತ್ರ ಕಡಿಮೆಯಾಗಿ', NULL, 'Betel leaf is a crop that requires a lot of fertilizer. Recommended manure and fertilizers should be provided immediately after the vines are planted, before the monsoon rains. Only the required amount should be retained in the seedlings of the sprouted rootstocks. The trunk of the rootstocks should be straight, thornless and branchless. The vine should be tied to the tree by making a knot with banana fiber. Planting the vine: After one year of planting the vine on the tree, the size of the leaves should decrease.', NULL, NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7471, 'BETEL VINE', NULL, N'>2', N'May-June', N'May-June', N'5,6', N'Harvesting', N'7', 'BELOW NORMAL', 'YES', 'ಬಲಿತ ಎಲೆಗಳನ್ನು ತೊಟ್ಟು ಸಹಿತ ಕೊಯ್ಲು ಮಾಡಬೇಕು', NULL, 'Mature leaves should be harvested along with the stalk.', NULL, NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7472, 'BETEL VINE', NULL, N'>2', N'May-June', N'May-June', N'5,6', N'Vegetative stage', N'7', 'BELOW NORMAL', 'NO', '• ತೋಟದ ಮಧ್ಯೆ ಉಳುಮೆ ಮಾಡಿ ಭೂಮಿಯನ್ನು ಸ್ವಚ್ಛಗೊಳಿಸುವುದು
• ನಂತರ ಗಿಡದ ಸುತ್ತ ಪಾತಿ ಮಾಡಿ LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ರಸಗೊಬ್ಬರಗಳನ್ನು ಕೊಡುವುದು
• ಹಸಿರೆಲೆ ಗೊಬ್ಬರದ ಗಿಡಗಳಾದ ಸೆಣಬು, ಅಲಸಂದಿ ಅಥವಾ ಹುರುಳಿ ಬೆಳೆಯನ್ನು ಬೆಳೆಯುವುದರಿಂದ ಭೂಮಿಯ ಫಲವತ್ತತೆಯನ್ನು ಹೆಚ್ಚಿಸಬಹುದು
• ತೋಟದ ಮಧ್ಯದಲ್ಲಿ ಅಂತರಬೆಳೆಗಳನ್ನಾಗಿ ಬೆಳೆಯಬಹುದು', NULL, '• Ploughing and clearing the land in the middle of the garden
• Then making a bed around the plant and applying fertilizers recommended based on LRI
• Growing green manure crops such as jute, sorghum or buckwheat can increase the fertility of the soil
• Can be grown as intercrops in the middle of the garden', NULL, NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7473, 'BETEL VINE', NULL, N'>2', N'May-June', N'May-June', N'5,6', N'Vegetative stage', N'7', 'ABOVE NORMAL', 'YES', 'ಬಳ್ಳಿ ಮರಕ್ಕೆ ಹಬ್ಬಿದ ಒಂದು ವರ್ಷದ ನಂತರ ಎಲೆಯ ಗಾತ್ರ ಕಡಿಮೆಯಾಗಿ ಇಳುವರಿ ಕಡಿಮೆಯಾಗುತ್ತದೆ. ಆಗಬಳ್ಳಿಗೆ ಪುನ:ಶ್ಚೇತನ ನೀಡಲು ಬಳ್ಳಿ ಇಳಿಸಬೇಕು', NULL, 'After a year of vine growth, the size of the leaves decreases and the yield decreases. Then the vine should be pruned to rejuvenate the vine.', NULL, NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
