INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7477, 'BETEL VINE', NULL, N'>2', N'July-August', N'July-August', N'7,8', N'Vegetative stage', N'2', 'BELOW NORMAL', 'YES', 'ಪ್ರಸ್ತುತ ಹಂತದಲ್ಲಿ ಬೆಳೆ ಉತ್ತಮವಾಗಿದ್ದರೆ, ಇತರೆ ಬೆಳೆ ಬೆಳೆದಿದ್ದಲ್ಲಿ ಅವುಗಳ ನಿರ್ವಹಣೆಯತ್ತ ಗಮನಹರಿಸುವುದು', NULL, 'If the crop is good at the current stage, focus on managing other crops if they have grown.', NULL, NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7512, 'DRUMSTICK', NULL, N'<1', N'July-December', N'July-December', N'7,12', N'Vegetative stage', N'2', 'NORMAL', 'YES', 'ಕೊಟ್ಟಿಗೆ ಗೊಬ್ಬರ: 25 ಟನ್ 50:125:30 ಕಿ. ಗ್ರಾಂ ರಾಸಾಯನಿಕ ಗೊಬ್ಬರಗಳನ್ನು ಪ್ರತಿ ಹೆಕ್ಟರಗೆ ನೀಡಬೇಕು. ಅರ್ಧ ಪ್ರಮಾಣದ ರಾಸಾಯನಿಕ ಗೊಬ್ಬರಗಳನ್ನು ನಾಟಿ ಮಾಡಿದ 3 ತಿಂಗಳ ನಂತರ ಮತ್ತು ಉಳಿದ ಅರ್ಧ ಪ್ರಮಾಣದ ರಾಸಾಯನಿಕ ಗೊಬ್ಬರಗಳನ್ನು ಮೊದಲು ಕಂತು ಕೊಟ್ಟು 3 ತಿಂಗಳ ನಂತರ ಕೊಡಬೇಕು', 'ಹೇನು, ಕಪ್ಪು ಕಂಬಳಿ ಹುಳು ಮತ್ತು ಹೂ ಮೊಗ್ಗಿನ/ ಕಾಯಿ ಕೊರಕದ ಹತೋಟಿಗೆ ಗಿಡಗಳು ಹೊಸದಾಗಿ ಚಿಗುರಿದಾಗ 2 ಮಿ.ಲೀ. ಮೆಲಾಥಿಯಾನ್ 50EC 1 ಲೀ. ನೀರಿನಲ್ಲಿ ಬೆರೆಸಿ ಸಿಂಪಡಿಸಬೇಕು ಹಾಗೂ ಹೂ ವಾಡಲು ಪ್ರಾರಂಭವಾದಾಗ 1 ಮಿ.ಲೀ. ಮೊನೋಕ್ರೊಟೋಫಾಸ್ 36 SL 1 ಲೀಟರ್‌ನೀರಿನಲ್ಲಿ ಕರಗಿಸಿ ಸಿಂಪಡಿಸಬೇಕು', 'Manure: 25 tons of 50:125:30 kg. of chemical fertilizers should be given per hectare. Half the amount of chemical fertilizers should be given 3 months after planting and the remaining half of the amount of chemical fertilizers should be given in the first installment and after 3 months', 'No action needs to be taken.', 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
