INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7514, 'DRUMSTICK', NULL, N'<1', N'July-December', N'July-December', N'7,12', N'Vegetative stage', N'2', 'BELOW NORMAL', 'YES', 'ಕೃಷಿ ಹೊಂಡ, ಇತರ ಮೂಲಗಳಲ್ಲಿ ಲಭ್ಯವಿರುವ ನೀರನ್ನು ಬಳಸಿ ಸಂರಕ್ಷಣಾ ನೀರಾವರಿ ಕೊಡುವುದು', NULL, 'Conservation irrigation using water available from agricultural wells and other sources', 'For powdery mildew at the time of blooming, spray 3 g per liter water soluble sulfur.', 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7515, 'DRUMSTICK', NULL, N'<1', N'July-December', N'July-December', N'7,12', N'Vegetative stage', N'2', 'BELOW NORMAL', 'NO', 'ಕೃಷಿ ಹೊಂಡ, ಇತರ ಮೂಲಗಳಲ್ಲಿ ಲಭ್ಯವಿರುವ ನೀರನ್ನು ಬಳಸಿ ಸಂರಕ್ಷಣಾ ನೀರಾವರಿ ಕೊಡುವುದು', 'ಬೂದು ರೋಗ ಹೂವಾಡಲು ಪ್ರಾರಂಭವಾದಾಗ 3 ಗ್ರಾಂ ನೀರಿನಲ್ಲಿ ಕರಗುವ ಗಂಧಕವನ್ನು 1 ಲೀಟರ್ ನೀರಿನಲ್ಲಿ ಕರಗಿಸಿ ಸಿಂಪಡಿಸಬೇಕು', 'Conservation irrigation using water available from agricultural wells and other sources', 'Spray 2 g Mancozeb 75 W.P per liter of water to control leaf spot disease.', 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
