INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7434, 'BETEL VINE', NULL, N'<1', N'January-February', N'January-February', N'1,2', N'Vegetative stage', N'3', 'NORMAL', 'NO', 'ನಾಟಿಯಾದ ನಂತರದಲ್ಲಿ ಕಳೆಗಳನ್ನು ತೆಗೆದು ಸ್ವಚ್ಛ ಮಾಡಬೇಕು', NULL, 'After planting, weeds should be removed and cleaned.', NULL, 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7435, 'BETEL VINE', NULL, N'<1', N'January-February', N'January-February', N'1,2', N'Vegetative stage', N'3', 'BELOW NORMAL', 'YES', 'ಸಂಪೂರ್ಣ ಬಳ್ಳಿಯನ್ನು ಮರದಿಂದ ಕೆಳಗಿಳಿಸಬೇಕು. ಬಳ್ಳಿಯ ಕೆಳಭಾಗವನ್ನು ಸುರುಳಿಯಾಗಿ ಸುತ್ತಿ ಸುಮಾರು 60 ಸೆಂ.ಮೀ ನಷ್ಟು ಬಳ್ಳಿಯ ಕುಡಿಭಾಗ ಮೇಲಿರುವಂತೆ, ಪಾತಿಯಲ್ಲಿ ಹೂಳಬೇಕು. ಇದರಿಂದ ಬರುವ ಚಿಗುರುಗಳಿಂದ ಹೆಚ್ಚು ಇಳುವರಿ ಮತ್ತು ಅಧಿಕ ಗುಣಮಟ್ಟದ ಎಲೆಗಳನ್ನು ಪಡೆಯಬಹುದು', 'ಸೊರಗು ರೋಗ ನಿಯಂತ್ರಣಕ್ಕಾಗಿ ಶೇ.1 ರ ಬೋರ್ಡೊ ದ್ರಾವಣದಿಂದ ಬಳ್ಳಿಯನ್ನು ಇಳಿಸಿದಾಗ ಮಣ್ಣನ್ನು ತೋಯಿಸಬೇಕು', 'The entire vine should be taken down from the tree. The lower part of the vine should be coiled and buried in the soil with about 60 cm of the stem on top. This will help to get higher yields and higher quality leaves from the shoots that emerge.', 'To control wilt disease, the soil should be drenched with 1% Bordeaux mixture.', 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7436, 'BETEL VINE', NULL, N'<1', N'January-February', N'January-February', N'1,2', N'Vegetative stage', N'3', 'BELOW NORMAL', 'NO', '• ಕೃಷಿ ಹೊಂಡ, ಇತರ ಮೂಲಗಳಲ್ಲಿ ಲಭ್ಯವಿರುವ ನೀರನ್ನು ಬಳಸಿ ನೀರಾವರಿ ಕೊಡುವುದು
• ಗಿಡದ ಸುತ್ತಲು ಒಣಗಿದ ಎಲೆಗಳಿಂದ ಮಣ್ಣಿನ ಮೇಲೊದಿಕೆ ಮಾಡುವುದರಿಂದ ಮಣ್ಣಿನ ತೇವಾಂಶವನ್ನು ಕಾಪಾಡಿಕೊಳ್ಳಬಹುದು', 'ಎಲೆ ಚುಕ್ಕೆ ರೋಗ ಮತ್ತು ಕೊಳೆ ರೋಗಗಳ ನಿಯಂತ್ರಣಕ್ಕಾಗಿ ಶೇ.1ರ ಬೋರ್ಡೋ ದ್ರಾವಣ ಅಥವಾ 3 ಗ್ರಾಂ ತಾಮ್ರದ ಆಕ್ಸಿಕ್ಲೋರೈಡ್ 50 ಡಬ್ಲೂಯ.ಪಿ. ಪ್ರತಿ ಲೀಟರ್ ನೀರಿನಲ್ಲಿ ಬೆರಸಿ ಸಿಂಪಡಿಸಬೇಕು', '• Irrigation using water available from agricultural wells and other sources
• Mulching the soil with dry leaves around the plant can help maintain soil moisture', 'For the control of leaf spot and rust diseases, spray 1% Bordeaux mixture or 3 grams of copper oxychloride 50 W.P. mixed in liter of water.', 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7437, 'BETEL VINE', NULL, N'<1', N'January-February', N'January-February', N'1,2', N'Vegetative stage', N'3', 'ABOVE NORMAL', 'YES', 'ತೋಟದಲ್ಲಿ ನೀರು ನಿಂತಿದ್ದಲ್ಲಿ ನೀರನ್ನು ಬಸಿಯುವಂತೆ ಮಾಡಬೇಕು', NULL, 'If there is standing water in the garden, it should be drained.', 'NIL', 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
