INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7528, 'DRUMSTICK', NULL, N'<1', N'March', N'March', N'3', N'Flowering', N'4', 'ABOVE NORMAL', 'YES', 'ತೋಟದಲ್ಲಿ ನೀರು ನಿಂತಿದ್ದಲ್ಲಿ ನೀರನ್ನು ಬಸಿಯುವಂತೆ ಮಾಡಬೇಕು', 'ಹೇನು, ಕಪ್ಪು ಕಂಬಳಿ ಹುಳು ಮತ್ತು ಹೂ ಮೊಗ್ಗಿನ/ ಕಾಯಿ ಕೊರಕದ ಹತೋಟಿಗೆ ಗಿಡಗಳು ಹೊಸದಾಗಿ ಚಿಗುರಿದಾಗ 2 ಮಿ.ಲೀ. ಮೆಲಾಥಿಯಾನ್ 50EC 1 ಲೀ. ನೀರಿನಲ್ಲಿ ಬೆರೆಸಿ ಸಿಂಪಡಿಸಬೇಕು ಹಾಗೂ ಹೂ ವಾಡಲು ಪ್ರಾರಂಭವಾದಾಗ 1 ಮಿ.ಲೀ. ಮೊನೋಕ್ರೊಟೋಫಾಸ್ 36 SL 1 ಲೀಟರ್‌ನೀರಿನಲ್ಲಿ ಕರಗಿಸಿ ಸಿಂಪಡಿಸಬೇಕು', 'If there is standing water in the garden, it should be drained.', 'No action needs to be taken.', 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7444, 'BETEL VINE', NULL, N'<1', N'March-April', N'April', N'4', N'Vegetative stage', N'5', 'ABOVE NORMAL', 'NO', 'ಪ್ರಸ್ತುತ ಹಂತದಲ್ಲಿ ಬೆಳೆ ಉತ್ತಮವಾಗಿದ್ದರೆ, ಇತರೆ ಬೆಳೆ ಬೆಳೆದಿದ್ದಲ್ಲಿ ಅವುಗಳ ನಿರ್ವಹಣೆಯತ್ತ ಗಮನಹರಿಸುವುದು', NULL, 'If the crop is good at the current stage, focus on managing other crops if they have grown.', NULL, NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7445, 'BETEL VINE', NULL, N'1-2', N'May-June', N'May-June', N'5,6', N'Vegetative stage', N'7', 'NORMAL', 'YES', 'ವೀಳ್ಯೆದೆಲೆಯು ಹೆಚ್ಚು ಗೊಬ್ಬರವನ್ನು ಬಯಸುವ ಬೆಳೆ. ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ಕೊಟ್ಟಿಗೆ ಗೊಬ್ಬರ ಮತ್ತು ರಸಗೊಬ್ಬರಗಳನ್ನು ಬಳ್ಳಿಗಳನ್ನು ಇಳಿಸಿದ ಕೂಡಲೇ ಮುಂಗಾರು ಮಳೆಗೆ ಮೊದಲು ಒದಗಿಸಬೇಕು. ಮೊಳಕೆಯೊಡೆದ ಆಧಾರದ ಮರಗಳ ಸಸಿಗಳಲ್ಲಿ ಬೇಕಾದಷ್ಟನ್ನು ಮಾತ್ರ ಉಳಿಸಿಕೊಳ್ಳಬೇಕು. ಆಧಾರ ಮರಗಳ ಕಾಂಡ ನೇರವಾಗಿದ್ದು, ಮುಳ್ಳು ಮತ್ತು ರೆಂಬೆರಹಿತವಾಗಿರಬೇಕು. ಬಳ್ಳಿಯನ್ನು ಮರಕ್ಕೆ ಹಬ್ಬಿಸಿ ಬಾಳೆ ನಾರಿನಿಂದ ಗಂಟು ಹಾಕಿ ಕಟ್ಟಬೇಕು. ಬಳ್ಳಿ ಇಳಿಸುವುದು : ಬಳ್ಳಿ ಮರಕ್ಕೆ ಹಬ್ಬಿದ ಒಂದು ವರ್ಷದ ನಂತರ ಎಲೆಯ ಗಾತ್ರ ಕಡಿಮೆಯಾಗಿ', NULL, 'Betel leaf is a crop that requires a lot of fertilizer. Recommended manure and fertilizers should be provided immediately after the vines are planted, before the monsoon rains. Only the required amount should be retained in the seedlings of the sprouted rootstocks. The trunk of the rootstocks should be straight, thornless and branchless. The vine should be tied to the tree by making a knot with banana fiber. Planting the vine: After one year of planting the vine on the tree, the size of the leaves should decrease.', NULL, NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
