INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7448, 'BETEL VINE', NULL, N'1-2', N'May-June', N'May-June', N'5,6', N'Vegetative stage', N'7', 'BELOW NORMAL', 'NO', '• ತೋಟದ ಮಧ್ಯೆ ಉಳುಮೆ ಮಾಡಿ ಭೂಮಿಯನ್ನು ಸ್ವಚ್ಛಗೊಳಿಸುವುದು
• ನಂತರ ಗಿಡದ ಸುತ್ತ ಪಾತಿ ಮಾಡಿ LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ರಸಗೊಬ್ಬರಗಳನ್ನು ಕೊಡುವುದು 
• ಹಸಿರೆಲೆ ಗೊಬ್ಬರದ ಗಿಡಗಳಾದ ಸೆಣಬು, ಅಲಸಂದಿ ಅಥವಾ ಹುರುಳಿ ಬೆಳೆಯನ್ನು ಬೆಳೆಯುವುದರಿಂದ ಭೂಮಿಯ ಫಲವತ್ತತೆಯನ್ನು ಹೆಚ್ಚಿಸಬಹುದು
• ತೋಟದ ಮಧ್ಯದಲ್ಲಿ ಅಂತರಬೆಳೆಗಳನ್ನಾಗಿ ಬೆಳೆಯಬಹುದು', 'ತೋಟದ ಸುತ್ತಲೂ ಗಾಳಿಯ ತಡೆಗಾಗಿ ಗೋಡೆ ತಡೆ ಅಥವಾ ಜೈವಿಕ ತಡೆಗಳಾದ ನುಗ್ಗೆ, ಹಿಪುöಪನೇರಳೆ, ಸೀಮೆ ಹುಣಸೆ ಇತ್ಯಾದಿಮರಗಳನ್ನು ದಟ್ಟವಾಗಿ ಬೆಳೆಯಬೇಕು', '• Ploughing and clearing the land in the middle of the garden
• Then making a bed around the plant and applying fertilizers recommended based on LRI 
• Growing green manure crops such as jute, sorghum or buckwheat can increase the fertility of the soil
• Can be grown as intercrops in the middle of the garden', NULL, NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7449, 'BETEL VINE', NULL, N'1-2', N'May-June', N'May-June', N'5,6', N'Vegetative stage', N'7', 'ABOVE NORMAL', 'YES', 'ಬಳ್ಳಿ ಮರಕ್ಕೆ ಹಬ್ಬಿದ ಒಂದು ವರ್ಷದ ನಂತರ ಎಲೆಯ ಗಾತ್ರ ಕಡಿಮೆಯಾಗಿ ಇಳುವರಿ ಕಡಿಮೆಯಾಗುತ್ತದೆ. ಆಗಬಳ್ಳಿಗೆ ಪುನ:ಶ್ಚೇತನ ನೀಡಲು ಬಳ್ಳಿ ಇಳಿಸಬೇಕು', NULL, 'After a year of vine growth, the size of the leaves decreases and the yield decreases. Then the vine should be pruned to rejuvenate the vine.', NULL, NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7450, 'BETEL VINE', NULL, N'1-2', N'May-June', N'May-June', N'5,6', N'Vegetative stage', N'7', 'ABOVE NORMAL', 'NO', 'ಪ್ರಸ್ತುತ ಹಂತದಲ್ಲಿ ಬೆಳೆ ಉತ್ತಮವಾಗಿದ್ದರೆ, ಇತರೆ ಬೆಳೆ ಬೆಳೆದಿದ್ದಲ್ಲಿ ಅವುಗಳ ನಿರ್ವಹಣೆಯತ್ತ ಗಮನಹರಿಸುವುದು', NULL, 'If the crop is good at the current stage, focus on managing other crops if they have grown.', NULL, NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
