INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7220, 'CASHEWNUT', 17, N'<1', N'May', N'May', N'5', N'Preparation', N'0', 'NIL', 'NIL', 'ಪೂರ್ವಸಿದ್ದತೆ: ಉಳುಮೆ ಮಾಡಿ ಭೂಮಿಯನ್ನು ಹದಗೊಳಿಸಿದ 8 ಮೀ. x 8 ಮೀ. ಅಥವಾ 4 ಮೀ. x 4 ಮೀ. ಅಂತರದಲ್ಲಿ 75x75x75 ಸೆಂ.ಮೀ. ಅಳತೆಯ ಗುಣಿಗಳನ್ನು ತೆಗೆಯುವುದು. ಈ ಗುಣಿಗಳನ್ನು ಮೇಲ್ಮಣ್ಣು ಮತ್ತು 25 ಕಿ.ಗ್ರಾಂ ಕೊಟ್ಟಿಗೆ ಗೊಬ್ಬರದ ಮಿಶ್ರಣದಿಂದ ತುಂಬುವುದು', NULL, 'Preparation: After ploughing and levelling the land, dig holes measuring 75x75x75 cm at a spacing of 8 m. x 8 m. or 4 m. x 4 m. Fill these holes with a mixture of topsoil and 25 kg of cow dung.', NULL, 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7221, 'CASHEWNUT', 17, N'<1', N'June', N'June', N'6', N'Planting', N'1', 'NORMAL', 'YES', 'ಗುಣಿಗಳ ಮಧ್ಯದಲ್ಲಿ ಕಸಿಗಿಡವನ್ನು ನಾಟಿ ಮಾಡುವುದು. ನಾಟಿ ಮಾಡಿದ ನಂತರ LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ರಸಗೊಬ್ಬರಗಳನ್ನು ಒದಗಿಸುವುದು', NULL, 'Planting of grafted plants in the middle of the ridges. Providing recommended fertilizers based on LRI after planting.', NULL, 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7222, 'CASHEWNUT', 17, N'<1', N'June', N'June', N'6', N'Planting', N'1', 'NORMAL', 'NO', 'ಮಳೆಯ ಮುನ್ಸೂಚನೆಯನ್ನು ಗಮನದಲ್ಲಿಟ್ಟುಕೊಂಡು ಗುಣಿಗಳ ಮಧ್ಯದಲ್ಲಿ ಕಸಿಗಿಡವನ್ನು ನಾಟಿ ಮಾಡುವುದು. ನಾಟಿ ಮಾಡಿದ ನಂತರ LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ರಸಗೊಬ್ಬರಗಳನ್ನು ಒದಗಿಸುವುದು', NULL, 'Planting of grafted plants in the middle of the ridges keeping in mind the rainfall forecast. Providing recommended fertilizers based on LRI after planting.', NULL, 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7223, 'CASHEWNUT', 17, N'<1', N'June', N'June', N'6', N'Planting', N'1', 'BELOW NORMAL', 'YES', 'ನೀರಾವರಿ ಸೌಲಭ್ಯವಿದ್ದಲ್ಲಿ ಗುಣಿಗಳ ಮಧ್ಯದಲ್ಲಿ ಕಸಿಗಿಡವನ್ನು ನಾಟಿ ಮಾಡುವುದು. ನಾಟಿ ಮಾಡಿದ ನಂತರ LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ರಸಗೊಬ್ಬರಗಳನ್ನು ಒದಗಿಸುವುದು', NULL, 'If irrigation facilities are available, transplant the grafted tree in the middle of the ridges. After planting, provide recommended fertilizers based on LRI.', NULL, NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7275, 'CASHEWNUT', 17, N'1-4', N'February-May', N'February-March-April-May', N'2,3,4,5', N'Vegetative stage', N'5', 'NORMAL', 'YES', 'ಹಣ್ಣುಗಳನ್ನು ಕೊಯ್ಲು ಮಾಡಿ ಮುಂದಿನ ಸಂಸ್ಕರಣೆಗೆ ಬಳಸುವುದು', NULL, 'Harvesting fruits and using them for further processing', NULL, 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7276, 'CASHEWNUT', 17, N'1-4', N'February-May', N'February-March-April-May', N'2,3,4,5', N'Vegetative stage', N'5', 'NORMAL', 'NO', 'ಹಣ್ಣುಗಳನ್ನು ಕೊಯ್ಲು ಮಾಡಿ ಮುಂದಿನ ಸಂಸ್ಕರಣೆಗೆ ಬಳಸುವುದು', NULL, 'Harvesting fruits and using them for further processing', NULL, 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7277, 'CASHEWNUT', 17, N'1-4', N'February-May', N'February-March-April-May', N'2,3,4,5', N'Vegetative stage', N'5', 'BELOW NORMAL', 'YES', 'ಮಾಗಿದ ಹಣ್ಣುಗಳನ್ನು ಕೊಯ್ಲು ಮಾಡಿ ಮುಂದಿನ ಸಂಸ್ಕರಣೆಗೆ ಬಳಸುವುದು', 'ಟೀ ಸೊಳೆ ಹಾಗೂ ಸುರಂಗ ಕೀಟ ಕಂಡು ಬಂದಲ್ಲಿ ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ 1.0 ಗ್ರಾಂ ಅಸಿಫೇಟ 75 SP ಹೂ ಬಿಡುವ ಸಮಯದಲ್ಲಿ ಅಥವಾ 2.5 ಮಿ.ಲೀ. ಪ್ರೊಫೆನೋಪಾಸ್ 50 EC ಅಥವಾ 0.5 ಮಿ.ಲೀ. ಲ್ಯಾಂಬ್ಡಸೈಹ್ಯಾಲೋತ್ರಿನ್‍ 2.5 EC ಅನ್ನು ಬೆರೆಸಿ ಸಿಂಪಡಿಸುವುದು', 'Harvesting ripe fruits and using them for further processing', 'If tea weevil and tunnelling insect are found, spray 1.0 g Acephate 75 SP per liter of water at the time of flowering or 2.5 ml Profenopas 50 EC or 0.5 ml Lambdacyhalothrin 2.5 EC mixed with it', 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7278, 'CASHEWNUT', 17, N'1-4', N'February-May', N'February-March-April-May', N'2,3,4,5', N'Vegetative stage', N'5', 'BELOW NORMAL', 'NO', 'ಮಾಗಿದ ಹಣ್ಣುಗಳನ್ನು ಕೊಯ್ಲು ಮಾಡಿ ಮುಂದಿನ ಸಂಸ್ಕರಣೆಗೆ ಬಳಸುವುದು', NULL, 'Harvesting ripe fruits and using them for further processing', NULL, 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7279, 'CASHEWNUT', 17, N'1-4', N'February-May', N'February-March-April-May', N'2,3,4,5', N'Vegetative stage', N'5', 'ABOVE NORMAL', 'YES', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', 'ಕಾಂಡಕೊರೆಯುವ ಹುಳುವಿನ ಭಾದೆ ಪ್ರಾರಂಭಿಕ ಹಂತದಲ್ಲಿ ಶೇ. 2 ಕಾಪರ್ ಆಕ್ಸಿಕ್ಲೊರೈಡ್ + 2 ಮಿ.ಲೀ. ಕ್ಲೋರೋಫೈರಿಫಾಸ್ 20 EC ಲೇಪಿಸಿವುದು ಅಥವಾ ಅಲ್ಯೂಮಿನಿಯಂ ಫಾಸ್ಫಾಯಿಡ್ ಗುಳಿಗೆಗಳನ್ನು ಕಾಂಡದ ರಂಧ್ರಗಳಲ್ಲಿ ಹಾಕಿ ಮಣ್ಣಿನಿಂದ ಮುಚ್ಚವುದು', 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field.', 'In the initial stage of stem borer infestation, apply 2% copper oxychloride + 2 ml. Chlorpyrifos 20 EC or put aluminum phosphide pellets in the holes of the stem and cover with soil', 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7280, 'CASHEWNUT', 17, N'1-4', N'February-May', N'February-March-April-May', N'2,3,4,5', N'Vegetative stage', N'5', 'ABOVE NORMAL', 'NO', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', NULL, 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field.', NULL, 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7281, 'CASHEWNUT', 17, N'>4', N'May-June', N'May-June', N'5,6', N'Vegetative stage', N'2', 'NORMAL', 'YES', '• ತೋಟದ ಮಧ್ಯೆ ಉಳುಮೆ ಮಾಡಿ ಗಿಡದ ಸುತ್ತಲು ಪಾತಿ ಮಾಡಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ಕೊಟ್ಟಿಗೆ ಗೊಬ್ಬರ ಮತ್ತು LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ರಸಗೊಬ್ಬರವನ್ನು ಕೊಡುವುದು
• ಹಸಿರೆಲೆ ಗೊಬ್ಬರದ ಗಿಡಗಳಾದ ಸೆಣಬು, ಅಲಸಂದಿ ಅಥವಾ ಹುರುಳಿ ಬೆಳೆಯನ್ನು ಬೆಳೆಯುವುದರಿಂದ ಭೂಮಿಯ ಫಲವತ್ತತೆಯನ್ನು ಹೆಚ್ಚಿಸಬಹುದು', NULL, '• Ploughing the garden and applying recommended manure and fertilizer based on LRI by making a bed around the plant
• Growing green manure crops such as jute, sorghum or gram can increase soil fertility', NULL, 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
