INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7110, 'COCONUT', 21, N'>4', N'September-October', N'September-October', N'9,10', N'NIL', N'4', 'ABOVE NORMAL', 'NO', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', 'ಸುಳಿಕೊರೆಯುವ ರೈನೋಸರಸ್ ದುಂಬಿಯ ಬಾಧೆ ಕಂಡುಬಂದಲ್ಲಿ
• ಎಳೆಯ ವಯಸ್ಸಿನ ಗಿಡಗಳ ಎಲೆಗಳನ್ನು ಒಟ್ಟುಗೂಡಿಸಿ ಕಟ್ಟವುದು ಉತ್ತಮ
• ಸುಳಿಯ ಭಾಗದ ರಂಧ್ರದಲ್ಲಿ ಕಬ್ಬಿಣದ ಕೊಕ್ಕೆಯನ್ನು ತೂರಿಸಿ ದುಂಬಿಗಳನ್ನು ಹೊರ ತೆಗೆದು ಸಾಯಿಸುವುದು 
• ಒಳ 2-3 ಗಿರಿಗಳ ಬುಡದಲ್ಲಿ 250 ಗ್ರಾಂ. ಕಹಿ ಬೇವಿನ ಹಿಂಡಿಯೊಂದಿಗೆ ಅಲ್ಪ ಪ್ರಮಾಣದ ಮರಳನ್ನು ಸೇರಿಸಿ ಹಾಕುವುದು
• ಪ್ರತಿ ಹೆಕ್ಟೇರ್‌ಗೆ 1 ಸಿ.ಪಿ. ಸಿ.ಆರ್.ಐ. ಮಾದರಿ ಮೋಹಕ ಬಲೆಗಳನ್ನು ಇಡುವುದು
• ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ 2 ಮಿ.ಲೀ. ಕ್ಲೋರೋಪೈರಿಫಾಸ್ ಅನ್ನು ಬೆರೆಸಿ 3 ಘನ.ಮೀ.ಕಾಂಪೋಸ್ಟ್ ಗುಂಡಿಗಳಿಗೆ ಉಪಯೋಗಿಸುವುದು', 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field.', 'If you find a problem with Rhinoceroses borer
• It is better to collect and tie the leaves of young plants
• Insert an iron hook into the hole in the borer and kill the borers 
• At the base of the inner 2-3 ridges, add 250 gm. of bitter neem powder along with a small amount of sand
• Place 1 C.P. C.R.I. type trap per hectare
• Mix 2 ml. Chlorpyrifos per liter of water and use it for 3 cubic meters of compost pits', 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
