INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7302, 'CASHEWNUT', 17, N'>4', N'November-January', N'November-December-January', N'11,12,1', N'Fruit set stage', N'4', 'BELOW NORMAL', 'NO', 'ಸೂಚಿಸಲಾದ ಸಸ್ಯ ಸಂರಕ್ಷಣಾ ಕ್ರಮಗಳನ್ನು ಕೈಗೊಳ್ಳುವುದು', 'ಕಾಂಡಕೊರೆಯುವ ಹುಳುವಿನ ಭಾದೆ ಪ್ರಾರಂಭಿಕ ಹಂತದಲ್ಲಿ ಶೇ. 2 ಕಾಪರ್ ಆಕ್ಸಿಕ್ಲೊರೈಡ್ + 2 ಮಿ.ಲೀ. ಕ್ಲೋರೋಫೈರಿಫಾಸ್ 20 EC ಲೇಪಿಸಿವುದು ಅಥವಾ ಅಲ್ಯೂಮಿನಿಯಂ ಫಾಸ್ಫಾಯಿಡ್ ಗುಳಿಗೆಗಳನ್ನು ಕಾಂಡದ ರಂಧ್ರಗಳಲ್ಲಿ ಹಾಕಿ ಮಣ್ಣಿನಿಂದ ಮುಚ್ಚವುದು', 'Carrying out the recommended plant protection measures', 'In the initial stage of stem borer infestation, apply 2% copper oxychloride + 2 ml. Chlorpyrifos 20 EC or put aluminum phosphide pellets in the holes of the stem and cover with soil', 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
