INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7317, 'Lemon', NULL, N'>1', N'June', N'June', N'6', N'Planting', N'1', 'ABOVE NORMAL', 'NO', 'ಹೆಚ್ಚಾಗಿರುವ ನೀರನ್ನು ತೋಟದಿಂದ ಬಸಿದುಹೋಗುವಂತೆ ಮಾಡಿ, ಕಸಿ ಸಸಿಗಳನ್ನು ನಾಟಿ ಮಾಡುವಾಗ ಕಸಿ ಮಾಡಿದ ಭಾಗ ಭೂಮಿಯ ಮೇಲಿರುವಂತೆ ಜಾಗ್ರತೆ ವಹಿಸಿ, ಗಿಡಗಳಿಗೆ ಕೋಲಿನ ಆಸರೆ ಕೊಡುವುದು. ನಾಟಿ ಮಾಡಿದ ನಂತರ ಗಿಡದ ಸುತ್ತಲು ಪಾತಿ ಮಾಡಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ಗೊಬ್ಬರವನ್ನು ಕೊಡುವುದು', NULL, 'Drain excess water from the garden, and when transplanting seedlings, make sure the grafted part is above the ground, and support the plants with a stake. After planting, make a bed around the plant and apply the recommended fertilizer.', NULL, NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7318, 'Lemon', NULL, N'>1', N'July-August', N'July-August', N'7,8', N'Establishment stage', N'2', 'NORMAL', 'YES', 'ಜೂನ್ ತಿಂಗಳಲ್ಲಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ಪೂರ್ಣ ಪ್ರಮಾಣದ ಕೊಟ್ಟಿಗೆ ಗೊಬ್ಬರ ಅಥವಾ ಕಾಂಪೋಸ್ಟ್ ಒದಗಿಸಬೇಕು. ರಸಗೊಬ್ಬರಗಳನ್ನು ಮೂರು ಸಮ ಕಂತುಗಳಲ್ಲಿ ಹೊಸ ಬೆಳವಣಿಗೆಯ ಸಮಯದಲ್ಲಿ ಅಂದರೆ ಮಾರ್ಚ್-ಏಪ್ರಿಲ್, ಜೂನ್-ಜುಲೈ (ಮಳೆಗಾಲಕ್ಕೆ ಮುಂಚೆ) ಮತ್ತು ಸೆಪ್ಟೆಂಬರ್- ಅಕ್ಟೋಬರ್ (ಮಳೆಗಾಲದ ನಂತರ) ತಿಂಗಳುಗಳಲ್ಲಿ ಒದಗಿಸಬೇಕು', NULL, 'Full dose of recommended manure or compost should be provided in the month of June. Fertilizers should be provided in three equal installments during the new growth period i.e. March-April, June-July (before monsoon) and September-October (after monsoon).', 'NIL', 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7133, 'ARECANUT', NULL, N'<1', N'June', N'June', N'6', N'Planting', N'1', 'BELOW NORMAL', 'NO', '• ನೀರಾವರಿ ಸೌಲಭ್ಯವಿದ್ದಲ್ಲಿ ಗುಣಿಗಳ ಮಧ್ಯದಲ್ಲಿ ಸಸಿಗಳನ್ನು 30-45 ಸೆಂ.ಮೀ. ಆಳದಲ್ಲಿ ನಾಟಿ ಮಾಡುವುದು
• ಅಡಿಕೆ ಮರಗಳು ಬಿಸಿಲಿನ ತಾಪದಿಂದ ಸುಡುವುದನ್ನು ತಪ್ಪಿಸಲು ಉತ್ತರ ದಕ್ಷಿಣ ರೇಖೆಯನ್ನು 35 ಯಷ್ಟು ಪಶ್ಚಿಮ ದಿಕ್ಕಿನೆಡೆಗೆ ವಾಲುವಂತೆ ಎಳೆದ ರೇಖೆಗಳಲ್ಲಿ ಸಸಿಗಳನ್ನು ನಾಟಿಮಾಡಿದಾಗ ಸಾಲಿನ ಮೊದಲಿನ ಗಿಡಗಳಿಗೆ ಮಾತ್ರ ನೆರಳನ್ನು ಒದಗಿಸಬೇಕಾಗುತ್ತದೆ
• ಹೆಚ್ಚು ಮಳೆಬೀಳುವ ಪ್ರದೇಶಗಳಲ್ಲಿ ಎರಡು ಸಾಲಿಗೊಂದರಂತೆ 2-3 ಅಡಿ ಆಳವಾದ ಬಸಿಗಾಲುವೆಗಳನ್ನು ನಿರ್ಮಿಸುವುದು 
• ಗಿಡಗಳಿಗೆ LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ರಸಗೊಬ್ಬರಗಳನ್ನು ಒದಗಿಸುವುದು', NULL, '• If irrigation facilities are available, plant the seedlings 30-45 cm deep in the middle of the rows
• To avoid scorching of the areca trees due to the heat of the sun, when planting the seedlings in lines drawn with a north-south line inclined by 35 degrees towards the west, only the first plants in the row need to be shaded
• In areas with high rainfall, construct 2-3 feet deep drainage ditches in two rows 
• Provide the plants with recommended fertilizers based on LRI', NULL, NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7134, 'ARECANUT', NULL, N'<1', N'June', N'June', N'6', N'Planting', N'1', 'ABOVE NORMAL', 'YES', '• ಹೆಚ್ಚಾಗಿರುವ ನೀರನ್ನು ತೋಟದಿಂದ ಬಸಿದುಹೋಗುವಂತೆ ಮಾಡಿ, ಗುಣಿಗಳ ಮಧ್ಯದಲ್ಲಿ ಸಸಿಗಳನ್ನು 30-45 ಸೆಂ.ಮೀ. ಆಳದಲ್ಲಿ ನಾಟಿ ಮಾಡುವುದು
• ಅಡಿಕೆ ಮರಗಳು ಬಿಸಿಲಿನ ತಾಪದಿಂದ ಸುಡುವುದನ್ನು ತಪ್ಪಿಸಲು ಉತ್ತರ ದಕ್ಷಿಣ ರೇಖೆಯನ್ನು 35 ಯಷ್ಟು ಪಶ್ಚಿಮ ದಿಕ್ಕಿನೆಡೆಗೆ ವಾಲುವಂತೆ ಎಳೆದ ರೇಖೆಗಳಲ್ಲಿ ಸಸಿಗಳನ್ನು ನಾಟಿಮಾಡಿದಾಗ ಸಾಲಿನ ಮೊದಲಿನ ಗಿಡಗಳಿಗೆ ಮಾತ್ರ ನೆರಳನ್ನು ಒದಗಿಸಬೇಕಾಗುತ್ತದೆ
• ಹೆಚ್ಚು ಮಳೆಬೀಳುವ ಪ್ರದೇಶಗಳಲ್ಲಿ ಎರಡು ಸಾಲಿಗೊಂದರಂತೆ 2-3 ಅಡಿ ಆಳವಾದ ಬಸಿಗಾಲುವೆಗಳನ್ನು ನಿರ್ಮಿಸುವುದು 
• ಗಿಡಗಳಿಗೆ LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ರಸಗೊಬ್ಬರಗಳನ್ನು ಒದಗಿಸುವುದು', NULL, '• To drain excess water from the garden, plant the seedlings 30-45 cm deep in the middle of the ridges
• To avoid scorching of the areca trees, the seedlings are planted in rows drawn with a north-south line inclined 35 degrees towards the west, providing shade only to the first plants in the row
• In areas with high rainfall, construct 2-3 feet deep drainage ditches in two rows 
• Provide the plants with recommended fertilizers based on LRI', NULL, NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7135, 'ARECANUT', NULL, N'<1', N'June', N'June', N'6', N'Planting', N'1', 'ABOVE NORMAL', 'NO', '• ಹೆಚ್ಚಾಗಿರುವ ನೀರನ್ನು ತೋಟದಿಂದ ಬಸಿದುಹೋಗುವಂತೆ ಮಾಡಿ, ಗುಣಿಗಳ ಮಧ್ಯದಲ್ಲಿ ಸಸಿಗಳನ್ನು 30-45 ಸೆಂ.ಮೀ. ಆಳದಲ್ಲಿ ನಾಟಿ ಮಾಡುವುದು
• ಅಡಿಕೆ ಮರಗಳು ಬಿಸಿಲಿನ ತಾಪದಿಂದ ಸುಡುವುದನ್ನು ತಪ್ಪಿಸಲು ಉತ್ತರ ದಕ್ಷಿಣ ರೇಖೆಯನ್ನು 35 ಯಷ್ಟು ಪಶ್ಚಿಮ ದಿಕ್ಕಿನೆಡೆಗೆ ವಾಲುವಂತೆ ಎಳೆದ ರೇಖೆಗಳಲ್ಲಿ ಸಸಿಗಳನ್ನು ನಾಟಿಮಾಡಿದಾಗ ಸಾಲಿನ ಮೊದಲಿನ ಗಿಡಗಳಿಗೆ ಮಾತ್ರ ನೆರಳನ್ನು ಒದಗಿಸಬೇಕಾಗುತ್ತದೆ
• ಹೆಚ್ಚು ಮಳೆಬೀಳುವ ಪ್ರದೇಶಗಳಲ್ಲಿ ಎರಡು ಸಾಲಿಗೊಂದರಂತೆ 2-3 ಅಡಿ ಆಳವಾದ ಬಸಿಗಾಲುವೆಗಳನ್ನು ನಿರ್ಮಿಸುವುದು 
• ಗಿಡಗಳಿಗೆ LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ರಸಗೊಬ್ಬರಗಳನ್ನು ಒದಗಿಸುವುದು', NULL, '• To drain excess water from the garden, plant the seedlings 30-45 cm deep in the middle of the ridges
• To avoid scorching of the areca trees, the seedlings are planted in rows drawn with a north-south line inclined 35 degrees towards the west, providing shade only to the first plants in the row
• In areas with high rainfall, construct 2-3 feet deep drainage ditches in two rows 
• Provide the plants with recommended fertilizers based on LRI', NULL, NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7136, 'ARECANUT', NULL, N'<1', N'July-August', N'July-August', N'7,8', N'Establishment stage', N'2', 'NORMAL', 'YES', '• ಗಿಡ ಸ್ಥಾಪಿತವಾಗದೆ ಇರುವ ಜಾಗದಲ್ಲಿ ಬೇರೆ ಸಸಿಯನ್ನು ನೆಡುವುದು
• ಹಸಿರೆಲೆ ಗೊಬ್ಬರದ ಗಿಡಗಳಾದ ಸೆಣಬು, ಅಲಸಂದಿ ಅಥವಾ ಹುರುಳಿ ಬೆಳೆಯನ್ನು ಬೆಳೆಯುವುದರಿಂದ ಭೂಮಿಯ ಫಲವತ್ತತೆಯನ್ನು ಹೆಚ್ಚಿಸಬಹುದು', NULL, '• Planting another plant in a place where the plant is not established
• Growing green manure plants such as jute, sorghum or beans can increase the fertility of the soil', NULL, 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7199, 'ARECANUT', NULL, N'>4', N'July-August', N'July-August', N'7,8', N'NIL', N'2', 'BELOW NORMAL', 'NO', 'ಕೃಷಿ ಹೊಂಡ, ಇತರ ಮೂಲಗಳಲ್ಲಿ ಲಭ್ಯವಿರುವ ನೀರನ್ನು ಬಳಸಿ ಸಂರಕ್ಷಣಾ ನೀರಾವರಿ ಕೊಡುವುದು. ಮಣ್ಣಿನ ತೇವಾಂಶವನ್ನು ಸಂರಕ್ಷಿಸಲು ಮಣ್ಣಿನ ಮೇಲೊದಿಕೆ ಮಾಡುವುದು', 'ಕೊಳೆರೋಗ ಮತ್ತು ಸುಳಿಕೊಳೆ ರೋಗವನ್ನು ತಡೆಗಟ್ಟಲು ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ ಶೇ. 1 ರ ಬೋರ್ಡೊ ದ್ರಾವಣ ಅಥವಾ 3 ಗ್ರಾಂ ತಾಮ್ರದ ಆಕ್ಸಿಕ್ಲೋರೈಡ್ 50 WP ಅಥವಾ 2 ಗ್ರಾಂ ಮೆಟಲಾಕ್ಸಿಲ್+ಮ್ಯಾಂಕೋಜೆಬ್ 72 WP ಅನ್ನು ಕರಗಿಸಿ ಮಳೆಗಾಲ ಪ್ರಾಂಭವಾಗುವುದಕ್ಕೆ ಮುನ್ನ ಮತ್ತು 30-45 ದಿನಗಳ ನಂತರ ಇನ್ನೊಮ್ಮೆ ಸಿಂಪಡಿಸುವುದು ಉತ್ತಮ', 'Conservation irrigation using water available from agricultural wells and other sources. Mulching to conserve soil moisture.', 'To prevent rot and downy mildew, it is best to spray 1% Bordeaux mixture or 3 grams of copper oxychloride 50 WP or 2 grams of metalaxyl+mancozeb 72 WP per liter of water before the onset of the rainy season and again after 30-45 days', 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7200, 'ARECANUT', NULL, N'>4', N'July-August', N'July-August', N'7,8', N'NIL', N'2', 'ABOVE NORMAL', 'YES', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', NULL, 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field.', NULL, 'NIL', 'NIK', TO_TIMESTAMP('2026-05-26 15:47:52', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
