INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (8395, 'COCONUT', 21, N'1-4', N'September-October', N'September-October', N'9,10', N'Vegetative stage', N'4', 'BELOW NORMAL', 'YES', 'ಮರದ ಸುತ್ತಲು ಪಾತಿ ಮಾಡಿ LRI ಆಧರಿಸಿ ಶಫಾರಸ್ಸು ಮಾಡಿದ ಗೊಬ್ಬರವನ್ನು ಮೇಲುಗೊಬ್ಬರವನ್ನು ಕೊಡುವುದು', NULL, 'Make a bed around the tree and top-dress with the recommended fertilizer based on LRI.', NULL, 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (8396, 'COCONUT', 21, N'1-4', N'September-October', N'September-October', N'9,10', N'Vegetative stage', N'4', 'BELOW NORMAL', 'NO', 'ಕೃಷಿ ಹೊಂಡ, ಇತರ ಮೂಲಗಳಲ್ಲಿ ಲಭ್ಯವಿರುವ ನೀರನ್ನು ಬಳಸಿ ಸಂರಕ್ಷಣಾ ನೀರಾವರಿ ಕೊಡುವುದು. ಮಣ್ಣಿನ ತೇವಾಂಶವನ್ನು ಸಂರಕ್ಷಿಸಲು ತೆಂಗಿನ ಚಿಪ್ಪುಗಳು ಅಥವಾ ಗರಿಗಳಿಂದ ಮೇಲೊದಿಕೆ ಮಾಡುವುದು', NULL, 'Conservation irrigation using water available from agricultural wells and other sources. Mulching with coconut shells or feathers to conserve soil moisture.', NULL, 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (8448, 'COCONUT', 21, N'>4', N'April-May', N'April-May', N'4,5', N'NIL', N'7', 'NORMAL', 'NO', '1 ಅಡಿ ಆಳದ ಟ್ರೆಂಚ್‌ಗಳನ್ನು ಕಾಂಡದಿಂದ 2.5 ರಿಂದ 3 ಮೀ. ದೂರದಲ್ಲಿ ಇಳಜಾರಿಗೆ ಅಡ್ಡಲಾಗಿ ನಿರ್ಮಿಸುವುದು. ಇದರಿಂದ ಅಧಿಕ ಮಳೆ ಸಂದರ್ಭಗಳಲ್ಲಿ ನೀರು ಬಸಿದುಹೊಗಲು ಸಹಕಾರಿಯಾಗುತ್ತದೆ', 'ಗೆದ್ದಲಿನ ಬಾಧೆ ಕಂಡು ಬಂದಲ್ಲಿ ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ 4 ಮಿ.ಲೀ. ಕ್ಲೋರೊಪೈರಿಫಾಸ್ 20 EC ಅನ್ನು ಬೆರೆಸಿ, ಪ್ರತಿ ಗಿಡಕ್ಕೆ ಸುಮಾರು 10 ಲೀ. ದ್ರಾವಣ ಗಿಡದ ಸುತ್ತಲೂ ಸುರಿಯುವುದು', 'Construct 1 foot deep trenches 2.5 to 3 m from the trunk across the slope. This will help in draining water during heavy rains.', 'If termite infestation is found, mix 4 ml of Chlorpyrifos 20 EC per liter of water and pour about 10 liters of solution around the plant for each plant', 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (8449, 'COCONUT', 21, N'>4', N'April-May', N'April-May', N'4,5', N'NIL', N'7', 'BELOW NORMAL', 'YES', 'ಪ್ರಸ್ತುತ ಹಂತದಲ್ಲಿ ಬೆಳೆ ಉತ್ತಮವಾಗಿದ್ದರೆ, ಇತರೆ ಬೆಳೆ ಬೆಳೆದಿದ್ದಲ್ಲಿ ಅವುಗಳ ನಿರ್ವಹಣೆಯತ್ತ ಗಮನಹರಿಸುವುದು', NULL, 'If the crop is good at the current stage, focus on managing other crops if they have grown.', NULL, 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (8450, 'COCONUT', 21, N'>4', N'April-May', N'April-May', N'4,5', N'NIL', N'7', 'BELOW NORMAL', 'NO', 'ಮಣ್ಣಿನ ತೇವಾಂಶವನ್ನು ಸಂರಕ್ಷಿಸಲು ತೆಂಗಿನ ಚಿಪ್ಪುಗಳು ಅಥವಾ ಗರಿಗಳಿಂದ ಮೇಲೊದಿಕೆ ಮಾಡುವುದು', NULL, 'Mulching with coconut shells or feathers to conserve soil moisture', NULL, 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (8451, 'COCONUT', 21, N'>4', N'April-May', N'April-May', N'4,5', N'NIL', N'7', 'ABOVE NORMAL', 'YES', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', 'ಹಿಟ್ಟು ತಿಗಣೆ, ಶಲ್ಕ ಮತ್ತು ನುಸಿ ಕೀಟ ಭಾದೆಗೆ ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ 1.7 ಮಿ.ಲೀ. ಡೈಮಿಥೊಯೇಟ್ 30 EC ಅಥವಾ 0.5 ಮಿ.ಲೀ. ಇಮಿಡಾಕ್ಲೋಪ್ಲಿಡ್ SL ಅಥವಾ ಶೇ. 1.4 ಮಿ.ಲೀ. ಅಝಾಡಿರಕ್ಟಿನ್ ಅನ್ನು ಬೆರೆಸಿ ಸಿಂಪಡಿಸುವುದು. ರುಗೋಸ್ ಬಿಳಿ ನೊಣ ಕೀಟದ ಭಾದೆಗೆ ಎಕರೆಗೆ 10 ಹಳದಿ ಅಂಟಿನ ಬಲೆಗಳನ್ನು ಅಳವಡಿಸುವುದು ಹಾಗೂ ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ 5 ಮಿ.ಲೀ ಬೇವಿನ ಎಣ್ಣೆ ಮತ್ತು 0.5 ಗ್ರಾಂ ಸಾಬೂನು ಪುಡಿಯನ್ನು ಬೆರಿಸಿ ಸಿಂಪಡಿಸುವುದು', 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field.', 'For flour beetles, scale insects and mealybugs, spray 1.7 ml of Dimethoate 30 EC or 0.5 ml of Imidacloprid SL or 1.4 ml of Azadirachtin per liter of water. For rugose whitefly, install 10 yellow sticky traps per acre and spray 5 ml of neem oil and 0.5 g of soap powder per liter of water', 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (8452, 'COCONUT', 21, N'>4', N'April-May', N'April-May', N'4,5', N'NIL', N'7', 'ABOVE NORMAL', 'NO', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', 'ಕೆಂಪು ಮೂತಿಯ ದುಂಬಿ ಭಾದೆ ಕಂಡು ಬಂದಲ್ಲಿ ಹುಳುವಿರುವ ಕಡೆ ಒಂದು ರಂಧ್ರವನ್ನು ಮಾಡಿ ಅದಕ್ಕೆ 4 ಮಿ.ಲೀ. ಕ್ಲೋರಾಂಟ್ರನಿಲಿಪ್ರೋಲ್ 18.5 SC ಅಥವಾ 4 ಮಿ.ಲೀ. ಇಂಡಾಕ್ಸಾಕಾರ್ಬ 14.5 SC ಅನ್ನು ಪ್ರತಿ ಲೀಟರ್ ನೀರಿನಲ್ಲಿ ಬೆರೆಸಿ ಸುರಿಯುವುದು', 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field.', 'If red-nosed beetle infestation is found, make a hole in the area where the worm is and pour 4 ml. Chlorantraniliprole 18.5 SC or 4 ml. Indoxacarb 14.5 SC mixed in every liter of water', 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (8453, 'ARECANUT', NULL, N'<1', N'May', N'May', N'5', N'Preparation', N'0', 'NIL', 'NIL', 'ಪೂರ್ವಸಿದ್ದತೆ: ಭೂಮಿಯನ್ನು ಉಳುಮೆ ಮಾಡಿ ಸಿದ್ದಗೊಳಿಸುವುದು. ಪಶ್ಚಿಮ ಮತ್ತು ದಕ್ಷಿಣ ಅಂಚಿನಲ್ಲಿ ಮಹಾಗನಿ, ಬೇವು, ಮುರುಗಲು, ಸಿಲ್ವರ್‌ಓಕ್ ನಂತಹ ಗಿಡಗಳನ್ನು ನಾಟಿ ಮಾಡಿ ಶಾಶ್ವತ ಗಾಳಿತಡೆ ಮತ್ತು ನೆರಳನ್ನು ಒದಗಿಸುವುದು. 75x75x75 ಸೆಂ. ಮೀ. ಗುಣಿಗಳನ್ನು ತೆಗೆದು ಮೇಲ್ಮಣ್ಣು ಮತ್ತು ಕೊಟ್ಟಿಗೆಗೊಬ್ಬರ ಮಿಶ್ರಣದಿಂದ ತುಂಬುವುದು', NULL, 'Pre-preparation: Ploughing and preparing the land. Planting trees like Mahogany, Neem, Murugalu, Silver Oak on the western and southern edges to provide permanent windbreak and shade. 75x75x75 cm. M. Dig holes and fill with a mixture of topsoil and manure.', NULL, 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (8503, 'ARECANUT', NULL, N'1-4', N'November-December', N'November-December', N'11,12', N'Vegetative stage', N'4', 'NORMAL', 'NO', 'ಪ್ರಸ್ತುತ ಹಂತದಲ್ಲಿ ಬೆಳೆ ಉತ್ತಮವಾಗಿದ್ದರೆ, ಇತರೆ ಬೆಳೆ ಬೆಳೆದಿದ್ದಲ್ಲಿ ಅವುಗಳ ನಿರ್ವಹಣೆಯತ್ತ ಗಮನಹರಿಸುವುದು', NULL, 'If the crop is good at the current stage, focus on managing other crops if they have grown.', NULL, 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
