INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (8601, 'CASHEWNUT', 17, N'1-4', N'February-May', N'February-March-April-May', N'2,3,4,5', N'Vegetative stage', N'5', 'BELOW NORMAL', 'YES', 'ಮಾಗಿದ ಹಣ್ಣುಗಳನ್ನು ಕೊಯ್ಲು ಮಾಡಿ ಮುಂದಿನ ಸಂಸ್ಕರಣೆಗೆ ಬಳಸುವುದು', 'ಟೀ ಸೊಳೆ ಹಾಗೂ ಸುರಂಗ ಕೀಟ ಕಂಡು ಬಂದಲ್ಲಿ ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ 1.0 ಗ್ರಾಂ ಅಸಿಫೇಟ 75 SP ಹೂ ಬಿಡುವ ಸಮಯದಲ್ಲಿ ಅಥವಾ 2.5 ಮಿ.ಲೀ. ಪ್ರೊಫೆನೋಪಾಸ್ 50 EC ಅಥವಾ 0.5 ಮಿ.ಲೀ. ಲ್ಯಾಂಬ್ಡಸೈಹ್ಯಾಲೋತ್ರಿನ್‍ 2.5 EC ಅನ್ನು ಬೆರೆಸಿ ಸಿಂಪಡಿಸುವುದು', 'Harvesting ripe fruits and using them for further processing', 'If tea weevil and tunnelling insect are found, spray 1.0 g Acephate 75 SP per liter of water at the time of flowering or 2.5 ml Profenopas 50 EC or 0.5 ml Lambdacyhalothrin 2.5 EC mixed with it', 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (8602, 'CASHEWNUT', 17, N'1-4', N'February-May', N'February-March-April-May', N'2,3,4,5', N'Vegetative stage', N'5', 'BELOW NORMAL', 'NO', 'ಮಾಗಿದ ಹಣ್ಣುಗಳನ್ನು ಕೊಯ್ಲು ಮಾಡಿ ಮುಂದಿನ ಸಂಸ್ಕರಣೆಗೆ ಬಳಸುವುದು', NULL, 'Harvesting ripe fruits and using them for further processing', NULL, 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (8603, 'CASHEWNUT', 17, N'1-4', N'February-May', N'February-March-April-May', N'2,3,4,5', N'Vegetative stage', N'5', 'ABOVE NORMAL', 'YES', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', 'ಕಾಂಡಕೊರೆಯುವ ಹುಳುವಿನ ಭಾದೆ ಪ್ರಾರಂಭಿಕ ಹಂತದಲ್ಲಿ ಶೇ. 2 ಕಾಪರ್ ಆಕ್ಸಿಕ್ಲೊರೈಡ್ + 2 ಮಿ.ಲೀ. ಕ್ಲೋರೋಫೈರಿಫಾಸ್ 20 EC ಲೇಪಿಸಿವುದು ಅಥವಾ ಅಲ್ಯೂಮಿನಿಯಂ ಫಾಸ್ಫಾಯಿಡ್ ಗುಳಿಗೆಗಳನ್ನು ಕಾಂಡದ ರಂಧ್ರಗಳಲ್ಲಿ ಹಾಕಿ ಮಣ್ಣಿನಿಂದ ಮುಚ್ಚವುದು', 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field.', 'In the initial stage of stem borer infestation, apply 2% copper oxychloride + 2 ml. Chlorpyrifos 20 EC or put aluminum phosphide pellets in the holes of the stem and cover with soil', 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (8604, 'CASHEWNUT', 17, N'1-4', N'February-May', N'February-March-April-May', N'2,3,4,5', N'Vegetative stage', N'5', 'ABOVE NORMAL', 'NO', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', NULL, 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field.', NULL, 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
