INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (8607, 'CASHEWNUT', 17, N'>4', N'May-June', N'May-June', N'5,6', N'Vegetative stage', N'2', 'BELOW NORMAL', 'YES', '• ತೋಟದ ಮಧ್ಯೆ ಉಳುಮೆ ಮಾಡಿ ಗಿಡದ ಸುತ್ತಲು ಪಾತಿ ಮಾಡಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ಕೊಟ್ಟಿಗೆ ಗೊಬ್ಬರ ಮತ್ತು LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ರಸಗೊಬ್ಬರವನ್ನು ಕೊಡುವುದು
