INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (8663, 'BLACK PEPPER', 10, N'1-3', N'May- June', N'May-June', N'5,6', N'Vegetative stage', N'3', 'BELOW NORMAL', 'NO', '• ಕೃಷಿ ಹೊಂಡ, ಇತರ ಮೂಲಗಳಲ್ಲಿ ಲಭ್ಯವಿರುವ ನೀರನ್ನು ಬಳಸಿ ನೀರಾವರಿ ಕೊಡುವುದು
• ತೋಟದಲ್ಲಿ ಉಳುಮೆ ಮಾಡಿ LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ಶೇ. 50 ರ ರಸಗೊಬ್ಬರವನ್ನು ಒದಗಿಸುವುದು
• ಬಳ್ಳಿಗಳನ್ನು ಬಿಸಿಲಿನ ಧಗೆಯಿಂದ ರಕ್ಷಿಸಲು ನೆರಳನ್ನು ಒದಗಿಸುವುದು
• ಬಳ್ಳಿಯನ್ನು ಆಧಾರ ಮರಕ್ಕೆ ಹಬ್ಬುವಂತೆ ಮಾಡುವುದು
• ಗಿಡಗಳ ಸುತ್ತಲು ಒಣಗಿದ ಎಲೆಗಳಿಂದ ಮಣ್ಣಿನ ಮೇಲೊದಿಕೆ ಮಾಡುವುರದ ಮೂಲಕ ಮಣ್ಣಿನ ತೇವಾಂಶವನ್ನು ಕಾಪಾಡಿಕೊಳ್ಳಬಹುದು', NULL, '• Irrigation using water available from agricultural wells, other sources
• Ploughing the garden and providing 50% of the recommended fertilizer based on LRI
• Providing shade to the vines to protect them from the scorching sun
• Allowing the vines to grow on a support tree
• Mulching the soil with dry leaves around the plants can help maintain soil moisture', NULL, 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
