INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (8726, 'CARDAMOM', 15, N'<1', N'May', N'May', N'5', N'Preparation', N'0', 'NIL', 'NIL', 'ಪೂರ್ವಸಿದ್ದತೆ: ಭೂಮಿಯನ್ನು 2-3 ಬಾರಿ ಉಳುಮೆ ಮಾಡಿ 60x60x45 ಸೆಂ.ಮೀ. ಅಳತೆಯ ಗುಣಿಗಳನ್ನು ತೆಗೆದು, ಅವುಗಳನ್ನು ಕೊಟ್ಟಿಗೆ ಗೊಬ್ಬರ ಮತ್ತು ಮೇಲ್ಮಣ್ಣಿನ ಮಿಶ್ರಣದಿಂದ ತುಂಬುವುದು', NULL, 'Preparation: Plow the land 2-3 times, dig trenches measuring 60x60x45 cm, and fill them with a mixture of manure and topsoil.', NULL, 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (8637, 'BLACK PEPPER', 10, N'<1', N'June-july', N'June-july', N'6,7', N'Planting', N'1', 'NORMAL', 'NO', 'ಮಳೆಯ ಮುನ್ಸೂಚನೆಯನ್ನು ಗಮನದಲ್ಲಿಟ್ಟುಕೊಂಡು ಪ್ರತಿ ಗುಂಡಿಗೆ 1 ಕಿ. ಗ್ರಾಂ. ಬೇವಿನ ಹಿಂಡಿ ಮತ್ತು 50 ಗ್ರಾಂ. ಟ್ರೈಕೋಡರ್ಮಾ ಹಾರ್ಜಿಯಾನಂ ಜೈವಿಕ ಸೂಕ್ಷ್ಮಾಣುಗಳನ್ನು ಮಣ್ಣಿಗೆ ಸೇರಿಸುವುದು, 2 ರಿಂದ 3 ಬೇರು ಬಂದ ಬಳ್ಳಿಯ ತುಂಡುಗಳನ್ನು ಒಂದೊಂದಾಗಿ ಗುಂಡಿಯಲ್ಲಿ ನಾಟಿ ಮಾಡುವುದು. ಬುಡದ ಕಡೆಯ ಒಂದು ಗೆಣ್ಣು ಮತ್ತು ಬೇರುಗಳು ಮಣ್ಣಿನಲ್ಲಿರುವಂತೆ ನಾಟಿ ಮಾಡುವುದರಿಂದ ಬಳ್ಳಿಗಳಿಗೆ ಉತ್ತಮ ಆಧಾರ ಸಿಗುವುದು', NULL, 'Keeping in mind the rainfall forecast, add 1 kg. Neem leaves and 50 g. Trichoderma harzianum to the soil for each hole, and plant 2 to 3 rooted vine pieces one by one in the hole. Planting with one node at the base and the roots in the soil will provide good support for the vines.', 'For black rot and wilt disease, it is better to spray the beds with 0.12% Metalaxyl 72 gm or 2% Copper Oxychloride 50 WP or 1% Bordeaux mixture with the onset of rains in May-June', 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (8638, 'BLACK PEPPER', 10, N'<1', N'June-july', N'June-july', N'6,7', N'Planting', N'1', 'BELOW NORMAL', 'YES', 'ನೀರಾವರಿ ಸೌಲಭ್ಯವಿದ್ದಲ್ಲಿ  ಪ್ರತಿ ಗುಂಡಿಗೆ 1 ಕಿ. ಗ್ರಾಂ. ಬೇವಿನ ಹಿಂಡಿ ಮತ್ತು 50 ಗ್ರಾಂ. ಟ್ರೈಕೋಡರ್ಮಾ ಹಾರ್ಜಿಯಾನಂ ಜೈವಿಕ ಸೂಕ್ಷ್ಮಾಣುಗಳನ್ನು ಮಣ್ಣಿಗೆ ಸೇರಿಸುವುದು, 2 ರಿಂದ 3 ಬೇರು ಬಂದ ಬಳ್ಳಿಯ ತುಂಡುಗಳನ್ನು ಒಂದೊಂದಾಗಿ ಗುಂಡಿಯಲ್ಲಿ ನಾಟಿ ಮಾಡುವುದು. ಬುಡದ ಕಡೆಯ ಒಂದು ಗೆಣ್ಣು ಮತ್ತು ಬೇರುಗಳು ಮಣ್ಣಿನಲ್ಲಿರುವಂತೆ ನಾಟಿ ಮಾಡುವುದರಿಂದ ಬಳ್ಳಿಗಳಿಗೆ ಉತ್ತಮ ಆಧಾರ ಸಿಗುವುದು', NULL, 'If irrigation facilities are available, add 1 kg. Neem leaves and 50 g. Trichoderma harzianum to the soil for each hole, and plant 2 to 3 rooted vine pieces one by one in the hole. Planting with one node at the base and the roots in the soil will provide good support for the vines.', NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (8639, 'BLACK PEPPER', 10, N'<1', N'June-july', N'June-july', N'6,7', N'Planting', N'1', 'BELOW NORMAL', 'NO', 'ನೀರಾವರಿ ಸೌಲಭ್ಯವಿದ್ದಲ್ಲಿ  ಪ್ರತಿ ಗುಂಡಿಗೆ 1 ಕಿ. ಗ್ರಾಂ. ಬೇವಿನ ಹಿಂಡಿ ಮತ್ತು 50 ಗ್ರಾಂ. ಟ್ರೈಕೋಡರ್ಮಾ ಹಾರ್ಜಿಯಾನಂ ಜೈವಿಕ ಸೂಕ್ಷ್ಮಾಣುಗಳನ್ನು ಮಣ್ಣಿಗೆ ಸೇರಿಸುವುದು, 2 ರಿಂದ 3 ಬೇರು ಬಂದ ಬಳ್ಳಿಯ ತುಂಡುಗಳನ್ನು ಒಂದೊಂದಾಗಿ ಗುಂಡಿಯಲ್ಲಿ ನಾಟಿ ಮಾಡುವುದು. ಬುಡದ ಕಡೆಯ ಒಂದು ಗೆಣ್ಣು ಮತ್ತು ಬೇರುಗಳು ಮಣ್ಣಿನಲ್ಲಿರುವಂತೆ ನಾಟಿ ಮಾಡುವುದರಿಂದ ಬಳ್ಳಿಗಳಿಗೆ ಉತ್ತಮ ಆಧಾರ ಸಿಗುವುದು', NULL, 'If irrigation facilities are available, add 1 kg. Neem leaves and 50 g. Trichoderma harzianum to the soil for each hole, and plant 2 to 3 rooted vine pieces one by one in the hole. Planting with one node at the base and the roots in the soil will provide good support for the vines.', NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (8640, 'BLACK PEPPER', 10, N'<1', N'June-july', N'June-july', N'6,7', N'Planting', N'1', 'ABOVE NORMAL', 'YES', 'ಹೆಚ್ಚಾಗಿರುವ ನೀರನ್ನು ತೋಟದಿಂದ ಬಸಿದುಹೋಗುವಂತೆ ಮಾಡಿ, ಪ್ರತಿ ಗುಂಡಿಗೆ 1 ಕಿ. ಗ್ರಾಂ. ಬೇವಿನ ಹಿಂಡಿ ಮತ್ತು 50 ಗ್ರಾಂ. ಟ್ರೈಕೋಡರ್ಮಾ ಹಾರ್ಜಿಯಾನಂ ಜೈವಿಕ ಸೂಕ್ಷ್ಮಾಣುಗಳನ್ನು ಮಣ್ಣಿಗೆ ಸೇರಿಸುವುದು, 2 ರಿಂದ 3 ಬೇರು ಬಂದ ಬಳ್ಳಿಯ ತುಂಡುಗಳನ್ನು ಒಂದೊಂದಾಗಿ ಗುಂಡಿಯಲ್ಲಿ ನಾಟಿ ಮಾಡುವುದು. ಬುಡದ ಕಡೆಯ ಒಂದು ಗೆಣ್ಣು ಮತ್ತು ಬೇರುಗಳು ಮಣ್ಣಿನಲ್ಲಿರುವಂತೆ ನಾಟಿ ಮಾಡುವುದರಿಂದ ಬಳ್ಳಿಗಳಿಗೆ ಉತ್ತಮ ಆಧಾರ ಸಿಗುವುದು', NULL, 'Drain excess water from the garden, add 1 kg. Neem leaves and 50 g. Trichoderma harzianum to the soil per hole, and plant 2 to 3 rooted vine pieces one by one in the hole. Planting with one node at the base and the roots in the soil will provide good support for the vines.', NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (8672, 'BLACK PEPPER', 10, N'1-3', N'December-February', N'December-January-February', N'12,1,2', N'Vegetative stage', N'5', 'NORMAL', 'YES', '• ಬಳ್ಳಿಯನ್ನು ಆಧಾರ ಮರಕ್ಕೆ ಹಬ್ಬುವಂತೆ ಮಾಡುವುದು
• ಗಿಡಗಳ ಸುತ್ತಲು ಒಣಗಿದ ಎಲೆಗಳಿಂದ ಮಣ್ಣಿನ ಮೇಲೊದಿಕೆ ಮಾಡುವುರದ ಮೂಲಕ ಮಣ್ಣಿನ ತೇವಾಂಶವನ್ನು ಕಾಪಾಡಿಕೊಳ್ಳಬಹುದು', NULL, '• Allow the vine to grow to the base tree
• Mulch the soil with dry leaves around the plants to help retain soil moisture', NULL, 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
