INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (8682, 'BLACK PEPPER', 10, N'1-3', N'March-May', N'March-April-May', N'3,4,5', N'Vegetative stage', N'2', 'ABOVE NORMAL', 'YES', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', NULL, 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field.', NULL, 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (8683, 'BLACK PEPPER', 10, N'1-3', N'March-May', N'March-April-May', N'3,4,5', N'Vegetative stage', N'2', 'ABOVE NORMAL', 'NO', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', NULL, 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field.', NULL, 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (8684, 'BLACK PEPPER', 10, N'>3', N'May- June', N'May-June', N'5,6', N'Flowering stage', N'3', 'NORMAL', 'YES', '• ತೋಟದಲ್ಲಿ ಉಳುಮೆ ಮಾಡಿ LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ಶೇ. 50 ರ ರಸಗೊಬ್ಬರವನ್ನು ಒದಗಿಸುವುದು
• ಬಳ್ಳಿ ಹೂ ಬಿಡುವ ಸಮಯದಲ್ಲಿ ಅತಿಯಾದ ನೆರಳಿದ್ದಲ್ಲಿ ಕೀಟಗಳ ಬಾಧೆ ಹೆಚ್ಚಾಗಲು ಸಹಕಾರಿಯಾಗುತ್ತದೆ ಆದ್ದರಿಂದ ಆಧಾರದ ಮರಗಳ ಅನಗತ್ಯ ರೆಂಬೆಗಳನ್ನು ಕತ್ತರಿಸಿ ತೆಗೆದು ನೆರಳನ್ನು ನಿಯಂತ್ರಿಸುವುದು', NULL, '• Plough the garden and provide 50% of the recommended fertilizer based on LRI
• Excessive shade during flowering can increase the risk of pests, so control shade by cutting off unnecessary branches from the base trees', 'To prevent slow wilt disease, treat the soil around the stem with 0.2% copper oxychloride 50 WP or 0.1% carbendazim or 0.125% metalaxyl 72 WP or 3 g metalaxyl 8 + mancozeb 64 WP', 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (8732, 'CARDAMOM', 15, N'<1', N'May- June', N'June', N'6', N'Planting', N'1', 'ABOVE NORMAL', 'NO', 'ಹೆಚ್ಚಾಗಿರುವ ನೀರನ್ನು ತೋಟದಿಂದ ಬಸಿದುಹೋಗುವಂತೆ ಮಾಡಿ, ಸಸಿಗಳನ್ನು ಗುಣಿಗಳ ಮಧ್ಯದಲ್ಲಿ ನಾಟಿ ಮಾಡಿ, ಕೋಲಿನಿಂದ ಆಧಾರ ಒದಗಿಸುವುದು. ಕಂದುಗಳನ್ನು ಬಳಸುವುದಾದರೆ 8 ರಿಂದ 10 ಸೆಂ.ಮೀ. ಉದ್ದದ ಕೊಂಬುಗಳನ್ನು ಬಳಸಿ, ಕೊಂಬುಗಳನ್ನು ಶಿಲೀಂಧ್ರನಾಶಕ ದ್ರಾವಣದಲ್ಲಿ (ಶೇ. 0.2 ಕ್ಯಾಪ್ಟಾನ್‌ನಲ್ಲಿ) ಅದ್ದಿ ನಾಟಿ ಮಾಡುವುದು', NULL, 'Drain excess water from the garden, plant the seedlings in the middle of the holes, and support them with stakes. If using saplings, use 8 to 10 cm long branches and dip the branches in a fungicide solution (0.2% Captan) before planting.', NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (8733, 'CARDAMOM', 15, N'<1', N'July-August', N'July-August', N'7,8', N'Establishment stage', N'2', 'NORMAL', 'YES', '• ಗಿಡ ಸ್ಥಾಪಿತವಾಗದೆ ಇರುವ ಜಾಗದಲ್ಲಿ ಬೇರೆ ಸಸಿಯನ್ನು ನೆಡುವುದು
•ನೆರಳು ಮರಗಳಲ್ಲಿ ಹೆಚ್ಚಾಗಿರುವ ಕೊಂಬೆಗಳನ್ನು ತೆಗೆದು ತೋಟದಲ್ಲಿ ಬೆಳಕನ್ನು ಒದಗಿಸುವುದು', NULL, '• Planting another plant in a place where the plant is not established
