INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (8685, 'BLACK PEPPER', 10, N'>3', N'May- June', N'May-June', N'5,6', N'Flowering stage', N'3', 'NORMAL', 'NO', '• ತೋಟದಲ್ಲಿ ಉಳುಮೆ ಮಾಡಿ LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ಶೇ. 50 ರ ರಸಗೊಬ್ಬರವನ್ನು ಒದಗಿಸುವುದು
• ಬಳ್ಳಿ ಹೂ ಬಿಡುವ ಸಮಯದಲ್ಲಿ ಅತಿಯಾದ ನೆರಳಿದ್ದಲ್ಲಿ ಕೀಟಗಳ ಬಾಧೆ ಹೆಚ್ಚಾಗಲು ಸಹಕಾರಿಯಾಗುತ್ತದೆ ಆದ್ದರಿಂದ ಆಧಾರದ ಮರಗಳ ಅನಗತ್ಯ ರೆಂಬೆಗಳನ್ನು ಕತ್ತರಿಸಿ ತೆಗೆದು ನೆರಳನ್ನು ನಿಯಂತ್ರಿಸುವುದು', NULL, '• Plough the garden and provide 50% of the recommended fertilizer based on LRI
• Excessive shade during flowering can increase the risk of pests, so control shade by cutting off unnecessary branches from the base trees', 'To prevent slow wilt disease, treat the soil around the stem with 0.2% copper oxychloride 50 WP or 0.1% carbendazim or 0.125% metalaxyl 72 WP or 3 g metalaxyl 8 + mancozeb 64 WP', 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
