INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (8699, 'BLACK PEPPER', 10, N'>3', N'November-February', N'December-January-February', N'12,1,2', N'Harvesting stage', N'5', 'BELOW NORMAL', 'NO', '• ಕೃಷಿ ಹೊಂಡ, ಇತರ ಮೂಲಗಳಲ್ಲಿ ಲಭ್ಯವಿರುವ ನೀರನ್ನು ಬಳಸಿ ಸಂರಕ್ಷಣಾ ನೀರಾವರಿ ಕೊಡುವುದು
• ಕೊಯ್ಲು ಮಾಡಿ ಮುಂದಿನ ಸಂಸ್ಕರಣೆ ಮಾಡುವುದು', NULL, '• Conservation irrigation using water available from agricultural wells and other sources
