INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (8343, 'PAPAYA', NULL, N'>3', N'May', N'May', N'5', N'Post harvest', N'6', 'NIL', 'NIL', NULL, NULL, '• Uproot all plants after harvesting the fruits
• Destroy diseased plants
• Plough the land deeply to destroy the remains of diseases and pests in the soil
• Green manure crops such as jute, garlic or beans can be grown in the field to increase soil fertility
• It is better to grow other crops (vegetables, pulses, grains) instead of papaya in the next season', NULL, 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (8344, 'COCONUT', 21, N'<1', N'May', N'May', N'5', N'Preparation', N'0', 'NIL', 'NIL', 'ಪೂರ್ವಸಿದ್ದತೆ: ಭೂಮಿಯನ್ನು ಉಳುಮೆ ಮಾಡುವುದು, 7.5 ಮೀ. x 7.5 ಮೀ. ಅಂತರದಲ್ಲಿ 1x1x1 ಮೀಟರ್ ಅಳತೆಯ ಗುಣಿಗಳನ್ನು ತೆಗೆಯುವುದು. ಗುಣಿಗಳನ್ನು ಹಸಿರೆಲೆ, ಕೊಟ್ಟಿಗೆ ಗೊಬ್ಬರ ಮತ್ತು ಮೇಲ್ಮಣ್ಣಿನಿಂದ 0.60 ಘನ ಮೀಟರ್‌ವರೆಗೆ ತುಂಬುವುದು', NULL, 'Preparation: Ploughing the land, digging 1x1x1 meter pits at a distance of 7.5 m. x 7.5 m. Filling the pits with green manure, manure and topsoil up to 0.60 cubic meters', NULL, 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (8345, 'COCONUT', 21, N'<1', N'June-July', N'June-July', N'6,7', N'Planting', N'1', 'NORMAL', 'YES', 'ಗೆದ್ದಲಿನ ಹತೋಟಿಗೆ ಪ್ರತಿ ಗುಣಿಗೆ 10 ಗ್ರಾಂ ನಂತೆ ಫೋರೇಟ್ ಹರಳುಗಳನ್ನು ಹಾಕುವುದು. 45 ಸೆಂ.ಮೀ. ಆಳದಲ್ಲಿ 12-18 ತಿಂಗಳ ಸಸಿಗಳನ್ನು ನಾಟಿ ಮಾಡಿ LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ಗೊಬ್ಬರವನ್ನು ಒದಗಿಸುವುದು. ನಂತರ 2-3 ದಿನಕ್ಕೊಮ್ಮೆ ನೀರಾವರಿ ಒದಗಿಸುವುದು', NULL, 'For termite control, apply 10 grams of phorate granules per plant. Plant 12-18 month old seedlings at a depth of 45 cm and provide fertilizer as recommended based on LRI. Then provide irrigation every 2-3 days.', NULL, 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (8346, 'COCONUT', 21, N'<1', N'June-July', N'June-July', N'6,7', N'Planting', N'1', 'NORMAL', 'NO', 'ಮಳೆಯ ಮುನ್ಸೂಚನೆಯನ್ನು ಗಮನದಲ್ಲಿಟ್ಟುಕೊಂಡು ಗೆದ್ದಲಿನ ಹತೋಟಿಗೆ ಪ್ರತಿ ಗುಣಿಗೆ 10 ಗ್ರಾಂ ನಂತೆ ಫೋರೇಟ್ ಹರಳುಗಳನ್ನು ಹಾಕುವುದು. 45 ಸೆಂ.ಮೀ. ಆಳದಲ್ಲಿ 12-18 ತಿಂಗಳ ಸಸಿಗಳನ್ನು ನಾಟಿ ಮಾಡಿ LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ಗೊಬ್ಬರವನ್ನು ಒದಗಿಸುವುದು. ನಂತರ 2-3 ದಿನಕ್ಕೊಮ್ಮೆ ನೀರಾವರಿ ಒದಗಿಸುವುದು', NULL, 'Keeping in mind the rainfall forecast, apply 10 grams of phorate granules per plant for termite control. Plant 12-18 month old seedlings at a depth of 45 cm and provide recommended fertilizer based on LRI. Then provide irrigation once in 2-3 days.', NULL, 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (8347, 'COCONUT', 21, N'<1', N'June-July', N'June-July', N'6,7', N'Planting', N'1', 'BELOW NORMAL', 'YES', '• ಗೆದ್ದಲಿನ ಹತೋಟಿಗೆ ಪ್ರತಿ ಗುಣಿಗೆ 10 ಗ್ರಾಂ ನಂತೆ ಫೋರೇಟ್ ಹರಳುಗಳನ್ನು ಹಾಕುವುದು  
• ನೀರಾವರಿ ಸೌಲಭ್ಯವಿದ್ದಲ್ಲಿ 45 ಸೆಂ.ಮೀ. ಆಳದಲ್ಲಿ 12-18 ತಿಂಗಳ ಸಸಿಗಳನ್ನು ನಾಟಿ ಮಾಡಿ LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ಗೊಬ್ಬರವನ್ನು ಒದಗಿಸುವುದು', NULL, '• For termite control, apply 10 grams of phorate granules per plant 
• If irrigation facilities are available, plant 12-18 month old seedlings at a depth of 45 cm and provide recommended fertilizer based on LRI', NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (8397, 'COCONUT', 21, N'1-4', N'September-October', N'September-October', N'9,10', N'Vegetative stage', N'4', 'ABOVE NORMAL', 'YES', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', 'ಎಲೆಚುಕ್ಕೆ ಅಥವಾ ಕಣ್ಣು ಕೊಳೆ ರೋಗ ಕಂಡುಬಂದಲ್ಲಿ ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ 2 ಗ್ರಾಂ ಮ್ಯಾಂಕೋಜೆಬ್ 75 WP ಅಥವಾ 3 ಗ್ರಾಂ ತಾಮ್ರದ ಆಕ್ಸಿಕ್ಲೋರೈಡ್ 50 WP ಅನ್ನು ಗರಿಗಳ ಮೇಲೆ ಸಿಂಪಡಿಸುವುದು', 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field.', 'If leaf spot or eye rot is observed, spray 2 grams of Mancozeb 75 WP or 3 grams of Copper Oxychloride 50 WP per liter of water on the feathers', 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (8398, 'COCONUT', 21, N'1-4', N'September-October', N'September-October', N'9,10', N'Vegetative stage', N'4', 'ABOVE NORMAL', 'NO', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', 'ಸುಳಿಕೊರೆಯುವ ರೈನೋಸರಸ್ ದುಂಬಿಯ ಬಾಧೆ ಕಂಡುಬಂದಲ್ಲಿ
• ಎಳೆಯ ವಯಸ್ಸಿನ ಗಿಡಗಳ ಎಲೆಗಳನ್ನು ಒಟ್ಟುಗೂಡಿಸಿ ಕಟ್ಟವುದು ಉತ್ತಮ
• ಸುಳಿಯ ಭಾಗದ ರಂಧ್ರದಲ್ಲಿ ಕಬ್ಬಿಣದ ಕೊಕ್ಕೆಯನ್ನು ತೂರಿಸಿ ದುಂಬಿಗಳನ್ನು ಹೊರ ತೆಗೆದು ಸಾಯಿಸುವುದು 
• ಒಳ 2-3 ಗಿರಿಗಳ ಬುಡದಲ್ಲಿ 250 ಗ್ರಾಂ. ಕಹಿ ಬೇವಿನ ಹಿಂಡಿಯೊಂದಿಗೆ ಅಲ್ಪ ಪ್ರಮಾಣದ ಮರಳನ್ನು ಸೇರಿಸಿ ಹಾಕುವುದು
• ಪ್ರತಿ ಹೆಕ್ಟೇರ್‌ಗೆ 1 ಸಿ.ಪಿ. ಸಿ.ಆರ್.ಐ. ಮಾದರಿ ಮೋಹಕ ಬಲೆಗಳನ್ನು ಇಡುವುದು
• ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ 2 ಮಿ.ಲೀ. ಕ್ಲೋರೋಪೈರಿಫಾಸ್ ಅನ್ನು ಬೆರೆಸಿ 3 ಘನ.ಮೀ.ಕಾಂಪೋಸ್ಟ್ ಗುಂಡಿಗಳಿಗೆ ಉಪಯೋಗಿಸುವುದು', 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field.', 'If you find a problem with Rhinoceroses borer
• It is better to collect and tie the leaves of young plants
• Insert an iron hook into the hole in the borer and kill the borers 
• At the base of the inner 2-3 ridges, add 250 gm. of bitter neem powder along with a small amount of sand
• Place 1 C.P. C.R.I. type trap per hectare
• Mix 2 ml. Chlorpyrifos per liter of water and use it for 3 cubic meters of compost pits', 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (8399, 'COCONUT', 21, N'1-4', N'November-January', N'November-December-January', N'11,12,1', N'Vegetative stage', N'5', 'NORMAL', 'YES', 'ತೋಟದಲ್ಲಿ ಕಳೆ ನಿರ್ವಹಣೆ ಮಾಡಿ ಸ್ವಚ್ಛವಾಗಿಡುವುದು', NULL, 'Weed management and keeping the garden clean', NULL, 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
