INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (8402, 'COCONUT', 21, N'1-4', N'November-January', N'November-December-January', N'11,12,1', N'Vegetative stage', N'5', 'BELOW NORMAL', 'NO', 'ಕೃಷಿ ಹೊಂಡ, ಇತರ ಮೂಲಗಳಲ್ಲಿ ಲಭ್ಯವಿರುವ ನೀರನ್ನು ಬಳಸಿ ಸಂರಕ್ಷಣಾ ನೀರಾವರಿ ಕೊಡುವುದು', 'ಕೆಂಪು ಮೂತಿಯ ದುಂಬಿ ಭಾದೆ ಕಂಡು ಬಂದಲ್ಲಿ ಹುಳುವಿರುವ ಕಡೆ ಒಂದು ರಂಧ್ರವನ್ನು ಮಾಡಿ ಅದಕ್ಕೆ 4 ಮಿ.ಲೀ. ಕ್ಲೋರಾಂಟ್ರನಿಲಿಪ್ರೋಲ್ 18.5 SC ಅಥವಾ 4 ಮಿ.ಲೀ. ಇಂಡಾಕ್ಸಾಕಾರ್ಬ 14.5 SC ಅನ್ನು ಪ್ರತಿ ಲೀಟರ್ ನೀರಿನಲ್ಲಿ ಬೆರೆಸಿ ಸುರಿಯುವುದು', 'Conservation irrigation using water available from agricultural wells and other sources', 'If red-nosed beetle infestation is found, make a hole in the area where the worm is and pour 4 ml. Chlorantraniliprole 18.5 SC or 4 ml. Indoxacarb 14.5 SC mixed in every liter of water', 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (8454, 'ARECANUT', NULL, N'<1', N'June', N'June', N'6', N'Planting', N'1', 'NORMAL', 'YES', '• ಗುಣಿಗಳ ಮಧ್ಯದಲ್ಲಿ ಸಸಿಗಳನ್ನು 30-45 ಸೆಂ.ಮೀ. ಆಳದಲ್ಲಿ ನಾಟಿ ಮಾಡುವುದು
• ಅಡಿಕೆ ಮರಗಳು ಬಿಸಿಲಿನ ತಾಪದಿಂದ ಸುಡುವುದನ್ನು ತಪ್ಪಿಸಲು ಉತ್ತರ ದಕ್ಷಿಣ ರೇಖೆಯನ್ನು 35 ಯಷ್ಟು ಪಶ್ಚಿಮ ದಿಕ್ಕಿನೆಡೆಗೆ ವಾಲುವಂತೆ ಎಳೆದ ರೇಖೆಗಳಲ್ಲಿ ಸಸಿಗಳನ್ನು ನಾಟಿಮಾಡಿದಾಗ ಸಾಲಿನ ಮೊದಲಿನ ಗಿಡಗಳಿಗೆ ಮಾತ್ರ ನೆರಳನ್ನು ಒದಗಿಸಬೇಕಾಗುತ್ತದೆ
• ಹೆಚ್ಚು ಮಳೆಬೀಳುವ ಪ್ರದೇಶಗಳಲ್ಲಿ ಎರಡು ಸಾಲಿಗೊಂದರಂತೆ 2-3 ಅಡಿ ಆಳವಾದ ಬಸಿಗಾಲುವೆಗಳನ್ನು ನಿರ್ಮಿಸುವುದು 
• ಗಿಡಗಳಿಗೆ LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ರಸಗೊಬ್ಬರಗಳನ್ನು ಒದಗಿಸುವುದು', NULL, '• Planting seedlings 30-45 cm deep in the middle of the ridges
• To avoid scorching of the areca trees due to the heat of the sun, when planting seedlings in lines drawn with a north-south line inclined by 35 degrees towards the west, only the first plants in the row need to be shaded
• In areas with high rainfall, 2-3 feet deep drainage ditches should be constructed in two rows 
• Providing recommended fertilizers based on LRI to the plants', NULL, 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (8455, 'ARECANUT', NULL, N'<1', N'June', N'June', N'6', N'Planting', N'1', 'NORMAL', 'NO', '• ಮಳೆಯ ಮುನ್ಸೂಚನೆಯನ್ನು ಗಮನದಲ್ಲಿಟ್ಟುಕೊಂಡು ಗುಣಿಗಳ ಮಧ್ಯದಲ್ಲಿ ಸಸಿಗಳನ್ನು 30-45 ಸೆಂ.ಮೀ. ಆಳದಲ್ಲಿ ನಾಟಿ ಮಾಡುವುದು
• ಅಡಿಕೆ ಮರಗಳು ಬಿಸಿಲಿನ ತಾಪದಿಂದ ಸುಡುವುದನ್ನು ತಪ್ಪಿಸಲು ಉತ್ತರ ದಕ್ಷಿಣ ರೇಖೆಯನ್ನು 35 ಯಷ್ಟು ಪಶ್ಚಿಮ ದಿಕ್ಕಿನೆಡೆಗೆ ವಾಲುವಂತೆ ಎಳೆದ ರೇಖೆಗಳಲ್ಲಿ ಸಸಿಗಳನ್ನು ನಾಟಿಮಾಡಿದಾಗ ಸಾಲಿನ ಮೊದಲಿನ ಗಿಡಗಳಿಗೆ ಮಾತ್ರ ನೆರಳನ್ನು ಒದಗಿಸಬೇಕಾಗುತ್ತದೆ
• ಹೆಚ್ಚು ಮಳೆಬೀಳುವ ಪ್ರದೇಶಗಳಲ್ಲಿ ಎರಡು ಸಾಲಿಗೊಂದರಂತೆ 2-3 ಅಡಿ ಆಳವಾದ ಬಸಿಗಾಲುವೆಗಳನ್ನು ನಿರ್ಮಿಸುವುದು
• ಗಿಡಗಳಿಗೆ LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ರಸಗೊಬ್ಬರಗಳನ್ನು ಒದಗಿಸುವುದು', NULL, '• Planting seedlings 30-45 cm deep in the middle of the rows, keeping in mind the rainfall forecast
• To avoid scorching of the areca trees due to the heat of the sun, when planting seedlings in lines drawn with a north-south line inclined by 35 degrees towards the west, only the first plants in the row need to be shaded
• In areas with high rainfall, 2-3 feet deep drainage ditches should be constructed in two rows
• Providing recommended fertilizers based on LRI to the plants', NULL, 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
