INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (8424, 'COCONUT', 21, N'>4', N'July-August', N'July-August', N'7,8', N'NIL', N'3', 'NORMAL', 'NO', 'ಪ್ರಸ್ತುತ ಹಂತದಲ್ಲಿ ಬೆಳೆ ಉತ್ತಮವಾಗಿದ್ದರೆ, ಇತರೆ ಬೆಳೆ ಬೆಳೆದಿದ್ದಲ್ಲಿ ಅವುಗಳ ನಿರ್ವಹಣೆಯತ್ತ ಗಮನಹರಿಸುವುದು', NULL, 'If the crop is good at the current stage, focus on managing other crops if they have grown.', NULL, 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (8425, 'COCONUT', 21, N'>4', N'July-August', N'July-August', N'7,8', N'NIL', N'3', 'BELOW NORMAL', 'YES', 'ಪ್ರಸ್ತುತ ಹಂತದಲ್ಲಿ ಬೆಳೆ ಉತ್ತಮವಾಗಿದ್ದರೆ, ಇತರೆ ಬೆಳೆ ಬೆಳೆದಿದ್ದಲ್ಲಿ ಅವುಗಳ ನಿರ್ವಹಣೆಯತ್ತ ಗಮನಹರಿಸುವುದು', NULL, 'If the crop is good at the current stage, focus on managing other crops if they have grown.', NULL, 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (8426, 'COCONUT', 21, N'>4', N'July-August', N'July-August', N'7,8', N'NIL', N'3', 'BELOW NORMAL', 'NO', 'ಮಣ್ಣಿನ ತೇವಾಂಶವನ್ನು ಸಂರಕ್ಷಿಸಲು ತೆಂಗಿನ ಚಿಪ್ಪುಗಳು ಅಥವಾ ಗರಿಗಳಿಂದ ಮೇಲೊದಿಕೆ ಮಾಡುವುದು', 'ಗರಿತಿನ್ನುವ ಕಪ್ಪು ತಲೆ ಕಂಬಳಿ ಹುಳು ಕಂಡು ಬಂದಾಗ ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ 0.1 ಮಿ.ಲೀ. ಕ್ಲೋರಾಂಟ್ರನಿಲಿಪ್ರೋಲ್ 18.5 SC ಅಥವಾ 1.5 ಮಿ.ಲೀ. ಅಜಾಡಿರೆಕ್ಟಿನ್ ಅನ್ನು ಸಿಂಪಡಿಸುವುದು
•20 ಗೋನಿಯಾಜಸ್ ಅಥವಾ 30 ಬಕ್ರಾನ್ ಪರತಂತ್ರ ಜೀವಿಗಳನ್ನು ಪ್ರತಿ ಮರಕ್ಕೆ 15 ದಿನಗಳಿಗೊಮ್ಮೆ4 ಬಾರಿ ಬಿಡುವುದು', 'Mulching with coconut shells or feathers to conserve soil moisture', 'When black-headed cotton bollworm is found, spray 0.1 ml. Chlorantraniliprole 18.5 SC or 1.5 ml. Azadirachtin per liter of water
•Release 20 Goniages or 30 Bacran parasites per tree 4 times every 15 days', 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (8427, 'COCONUT', 21, N'>4', N'July-August', N'July-August', N'7,8', N'NIL', N'3', 'ABOVE NORMAL', 'YES', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', 'ಸುಳಿ ಕೊಳೆ ರೋಗ ಕಂಡುಬಂದಲ್ಲಿ ರೋಗಪೀಡಿತ ಸುಳಿಯ ಭಾಗವನ್ನು ಸ್ವಚ್ಛಗೊಳಿಸಿ, ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ 2 ಗ್ರಾಂ ಮೆಟಲಾಕ್ಸಿಲ್+ಮ್ಯಾಂಕೊಜೆಬ್ 72 WP ಅನ್ನು ಬೆರೆಸಿ ಸಿಂಪಡಿಸುವುದು ಅಥವಾ 10 % ಬೋರ್ಡೊ ಪೇಸ್ಟ್ ಅನ್ನು ಲೇಪಿಸಿ, ಮಳೆಯ ನೀರು ಬೀಳದಂತೆ ರಕ್ಷಿಸುವುದು', 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field.', 'If root rot is found, clean the affected part of the root, spray with 2 grams of Metalaxyl + Mancozeb 72 WP per liter of water or apply 10% Bordeaux paste and protect from rain water', 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (8428, 'COCONUT', 21, N'>4', N'July-August', N'July-August', N'7,8', N'NIL', N'3', 'ABOVE NORMAL', 'NO', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', NULL, 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field.', NULL, 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (8475, 'ARECANUT', NULL, N'<1', N'November-December', N'November-December', N'11,12', N'Vegetative stage', N'4', 'BELOW NORMAL', 'NO', 'ಕೃಷಿ ಹೊಂಡ, ಇತರ ಮೂಲಗಳಲ್ಲಿ ಲಭ್ಯವಿರುವ ನೀರನ್ನು ಬಳಸಿ ಸಂರಕ್ಷಣಾ ನೀರಾವರಿ ಕೊಡುವುದು. ಮಣ್ಣಿನ ತೇವಾಂಶವನ್ನು ಸಂರಕ್ಷಿಸಲು ಮಣ್ಣಿನ ಮೇಲೊದಿಕೆ ಮಾಡುವುದು', 'ಸುಳಿ ತಿಗಣೆ ಕಂಡು ಬಂದಲ್ಲಿ ಸುಳಿ ಸುತ್ತಲಿನ ಎಲೆಗಳ ಬುಡದಲ್ಲಿ ಮೂರು ತಿಂಗಳಿಗೊಮ್ಮೆ 2 ಗ್ರಾಂ ಥೈಯಾಮಿಥಾಕ್ಸಮ್ 25 WG ಚಿಕ್ಕಪಾಲಿಥೀನ್ ಚೀಲದಲ್ಲಿ ತೂತುಗಳನ್ನು ಮಾಡಿ ಇಡುವುದರಿಂದ ಸುಳಿ ತಿಗಣೆ ಬಾಧೆಯನ್ನು ನಿಯಂತ್ರಿಸಬಹುದು', 'Conservation irrigation using water available from agricultural wells and other sources. Mulching to conserve soil moisture.', 'If the leafhopper is found, the leafhopper infestation can be controlled by spraying 2 grams of Thiamethoxam 25 WG in small polythene bags at the base of the leaves around the leafhopper every three months', 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
