INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (8390, 'COCONUT', 21, N'1-4', N'July-August', N'July-August', N'7,8', N'Vegetative stage', N'3', 'BELOW NORMAL', 'NO', 'ಕೃಷಿ ಹೊಂಡ, ಇತರ ಮೂಲಗಳಲ್ಲಿ ಲಭ್ಯವಿರುವ ನೀರನ್ನು ಬಳಸಿ ಸಂರಕ್ಷಣಾ ನೀರಾವರಿ ಕೊಡುವುದು. ಮಣ್ಣಿನ ತೇವಾಂಶವನ್ನು ಸಂರಕ್ಷಿಸಲು ತೆಂಗಿನ ಚಿಪ್ಪುಗಳು ಅಥವಾ ಗರಿಗಳಿಂದ ಮೇಲೊದಿಕೆ ಮಾಡುವುದು', 'ಗರಿತಿನ್ನುವ ಕಪ್ಪು ತಲೆ ಕಂಬಳಿ ಹುಳು ಕಂಡು ಬಂದಾಗ ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ 0.1 ಮಿ.ಲೀ. ಕ್ಲೋರಾಂಟ್ರನಿಲಿಪ್ರೋಲ್ 18.5 SC ಅಥವಾ 1.5 ಮಿ.ಲೀ. ಅಜಾಡಿರೆಕ್ಟಿನ್ ಅನ್ನು ಸಿಂಪಡಿಸುವುದು
•20 ಗೋನಿಯಾಜಸ್ ಅಥವಾ 30 ಬಕ್ರಾನ್ ಪರತಂತ್ರ ಜೀವಿಗಳನ್ನು ಪ್ರತಿ ಮರಕ್ಕೆ 15 ದಿನಗಳಿಗೊಮ್ಮೆ4 ಬಾರಿ ಬಿಡುವುದು', 'Conservation irrigation using water available from agricultural wells and other sources. Mulching with coconut shells or feathers to conserve soil moisture.', 'When black-headed cotton bollworm is found, spray 0.1 ml. Chlorantraniliprole 18.5 SC or 1.5 ml. Azadirachtin per liter of water
•Release 20 Goniages or 30 Bacran parasites per tree 4 times every 15 days', 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
