INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (8147, 'SAPOTA', NULL, N'>4', N'July-August', N'July-August', N'7,8', N'Flower bud initiation stage', N'4', 'ABOVE NORMAL', 'YES', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', 'ಮೊಗ್ಗು ಮತ್ತು ಹಣ್ಣು ಕೊರಕ ಹಾಗೂ ಹಿಟ್ಟು ತಿಗಣೆ ಬಾಧೆ ಕಂಡು ಬಂದಾಗ ಗಿಡಗಳಿಗೆ ಲೀ ನೀರಿಗೆ 2 ಗ್ರಾಂ ಬಿ.ಟಿ ಬ್ಯಾಕ್ಟೀರಿಯಾ ಅಥವಾ 1.7 ಮಿಲೀ. ಡೈಮಿಥೊಯೇಟ್ 30 EC ಸೇರಿಸಿ ಸಿಂಪರಣೆ ಮಾಡುವುದು', 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field.', 'When bud and fruit borer and mealybug infestation is observed, spray the plants with 2 g of Bt bacteria or 1.7 ml of dimethoate 30 EC per liter of water', 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
