INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (8203, 'JACKFRUIT', NULL, N'<1', N'February-April', N'February-March-April', N'2,3,4', N'Vegetative stage', N'5', 'ABOVE NORMAL', 'NO', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', NULL, 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field.', NULL, 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (8204, 'JACKFRUIT', NULL, N'1-4', N'June-July', N'June-July', N'6,7', N'Vegetative stage', N'6', 'NORMAL', 'YES', '• ತೋಟದ ಮಧ್ಯೆ ಉಳುಮೆ ಮಾಡಿ ಭೂಮಿಯನ್ನು ಸ್ವಚ್ಛಗೊಳಿಸುವುದು
• ನಂತರ ಗಿಡದ ಸುತ್ತ ಪಾತಿ ಮಾಡಿ LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ರಸಗೊಬ್ಬರಗಳನ್ನು ಕೊಡುವುದು
• ಹಸಿರೆಲೆ ಗೊಬ್ಬರದ ಗಿಡಗಳಾದ ಸೆಣಬು, ಅಲಸಂದಿ ಅಥವಾ ಹುರುಳಿ ಬೆಳೆಯನ್ನು ಬೆಳೆಯುವುದರಿಂದ ಭೂಮಿಯ ಫಲವತ್ತತೆಯನ್ನು ಹೆಚ್ಚಿಸಬಹುದು
• ತೋಟದ ಮಧ್ಯದಲ್ಲಿ ಅಂತರಬೆಳೆಗಳನ್ನಾಗಿ ಬೆಳೆಯಬಹುದು', NULL, '• Ploughing and clearing the land in the middle of the garden
• Then making a bed around the plant and applying fertilizers recommended based on LRI
• Growing green manure crops such as jute, sorghum or buckwheat can increase the fertility of the soil
• Can be grown as intercrops in the middle of the garden', NULL, 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (8180, 'JACKFRUIT', NULL, N'<1', N'August-November', N'August-September-October-November', N'8,9,10,11', N'Vegetative stage', N'2', 'NORMAL', 'YES', '• ಗಿಡ ಸ್ಥಾಪಿತವಾಗದೆ ಇರುವ ಜಾಗದಲ್ಲಿ ಬೇರೆ ಸಸಿಯನ್ನು ನೆಡುವುದು
• ಗಿಡಗಳು ನೇರವಾಗಿ ಬೆಳೆಯಲು ಅವುಗಳಿಗೆ ಕೋಲಿನ ಆಸರೆ ಒದಗಿಸುವುದು
• ತೋಟದಲ್ಲಿ ಹಸಿರೆಲೆ ಗೊಬ್ಬರದ ಗಿಡಗಳನ್ನು ಬೆಳೆದಿದ್ದರೆ ಅವನ್ನು ಬಿತ್ತಿದ 45 ದಿನಗಳ ನಂತರ ಮಣ್ಣಿಗೆ ಸೇರಿಸುವುದು
• ತೋಟದ ಮಧ್ಯೆ ಅಂತರಬೆಳೆ ಬೆಳೆದಿದ್ದರೆ ಅವುಗಳಿಗೆ ತಗುಲುವ ರೋಗ ಮತ್ತು ಕೀಟಗಳ ಮೇಲೆ ಗಮನ ಹರಿಸುವುದು', 'ಕಾಂಡ ಕೊರಕ ಕೀಟ ಕಂಡುಬಂದಲ್ಲಿ ಕಾಂಡದಲ್ಲಿ ಕೊರೆದ ಪ್ರತಿ ರಂಧ್ರಗಳಿಗೆ ಪ್ರತಿ ಲೀಟರ್ ನೀರಿಗೆ 2 ಮಿ.ಲೀ. ಕ್ಲೋರಾಂಟ್ರನಿಲಿಪ್ರೋಲ್ 18.5 SC ಅನ್ನು ಬೆರೆಸಿ, 10 ಮಿ.ಲೀ. ದ್ರಾವಣವನ್ನು ಸಿರಿಂಜ್ ಮೂಲಕ ರಂಧ್ರಗಳಲ್ಲಿ ಹಾಕಿ, ನಂತರ 10% ಬೋರ್ಡೋ ಪೇಸ್ಟ್ ನಿಂದ ರಂಧ್ರಗಳನ್ನು ಮುಚ್ಚುವುದು ಉತ್ತಮ', '• Planting another plant in the area where the plant is not established
• Providing support for the plants with sticks so that they can grow upright
• If green manure plants are grown in the garden, incorporate them into the soil 45 days after sowing
• If intercrops are grown in the garden, pay attention to the diseases and pests that they are susceptible to', 'If stem borer is found, mix 2 ml of chlorantraniliprole 18.5 SC per liter of water for each hole drilled in the stem, and inject 10 ml of the solution into the holes through a syringe, then it is better to seal the holes with 10% Bordeaux paste', 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (8181, 'JACKFRUIT', NULL, N'<1', N'August-November', N'August-September-October-November', N'8,9,10,11', N'Vegetative stage', N'2', 'NORMAL', 'NO', '• ಗಿಡ ಸ್ಥಾಪಿತವಾಗದೆ ಇರುವ ಜಾಗದಲ್ಲಿ ಬೇರೆ ಸಸಿಯನ್ನು ನೆಡುವುದು
• ಗಿಡಗಳು ನೇರವಾಗಿ ಬೆಳೆಯಲು ಅವುಗಳಿಗೆ ಕೋಲಿನ ಆಸರೆ ಒದಗಿಸುವುದು
• ತೋಟದಲ್ಲಿ ಹಸಿರೆಲೆ ಗೊಬ್ಬರದ ಗಿಡಗಳನ್ನು ಬೆಳೆದಿದ್ದರೆ ಅವನ್ನು ಬಿತ್ತಿದ 45 ದಿನಗಳ ನಂತರ ಮಣ್ಣಿಗೆ ಸೇರಿಸುವುದು
• ತೋಟದ ಮಧ್ಯೆ ಅಂತರಬೆಳೆ ಬೆಳೆದಿದ್ದರೆ ಅವುಗಳಿಗೆ ತಗುಲುವ ರೋಗ ಮತ್ತು ಕೀಟಗಳ ಮೇಲೆ ಗಮನ ಹರಿಸುವುದು', 'ಕಾಂಡ ಕೊರಕ ಕೀಟ ಕಂಡುಬಂದಲ್ಲಿ ಕಾಂಡದಲ್ಲಿ ಕೊರೆದ ಪ್ರತಿ ರಂಧ್ರಗಳಿಗೆ ಪ್ರತಿ ಲೀಟರ್ ನೀರಿಗೆ 2 ಮಿ.ಲೀ. ಕ್ಲೋರಾಂಟ್ರನಿಲಿಪ್ರೋಲ್ 18.5 SC ಅನ್ನು ಬೆರೆಸಿ, 10 ಮಿ.ಲೀ. ದ್ರಾವಣವನ್ನು ಸಿರಿಂಜ್ ಮೂಲಕ ರಂಧ್ರಗಳಲ್ಲಿ ಹಾಕಿ, ನಂತರ 10% ಬೋರ್ಡೋ ಪೇಸ್ಟ್ ನಿಂದ ರಂಧ್ರಗಳನ್ನು ಮುಚ್ಚುವುದು ಉತ್ತಮ', '• Planting another plant in the area where the plant is not established
• Providing support for the plants with sticks so that they can grow upright
• If green manure plants are grown in the garden, incorporate them into the soil 45 days after sowing
• If intercrops are grown in the garden, pay attention to the diseases and pests that they are susceptible to', 'If stem borer is found, mix 2 ml of chlorantraniliprole 18.5 SC per liter of water for each hole drilled in the stem, and inject 10 ml of the solution into the holes through a syringe, then it is better to seal the holes with 10% Bordeaux paste', 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
