INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (8337, 'PAPAYA', NULL, N'1-3', N'March-April', N'March-April', N'3,4', N'Fruit maturity', N'5', 'NORMAL', 'YES', NULL, NULL, 'Harvesting ripe fruits', NULL, 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (8228, 'JACKFRUIT', NULL, N'1-4', N'February-May', N'February-March-April-May', N'2,3,4,5', N'Vegetative stage', N'5', 'NORMAL', 'YES', 'ಗಿಡದ ಸುತ್ತಲು ಒಣಗಿದ ಎಲೆಗಳಿಂದ ಮಣ್ಣಿನ ಮೇಲೊದಿಕೆ ಮಾಡುವುದರಿಂದ ಮಣ್ಣಿನ ತೇವಾಂಶವನ್ನು ಕಾಪಾಡಿಕೊಳ್ಳಬಹುದು', 'ಹಣ್ಣು ಕೊಳೆಯುವ ರೋಗಕ್ಕೆ ಶೇ. 1ರ ಬೋರ್ಡೋ ದ್ರಾವಣ ಅಥವಾ ಪ್ರತಿ ಲೀಟರ್ ನೀರಿಗೆ 3.0 ಗ್ರಾಂ ತಾಮ್ರದ ಅಕ್ಸಿಕ್ಲೋರೈಡ್ 50 WP ಅಥವಾ 1.0 ಗ್ರಾಂ ಕಾರ್ಬೆಡಜಿಂ 50 WP ಸೇರಿಸಿ ಸಿಂಪಡಿಸುವುದು', 'Mulching the soil with dry leaves around the plant can help maintain soil moisture.', 'For fruit rot, spray with 1% Bordeaux mixture or 3.0 gm copper oxychloride 50 WP or 1.0 gm carbedazim 50 WP per liter of water', 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (8229, 'JACKFRUIT', NULL, N'1-4', N'February-May', N'February-March-April-May', N'2,3,4,5', N'Vegetative stage', N'5', 'NORMAL', 'NO', 'ಗಿಡದ ಸುತ್ತಲು ಒಣಗಿದ ಎಲೆಗಳಿಂದ ಮಣ್ಣಿನ ಮೇಲೊದಿಕೆ ಮಾಡುವುದರಿಂದ ಮಣ್ಣಿನ ತೇವಾಂಶವನ್ನು ಕಾಪಾಡಿಕೊಳ್ಳಬಹುದು', 'ಹಣ್ಣು ಕೊಳೆಯುವ ರೋಗಕ್ಕೆ ಶೇ. 1ರ ಬೋರ್ಡೋ ದ್ರಾವಣ ಅಥವಾ ಪ್ರತಿ ಲೀಟರ್ ನೀರಿಗೆ 3.0 ಗ್ರಾಂ ತಾಮ್ರದ ಅಕ್ಸಿಕ್ಲೋರೈಡ್ 50 WP ಅಥವಾ 1.0 ಗ್ರಾಂ ಕಾರ್ಬೆಡಜಿಂ 50 WP ಸೇರಿಸಿ ಸಿಂಪಡಿಸುವುದು', 'Mulching the soil with dry leaves around the plant can help maintain soil moisture.', 'For fruit rot, spray with 1% Bordeaux mixture or 3.0 gm copper oxychloride 50 WP or 1.0 gm carbedazim 50 WP per liter of water', 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
