INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (8231, 'JACKFRUIT', NULL, N'1-4', N'February-May', N'February-March-April-May', N'2,3,4,5', N'Vegetative stage', N'5', 'BELOW NORMAL', 'NO', '• ಕೃಷಿ ಹೊಂಡ, ಇತರ ಮೂಲಗಳಲ್ಲಿ ಲಭ್ಯವಿರುವ ನೀರನ್ನು ಬಳಸಿ ನೀರಾವರಿ ಕೊಡುವುದು 
• ಗಿಡದ ಸುತ್ತಲು ಒಣಗಿದ ಎಲೆಗಳಿಂದ ಮಣ್ಣಿನ ಮೇಲೊದಿಕೆ ಮಾಡಿ ತೇವಾಂಶವನ್ನು ಕಾಪಾಡಿಕೊಳ್ಳುವುದು', NULL, '• Irrigation using water available from agricultural wells and other sources 
• Mulching the soil with dry leaves around the plant to maintain moisture', NULL, 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (8232, 'JACKFRUIT', NULL, N'1-4', N'February-May', N'February-March-April-May', N'2,3,4,5', N'Vegetative stage', N'5', 'ABOVE NORMAL', 'YES', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', NULL, 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field.', NULL, 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (8233, 'JACKFRUIT', NULL, N'1-4', N'February-May', N'February-March-April-May', N'2,3,4,5', N'Vegetative stage', N'5', 'ABOVE NORMAL', 'NO', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', NULL, 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field.', NULL, 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (8234, 'JACKFRUIT', NULL, N'>4', N'June-July', N'June-July', N'6,7', N'Fruit maturity', N'6', 'NORMAL', 'YES', '• ತೋಟದ ಮಧ್ಯೆ ಉಳುಮೆ ಮಾಡಿ ಭೂಮಿಯನ್ನು ಸ್ವಚ್ಛಗೊಳಿಸುವುದು
• ನಂತರ ಗಿಡದ ಸುತ್ತ ಪಾತಿ ಮಾಡಿ LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ರಸಗೊಬ್ಬರಗಳನ್ನು ಕೊಡುವುದು
• ಹಸಿರೆಲೆ ಗೊಬ್ಬರದ ಗಿಡಗಳಾದ ಸೆಣಬು, ಅಲಸಂದಿ ಅಥವಾ ಹುರುಳಿ ಬೆಳೆಯನ್ನು ಬೆಳೆಯುವುದರಿಂದ ಭೂಮಿಯ ಫಲವತ್ತತೆಯನ್ನು ಹೆಚ್ಚಿಸಬಹುದು
• ತೋಟದ ಮಧ್ಯದಲ್ಲಿ ಅಂತರಬೆಳೆಗಳನ್ನಾಗಿ ಬೆಳೆಯಬಹುದು', NULL, '• Ploughing and clearing the land in the middle of the garden
• Then making a bed around the plant and applying fertilizers recommended based on LRI
• Growing green manure crops such as jute, sorghum or buckwheat can increase the fertility of the soil
• Can be grown as intercrops in the middle of the garden', NULL, 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7917, 'POMEGRANATE', NULL, N'1-2', N'July-August', N'July-August', N'7,8', N'Vegetative stage', N'2', 'ABOVE NORMAL', 'YES', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', 'ಹಣ್ಣು ಕೊರಕ ನಿಯಂತ್ರಣಕ್ಕಾಗಿ ಹೂವು ಬಿಡುವ ಸಮಯದಿಂದ ಹಣ್ಣು ಕೊಯ್ಲು ಮಾಡುವವರೆಗೆ ಪ್ರತಿ ಮೂರು ವಾರಕ್ಕೊಮ್ಮೆ 0.15 ಮಿ.ಲೀ. ಸೈಯಾಂಟ್ರನಿಲಿಪ್ರೋಲ್‍ 10.26OD ಅಥವಾ 0.5 ಮಿ.ಲೀ. ಸ್ಪೈಯನೋಸಾಡ್ 45 SC ಅಥವಾ 0.5 ಮಿ.ಲೀ. ಸೈಪರ್‌ಮೆಥ್ರಿನ್ 25 EC ಅನ್ನು ಪ್ರತಿ ಲೀಟರ್ ನೀರಿಗೆ ಬೆರೆಸಿ ಸಿಂಪಡಿಸುವುದು', 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field.', 'For fruit borer control, spray 0.15 ml. Cyantraniliprole 10.26OD or 0.5 ml. Spyanosad 45 SC or 0.5 ml. Cypermethrin 25 EC per liter of water every three weeks from the time of flowering to fruit harvest', 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7918, 'POMEGRANATE', NULL, N'1-2', N'July-August', N'July-August', N'7,8', N'Vegetative stage', N'2', 'ABOVE NORMAL', 'NO', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', NULL, 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field.', NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7919, 'POMEGRANATE', NULL, N'1-2', N'September-October', N'September-October', N'9,10', N'Vegetative stage', N'2', 'NORMAL', 'YES', 'ಗಿಡಗಳಿಗೆ ಆಕಾರ ಒದಗಿಸಲು ಅನಗತ್ಯ ರೆಂಬೆಗಳನ್ನು ಕತ್ತರಿಸುವುದು (ಹೆಚ್ಚಿನ ಮಾಹಿತಿಗಾಗಿ ತಂತ್ರಾಂಶದಲ್ಲಿರುವ ದಾಳಿಂಬೆ ಬೆಳೆ ಪದ್ಧತಿಯಲ್ಲಿ ವೀಕ್ಷಿಸಬಹುದು)', NULL, 'Pruning unwanted branches to shape plants (for more information, see the pomegranate cropping system in the software)', NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7920, 'POMEGRANATE', NULL, N'1-2', N'September-October', N'September-October', N'9,10', N'Vegetative stage', N'2', 'NORMAL', 'NO', 'ಗಿಡಗಳಿಗೆ ಆಕಾರ ಒದಗಿಸಲು ಅನಗತ್ಯ ರೆಂಬೆಗಳನ್ನು ಕತ್ತರಿಸುವುದು (ಹೆಚ್ಚಿನ ಮಾಹಿತಿಗಾಗಿ ತಂತ್ರಾಂಶದಲ್ಲಿರುವ ದಾಳಿಂಬೆ ಬೆಳೆ ಪದ್ಧತಿಯಲ್ಲಿ ವೀಕ್ಷಿಸಬಹುದು)', NULL, 'Pruning unwanted branches to shape plants (for more information, see the pomegranate cropping system in the software)', NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7921, 'POMEGRANATE', NULL, N'1-2', N'September-October', N'September-October', N'9,10', N'Vegetative stage', N'2', 'BELOW NORMAL', 'YES', 'ಗಿಡಗಳಿಗೆ ಆಕಾರ ಒದಗಿಸಲು ಅನಗತ್ಯ ರೆಂಬೆಗಳನ್ನು ಕತ್ತರಿಸುವುದು (ಹೆಚ್ಚಿನ ಮಾಹಿತಿಗಾಗಿ ತಂತ್ರಾಂಶದಲ್ಲಿರುವ ದಾಳಿಂಬೆ ಬೆಳೆ ಪದ್ಧತಿಯಲ್ಲಿ ವೀಕ್ಷಿಸಬಹುದು)', NULL, 'Pruning unwanted branches to shape plants (for more information, see the pomegranate cropping system in the software)', NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7922, 'POMEGRANATE', NULL, N'1-2', N'September-October', N'September-October', N'9,10', N'Vegetative stage', N'2', 'BELOW NORMAL', 'NO', '• ಕೃಷಿ ಹೊಂಡ, ಇತರ ಮೂಲಗಳಲ್ಲಿ ಲಭ್ಯವಿರುವ ನೀರನ್ನು ಬಳಸಿ ನೀರಾವರಿ ಕೊಡುವುದು
• ಗಿಡಗಳಿಗೆ ಆಕಾರ ಒದಗಿಸಲು ಅನಗತ್ಯ ರೆಂಬೆಗಳನ್ನು ಕತ್ತರಿಸುವುದು (ಹೆಚ್ಚಿನ ಮಾಹಿತಿಗಾಗಿ ತಂತ್ರಾಂಶದಲ್ಲಿರುವ ದಾಳಿಂಬೆ ಬೆಳೆ ಪದ್ಧತಿಯಲ್ಲಿ ವೀಕ್ಷಿಸಬಹುದು)', NULL, '• Irrigation using water available from agricultural wells and other sources
• Pruning of unwanted branches to give shape to the plants (for more information, see the pomegranate cropping system in the software)', NULL, 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7923, 'POMEGRANATE', NULL, N'1-2', N'September-October', N'September-October', N'9,10', N'Vegetative stage', N'2', 'ABOVE NORMAL', 'YES', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', 'ಸಸ್ಯ ಹೇನು, ಹಿಟ್ಟುತಿಗಣೆ, ಬಿಳಿನೊಣ, ಥ್ರಿಪ್ಸ್ ನುಸಿ ನಿಯಂತ್ರಣಕ್ಕಾಗಿ ಪ್ರತಿ ಲೀಟರ್ ನೀರಿಗೆ 0.2 ಗ್ರಾಂ ಥೈಯೋಮಿಥಾಕ್ಸಾಮ್ 25 WG ಅಥವಾ 0.25 ಮಿ.ಲೀ. ಇಮಿಡಾಕ್ಲೋಪ್ರಿಡ್ 200 SL ಅನ್ನು ಬೆರೆಸಿ ಸಿಂಪಡಿಸುವುದು', 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field.', 'Spraying with 0.2 g Thiomethoxam 25 WG or 0.25 ml Imidacloprid 200 SL per liter of water for the control of aphids, mealybugs, whiteflies, and thrips', 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7984, 'GUAVA', NULL, N'<1', N'June-July', N'June-July', N'6,7', N'Planting', N'1', 'ABOVE NORMAL', 'YES', '• ಹೆಚ್ಚಾಗಿರುವ ನೀರನ್ನು ತೋಟದಿಂದ ಬಸಿದುಹೋಗುವಂತೆ ಮಾಡಿ ನಾಟಿ ಮಾಡುವುದು, ಕಸಿ ಸಸಿಗಳನ್ನು ನಾಟಿ ಮಾಡುವಾಗ ಕಸಿ ಮಾಡಿದ ಭಾಗ ಭೂಮಿಯ ಮೇಲಿರುವಂತೆ ಜಾಗ್ರತೆ ವಹಿಸಿ, ಗಿಡಗಳಿಗೆ ಕೋಲಿನ ಆಸರೆ ಕೊಡುವುದು. 
• ನಾಟಿ ಮಾಡಿದ ನಂತರ ಗಿಡದ ಸುತ್ತಲು ಪಾತಿ ಮಾಡಿ LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ಗೊಬ್ಬರವನ್ನು ಕೊಡುವುದು
• ನಾಟಿಯ ನಂತರ ತೋಟದಲ್ಲಿ ಹಸಿರೆಲೆ ಗೊಬ್ಬರದ ಗಿಡಗಳಾದ ಸೆಣಬು, ಅಲಸಂದಿ ಅಥವಾ ಹುರುಳಿ ಬೆಳೆಯನ್ನು ಬೆಳೆಯುವುದರಿಂದ ಭೂಮಿಯ ಫಲವತ್ತತೆಯನ್ನು ಹೆಚ್ಚಿಸಬಹುದು
• ಅಥವಾ ತೋಟದ ಮಧ್ಯ ಅಂತರ ಬೆಳೆಗಳನ್ನು ಬೆಳೆಯಬಹುದು', NULL, '• Drain excess water from the garden and plant, while planting the grafted seedlings, ensure that the grafted part is above the ground, and support the plants with a stake. 
• After planting, make a bed around the plant and apply fertilizer recommended based on LRI
• After planting, grow green manure crops such as jute, sorghum or buckwheat in the garden to increase soil fertility
• Or grow intercropping crops in the garden', NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7985, 'GUAVA', NULL, N'<1', N'June-July', N'June-July', N'6,7', N'Planting', N'1', 'ABOVE NORMAL', 'NO', '• ಹೆಚ್ಚಾಗಿರುವ ನೀರನ್ನು ತೋಟದಿಂದ ಬಸಿದುಹೋಗುವಂತೆ ಮಾಡಿ ನಾಟಿ ಮಾಡುವುದು, ಕಸಿ ಸಸಿಗಳನ್ನು ನಾಟಿ ಮಾಡುವಾಗ ಕಸಿ ಮಾಡಿದ ಭಾಗ ಭೂಮಿಯ ಮೇಲಿರುವಂತೆ ಜಾಗ್ರತೆ ವಹಿಸಿ, ಗಿಡಗಳಿಗೆ ಕೋಲಿನ ಆಸರೆ ಕೊಡುವುದು. 
• ನಾಟಿ ಮಾಡಿದ ನಂತರ ಗಿಡದ ಸುತ್ತಲು ಪಾತಿ ಮಾಡಿ LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ಗೊಬ್ಬರವನ್ನು ಕೊಡುವುದು
• ನಾಟಿಯ ನಂತರ ತೋಟದಲ್ಲಿ ಹಸಿರೆಲೆ ಗೊಬ್ಬರದ ಗಿಡಗಳಾದ ಸೆಣಬು, ಅಲಸಂದಿ ಅಥವಾ ಹುರುಳಿ ಬೆಳೆಯನ್ನು ಬೆಳೆಯುವುದರಿಂದ ಭೂಮಿಯ ಫಲವತ್ತತೆಯನ್ನು ಹೆಚ್ಚಿಸಬಹುದು
• ಅಥವಾ ತೋಟದ ಮಧ್ಯ ಅಂತರ ಬೆಳೆಗಳನ್ನು ಬೆಳೆಯಬಹುದು', NULL, '• Drain excess water from the garden and plant, while planting the grafted seedlings, ensure that the grafted part is above the ground, and support the plants with a stake. 
• After planting, make a bed around the plant and apply fertilizer recommended based on LRI
• After planting, grow green manure crops such as jute, sorghum or buckwheat in the garden to increase soil fertility
• Or grow intercropping crops in the garden', NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (8017, 'GUAVA', NULL, N'1-4', N'January-February', N'January-February', N'1,2', N'Vegetative stage', N'3', 'NORMAL', 'NO', 'ಗಿಡದ ಸುತ್ತಲು ಒಣಗಿದ ಎಲೆಗಳಿಂದ ಮಣ್ಣಿನ ಮೇಲೊದಿಕೆ ಮಾಡುವುದರಿಂದ ಮಣ್ಣಿನ ತೇವಾಂಶವನ್ನು ಕಾಪಾಡಿಕೊಳ್ಳಬಹುದು', 'ಕಜ್ಜಿ ತಿಗಣೆ ಕಂಡುಬಂದಲ್ಲಿ ಲೀ. ನೀರಿಗೆ ಪ್ರತಿ ಲೀಟರ್ ನೀರಿಗೆ 0.3 ಮಿಲಿ ಇಮಿಡಾಕ್ಲೋಪ್ರಿಡ್ 17.8% SL ಅಥವಾ 0.3 ಗ್ರಾಂ ಥಿಯಾಮೆಥಾಕ್ಸಮ್ 25% WG ಅಥವಾ 0.5 ಮಿಲಿ ಲ್ಯಾಂಬ್ಡಾ-ಸೈಹಲೋಥ್ರಿನ್ 5% EC ಸೇರಿಸಿ ಸಿಂಪಡಿಸುವುದು', 'Mulching the soil with dry leaves around the plant can help maintain soil moisture.', 'If scabies is found, spray 0.3 ml of Imidacloprid 17.8% SL or 0.3 g of Thiamethoxam 25% WG or 0.5 ml of Lambda-cyhalothrin 5% EC per liter of water', 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (8018, 'GUAVA', NULL, N'1-4', N'January-February', N'January-February', N'1,2', N'Vegetative stage', N'3', 'BELOW NORMAL', 'YES', 'ಗಿಡದ ಸುತ್ತಲು ಒಣಗಿದ ಎಲೆಗಳಿಂದ ಮಣ್ಣಿನ ಮೇಲೊದಿಕೆ ಮಾಡುವುದರಿಂದ ಮಣ್ಣಿನ ತೇವಾಂಶವನ್ನು ಕಾಪಾಡಿಕೊಳ್ಳಬಹುದು', NULL, 'Mulching the soil with dry leaves around the plant can help maintain soil moisture.', NULL, 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (8019, 'GUAVA', NULL, N'1-4', N'January-February', N'January-February', N'1,2', N'Vegetative stage', N'3', 'BELOW NORMAL', 'NO', '• ಗಿಡದ ಸುತ್ತಲು ಒಣಗಿದ ಎಲೆಗಳಿಂದ ಮಣ್ಣಿನ ಮೇಲೊದಿಕೆ ಮಾಡುವುದರಿಂದ ಮಣ್ಣಿನ ತೇವಾಂಶವನ್ನು ಕಾಪಾಡಿಕೊಳ್ಳಬಹುದು
• ಕೃಷಿ ಹೊಂಡ, ಇತರ ಮೂಲಗಳಲ್ಲಿ ಲಭ್ಯವಿರುವ ನೀರನ್ನು ಬಳಸಿ ನೀರಾವರಿ ಕೊಡುವುದು', NULL, '• Mulching the soil with dry leaves around the plant can help maintain soil moisture. • Irrigation using water available from agricultural wells and other sources', NULL, 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (8020, 'GUAVA', NULL, N'1-4', N'January-February', N'January-February', N'1,2', N'Vegetative stage', N'3', 'ABOVE NORMAL', 'YES', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', 'ಹಿಟ್ಟು ತಿಗಣೆ ಹಾಗೂ ಶಲ್ಕಕೀಟ ಕಂಡು ಬಂದಲ್ಲಿ ಲೀ. ನೀರಿಗೆ 1.25 ಮಿಲೀ. ಬುಪ್ರೊಫೆಜಿನ್ 25% SC ಅಥವಾ 2 ಮಿಲೀ. ಪ್ರೊಫೆನೊಫಾಸ್ 50 EC+ 5 ಗ್ರಾಂ ಮೀನಿನ ಎಣ್ಣೆ ರೋಸಿನ್ ಸೋಪ್ ಅಥವಾ 5% ಬೇವಿನ ಬೀಜ ಕಷಾಯವನ್ನು ಬೆರೆಸಿ ಸಿಂಪರಿಸುವುದು ಸಿಂಪಡಿಸುವುದು', 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field.', 'If mealybugs and scale insects are found, spray 1.25 ml. Buprofezin 25% SC or 2 ml. Profenophos 50 EC + 5 gm fish oil mixed with rosin soap or 5% neem seed decoction per liter of water', 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
