INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7947, 'POMEGRANATE', NULL, N'>2', N'May-June', N'May-June', N'5,6', N'Resting/ Bahar treatment', N'3', 'ABOVE NORMAL', 'YES', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', NULL, 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field.', NULL, 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7948, 'POMEGRANATE', NULL, N'>2', N'May-June', N'May-June', N'5,6', N'Resting/ Bahar treatment', N'3', 'ABOVE NORMAL', 'NO', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', NULL, 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field.', NULL, 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7990, 'GUAVA', NULL, N'<1', N'August-December', N'August-December', N'8,9,10,11,12', N'Vegetative stage', N'2', 'ABOVE NORMAL', 'YES', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', 'ಬಿಳಿ ನೊಣಗಳು ಹತೋಟಿಗೆ ಪ್ರತಿ ಎಕರೆಗೆ 10 ಹಳದಿ ಜಿಗುಟಾದ ಬಲೆಗಳನ್ನು ಸ್ಥಾಪಿಸುವುದು ಹಾಗೂ ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ 0.3 ಮಿ.ಲೀ. ಇಮಿಡಾಕ್ಲೋಪ್ರಿಡ್ 17.8% SL ಅಥವಾ 0.3 ಗ್ರಾಂ ಥಿಯಾಮೆಥಾಕ್ಸಮ್ 25% WG ಅಥವಾ 0.2 ಗ್ರಾಂ ಅಸೆಟಾಮಿಪ್ರಿಡ್ 20% SP ಅಥವಾ 5 ಮಿ.ಲೀ. ಬೇವಿನ ಎಣ್ಣೆಯನ್ನು ಬೆರೆಸಿ ಸಿಂಪಡಿಸುವುದು ಉತ್ತಮ', 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field.', 'For whitefly control, it is best to set up 10 yellow sticky traps per acre and spray with 0.3 ml of Imidacloprid 17.8% SL or 0.3 g of Thiamethoxam 25% WG or 0.2 g of Acetamiprid 20% SP or 5 ml of Neem oil mixed in each liter of water', 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7991, 'GUAVA', NULL, N'<1', N'August-December', N'August-December', N'8,9,10,11,12', N'Vegetative stage', N'2', 'ABOVE NORMAL', 'NO', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', NULL, 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field.', NULL, 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7992, 'GUAVA', NULL, N'<1', N'January-February', N'January-February', N'1,2', N'Vegetative stage', N'3', 'NORMAL', 'YES', 'ಗಿಡದ ಸುತ್ತಲು ಒಣಗಿದ ಎಲೆಗಳಿಂದ ಮಣ್ಣಿನ ಮೇಲೊದಿಕೆ ಮಾಡುವುದರಿಂದ ಮಣ್ಣಿನ ತೇವಾಂಶವನ್ನು ಕಾಪಾಡಿಕೊಳ್ಳಬಹುದು', 'ಹಿಟ್ಟು ತಿಗಣೆ ಹಾಗೂ ಶಲ್ಕಕೀಟ ಕಂಡು ಬಂದಲ್ಲಿ ಲೀ. ನೀರಿಗೆ 1.25 ಮಿಲೀ. ಬುಪ್ರೊಫೆಜಿನ್ 25% SC ಅಥವಾ 2 ಮಿಲೀ. ಪ್ರೊಫೆನೊಫಾಸ್ 50 EC + 5 ಗ್ರಾಂ ಮೀನಿನ ಎಣ್ಣೆ ರೋಸಿನ್ ಸೋಪ್ ಅಥವಾ 5% ಬೇವಿನ ಬೀಜ ಕಷಾಯವನ್ನು ಬೆರೆಸಿ ಸಿಂಪರಿಸುವುದು ಸಿಂಪಡಿಸುವುದು', 'Mulching the soil with dry leaves around the plant can help maintain soil moisture.', 'If mealybugs and scale insects are found, spray 1.25 ml. Buprofezin 25% SC or 2 ml. Profenophos 50 EC + 5 gm fish oil mixed with rosin soap or 5% neem seed decoction per liter of water', 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7993, 'GUAVA', NULL, N'<1', N'January-February', N'January-February', N'1,2', N'Vegetative stage', N'3', 'NORMAL', 'NO', 'ಗಿಡದ ಸುತ್ತಲು ಒಣಗಿದ ಎಲೆಗಳಿಂದ ಮಣ್ಣಿನ ಮೇಲೊದಿಕೆ ಮಾಡುವುದರಿಂದ ಮಣ್ಣಿನ ತೇವಾಂಶವನ್ನು ಕಾಪಾಡಿಕೊಳ್ಳಬಹುದು', 'ಹಿಟ್ಟು ತಿಗಣೆ ಹಾಗೂ ಶಲ್ಕಕೀಟ ಕಂಡು ಬಂದಲ್ಲಿ ಲೀ. ನೀರಿಗೆ 1.25 ಮಿಲೀ. ಬುಪ್ರೊಫೆಜಿನ್ 25% SC ಅಥವಾ 2 ಮಿಲೀ. ಪ್ರೊಫೆನೊಫಾಸ್ 50 EC + 5 ಗ್ರಾಂ ಮೀನಿನ ಎಣ್ಣೆ ರೋಸಿನ್ ಸೋಪ್ ಅಥವಾ 5% ಬೇವಿನ ಬೀಜ ಕಷಾಯವನ್ನು ಬೆರೆಸಿ ಸಿಂಪರಿಸುವುದು ಸಿಂಪಡಿಸುವುದು', 'Mulching the soil with dry leaves around the plant can help maintain soil moisture.', 'If mealybugs and scale insects are found, spray 1.25 ml. Buprofezin 25% SC or 2 ml. Profenophos 50 EC + 5 gm fish oil mixed with rosin soap or 5% neem seed decoction per liter of water', 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7994, 'GUAVA', NULL, N'<1', N'January-February', N'January-February', N'1,2', N'Vegetative stage', N'3', 'BELOW NORMAL', 'YES', 'ಗಿಡದ ಸುತ್ತಲು ಒಣಗಿದ ಎಲೆಗಳಿಂದ ಮಣ್ಣಿನ ಮೇಲೊದಿಕೆ ಮಾಡುವುದರಿಂದ ಮಣ್ಣಿನ ತೇವಾಂಶವನ್ನು ಕಾಪಾಡಿಕೊಳ್ಳಬಹುದು', NULL, 'Mulching the soil with dry leaves around the plant can help maintain soil moisture.', NULL, 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7995, 'GUAVA', NULL, N'<1', N'January-February', N'January-February', N'1,2', N'Vegetative stage', N'3', 'BELOW NORMAL', 'NO', 'ಕೃಷಿ ಹೊಂಡ, ಇತರ ಮೂಲಗಳಲ್ಲಿ ಲಭ್ಯವಿರುವ ನೀರನ್ನು ಬಳಸಿ ನೀರಾವರಿ ಕೊಡುವುದು', NULL, 'Irrigation using water available from agricultural wells and other sources', NULL, 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7996, 'GUAVA', NULL, N'<1', N'January-February', N'January-February', N'1,2', N'Vegetative stage', N'3', 'ABOVE NORMAL', 'YES', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', NULL, 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field.', NULL, 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (8034, 'GUAVA', NULL, N'>4', N'July-August', N'July-August', N'7,8', N'Vegetative stage', N'2', 'NORMAL', 'YES', '• ತೋಟದಲ್ಲಿ ಹಸಿರೆಲೆ ಗೊಬ್ಬರದ ಗಿಡಗಳನ್ನು ಬೆಳೆದಿದ್ದರೆ ಅವನ್ನು ಬಿತ್ತಿದ 45 ದಿನಗಳ ನಂತರ ಮಣ್ಣಿಗೆ ಸೇರಿಸುವುದು
• ತೋಟದ ಮಧ್ಯೆ ಅಂತರಬೆಳೆ ಬೆಳೆದಿದ್ದರೆ ಅವುಗಳಿಗೆ ತಗುಲುವ ರೋಗ ಮತ್ತು ಕೀಟಗಳ ಮೇಲೆ ಗಮನ ಹರಿಸುವುದು
• ಗಿಡದ ಸುತ್ತಲು ಪಾತಿ ಮಾಡಿ LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ಶೇ. 50ರ ರಸಗೊಬ್ಬರಗಳನ್ನು ಒದಗಿಸುವುದು 
• ಗಿಡದ ಸುತ್ತಲು ಒಣಗಿದ ಎಲೆಗಳಿಂದ ಮಣ್ಣಿನ ಮೇಲೊದಿಕೆ ಮಾಡುವುದರಿಂದ ಮಣ್ಣಿನ ತೇವಾಂಶವನ್ನು ಕಾಪಾಡಿಕೊಳ್ಳಬಹುದು', '•ಬಿಳಿ ನೊಣಗಳು ಹತೋಟಿಗೆ ಪ್ರತಿ ಎಕರೆಗೆ 10 ಹಳದಿ ಜಿಗುಟಾದ ಬಲೆಗಳನ್ನು ಸ್ಥಾಪಿಸುವುದು ಹಾಗೂ ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ 0.3 ಮಿ.ಲೀ. ಇಮಿಡಾಕ್ಲೋಪ್ರಿಡ್ 17.8% SL ಅಥವಾ 0.3 ಗ್ರಾಂ ಥಿಯಾಮೆಥಾಕ್ಸಮ್ 25% WG ಅಥವಾ 0.2 ಗ್ರಾಂ ಅಸೆಟಾಮಿಪ್ರಿಡ್ 20% SP ಅಥವಾ 5 ಮಿ.ಲೀ. ಬೇವಿನ ಎಣ್ಣೆಯನ್ನು ಬೆರೆಸಿ ಸಿಂಪಡಿಸುವುದು ಉತ್ತಮ

•ಕಜ್ಜಿ ತಿಗಣೆ ಕಂಡುಬಂದಲ್ಲಿ ಲೀ. ನೀರಿಗೆ ಪ್ರತಿ ಲೀಟರ್ ನೀರಿಗೆ 0.3 ಮಿಲಿ ಇಮಿಡಾಕ್ಲೋಪ್ರಿಡ್ 17.8% SL ಅಥವಾ 0.3 ಗ್ರಾಂ ಥಿಯಾಮೆಥಾಕ್ಸಮ್ 25% WG ಅಥವಾ 0.5 ಮಿಲಿ ಲ್ಯಾಂಬ್ಡಾ-ಸೈಹಲೋಥ್ರಿನ್ 5% EC ಸೇರಿಸಿ ಸಿಂಪಡಿಸುವುದು', '• If green manure crops are grown in the garden, incorporate them into the soil 45 days after sowing
• If intercrops are grown in the garden, pay attention to the diseases and pests that they are susceptible to
• Make a bed around the plant and provide 50% of the recommended fertilizer based on LRI 
• Mulching the soil with dry leaves around the plant can help maintain soil moisture', '•To control whiteflies, set up 10 yellow sticky traps per acre and spray 0.3 ml of Imidacloprid 17.8% SL or 0.3 g of Thiamethoxam 25% WG or 0.2 g of Acetamiprid 20% SP or 5 ml of Neem oil per litre of water

•If scabies is found, spray 0.3 ml of Imidacloprid 17.8% SL or 0.3 g of Thiamethoxam 25% WG or 0.5 ml of Lambda-cyhalothrin 5% EC per litre of water', 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (8035, 'GUAVA', NULL, N'>4', N'July-August', N'July-August', N'7,8', N'Vegetative stage', N'2', 'NORMAL', 'NO', '• ತೋಟದಲ್ಲಿ ಹಸಿರೆಲೆ ಗೊಬ್ಬರದ ಗಿಡಗಳನ್ನು ಬೆಳೆದಿದ್ದರೆ ಅವನ್ನು ಬಿತ್ತಿದ 45 ದಿನಗಳ ನಂತರ ಮಣ್ಣಿಗೆ ಸೇರಿಸುವುದು
• ತೋಟದ ಮಧ್ಯೆ ಅಂತರಬೆಳೆ ಬೆಳೆದಿದ್ದರೆ ಅವುಗಳಿಗೆ ತಗುಲುವ ರೋಗ ಮತ್ತು ಕೀಟಗಳ ಮೇಲೆ ಗಮನ ಹರಿಸುವುದು
• ಗಿಡದ ಸುತ್ತಲು ಪಾತಿ ಮಾಡಿ LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ಶೇ. 50ರ ರಸಗೊಬ್ಬರಗಳನ್ನು ಒದಗಿಸುವುದು
