INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (8103, 'SAPOTA', NULL, N'1-4', N'May-June', N'May-June', N'5,6', N'Vegetative stage', N'3', 'BELOW NORMAL', 'YES', '• ತೋಟದ ಮಧ್ಯೆ ಉಳುಮೆ ಮಾಡಿ LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ರಸಗೊಬ್ಬರಗಳನ್ನು ಒದಗಿಸುವುಸು
• ಹಸಿರೆಲೆಗೊಬ್ಬರದ ಬೆಳೆ ಅಥವಾ ಅಂತರ ಬೆಳೆಗಳನ್ನು ಬೆಳೆಯಬಹುದು', NULL, '• Plough the field and provide recommended fertilizers based on LRI
• Green manure crops or intercrops can be grown', NULL, 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (8104, 'SAPOTA', NULL, N'1-4', N'May-June', N'May-June', N'5,6', N'Vegetative stage', N'3', 'BELOW NORMAL', 'NO', '• ಕೃಷಿ ಹೊಂಡ, ಇತರ ಮೂಲಗಳಲ್ಲಿ ಲಭ್ಯವಿರುವ ನೀರನ್ನು ಬಳಸಿ ನೀರಾವರಿ ಕೊಡುವುದು
• ತೋಟದ ಮಧ್ಯೆ ಉಳುಮೆ ಮಾಡಿ LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ರಸಗೊಬ್ಬರಗಳನ್ನು ಒದಗಿಸುವುಸು
• ಹಸಿರೆಲೆಗೊಬ್ಬರದ ಬೆಳೆ ಅಥವಾ ಅಂತರ ಬೆಳೆಗಳನ್ನು ಬೆಳೆಯಬಹುದು', NULL, '• Irrigation using water available from agricultural wells, other sources
• Ploughing the field and providing fertilizers as recommended based on LRI
• Green manure crops or intercropping can be grown', NULL, 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7958, 'POMEGRANATE', NULL, N'>2', N'September-October', N'September-October', N'9,10', N'Flower initiation & Flowering', N'5', 'BELOW NORMAL', 'NO', '• ಕೃಷಿ ಹೊಂಡ, ಇತರ ಮೂಲಗಳಲ್ಲಿ ಲಭ್ಯವಿರುವ ನೀರನ್ನು ಬಳಸಿ ನೀರಾವರಿ ಕೊಡುವುದು
• ತೋಟದಲ್ಲಿ ಹಸಿರೆಲೆ ಗೊಬ್ಬರದ ಗಿಡಗಳನ್ನು ಬೆಳೆದಿದ್ದರೆ ಅವನ್ನು ಬಿತ್ತಿದ 45 ದಿನಗಳ ನಂತರ ಮಣ್ಣಿಗೆ ಸೇರಿಸುವುದು
• ತೋಟದ ಮಧ್ಯೆ ಅಂತರಬೆಳೆ ಬೆಳೆದಿದ್ದರೆ ಅವುಗಳಿಗೆ ತಗುಲುವ ರೋಗ ಮತ್ತು ಕೀಟಗಳ ಮೇಲೆ ಗಮನ ಹರಿಸುವುದು', NULL, '• Irrigation using water available from agricultural wells and other sources
• If green manure crops are grown in the garden, incorporate them into the soil 45 days after sowing
• If intercrops are grown in the garden, pay attention to the diseases and pests that they are susceptible to', NULL, 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7959, 'POMEGRANATE', NULL, N'>2', N'September-October', N'September-October', N'9,10', N'Flower initiation & Flowering', N'5', 'ABOVE NORMAL', 'YES', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', 'ಸಸ್ಯ ಹೇನು, ಹಿಟ್ಟುತಿಗಣೆ, ಬಿಳಿನೊಣ, ಥ್ರಿಪ್ಸ್ ನುಸಿ ನಿಯಂತ್ರಣಕ್ಕಾಗಿ ಪ್ರತಿ ಲೀಟರ್ ನೀರಿಗೆ 0.2 ಗ್ರಾಂ ಥೈಯೋಮಿಥಾಕ್ಸಾಮ್ 25 WG ಅಥವಾ 0.25 ಮಿ.ಲೀ. ಇಮಿಡಾಕ್ಲೋಪ್ರಿಡ್ 200 SL ಅನ್ನು ಬೆರೆಸಿ ಸಿಂಪಡಿಸುವುದು', 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field.', 'Spraying with 0.2 g Thiomethoxam 25 WG or 0.25 ml Imidacloprid 200 SL per liter of water for the control of aphids, mealybugs, whiteflies, and thrips', 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7960, 'POMEGRANATE', NULL, N'>2', N'September-October', N'September-October', N'9,10', N'Flower initiation & Flowering', N'5', 'ABOVE NORMAL', 'NO', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', NULL, 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field.', NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7961, 'POMEGRANATE', NULL, N'>2', N'November-December', N'November-December', N'11,12', N'Fruit set & Development', N'6', 'NORMAL', 'YES', 'ಗಿಡಗಳಿಗೆ ಪೊಟ್ಯಾಷ್‌ಯುಕ್ತ ಗೊಬ್ಬರವನ್ನು ಕೊಡುವುದು', 'ದುಂಡಾಣು ಎಲೆಚುಕ್ಕೆ ಕಂಡು ಬಂದಾಗ ಪ್ರಾರಂಭಿಕ ಹಂತದಲ್ಲಿ 0.5 ಗ್ರಾಂ 2 ಬ್ರೋಮೋ-2 ನೈಟ್ರೋಪ್ರೋಪೇನ್‍1,3 ಅಥವಾ 0.5 ಗ್ರಾಂ ಸ್ಟ್ರೆಪ್ಟೋಸೈಕ್ಲೀನ್‍ ಅಥವಾ 3.0 ಗ್ರಾಂ ತಾಮ್ರದ ಆಕ್ಸಿಕ್ಲೋರೈಡ್‍ 50 WP ಅನ್ನು ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿನಲ್ಲಿ ಬೆರೆಸಿ ಸಿಂಪಡಿಸುವುದು. ಹವಾಮಾನ ಹಾಗೂ ರೋಗ ಬಾಧೆಗೆ ಅನುಸಾರವಾಗಿ 5 ರಿಂದ 6 ಸಿಂಪರಣೆಗಳನ್ನು 10 ದಿನಗಳ ಅಂತರದಲ್ಲಿ ಕೈಗೊಳ್ಳುವುದು ಉತ್ತಮ', 'Fertilizing plants with potash', 'When round leaf spot is found, spray 0.5 g 2 bromo-2 nitropropane 1,3 or 0.5 g streptocycline or 3.0 g copper oxychloride 50 WP per liter of water at the initial stage. It is better to do 5 to 6 sprays at an interval of 10 days depending on the weather and disease severity', NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
