INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7963, 'POMEGRANATE', NULL, N'>2', N'November-December', N'November-December', N'11,12', N'Fruit set & Development', N'6', 'BELOW NORMAL', 'YES', 'ಗಿಡಗಳಿಗೆ ಪೊಟ್ಯಾಷ್‌ಯುಕ್ತ ಗೊಬ್ಬರವನ್ನು ಕೊಡುವುದು', NULL, 'Fertilizing plants with potash', NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (8008, 'GUAVA', NULL, N'1-4', N'May-June', N'May-June', N'5,6', N'Vegetative stage', N'7', 'ABOVE NORMAL', 'YES', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', NULL, 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field.', NULL, 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (8009, 'GUAVA', NULL, N'1-4', N'May-June', N'May-June', N'5,6', N'Vegetative stage', N'7', 'ABOVE NORMAL', 'NO', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', NULL, 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field.', NULL, 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (8010, 'GUAVA', NULL, N'1-4', N'July-December', N'July-December', N'7,12', N'Vegetative stage', N'2', 'NORMAL', 'YES', '• ಗಿಡದ ಆಕಾರ ರೂಪಿಸಲು ಅನಾವಶ್ಯಕ ಕೊಂಬೆ ಕತ್ತರಿಸುವುದು (ಹೆಚ್ಚಿನ ಮಾಹಿತಿಗಾಗಿ ತಂತ್ರಾಂಶದಲ್ಲಿರುವ ಪೇರಲ ಬೆಳೆಯ ಬೇಸಾಯ ಪದ್ದತಿಯನ್ನು ಅನುಸರಿಸಿ)
• ಎಲೆಗಳು ತಾಮ್ರ ವರ್ಣಕ್ಕೆ ತಿರುಗಿದಲ್ಲಿ ಗಿಡಗಳಿಗೆ ಶೇ. 0.5 ರ ಡಿ.ಎ.ಪಿ. ಮತ್ತು ಸತುವಿನ ಸಲ್ಫೇಟ್‌ಗಳನ್ನು ಅಕ್ಟೋಬರ್-ನವೆಂಬರ್ ತಿಂಗಳಲ್ಲಿ 4-6 ಸಲ ಪ್ರತಿ ವಾರಕ್ಕೊಮ್ಮೆ ಸಿಂಪರಣೆ ಮಾಡುವುದು. ಪ್ರತಿ ಕಿ. ಗ್ರಾಂ. ಸತುವಿನ ಸಲ್ಫೇಟ್ ದ್ರಾವಣಕ್ಕೆ 0.5 ಕಿ.ಗ್ರಾಂ. ಸುಣ್ಣದೊಂದಿಗೆ ಬೆರೆಸಿ ತಟಸ್ಥಗೊಳಿಸಿ
• ಗಿಡದ ಸುತ್ತಲು ಪಾತಿ ಮಾಡಿ LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ಗೊಬ್ಬರವನ್ನು ಕೊಡುವುದು. ಮಣ್ಣಿನ ಮೇಲೊದಿಕೆ ಮಾಡುವುದು', 'ಬಿಳಿ ನೊಣಗಳು ಹತೋಟಿಗೆ ಪ್ರತಿ ಎಕರೆಗೆ 10 ಹಳದಿ ಜಿಗುಟಾದ ಬಲೆಗಳನ್ನು ಸ್ಥಾಪಿಸುವುದು ಹಾಗೂ ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ 0.3 ಮಿ.ಲೀ. ಇಮಿಡಾಕ್ಲೋಪ್ರಿಡ್ 17.8% SL ಅಥವಾ 0.3 ಗ್ರಾಂ ಥಿಯಾಮೆಥಾಕ್ಸಮ್ 25% WG ಅಥವಾ 0.2 ಗ್ರಾಂ ಅಸೆಟಾಮಿಪ್ರಿಡ್ 20% SP ಅಥವಾ 5 ಮಿ.ಲೀ. ಬೇವಿನ ಎಣ್ಣೆಯನ್ನು ಬೆರೆಸಿ ಸಿಂಪಡಿಸುವುದು ಉತ್ತಮ', '• Prune unnecessary branches to shape the plant (For more information, follow the Guava cultivation method in the software)
• If the leaves turn copper-colored, spray the plants with 0.5% DAP and zinc sulfate 4-6 times a week in the month of October-November. For every kg. g. of zinc sulfate solution, mix it with 0.5 kg. lime and neutralize it
• Make a bed around the plant and apply the recommended fertilizer based on LRI. Top dressing the soil', 'For whitefly control, it is best to set up 10 yellow sticky traps per acre and spray with 0.3 ml of Imidacloprid 17.8% SL or 0.3 g of Thiamethoxam 25% WG or 0.2 g of Acetamiprid 20% SP or 5 ml of Neem oil mixed in each liter of water', 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (8046, 'GUAVA', NULL, N'>4', N'November-December', N'November-December', N'11,12', N'Fruit setting & Fruit maturing', N'4', 'NORMAL', 'YES', '• ಎಲೆಗಳು ತಾಮ್ರ ವರ್ಣಕ್ಕೆ ತಿರುಗಿದಲ್ಲಿ ಗಿಡಗಳಿಗೆ ಶೇ. 0.5 ರ ಡಿ.ಎ.ಪಿ. ಮತ್ತು ಸತುವಿನ ಸಲ್ಫೇಟ್‌ಗಳನ್ನು ಅಕ್ಟೋಬರ್-ನವೆಂಬರ್ ತಿಂಗಳಲ್ಲಿ 4-6 ಸಲ ಪ್ರತಿ ವಾರಕ್ಕೊಮ್ಮೆ ಸಿಂಪರಣೆ ಮಾಡುವುದು. ಪ್ರತಿ ಕಿ. ಗ್ರಾಂ. ಸತುವಿನ ಸಲ್ಫೇಟ್ ದ್ರಾವಣಕ್ಕೆ 0.5 ಕಿ.ಗ್ರಾಂ. ಸುಣ್ಣದೊಂದಿಗೆ ಬೆರೆಸಿ ತಟಸ್ಥಗೊಳಿಸಿ
• ಗಿಡಗಳಿಗೆ LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಲಾದ ಪೊಟ್ಯಾಷ್‌ಯುಕ್ತ ಗೊಬ್ಬರವನ್ನು ಕೊಡುವುದು, ಇದರಿಂದ ಹಣ್ಣುಗಳ ಬೆಳವಣಿಗೆ ಉತ್ತಮವಾಗಿರುತ್ತದೆ', '•ಕಜ್ಜಿ ತಿಗಣೆ ಕಂಡುಬಂದಲ್ಲಿ ಲೀ. ನೀರಿಗೆ ಪ್ರತಿ ಲೀಟರ್ ನೀರಿಗೆ 0.3 ಮಿಲಿ ಇಮಿಡಾಕ್ಲೋಪ್ರಿಡ್ 17.8% SL ಅಥವಾ 0.3 ಗ್ರಾಂ ಥಿಯಾಮೆಥಾಕ್ಸಮ್ 25% WG ಅಥವಾ 0.5 ಮಿಲಿ ಲ್ಯಾಂಬ್ಡಾ-ಸೈಹಲೋಥ್ರಿನ್ 5% EC ಸೇರಿಸಿ ಸಿಂಪಡಿಸುವುದು

•ಚಿಬ್ಬು ರೋಗ ಕಂಡುಬಂದರೆ ಲೀ. ನೀರಿಗೆ 2.0 ಗ್ರಾಂ ತಾಮ್ರದ ಆಕ್ಸಿಕ್ಲೋರೈಡ್ 50 WP ಅಥವಾ 1 ಗ್ರಾಂ ಕಾರ್ಬೆಂಡಜಿಂ 50 WP ಅಥವಾ ಥಯೋಫಿನೆಟ್ ಮಿಥೈಲ್ 70 WP ಸೇರಿಸಿ ಸಿಂಪರಿಸುವುದು. ಬಿಳಿನೊಣ ಬಾಧೆಗೆ ಲೀ. ನೀರಿಗೆ 5 ಮಿ.ಲೀ. ಬೇವಿನ ಎಣ್ಣೆ + 5 ಮಿಲೀ. ಮೀನೆಣ್ಣೆ ಸಿಂಪರಣೆ ಮಾಡುವುದು', '• If the leaves turn copper in color, spray the plants with 0.5% DAP and zinc sulphate 4-6 times a week in the month of October-November. For every kg. of zinc sulphate solution, mix 0.5 kg. of lime and neutralize it. • Give the plants a potash fertilizer recommended based on LRI, so that the growth of fruits is good.', '•If scabies is found, spray 0.3 ml of imidacloprid 17.8% SL or 0.3 g of thiamethoxam 25% WG or 0.5 ml of lambda-cyhalothrin 5% EC per liter of water

•If scab is found, spray 2.0 g of copper oxychloride 50 WP or 1 g of carbendazim 50 WP or thiophene methyl 70 WP per liter of water. For whitefly infestation, spray 5 ml of neem oil + 5 ml of fish oil per liter of water', 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
