INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (8109, 'SAPOTA', NULL, N'1-4', N'July-August', N'July-August', N'7,8', N'Vegetative stage', N'3', 'BELOW NORMAL', 'YES', '• ಗಿಡಗಳು ನೇರವಾಗಿ ಬೆಳೆಯಲು ಅವುಗಳಿಗೆ ಆಸರೆ ಒದಗಿಸುವುದು
• ತೋಟದಲ್ಲಿ ಹಸಿರೆಲೆ ಗೊಬ್ಬರದ ಗಿಡಗಳನ್ನು ಬೆಳೆದಿದ್ದರೆ ಅವನ್ನು ಬಿತ್ತಿದ 45 ದಿನಗಳ ನಂತರ ಮಣ್ಣಿಗೆ ಸೇರಿಸುವುದು
• ತೋಟದ ಮಧ್ಯೆ ಅಂತರಬೆಳೆ ಬೆಳೆದಿದ್ದರೆ ಅವುಗಳಿಗೆ ತಗುಲುವ ರೋಗ ಮತ್ತು ಕೀಟಗಳ ಮೇಲೆ ಗಮನ ಹರಿಸುವುದು', 'ಎಲೆ ಚುಕ್ಕೆ ರೋಗ ಕಂಡುಬಂದಲ್ಲಿ ಲೀ. ನೀರಿಗೆ 2.0 ಗ್ರಾಂ ಮ್ಯಾಂಕೋಜೆಬ್ 75 WP ಅಥವಾ 2.0 ಗ್ರಾಂ ಜೈನೆಬ್ 75 WP ಅಥವಾ 1.0 ಗ್ರಾಂ ಕಾರ್ಬೆಂಡಜಿಂ 50 WP  ಸೇರಿಸಿ ಸಿಂಪಡಿಸುವುದು', '• Provide support for plants to grow upright
• If green manure plants are grown in the garden, incorporate them into the soil 45 days after sowing
• If intercrops are grown in the garden, pay attention to diseases and pests that affect them', 'If leaf spot disease is found, spray by adding 2.0 g Mancozeb 75 WP or 2.0 g Zaineb 75 WP or 1.0 g Carbendazim 50 WP to 1 liter of water', 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
