INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7972, 'POMEGRANATE', NULL, N'>2', N'January-February', N'January-February', N'1,2', N'Harvesting', N'7', 'ABOVE NORMAL', 'NO', '• ಮಳೆ ಇಲ್ಲದ ಸಂದರ್ಭದಲ್ಲಿ ಮಾಗಿದ ಹಣ್ಣುಗಳನ್ನು ಕೊಯ್ಲು ಮಾಡುವುದು
• ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', 'ಶಲ್ಕ ಕೀಟ ಹಾಗೂ ಥ್ರಿಪ್ಸ್ ಕಂಡುಬಂದರೆ ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ 1 ಮಿ.ಲೀ. ಸೈಯಾಂಟ್ರನಿಲಿಪ್ರೋಲ್ 10.26 OD ಅಥವಾ 0.2 ಗ್ರಾಂ ಇಮಾಮೆಕ್ಟಿನ್ ಬೆಂಜೋಯೇಟ್ 5 SG ಅಥವಾ 2 ಮಿ ಲೀ. ಪ್ರೊಫೆನೋಫಾಸ್ 50 EC+ 5 ಮಿ.ಲೀ. ಫಿಶ್‌ಆಯಲ್ ರೋಸಿನ್ ಸೋಪ್ ಸೇರಿಸಿ ಸಿಂಪಡಿಸುವುದು', '• Harvesting ripe fruits when there is no rain
• If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field', 'If scale insects and thrips are found, spray 1 ml. Cyantraniliprole 10.26 OD or 0.2 gm. Emamectin Benzoate 5 SG or 2 ml. Profenophos 50 EC + 5 ml. Fish Oil Rosin Soap per liter of water', 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (7973, 'POMEGRANATE', NULL, N'>2', N'March-April', N'March-April', N'3,4', N'Vegetative stage', N'8', 'NORMAL', 'YES', 'ಹಣ್ಣುಗಳ ಕೊಯ್ಲಿನ ನಂತರ ಒಣ ಕೊಂಬೆಗಳನ್ನು ತೆಗೆದುಹಾಕುವುದು', NULL, 'Removing dry branches after harvesting fruits', NULL, 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (8011, 'GUAVA', NULL, N'1-4', N'July-December', N'July-December', N'7,12', N'Vegetative stage', N'2', 'NORMAL', 'NO', '• ಗಿಡದ ಆಕಾರ ರೂಪಿಸಲು ಅನಾವಶ್ಯಕ ಕೊಂಬೆ ಕತ್ತರಿಸುವುದು (ಹೆಚ್ಚಿನ ಮಾಹಿತಿಗಾಗಿ ತಂತ್ರಾಂಶದಲ್ಲಿರುವ ಪೇರಲ ಬೆಳೆಯ ಬೇಸಾಯ ಪದ್ದತಿಯನ್ನು ಅನುಸರಿಸಿ)
• ಎಲೆಗಳು ತಾಮ್ರ ವರ್ಣಕ್ಕೆ ತಿರುಗಿದಲ್ಲಿ ಗಿಡಗಳಿಗೆ ಶೇ. 0.5 ರ ಡಿ.ಎ.ಪಿ. ಮತ್ತು ಸತುವಿನ ಸಲ್ಫೇಟ್‌ಗಳನ್ನು ಅಕ್ಟೋಬರ್-ನವೆಂಬರ್ ತಿಂಗಳಲ್ಲಿ 4-6 ಸಲ ಪ್ರತಿ ವಾರಕ್ಕೊಮ್ಮೆ ಸಿಂಪರಣೆ ಮಾಡುವುದು. ಪ್ರತಿ ಕಿ. ಗ್ರಾಂ. ಸತುವಿನ ಸಲ್ಫೇಟ್ ದ್ರಾವಣಕ್ಕೆ 0.5 ಕಿ.ಗ್ರಾಂ. ಸುಣ್ಣದೊಂದಿಗೆ ಬೆರೆಸಿ ತಟಸ್ಥಗೊಳಿಸಿ
• ಗಿಡದ ಸುತ್ತಲು ಪಾತಿ ಮಾಡಿ LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ಗೊಬ್ಬರವನ್ನು ಕೊಡುವುದು. ಮಣ್ಣಿನ ಮೇಲೊದಿಕೆ ಮಾಡುವುದು', 'ಬಿಳಿ ನೊಣಗಳು ಹತೋಟಿಗೆ ಪ್ರತಿ ಎಕರೆಗೆ 10 ಹಳದಿ ಜಿಗುಟಾದ ಬಲೆಗಳನ್ನು ಸ್ಥಾಪಿಸುವುದು ಹಾಗೂ ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ 0.3 ಮಿ.ಲೀ. ಇಮಿಡಾಕ್ಲೋಪ್ರಿಡ್ 17.8% SL ಅಥವಾ 0.3 ಗ್ರಾಂ ಥಿಯಾಮೆಥಾಕ್ಸಮ್ 25% WG ಅಥವಾ 0.2 ಗ್ರಾಂ ಅಸೆಟಾಮಿಪ್ರಿಡ್ 20% SP ಅಥವಾ 5 ಮಿ.ಲೀ. ಬೇವಿನ ಎಣ್ಣೆಯನ್ನು ಬೆರೆಸಿ ಸಿಂಪಡಿಸುವುದು ಉತ್ತಮ', '• Prune unnecessary branches to shape the plant (For more information, follow the Guava cultivation method in the software)
• If the leaves turn copper-colored, spray the plants with 0.5% DAP and zinc sulfate 4-6 times a week in the month of October-November. For every kg. g. of zinc sulfate solution, mix it with 0.5 kg. lime and neutralize it
• Make a bed around the plant and apply the recommended fertilizer based on LRI. Top dressing the soil', 'For whitefly control, it is best to set up 10 yellow sticky traps per acre and spray with 0.3 ml of Imidacloprid 17.8% SL or 0.3 g of Thiamethoxam 25% WG or 0.2 g of Acetamiprid 20% SP or 5 ml of Neem oil mixed in each liter of water', 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (8012, 'GUAVA', NULL, N'1-4', N'July-December', N'July-December', N'7,12', N'Vegetative stage', N'2', 'BELOW NORMAL', 'YES', '• ಗಿಡದ ಆಕಾರ ರೂಪಿಸಲು ಅನಾವಶ್ಯಕ ಕೊಂಬೆ ಕತ್ತರಿಸುವುದು (ಹೆಚ್ಚಿನ ಮಾಹಿತಿಗಾಗಿ ತಂತ್ರಾಂಶದಲ್ಲಿರುವ ಪೇರಲ ಬೆಳೆಯ ಬೇಸಾಯ ಪದ್ದತಿಯನ್ನು ಅನುಸರಿಸಿ)
