INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (8757, 'CARDAMOM', 15, N'1-2', N'May-June', N'May-June', N'5,6', N'Vegetative stage', N'3', 'NORMAL', 'YES', 'ತೋಟದಲ್ಲಿ ಅಂತರ ಬೇಸಾಯದ ಮೂಲಕ ಕಳೆ ನಿರ್ವಹಣೆ ಮಾಡಿ LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ಶೇ. 50 ರ ರಸಗೊಬ್ಬರವನ್ನು ಕೊಡುವುದು', NULL, 'Weed management through intercropping in the garden and application of 50% fertilizer as recommended based on LRI', NULL, 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (8758, 'CARDAMOM', 15, N'1-2', N'May-June', N'May-June', N'5,6', N'Vegetative stage', N'3', 'NORMAL', 'NO', 'ತೋಟದಲ್ಲಿ ಅಂತರ ಬೇಸಾಯದ ಮೂಲಕ ಕಳೆ ನಿರ್ವಹಣೆ ಮಾಡಿ LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ಶೇ. 50 ರ ರಸಗೊಬ್ಬರವನ್ನು ಕೊಡುವುದು', NULL, 'Weed management through intercropping in the garden and application of 50% fertilizer as recommended based on LRI', NULL, 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (8759, 'CARDAMOM', 15, N'1-2', N'May-June', N'May-June', N'5,6', N'Vegetative stage', N'3', 'BELOW NORMAL', 'YES', 'ತೋಟದಲ್ಲಿ ಅಂತರ ಬೇಸಾಯದ ಮೂಲಕ ಕಳೆ ನಿರ್ವಹಣೆ ಮಾಡಿ LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ಶೇ. 50 ರ ರಸಗೊಬ್ಬರವನ್ನು ಕೊಡುವುದು', 'ಎಲೆ ಚುಕ್ಕೆ ರೋಗ ಮತ್ತು ಕೊಳೆ ರೋಗ ಕಂಡು ಬಂದಾಗ ಪ್ರತಿ ಲೀಟರ್‍ 1% ಬೋರ್ಡೋ ದ್ರಾವಣ ಅಥವಾ 3 ಗ್ರಾಂ ತಾಮ್ರದ ಆಕ್ಸಿಕ್ಲೋರೈಡ್ 50 WP ಸೇರಿಸಿ ಸಿಂಪರಣೆ ಮಾಡುವುದು. ಥ್ರಿಪ್ಸ್ ನುಸಿಗಳ ಹತೋಟಿಗಾಗಿ ಲೀ. ನೀರಿಗೆ 1.7 ಮಿ.ಲೀ. ಡೈಮಿಥೋಯೇಟ್ 30 EC ಅಥವಾ 1.0 ಗ್ರಾಂ ಮಿಥೋಮಿಲ್ 40 SP ಯನ್ನು ಸಿಂಪಡಿಸುವುದು', 'Weed management through intercropping in the garden and application of 50% fertilizer as recommended based on LRI', 'When leaf spot and powdery mildew are found, spray with 1% Bordeaux mixture or 3 gm copper oxychloride 50 WP per liter. For thrips control, spray 1.7 ml dimethoate 30 EC or 1.0 gm methomyl 40 SP per liter of water', 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
