INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (8764, 'CARDAMOM', 15, N'1-2', N'July-August', N'July-August', N'7,8', N'Vegetative stage', N'3', 'NORMAL', 'NO', 'ನೆರಳು ಮರಗಳಲ್ಲಿ ಹೆಚ್ಚಾಗಿರುವ ಕೊಂಬೆಗಳನ್ನು ತೆಗೆದು ತೋಟದಲ್ಲಿ ಬೆಳಕನ್ನು ಒದಗಿಸುವುದು', NULL, 'Removing overgrown branches from shade trees to provide light in the garden', NULL, 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (8765, 'CARDAMOM', 15, N'1-2', N'July-August', N'July-August', N'7,8', N'Vegetative stage', N'3', 'BELOW NORMAL', 'YES', 'ನೆರಳು ಮರಗಳಲ್ಲಿ ಹೆಚ್ಚಾಗಿರುವ ಕೊಂಬೆಗಳನ್ನು ತೆಗೆದು ತೋಟದಲ್ಲಿ ಬೆಳಕನ್ನು ಒದಗಿಸುವುದು', 'ಗೊಂಚಲು ಕೊಳೆ ರೋಗ ಕಂಡುಬಂದಾಗ ಲೀ. ನೀರಿಗೆ 3 ಗ್ರಾಂ ತಾಮ್ರದ ಆಕ್ಸಿಕ್ಲೋರೈಡ್ 50 WP ಅಥವಾ 2 ಗ್ರಾಂ ಮ್ಯಾಂಕೋಜೆಬ್ 75 WP ಸೇರಿಸಿ ಸಿಂಪಡಿಸುವುದು', 'Removing overgrown branches from shade trees to provide light in the garden', 'When cluster rot disease is detected, spray by adding 3 gm copper oxychloride 50 WP or 2 gm mancozeb 75 WP to 1 liter of water', 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (8766, 'CARDAMOM', 15, N'1-2', N'July-August', N'July-August', N'7,8', N'Vegetative stage', N'3', 'BELOW NORMAL', 'NO', '• ಕೃಷಿ ಹೊಂಡ, ಇತರ ಮೂಲಗಳಲ್ಲಿ ಲಭ್ಯವಿರುವ ನೀರನ್ನು ಬಳಸಿ ನೀರಾವರಿ ಕೊಡುವುದು
• ನೆರಳು ಮರಗಳಲ್ಲಿ ಹೆಚ್ಚಾಗಿರುವ ಕೊಂಬೆಗಳನ್ನು ತೆಗೆದು ತೋಟದಲ್ಲಿ ಬೆಳಕನ್ನು ಒದಗಿಸುವುದು', 'ಕಂಬಳಿ ಹುಳು ಮತ್ತು ಕಾಯಿ ಕೊರೆಯುವ ಹುಳು ಕಂಡುಬಂದಲ್ಲಿ ಲೀ. ನೀರಿಗೆ 0.25 ಮಿ.ಲೀ. ಫ್ಲುಬೆಂಡಿಅಮೈಡ್ 45 SC ಅಥವಾ 1 ಗ್ರಾಂ ಮಿಥೋಮಿಲ್ 40 SP ಅಥವಾ 2.0 ಮಿ.ಲೀ. ಕ್ವಿನಾಲ್‌ಫಾಸ್ 25 EC ಅಥವಾ 2 ಮಿ.ಲೀ. ಕ್ಲೋರ್‌ಪೈರಿಫಾಸ್ 20 EC ಯನ್ನು ಬೆರೆಸಿ ಸಿಂಪಡಿಸುವುದು', '• Irrigation using water available from agricultural wells and other sources
• Removing overgrown branches from shade trees to provide light in the garden', 'If carpet beetle and nut borer are found, spray 0.25 ml. Flubendiamide 45 SC or 1 gm. Methomyl 40 SP or 2.0 ml. Quinalphos 25 EC or 2 ml. Chlorpyrifos 20 EC per liter of water', 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (8767, 'CARDAMOM', 15, N'1-2', N'July-August', N'July-August', N'7,8', N'Vegetative stage', N'3', 'ABOVE NORMAL', 'YES', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', NULL, 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field.', NULL, 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
