INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (8775, 'CARDAMOM', 15, N'1-2', N'January-February', N'January-February', N'1,2', N'Vegetative stage', N'3', 'NORMAL', 'YES', 'ಗಿಡಗಳ ಬುಡಕ್ಕೆ ಮಣ್ಣು ಏರಿ ಹಾಕುವುದು. ಗಿಡಗಳ ಸುತ್ತಲು ಒಣಗಿದ ಎಲೆಗಳಿಂದ ಮಣ್ಣಿನ ಮೇಲೊದಿಕೆ ಮಾಡುವುರದ ಮೂಲಕ ಮಣ್ಣಿನ ತೇವಾಂಶವನ್ನು ಕಾಪಾಡಿಕೊಳ್ಳಬಹುದು', '•ಸಸಿ ಕತ್ತರಿಸುವ ಹುಳುವಿನ ಬಾಧೆ ಇದ್ದಲ್ಲಿ ಲೀ. ನೀರಿಗೆ 2 ಮಿ.ಲೀ ಕ್ವಿನಾಲ್ ಫಾಸ್ 25 EC ಅಥವಾ 2 ಮಿ.ಲೀ. ಕ್ಲೋರೋಪೈರಿಫಾಸ್ 20 EC ಸೇರಿಸಿ ಸಸಿಗಳ ಬುಡಕ್ಕೆ ಸಿಂಪಡಿಸುವುದು
•ಸಸಿಕೊಳೆ ರೋಗ ತಡೆಗಟ್ಟಲು ಸಸಿ ಮಡಿಯನ್ನು ಶೇ.1 ರ ಬೋರ್ಡೋ ದ್ರಾವಣ ಅಥವಾ 2 ಗ್ರಾಂ ತಾಮ್ರದ ಆಕ್ಸಿಕ್ಲೋರೈಡ್ 50 WP ಪ್ರತಿ ಲೀಟರ್ ನೀರಿನಲ್ಲಿ ಸೇರಿಸಿ ಕೊಳೆ ರೋಗದಿಂದ ಬಳುಲುತ್ತಿರುವ ಸಸಿಗಳ ಸುತ್ತಲೂ ನೆನೆಯುವ ಹಾಗೆ ಸಿಂಪಡಿಸುವುದು', 'Mulching the soil around the base of the plants. Mulching the soil with dry leaves around the plants can help maintain soil moisture.', '•If there is a problem of sapling cutworm, add 2 ml Quinolphos 25 EC or 2 ml Chlorpyrifos 20 EC to 1 liter of water and spray it at the base of the seedlings
•To prevent sapling rot, add 1% Bordeaux mixture or 2 gm Copper Oxychloride 50 WP per liter of water and spray it around the seedlings that are suffering from rot', 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
