INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (8780, 'CARDAMOM', 15, N'1-2', N'January-February', N'January-February', N'1,2', N'Vegetative stage', N'3', 'ABOVE NORMAL', 'NO', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', NULL, 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field.', NULL, 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (8781, 'CARDAMOM', 15, N'1-2', N'March-April', N'March-April', N'3,4', N'Vegetative stage', N'3', 'NORMAL', 'YES', 'ಗಿಡಗಳ ಸುತ್ತಲು ಒಣಗಿದ ಎಲೆಗಳಿಂದ ಮಣ್ಣಿನ ಮೇಲೊದಿಕೆ ಮಾಡುವುರದ ಮೂಲಕ ಮಣ್ಣಿನ ತೇವಾಂಶವನ್ನು ಕಾಪಾಡಿಕೊಳ್ಳಬಹುದು', 'ಕಟ್ಟೆ ರೋಗದ ನಿಯಂತ್ರಣಕ್ಕಾಗಿ ಲೀ. ನೀರಿಗೆ 0.5 ಮಿ.ಲೀ. ಪಾಸ್ಫಾಮಿಡಾನ್ 85 WP ಅಥವಾ 1.7 ಮಿ.ಲೀ. ಡೈಮಿಥೋಯೇಟ್ 30 EC ಬೆರೆಸಿ ಸಿಂಪಡಿಸಬೇಕು. ಸುಳಿನೊಣ ಕಂಡು ಬಂದಲ್ಲಿ ಲೀ. ನೀರಿಗೆ 2 ಮಿ.ಲೀ ಕ್ವಿನಾಲ್ ಫಾಸ್ 25 EC ಅಥವಾ 1.70 ಮಿ.ಲೀ. ಡೈಮಿಥೋಯೇಟ್ 30 EC ಯನ್ನು ಸೇರಿಸಿ ಸಿಂಪಡಿಸುವುದು', 'Soil moisture can be maintained by mulching the soil around plants with dry leaves.', 'For the control of scab, spray 0.5 ml of phosphamidon 85 WP or 1.7 ml of dimethoate 30 EC per liter of water. If powdery mildew is found, spray 2 ml of quinal phos 25 EC or 1.70 ml of dimethoate 30 EC per liter of water', 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_MONTHS_CROPS_ADVISORY" ("HORTI_MONTH_ADVISORY_ID", "CROP_NAME", "CROP_ID", "AGE_OF_THE_CROP", "MONTH_PERIOD", "MONTH_NAME", "MONTH_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_MONTH_RAINFALL", "NEXT_MONTH_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (8782, 'CARDAMOM', 15, N'1-2', N'March-April', N'March-April', N'3,4', N'Vegetative stage', N'3', 'NORMAL', 'NO', 'ಗಿಡಗಳ ಸುತ್ತಲು ಒಣಗಿದ ಎಲೆಗಳಿಂದ ಮಣ್ಣಿನ ಮೇಲೊದಿಕೆ ಮಾಡುವುರದ ಮೂಲಕ ಮಣ್ಣಿನ ತೇವಾಂಶವನ್ನು ಕಾಪಾಡಿಕೊಳ್ಳಬಹುದು', 'ಕಟ್ಟೆ ರೋಗದ ನಿಯಂತ್ರಣಕ್ಕಾಗಿ ಲೀ. ನೀರಿಗೆ 0.5 ಮಿ.ಲೀ. ಪಾಸ್ಫಾಮಿಡಾನ್ 85 WP ಅಥವಾ 1.7 ಮಿ.ಲೀ. ಡೈಮಿಥೋಯೇಟ್ 30 EC ಬೆರೆಸಿ ಸಿಂಪಡಿಸಬೇಕು. ಸುಳಿನೊಣ ಕಂಡು ಬಂದಲ್ಲಿ ಲೀ. ನೀರಿಗೆ 2 ಮಿ.ಲೀ ಕ್ವಿನಾಲ್ ಫಾಸ್ 25 EC ಅಥವಾ 1.70 ಮಿ.ಲೀ. ಡೈಮಿಥೋಯೇಟ್ 30 EC ಯನ್ನು ಸೇರಿಸಿ ಸಿಂಪಡಿಸುವುದು', 'Soil moisture can be maintained by mulching the soil around plants with dry leaves.', 'For the control of scab, spray 0.5 ml of phosphamidon 85 WP or 1.7 ml of dimethoate 30 EC per liter of water. If powdery mildew is found, spray 2 ml of quinal phos 25 EC or 1.70 ml of dimethoate 30 EC per liter of water', 'NIL', 'SIK', TO_TIMESTAMP('2026-05-26 15:47:53', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
